INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/expo-tailwind-setup', 'official', 'expo', 'skills', 'expo/skills', 'expo-tailwind-setup', 1349, 59, 97, '2026-03-06T04:04:30Z', '2026-03-06T05:23:38.283Z', '6abfc223a376571e0ee84014b3b474a3f2828ac2ebcde59c5c2b6b4bc802e233', '{"id":"expo/skills/expo-tailwind-setup","name":"expo-tailwind-setup","description":{"en":"The expo-tailwind-setup skill sets up Tailwind CSS v4 in Expo using react-native-css and NativeWind v5 for universal styling. This skill benefits developers working on cross-platform React Native projects.","es":"Configuración de Tailwind CSS v4 en Expo con react-native-css y NativeWind v5 para estilos universales","fr":"Configuration de Tailwind CSS v4 dans Expo avec react-native-css et NativeWind v5 pour des styles universels","de":"Einrichtung von Tailwind CSS v4 in Expo mit react-native-css und NativeWind v5 für universelle Stile"},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"expo-tailwind-setup","description":"Set up Tailwind CSS v4 in Expo with react-native-css and NativeWind v5 for universal styling","version":"1.0.0","bodyPreview":"# Tailwind CSS Setup for Expo with react-native-css\n\nThis guide covers setting up Tailwind CSS v4 in Expo using react-native-css and NativeWind v5 for universal styling across iOS, Android, and Web.\n\n## Overview\n\nThis setup uses:\n\n- **Tailwind CSS v4** - Modern CSS-first configuration\n- **react-native-css** - CSS runtime for React Native\n- **NativeWind v5** - Metro transformer for Tailwind in React Native\n- **@tailwindcss/postcss** - PostCSS plugin for Tailwind v4\n\n## Installation\n\n```bash\n# Ins","body":"# Tailwind CSS Setup for Expo with react-native-css\n\nThis guide covers setting up Tailwind CSS v4 in Expo using react-native-css and NativeWind v5 for universal styling across iOS, Android, and Web.\n\n## Overview\n\nThis setup uses:\n\n- **Tailwind CSS v4** - Modern CSS-first configuration\n- **react-native-css** - CSS runtime for React Native\n- **NativeWind v5** - Metro transformer for Tailwind in React Native\n- **@tailwindcss/postcss** - PostCSS plugin for Tailwind v4\n\n## Installation\n\n```bash\n# Install dependencies\nnpx expo install tailwindcss@^4 nativewind@5.0.0-preview.2 react-native-css@0.0.0-nightly.5ce6396 @tailwindcss/postcss tailwind-merge clsx\n```\n\nAdd resolutions for lightningcss compatibility:\n\n```json\n// package.json\n{\n  \"resolutions\": {\n    \"lightningcss\": \"1.30.1\"\n  }\n}\n```\n\n- autoprefixer is not needed in Expo because of lightningcss\n- postcss is included in expo by default\n\n## Configuration Files\n\n### Metro Config\n\nCreate or update `metro.config.js`:\n\n```js\n// metro.config.js\nconst { getDefaultConfig } = require(\"expo/metro-config\");\nconst { withNativewind } = require(\"nativewind/metro\");\n\n/** @type {import(''expo/metro-config'').MetroConfig} */\nconst config = getDefaultConfig(__dirname);\n\nmodule.exports = withNativewind(config, {\n  // inline variables break PlatformColor in CSS variables\n  inlineVariables: false,\n  // We add className support manually\n  globalClassNamePolyfill: false,\n});\n```\n\n### PostCSS Config\n\nCreate `postcss.config.mjs`:\n\n```js\n// postcss.config.mjs\nexport default {\n  plugins: {\n    \"@tailwindcss/postcss\": {},\n  },\n};\n```\n\n### Global CSS\n\nCreate `src/global.css`:\n\n```css\n@import \"tailwindcss/theme.css\" layer(theme);\n@import \"tailwindcss/preflight.css\" layer(base);\n@import \"tailwindcss/utilities.css\";\n\n/* Platform-specific font families */\n@media android {\n  :root {\n    --font-mono: monospace;\n    --font-rounded: normal;\n    --font-serif: serif;\n    --font-sans: normal;\n  }\n}\n\n@media ios {\n  :root {\n    --font-mono: ui-monospace;\n    --font-serif: ui-serif;\n    --font-sans: system-ui;\n    --font-rounded: ui-rounded;\n  }\n}\n```\n\n## IMPORTANT: No Babel Config Needed\n\nWith Tailwind v4 and NativeWind v5, you do NOT need a babel.config.js for Tailwind. Remove any NativeWind babel presets if present:\n\n```js\n// DELETE babel.config.js if it only contains NativeWind config\n// The following is NO LONGER needed:\n// module.exports = function (api) {\n//   api.cache(true);\n//   return {\n//     presets: [\n//       [\"babel-preset-expo\", { jsxImportSource: \"nativewind\" }],\n//       \"nativewind/babel\",\n//     ],\n//   };\n// };\n```\n\n## CSS Component Wrappers\n\nSince react-native-css requires explicit CSS element wrapping, create reusable components:\n\n### Main Components (`src/tw/index.tsx`)\n\n```tsx\nimport {\n  useCssElement,\n  useNativeVariable as useFunctionalVariable,\n} from \"react-native-css\";\n\nimport { Link as RouterLink } from \"expo-router\";\nimport Animated from \"react-native-reanimated\";\nimport React from \"react\";\nimport {\n  View as RNView,\n  Text as RNText,\n  Pressable as RNPressable,\n  ScrollView as RNScrollView,\n  TouchableHighlight as RNTouchableHighlight,\n  TextInput as RNTextInput,\n  StyleSheet,\n} from \"react-native\";\n\n// CSS-enabled Link\nexport const Link = (\n  props: React.ComponentProps<typeof RouterLink> & { className?: string }\n) => {\n  return useCssElement(RouterLink, props, { className: \"style\" });\n};\n\nLink.Trigger = RouterLink.Trigger;\nLink.Menu = RouterLink.Menu;\nLink.MenuAction = RouterLink.MenuAction;\nLink.Preview = RouterLink.Preview;\n\n// CSS Variable hook\nexport const useCSSVariable =\n  process.env.EXPO_OS !== \"web\"\n    ? useFunctionalVariable\n    : (variable: string) => `var(${variable})`;\n\n// View\nexport type ViewProps = React.ComponentProps<typeof RNView> & {\n  className?: string;\n};\n\nexport const View = (props: ViewProps) => {\n  return useCssElement(RNView, props, { className: \"style\" });\n};\nView.displayName = \"CSS(View)\";\n\n// Text\nexport const Text = (\n  props: React.ComponentProps<typeof RNText> & { className?: string }\n) => {\n  return useCssElement(RNText, props, { className: \"style\" });\n};\nText.displayName = \"CSS(Text)\";\n\n// ScrollView\nexport const ScrollView = (\n  props: React.ComponentProps<typeof RNScrollView> & {\n    className?: string;\n    contentContainerClassName?: string;\n  }\n) => {\n  return useCssElement(RNScrollView, props, {\n    className: \"style\",\n    contentContainerClassName: \"contentContainerStyle\",\n  });\n};\nScrollView.displayName = \"CSS(ScrollView)\";\n\n// Pressable\nexport const Pressable = (\n  props: React.ComponentProps<typeof RNPressable> & { className?: string }\n) => {\n  return useCssElement(RNPressable, props, { className: \"style\" });\n};\nPressable.displayName = \"CSS(Pressable)\";\n\n// TextInput\nexport const TextInput = (\n  props: React.ComponentProps<typeof RNTextInput> & { className?: string }\n) => {\n  return useCssElement(RNTextInput, props, { className: \"style\" });\n};\nTextInput.displayName = \"CSS(TextInput)\";\n\n// AnimatedScrollView\nexport const AnimatedScrollView = (\n  props: React.ComponentProps<typeof Animated.ScrollView> & {\n    className?: string;\n    contentClassName?: string;\n    contentContainerClassName?: string;\n  }\n) => {\n  return useCssElement(Animated.ScrollView, props, {\n    className: \"style\",\n    contentClassName: \"contentContainerStyle\",\n    contentContainerClassName: \"contentContainerStyle\",\n  });\n};\n\n// TouchableHighlight with underlayColor extraction\nfunction XXTouchableHighlight(\n  props: React.ComponentProps<typeof RNTouchableHighlight>\n) {\n  const { underlayColor, ...style } = StyleSheet.flatten(props.style) || {};\n  return (\n    <RNTouchableHighlight\n      underlayColor={underlayColor}\n      {...props}\n      style={style}\n    />\n  );\n}\n\nexport const TouchableHighlight = (\n  props: React.ComponentProps<typeof RNTouchableHighlight>\n) => {\n  return useCssElement(XXTouchableHighlight, props, { className: \"style\" });\n};\nTouchableHighlight.displayName = \"CSS(TouchableHighlight)\";\n```\n\n### Image Component (`src/tw/image.tsx`)\n\n```tsx\nimport { useCssElement } from \"react-native-css\";\nimport React from \"react\";\nimport { StyleSheet } from \"react-native\";\nimport Animated from \"react-native-reanimated\";\nimport { Image as RNImage } from \"expo-image\";\n\nconst AnimatedExpoImage = Animated.createAnimatedComponent(RNImage);\n\nexport type ImageProps = React.ComponentProps<typeof Image>;\n\nfunction CSSImage(props: React.ComponentProps<typeof AnimatedExpoImage>) {\n  // @ts-expect-error: Remap objectFit style to contentFit property\n  const { objectFit, objectPosition, ...style } =\n    StyleSheet.flatten(props.style) || {};\n\n  return (\n    <AnimatedExpoImage\n      contentFit={objectFit}\n      contentPosition={objectPosition}\n      {...props}\n      source={\n        typeof props.source === \"string\" ? { uri: props.source } : props.source\n      }\n      // @ts-expect-error: Style is remapped above\n      style={style}\n    />\n  );\n}\n\nexport const Image = (\n  props: React.ComponentProps<typeof CSSImage> & { className?: string }\n) => {\n  return useCssElement(CSSImage, props, { className: \"style\" });\n};\n\nImage.displayName = \"CSS(Image)\";\n```\n\n### Animated Components (`src/tw/animated.tsx`)\n\n```tsx\nimport * as TW from \"./index\";\nimport RNAnimated from \"react-native-reanimated\";\n\nexport const Animated = {\n  ...RNAnimated,\n  View: RNAnimated.createAnimatedComponent(TW.View),\n};\n```\n\n## Usage\n\nImport CSS-wrapped components from your tw directory:\n\n```tsx\nimport { View, Text, ScrollView, Image } from \"@/tw\";\n\nexport default function MyScreen() {\n  return (\n    <ScrollView className=\"flex-1 bg-white\">\n      <View className=\"p-4 gap-4\">\n        <Text className=\"text-xl font-bold text-gray-900\">Hello Tailwind!</Text>\n        <Image\n          className=\"w-full h-48 rounded-lg object-cover\"\n          source={{ uri: \"https://example.com/image.jpg\" }}\n        />\n      </View>\n    </ScrollView>\n  );\n}\n```\n\n## Custom Theme Variables\n\nAdd custom theme variables in your global.css using `@theme`:\n\n```css\n@layer theme {\n  @theme {\n    /* Custom fonts */\n    --font-rounded: \"SF Pro Rounded\", sans-serif;\n\n    /* Custom line heights */\n    --text-xs--line-height: calc(1em / 0.75);\n    --text-sm--line-height: calc(1.25em / 0.875);\n    --text-base--line-height: calc(1.5em / 1);\n\n    /* Custom leading scales */\n    --leading-tight: 1.25em;\n    --leading-snug: 1.375em;\n    --leading-normal: 1.5em;\n  }\n}\n```\n\n## Platform-Specific Styles\n\nUse platform media queries for platform-specific styling:\n\n```css\n@media ios {\n  :root {\n    --font-sans: system-ui;\n    --font-rounded: ui-rounded;\n  }\n}\n\n@media android {\n  :root {\n    --font-sans: normal;\n    --font-rounded: normal;\n  }\n}\n```\n\n## Apple System Colors with CSS Variables\n\nCreate a CSS file for Apple semantic colors:\n\n```css\n/* src/css/sf.css */\n@layer base {\n  html {\n    color-scheme: light;\n  }\n}\n\n:root {\n  /* Accent colors with light/dark mode */\n  --sf-blue: light-dark(rgb(0 122 255), rgb(10 132 255));\n  --sf-green: light-dark(rgb(52 199 89), rgb(48 209 89));\n  --sf-red: light-dark(rgb(255 59 48), rgb(255 69 58));\n\n  /* Gray scales */\n  --sf-gray: light-dark(rgb(142 142 147), rgb(142 142 147));\n  --sf-gray-2: light-dark(rgb(174 174 178), rgb(99 99 102));\n\n  /* Text colors */\n  --sf-text: light-dark(rgb(0 0 0), rgb(255 255 255));\n  --sf-text-2: light-dark(rgb(60 60 67 / 0.6), rgb(235 235 245 / 0.6));\n\n  /* Background colors */\n  --sf-bg: light-dark(rgb(255 255 255), rgb(0 0 0));\n  --sf-bg-2: light-dark(rgb(242 242 247), rgb(28 28 30));\n}\n\n/* iOS native colors via platformColor */\n@media ios {\n  :root {\n    --sf-blue: platformColor(systemBlue);\n    --sf-green: platformColor(systemGreen);\n    --sf-red: platformColor(systemRed);\n    --sf-gray: platformColor(systemGray);\n    --sf-text: platformColor(label);\n    --sf-text-2: platformColor(secondaryLabel);\n    --sf-bg: platformColor(systemBackground);\n    --sf-bg-2: platformColor(secondarySystemBackground);\n  }\n}\n\n/* Register as Tailwind theme colors */\n@layer theme {\n  @theme {\n    --color-sf-blue: var(--sf-blue);\n    --color-sf-green: var(--sf-green);\n    --color-sf-red: var(--sf-red);\n    --color-sf-gray: var(--sf-gray);\n    --color-sf-text: var(--sf-text);\n    --color-sf-text-2: var(--sf-text-2);\n    --color-sf-bg: var(--sf-bg);\n    --color-sf-bg-2: var(--sf-bg-2);\n  }\n}\n```\n\nThen use in components:\n\n```tsx\n<Text className=\"text-sf-text\">Primary text</Text>\n<Text className=\"text-sf-text-2\">Secondary text</Text>\n<View className=\"bg-sf-bg\">...</View>\n```\n\n## Using CSS Variables in JavaScript\n\nUse the `useCSSVariable` hook:\n\n```tsx\nimport { useCSSVariable } from \"@/tw\";\n\nfunction MyComponent() {\n  const blue = useCSSVariable(\"--sf-blue\");\n\n  return <View style={{ borderColor: blue }} />;\n}\n```\n\n## Key Differences from NativeWind v4 / Tailwind v3\n\n1. **No babel.config.js** - Configuration is now CSS-first\n2. **PostCSS plugin** - Uses `@tailwindcss/postcss` instead of `tailwindcss`\n3. **CSS imports** - Use `@import \"tailwindcss/...\"` instead of `@tailwind` directives\n4. **Theme config** - Use `@theme` in CSS instead of `tailwind.config.js`\n5. **Component wrappers** - Must wrap components with `useCssElement` for className support\n6. **Metro config** - Use `withNativewind` with different options (`inlineVariables: false`)\n\n## Troubleshooting\n\n### Styles not applying\n\n1. Ensure you have the CSS file imported in your app entry\n2. Check that components are wrapped with `useCssElement`\n3. Verify Metro config has `withNativewind` applied\n\n### Platform colors not working\n\n1. Use `platformColor()` in `@media ios` blocks\n2. Fall back to `light-dark()` for web/Android\n\n### TypeScript errors\n\nAdd className to component props:\n\n```tsx\ntype Props = React.ComponentProps<typeof RNView> & { className?: string };\n```\n"},"category":"official","lastSynced":"2026-03-06T05:23:38.283Z","seo":{"title":{"en":"expo-tailwind-setup: Universal Styling Setup Guide | AI A...","es":"Configuración de Tailwind CSS para Expo con react-native-css","fr":"Guide d''installation de Tailwind CSS pour Expo avec react...","de":"Einrichtung von Tailwind CSS für Expo mit react-native-cs..."},"description":{"en":"Get started with expo-tailwind-setup and unlock universal styling across iOS, Android, and Web. Learn how to set up Tailwind CSS v4 with react-native-css and...","es":"Aprende a configurar Tailwind CSS v4 en Expo con react-native-css y NativeWind v5 para estilos universales en iOS, Android y Web","fr":"Découvrez comment configurer Tailwind CSS v4 dans Expo avec react-native-css et NativeWind v5 pour des styles universels","de":"Erfahren Sie, wie Sie Tailwind CSS v4 in Expo mit react-native-css und NativeWind v5 für universelle Stile einrichten"},"definition":{"en":"expo-tailwind-setup is a configuration setup for using Tailwind CSS v4 with react-native-css and NativeWind v5 in Expo projects for consistent styling across multiple platforms.","es":"expo-tailwind-setup es una configuración de Tailwind CSS v4 para Expo con react-native-css y NativeWind v5","fr":"expo-tailwind-setup est une configuration de Tailwind CSS v4 pour Expo avec react-native-css et NativeWind v5","de":"expo-tailwind-setup ist eine Einrichtung von Tailwind CSS v4 für Expo mit react-native-css und NativeWind v5"},"features":{"en":["Uses Tailwind CSS v4 for modern CSS-first configuration","Integrates react-native-css for CSS runtime in React Native","Utilizes NativeWind v5 as a Metro transformer for Tailwind in React Native","Employs @tailwindcss/postcss for PostCSS plugin functionality","Enables universal styling across iOS, Android, and Web platforms"],"es":["Soporte para Tailwind CSS v4","Integración con react-native-css","Uso de NativeWind v5 para estilos universales","Compatibilidad con iOS, Android y Web"],"fr":["Prise en charge de Tailwind CSS v4","Intégration avec react-native-css","Utilisation de NativeWind v5 pour des styles universels","Compatibilité avec iOS, Android et Web"],"de":["Unterstützung für Tailwind CSS v4","Integration mit react-native-css","Verwendung von NativeWind v5 für universelle Stile","Kompatibilität mit iOS, Android und Web"]},"keywords":{"en":["how to use expo-tailwind-setup","expo-tailwind-setup setup guide","Tailwind CSS v4 configuration","react-native-css integration","NativeWind v5 alternative","expo-tailwind-setup vs styled-components","install expo-tailwind-setup","expo-tailwind-setup tutorial","universal styling with expo-tailwind-setup"],"es":["expo-tailwind-setup","Tailwind CSS v4","react-native-css","NativeWind v5","estilos universales","configuración de Tailwind CSS","desarrollo de aplicaciones móviles","Herramientas de desarrollo de AI"],"fr":["expo-tailwind-setup","Tailwind CSS v4","react-native-css","NativeWind v5","styles universels","configuration de Tailwind CSS","développement d''applications mobiles","Outils de développement d''IA"],"de":["expo-tailwind-setup","Tailwind CSS v4","react-native-css","NativeWind v5","universelle Stile","Einrichtung von Tailwind CSS","Entwicklung von mobilen Anwendungen","AI-Entwicklungstools"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing universal styling across iOS, Android, and Web with Tailwind CSS v4 and React Native","zh":"适合需要在iOS、Android和Web上实现通用样式的前端代理，支持Tailwind CSS v4和React Native","ja":"iOS、Android、Web上でユニバーサルなスタイリングが必要なフロントエンドエージェントに適しています。Tailwind CSS v4とReact Nativeをサポートしています","ko":"iOS, Android, Web에서 유니버설 스타일링이 필요한 프론트엔드 에이전트에게 적합합니다. Tailwind CSS v4 및 React Native를 지원합니다","es":"Perfecto para Agentes Frontend que necesitan estilos universales en iOS, Android y Web con Tailwind CSS v4 y React Native","fr":"Parfait pour les agents Frontend ayant besoin d''un style universel sur iOS, Android et Web avec Tailwind CSS v4 et React Native","de":"Perfekt für Frontend-Agents, die universelle Stile über iOS, Android und Web mit Tailwind CSS v4 und React Native benötigen","pt":"Perfeito para Agentes Frontend que necessitam de estilização universal em iOS, Android e Web com Tailwind CSS v4 e React Native","ru":"Идеально подходит для агентов Frontend, требующих универсальной стилизации на iOS, Android и Web с Tailwind CSS v4 и React Native","ar":"مثالي لويب فرنت اند الذين يحتاجون إلى تنسيق عالمي عبر أجهزة iOS و Android والويب مع Tailwind CSS v4 و React Native"},"recommendation":{"en":"Empowers agents to utilize Tailwind CSS v4 with react-native-css and NativeWind v5 for seamless styling, leveraging @tailwindcss/postcss for enhanced CSS configuration and Metro transformer capabilities","zh":"赋予代理利用Tailwind CSS v4与react-native-css和NativeWind v5实现无缝样式，利用@tailwindcss/postcss增强CSS配置和Metro转换器功能","ja":"エージェントがTailwind CSS v4とreact-native-css、NativeWind v5を利用してシームレスなスタイリングを行えるようにし、@tailwindcss/postcssを利用してCSS構成とMetroトランスフォーマーの機能を強化します","ko":"에이전트가 Tailwind CSS v4와 react-native-css, NativeWind v5를 활용하여無縫 스타일링을 수행할 수 있도록 하며, @tailwindcss/postcss를 사용하여 CSS 구성과 Metro 트랜스포ーマ 기능을 강화합니다","es":"Habilita a los agentes a utilizar Tailwind CSS v4 con react-native-css y NativeWind v5 para un estilo sin problemas, aprovechando @tailwindcss/postcss para una configuración de CSS mejorada y capacidades de transformador de Metro","fr":"Permet aux agents d''utiliser Tailwind CSS v4 avec react-native-css et NativeWind v5 pour un style sans accroc, en exploitant @tailwindcss/postcss pour une configuration CSS améliorée et des capacités de transformateur de Metro","de":"Ermächtigt Agenten, Tailwind CSS v4 mit react-native-css und NativeWind v5 für ein nahtloses Styling zu nutzen, das @tailwindcss/postcss für eine verbesserte CSS-Konfiguration und Metro-Transformer-Fähigkeiten nutzt","pt":"Habilita os agentes a utilizarem Tailwind CSS v4 com react-native-css e NativeWind v5 para estilização sem problemas, aproveitando @tailwindcss/postcss para configuração avançada de CSS e capacidades de transformação do Metro","ru":"Предоставляет агентам возможность использовать Tailwind CSS v4 с react-native-css и NativeWind v5 для бесшовной стилизации, используя @tailwindcss/postcss для расширенной конфигурации CSS и возможностей трансформации Metro","ar":"تمكين الوكلاء من استخدام Tailwind CSS v4 مع react-native-css و NativeWind v5 لتنسيق ملاحة بدون مشاكل، واستخدام @tailwindcss/postcss لتهيئة CSS المتقدمة وقدرات التحويل المترو"},"useCases":{"en":["Configuring universal styling for cross-platform apps","Integrating Tailwind CSS v4 with React Native projects","Utilizing NativeWind v5 for Metro transformations"],"zh":["配置跨平台应用的通用样式","将Tailwind CSS v4集成到React Native项目中","利用NativeWind v5进行Metro转换"],"ja":["クロスプラットフォームアプリのユニバーサルスタイリングを構成する","React NativeプロジェクトにTailwind CSS v4を統合する","NativeWind v5を使用してMetro変換を行う"],"ko":["크로스 플랫폼 애플리케이션의 유니버설 스타일링을 구성하는 것","React Native 프로젝트에 Tailwind CSS v4를 통합하는 것","NativeWind v5를 사용하여 Metro 변환을 수행하는 것"],"es":["Configuración de estilos universales para aplicaciones de varias plataformas","Integración de Tailwind CSS v4 con proyectos de React Native","Uso de NativeWind v5 para transformaciones de Metro"],"fr":["Configuration de styles universels pour des applications multi-plateformes","Intégration de Tailwind CSS v4 avec des projets React Native","Utilisation de NativeWind v5 pour des transformations de Metro"],"de":["Konfiguration universeller Stile für Cross-Platform-Anwendungen","Integration von Tailwind CSS v4 in React Native-Projekte","Verwendung von NativeWind v5 für Metro-Transformationen"],"pt":["Configurando estilização universal para aplicativos cross-plataforma","Integrando Tailwind CSS v4 com projetos React Native","Utilizando NativeWind v5 para transformações do Metro"],"ru":["Настройка универсальной стилизации для кроссплатформенных приложений","Интеграция Tailwind CSS v4 с проектами React Native","Использование NativeWind v5 для трансформаций Metro"],"ar":["تكوين التنسيق العالمي للتطبيقات متعددة المنصات","دمج Tailwind CSS v4 مع مشاريع React Native","استخدام NativeWind v5 لتحويلات المترو"]},"limitations":{"en":["Requires Expo environment","React Native compatibility needed","Tailwind CSS v4 and NativeWind v5 specific versions required"],"zh":["需要Expo环境","需要React Native兼容性","需要Tailwind CSS v4和NativeWind v5的特定版本"],"ja":["Expo環境が必要","React Nativeの互換性が必要","Tailwind CSS v4とNativeWind v5の特定のバージョンが必要"],"ko":["Expo 환경이 필요합니다","React Native 호환성이 필요합니다","Tailwind CSS v4 및 NativeWind v5의 특정 버전이 필요합니다"],"es":["Requiere entorno Expo","Se requiere compatibilidad con React Native","Se requieren versiones específicas de Tailwind CSS v4 y NativeWind v5"],"fr":["Nécessite un environnement Expo","La compatibilité avec React Native est requise","Des versions spécifiques de Tailwind CSS v4 et NativeWind v5 sont requises"],"de":["Benötigt Expo-Umgebung","React Native-Kompatibilität erforderlich","Spezifische Versionen von Tailwind CSS v4 und NativeWind v5 erforderlich"],"pt":["Requer ambiente Expo","Compatibilidade com React Native necessária","Versões específicas do Tailwind CSS v4 e NativeWind v5 necessárias"],"ru":["Требуется среда Expo","Необходима совместимость с React Native","Требуются конкретные версии Tailwind CSS v4 и NativeWind v5"],"ar":["يتطلب بيئة Expo","تحتاج إلى توافق مع React Native","يتطلب إصدارات محددة من Tailwind CSS v4 و NativeWind v5"]},"version":4},"contentHash":"6abfc223a376571e0ee84014b3b474a3f2828ac2ebcde59c5c2b6b4bc802e233","repoEtag":"W/\"3d0b500324a01c512d7df52a068a135b350d8e49d3ce113161c97e6acbc0dfba\"","qualityScore":97}');
