INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/expo-tailwind-setup', 'expo-tailwind-setup', 'expo', 'skills', 'official', 'expo-tailwind-setup expo skills official The expo-tailwind-setup skill sets up Tailwind CSS v4 in Expo using react-native-css and NativeWind v5 for universal styling. This skill benefits developers working on cross-platform React Native projects. Configuración de Tailwind CSS v4 en Expo con react-native-css y NativeWind v5 para estilos universales Configuration de Tailwind CSS v4 dans Expo avec react-native-css et NativeWind v5 pour des styles universels Einrichtung von Tailwind CSS v4 in Expo mit react-native-css und NativeWind v5 für universelle Stile how to use expo-tailwind-setup expo-tailwind-setup setup guide Tailwind CSS v4 configuration react-native-css integration NativeWind v5 alternative expo-tailwind-setup vs styled-components install expo-tailwind-setup expo-tailwind-setup tutorial universal styling with expo-tailwind-setup Uses Tailwind CSS v4 for modern CSS-first configuration Integrates react-native-css for CSS runtime in React Native Utilizes NativeWind v5 as a Metro transformer for Tailwind in React Native Employs @tailwindcss/postcss for PostCSS plugin functionality Enables universal styling across iOS, Android, and Web platforms expo-tailwind-setup is a configuration setup for using Tailwind CSS v4 with react-native-css and NativeWind v5 in Expo projects for consistent styling across multiple platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/use-dom', 'official', 'expo', 'skills', 'expo/skills', 'use-dom', 1349, 59, 97, '2026-03-06T04:04:30Z', '2026-03-06T05:27:34.933Z', '7041bb26db02e24c45eb6c4c4879138a0f52786dd928eefd66c90a35b0e3197d', '{"id":"expo/skills/use-dom","name":"use-dom","description":{"en":"The use-dom skill enables developers to run web code in a webview on native platforms and as-is on web using Expo DOM components. This benefits developers who need to use web-only libraries like recharts or react-syntax-highlighter in their Expo apps.","zh":"use-dom技能允许使用Expo DOM组件在native和web平台上运行web代码，实现web-only库的使用和迁移","ja":"use-domスキルは、Expo DOMコンポーネントをネイティブとウェブプラットフォーム上で動作させ、web-onlyライブラリを使用して移行できるようにします","ko":"use-dom 스킬은 Expo DOM 컴포넌트를 네이티브와 웹 플랫폼에서 실행하여 웹 전용 라이브러리를 사용하고 무缝으로迁移할 수 있습니다","es":"Use-dom permite ejecutar código web en aplicaciones nativas y web utilizando componentes DOM de Expo. Migra tu código web a nativo de manera incremental.","fr":"Use-dom permet d''exécuter du code web dans des applications natives et web en utilisant les composants DOM d''Expo. Migrez votre code web vers natif de manière incrémentale.","de":"Use-dom ermöglicht die Ausführung von Webcode in nativen und Webanwendungen mithilfe von DOM-Komponenten von Expo. Migrieren Sie Ihren Webcode schrittweise zu nativ.","pt":"O use-dom permite executar código web em uma webview em plataformas nativas e na web, sem modificação. É ideal para bibliotecas web-only como recharts e react-syntax-highlighter.","ru":"Use-dom позволяет запускать веб-код в веб-представлении на родных платформах и в вебе без изменений. Он идеален для веб-библиотек, таких как recharts и react-syntax-highlighter.","ar":"يسمح use-dom بتشغيل رمز الويب في عرض الويب على منصات الأصلية وعلى الويب بدون تعديل. إنه مثالي لbibliotecas الويب فقط مثل recharts و react-syntax-highlighter."},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"use-dom","description":"Use Expo DOM components to run web code in a webview on native and as-is on web. Migrate web code to native incrementally.","version":"1.0.0","bodyPreview":"## What are DOM Components?\n\nDOM components allow web code to run verbatim in a webview on native platforms while rendering as-is on web. This enables using web-only libraries like `recharts`, `react-syntax-highlighter`, or any React web library in your Expo app without modification.\n\n## When to Use DOM Components\n\nUse DOM components when you need:\n\n- **Web-only libraries** — Charts (recharts, chart.js), syntax highlighters, rich text editors, or any library that depends on DOM APIs\n- **Migratin","body":"## What are DOM Components?\n\nDOM components allow web code to run verbatim in a webview on native platforms while rendering as-is on web. This enables using web-only libraries like `recharts`, `react-syntax-highlighter`, or any React web library in your Expo app without modification.\n\n## When to Use DOM Components\n\nUse DOM components when you need:\n\n- **Web-only libraries** — Charts (recharts, chart.js), syntax highlighters, rich text editors, or any library that depends on DOM APIs\n- **Migrating web code** — Bring existing React web components to native without rewriting\n- **Complex HTML/CSS layouts** — When CSS features aren''t available in React Native\n- **iframes or embeds** — Embedding external content that requires a browser context\n- **Canvas or WebGL** — Web graphics APIs not available natively\n\n## When NOT to Use DOM Components\n\nAvoid DOM components when:\n\n- **Native performance is critical** — Webviews add overhead\n- **Simple UI** — React Native components are more efficient for basic layouts\n- **Deep native integration** — Use local modules instead for native APIs\n- **Layout routes** — `_layout` files cannot be DOM components\n\n## Basic DOM Component\n\nCreate a new file with the `''use dom'';` directive at the top:\n\n```tsx\n// components/WebChart.tsx\n\"use dom\";\n\nexport default function WebChart({\n  data,\n}: {\n  data: number[];\n  dom: import(\"expo/dom\").DOMProps;\n}) {\n  return (\n    <div style={{ padding: 20 }}>\n      <h2>Chart Data</h2>\n      <ul>\n        {data.map((value, i) => (\n          <li key={i}>{value}</li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n```\n\n## Rules for DOM Components\n\n1. **Must have `''use dom'';` directive** at the top of the file\n2. **Single default export** — One React component per file\n3. **Own file** — Cannot be defined inline or combined with native components\n4. **Serializable props only** — Strings, numbers, booleans, arrays, plain objects\n5. **Include CSS in the component file** — DOM components run in isolated context\n\n## The `dom` Prop\n\nEvery DOM component receives a special `dom` prop for webview configuration. Always type it in your props:\n\n```tsx\n\"use dom\";\n\ninterface Props {\n  content: string;\n  dom: import(\"expo/dom\").DOMProps;\n}\n\nexport default function MyComponent({ content }: Props) {\n  return <div>{content}</div>;\n}\n```\n\n### Common `dom` Prop Options\n\n```tsx\n// Disable body scrolling\n<DOMComponent dom={{ scrollEnabled: false }} />\n\n// Flow under the notch (disable safe area insets)\n<DOMComponent dom={{ contentInsetAdjustmentBehavior: \"never\" }} />\n\n// Control size manually\n<DOMComponent dom={{ style: { width: 300, height: 400 } }} />\n\n// Combine options\n<DOMComponent\n  dom={{\n    scrollEnabled: false,\n    contentInsetAdjustmentBehavior: \"never\",\n    style: { width: ''100%'', height: 500 }\n  }}\n/>\n```\n\n## Exposing Native Actions to the Webview\n\nPass async functions as props to expose native functionality to the DOM component:\n\n```tsx\n// app/index.tsx (native)\nimport { Alert } from \"react-native\";\nimport DOMComponent from \"@/components/dom-component\";\n\nexport default function Screen() {\n  return (\n    <DOMComponent\n      showAlert={async (message: string) => {\n        Alert.alert(\"From Web\", message);\n      }}\n      saveData={async (data: { name: string; value: number }) => {\n        // Save to native storage, database, etc.\n        console.log(\"Saving:\", data);\n        return { success: true };\n      }}\n    />\n  );\n}\n```\n\n```tsx\n// components/dom-component.tsx\n\"use dom\";\n\ninterface Props {\n  showAlert: (message: string) => Promise<void>;\n  saveData: (data: {\n    name: string;\n    value: number;\n  }) => Promise<{ success: boolean }>;\n  dom?: import(\"expo/dom\").DOMProps;\n}\n\nexport default function DOMComponent({ showAlert, saveData }: Props) {\n  const handleClick = async () => {\n    await showAlert(\"Hello from the webview!\");\n    const result = await saveData({ name: \"test\", value: 42 });\n    console.log(\"Save result:\", result);\n  };\n\n  return <button onClick={handleClick}>Trigger Native Action</button>;\n}\n```\n\n## Using Web Libraries\n\nDOM components can use any web library:\n\n```tsx\n// components/syntax-highlight.tsx\n\"use dom\";\n\nimport SyntaxHighlighter from \"react-syntax-highlighter\";\nimport { docco } from \"react-syntax-highlighter/dist/esm/styles/hljs\";\n\ninterface Props {\n  code: string;\n  language: string;\n  dom?: import(\"expo/dom\").DOMProps;\n}\n\nexport default function SyntaxHighlight({ code, language }: Props) {\n  return (\n    <SyntaxHighlighter language={language} style={docco}>\n      {code}\n    </SyntaxHighlighter>\n  );\n}\n```\n\n```tsx\n// components/chart.tsx\n\"use dom\";\n\nimport {\n  LineChart,\n  Line,\n  XAxis,\n  YAxis,\n  CartesianGrid,\n  Tooltip,\n} from \"recharts\";\n\ninterface Props {\n  data: Array<{ name: string; value: number }>;\n  dom: import(\"expo/dom\").DOMProps;\n}\n\nexport default function Chart({ data }: Props) {\n  return (\n    <LineChart width={400} height={300} data={data}>\n      <CartesianGrid strokeDasharray=\"3 3\" />\n      <XAxis dataKey=\"name\" />\n      <YAxis />\n      <Tooltip />\n      <Line type=\"monotone\" dataKey=\"value\" stroke=\"#8884d8\" />\n    </LineChart>\n  );\n}\n```\n\n## CSS in DOM Components\n\nCSS imports must be in the DOM component file since they run in isolated context:\n\n```tsx\n// components/styled-component.tsx\n\"use dom\";\n\nimport \"@/styles.css\"; // CSS file in same directory\n\nexport default function StyledComponent({\n  dom,\n}: {\n  dom: import(\"expo/dom\").DOMProps;\n}) {\n  return (\n    <div className=\"container\">\n      <h1 className=\"title\">Styled Content</h1>\n    </div>\n  );\n}\n```\n\nOr use inline styles / CSS-in-JS:\n\n```tsx\n\"use dom\";\n\nconst styles = {\n  container: {\n    padding: 20,\n    backgroundColor: \"#f0f0f0\",\n  },\n  title: {\n    fontSize: 24,\n    color: \"#333\",\n  },\n};\n\nexport default function StyledComponent({\n  dom,\n}: {\n  dom: import(\"expo/dom\").DOMProps;\n}) {\n  return (\n    <div style={styles.container}>\n      <h1 style={styles.title}>Styled Content</h1>\n    </div>\n  );\n}\n```\n\n## Expo Router in DOM Components\n\nThe expo-router `<Link />` component and router API work inside DOM components:\n\n```tsx\n\"use dom\";\n\nimport { Link, useRouter } from \"expo-router\";\n\nexport default function Navigation({\n  dom,\n}: {\n  dom: import(\"expo/dom\").DOMProps;\n}) {\n  const router = useRouter();\n\n  return (\n    <nav>\n      <Link href=\"/about\">About</Link>\n      <button onClick={() => router.push(\"/settings\")}>Settings</button>\n    </nav>\n  );\n}\n```\n\n### Router APIs That Require Props\n\nThese hooks don''t work directly in DOM components because they need synchronous access to native routing state:\n\n- `useLocalSearchParams()`\n- `useGlobalSearchParams()`\n- `usePathname()`\n- `useSegments()`\n- `useRootNavigation()`\n- `useRootNavigationState()`\n\n**Solution:** Read these values in the native parent and pass as props:\n\n```tsx\n// app/[id].tsx (native)\nimport { useLocalSearchParams, usePathname } from \"expo-router\";\nimport DOMComponent from \"@/components/dom-component\";\n\nexport default function Screen() {\n  const { id } = useLocalSearchParams();\n  const pathname = usePathname();\n\n  return <DOMComponent id={id as string} pathname={pathname} />;\n}\n```\n\n```tsx\n// components/dom-component.tsx\n\"use dom\";\n\ninterface Props {\n  id: string;\n  pathname: string;\n  dom?: import(\"expo/dom\").DOMProps;\n}\n\nexport default function DOMComponent({ id, pathname }: Props) {\n  return (\n    <div>\n      <p>Current ID: {id}</p>\n      <p>Current Path: {pathname}</p>\n    </div>\n  );\n}\n```\n\n## Detecting DOM Environment\n\nCheck if code is running in a DOM component:\n\n```tsx\n\"use dom\";\n\nimport { IS_DOM } from \"expo/dom\";\n\nexport default function Component({\n  dom,\n}: {\n  dom?: import(\"expo/dom\").DOMProps;\n}) {\n  return <div>{IS_DOM ? \"Running in DOM component\" : \"Running natively\"}</div>;\n}\n```\n\n## Assets\n\nPrefer requiring assets instead of using the public directory:\n\n```tsx\n\"use dom\";\n\n// Good - bundled with the component\nconst logo = require(\"../assets/logo.png\");\n\nexport default function Component({\n  dom,\n}: {\n  dom: import(\"expo/dom\").DOMProps;\n}) {\n  return <img src={logo} alt=\"Logo\" />;\n}\n```\n\n## Usage from Native Components\n\nImport and use DOM components like regular components:\n\n```tsx\n// app/index.tsx\nimport { View, Text } from \"react-native\";\nimport WebChart from \"@/components/web-chart\";\nimport CodeBlock from \"@/components/code-block\";\n\nexport default function HomeScreen() {\n  return (\n    <View style={{ flex: 1 }}>\n      <Text>Native content above</Text>\n\n      <WebChart data={[10, 20, 30, 40, 50]} dom={{ style: { height: 300 } }} />\n\n      <CodeBlock\n        code=\"const x = 1;\"\n        language=\"javascript\"\n        dom={{ scrollEnabled: true }}\n      />\n\n      <Text>Native content below</Text>\n    </View>\n  );\n}\n```\n\n## Platform Behavior\n\n| Platform | Behavior                            |\n| -------- | ----------------------------------- |\n| iOS      | Rendered in WKWebView               |\n| Android  | Rendered in WebView                 |\n| Web      | Rendered as-is (no webview wrapper) |\n\nOn web, the `dom` prop is ignored since no webview is needed.\n\n## Tips\n\n- DOM components hot reload during development\n- Keep DOM components focused — don''t put entire screens in webviews\n- Use native components for navigation chrome, DOM components for specialized content\n- Test on all platforms — web rendering may differ slightly from native webviews\n- Large DOM components may impact performance — profile if needed\n- The webview has its own JavaScript context — cannot directly share state with native\n"},"category":"official","lastSynced":"2026-03-06T05:27:34.933Z","seo":{"title":{"en":"use-dom: Expo DOM Component Setup Guide | AI Agent Skill","zh":"使用use-dom技能： Expo DOM组件在native和web平台的应用指南","ja":"use-domスキルを使用する： Expo DOMコンポーネントのネイティブとウェブプラットフォームへの適用ガイド","ko":"use-dom 스킬 사용 가이드: Expo DOM 컴포넌트를 네이티브와 웹 플랫폼에서 사용하는 방법","es":"Guía de configuración de use-dom para Expo","fr":"Mise en route de use-dom pour les applications Expo","de":"Einrichtungsleitfaden für use-dom in Expo-Anwendungen","pt":"Guia de Configuração do use-dom para Expo","ru":"Настройка use-dom для Expo: Лучшие Практики","ar":"دليل إعداد use-dom ل_Expo"},"description":{"en":"Discover how to use Expo DOM components to run web code in a webview on native and web platforms. Learn how to migrate web code to native incrementally today!","zh":"使用use-dom技能，让Expo DOM组件在native和web平台上运行web代码，实现无缝迁移","ja":"use-domスキルを使用して、Expo DOMコンポーネントをネイティブとウェブプラットフォーム上で動作させ、シームレスに移行します","ko":"use-dom 스킬을 사용하여 Expo DOM 컴포넌트를 네이티브와 웹 플랫폼에서 실행하고 웹 코드를 무缝으로迁移합니다","es":"Aprende a utilizar componentes DOM de Expo para ejecutar código web en aplicaciones nativas y web con use-dom","fr":"Découvrez comment utiliser les composants DOM d''Expo pour exécuter du code web dans des applications natives et web avec use-dom","de":"Erfahren Sie, wie Sie mit use-dom DOM-Komponenten von Expo verwenden, um Webcode in nativen und Webanwendungen auszuführen","pt":"Aprenda a usar o use-dom para executar código web em uma webview em plataformas nativas e na web, com a ajuda de Ferramentas de IA","ru":"Используйте use-dom для запуска веб-кода в веб-представлении на родных платформах и в вебе с помощью ИИ Агентов","ar":"تعلم كيفية استخدام use-dom لتشغيل رمز الويب في عرض الويب على منصات الأصلية وعلى الويب باستخدام أدوات الإنسان الآلي"},"definition":{"en":"use-dom is a skill that allows web code to run verbatim in a webview on native platforms while rendering as-is on web, enabling the use of web-only libraries in Expo apps","zh":"use-dom技能是一种技术，允许Expo DOM组件在native和web平台上运行web代码","ja":"use-domスキルは、Expo DOMコンポーネントをネイティブとウェブプラットフォーム上で動作させる技術です","ko":"use-dom 스킬은 Expo DOM 컴포넌트를 네이티브와 웹 플랫폼에서 실행하는 기술입니다","es":"Use-dom es una habilidad que permite utilizar componentes DOM de Expo para ejecutar código web en aplicaciones nativas y web","fr":"Use-dom est une compétence qui permet d''utiliser les composants DOM d''Expo pour exécuter du code web dans des applications natives et web","de":"Use-dom ist eine Fähigkeit, die die Verwendung von DOM-Komponenten von Expo zur Ausführung von Webcode in nativen und Webanwendungen ermöglicht","pt":"O use-dom é uma funcionalidade que permite executar código web em uma webview em plataformas nativas e na web.","ru":"Use-dom — это функция, которая позволяет запускать веб-код в веб-представлении на родных платформах и в вебе.","ar":"use-dom هو ميزة تسمح بتشغيل رمز الويب في عرض الويب على منصات الأصلية وعلى الويب."},"features":{"en":["Runs web code in a webview on native platforms using Expo DOM components","Renders web code as-is on web platforms","Supports the use of web-only libraries like recharts and react-syntax-highlighter","Enables incremental migration of web code to native platforms","Allows the use of React web libraries in Expo apps without modification"],"zh":["使用Expo DOM组件在native和web平台上运行web代码","支持web-only库，如recharts和react-syntax-highlighter","实现web代码在native和web平台上的无缝迁移","允许使用React web库在Expo应用中","支持charts、syntax highlighters和rich text editors等库"],"ja":["Expo DOMコンポーネントをネイティブとウェブプラットフォーム上で動作させる","web-onlyライブラリ（recharts、react-syntax-highlighterなど）をサポート","webコードをネイティブとウェブプラットフォーム上でシームレスに移行","React webライブラリをExpoアプリで使用","charts、syntax highlighters、rich text editorsなどのライブラリをサポート"],"ko":["Expo DOM 컴포넌트를 네이티브와 웹 플랫폼에서 실행","웹 전용 라이브러리(recharts, react-syntax-highlighter 등) 지원","웹 코드를 네이티브와 웹 플랫폼에서 무증으로迁移","React 웹 라이브러리를 Expo 애플리케이션에서 사용","차트, 구문 하이라이터, 리치 텍스트 에디터 등의 라이브러리 지원"],"es":["Ejecución de código web en aplicaciones nativas y web","Compatibilidad con bibliotecas web como recharts y react-syntax-highlighter","Migración incremental de código web a nativo","Uso de componentes DOM de Expo","Compatibilidad con React y otras bibliotecas web"],"fr":["Exécution de code web dans des applications natives et web","Compatibilité avec des bibliothèques web comme recharts et react-syntax-highlighter","Migration incrémentale de code web vers natif","Utilisation de composants DOM d''Expo","Compatibilité avec React et d''autres bibliothèques web"],"de":["Ausführung von Webcode in nativen und Webanwendungen","Kompatibilität mit Webbibliotheken wie recharts und react-syntax-highlighter","Inkrementale Migration von Webcode zu nativ","Verwendung von DOM-Komponenten von Expo","Kompatibilität mit React und anderen Webbibliotheken"],"pt":["Executa código web em uma webview em plataformas nativas","Renderiza código web como-is na web","Suporta bibliotecas web-only como recharts e react-syntax-highlighter","Permite migração incremental de código web para nativo","Funciona com React e outras bibliotecas JavaScript"],"ru":["Запускает веб-код в веб-представлении на родных платформах","Отображает веб-код как-is в вебе","Подде