INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/api-design', 'api-design', 'affaan-m', 'everything-claude-code', 'official', 'api-design affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The api-design skill provides conventions and best practices for designing consistent, developer-friendly REST APIs, covering resource naming, status codes, and error handling. El diseño de API REST implica patrones de diseño y convenciones para APIs de producción, incluyendo nombres de recursos y códigos de estado La conception d''API REST implique des modèles de conception et des conventions pour les API de production, y compris les noms de ressources et les codes d''état Das Design von REST-APIs umfasst Designmuster und -konventionen für Produktions-APIs, einschließlich Ressourcennamen und Statuscodes Desenvolva APIs REST consistentes e amigáveis para desenvolvedores com recursos como nomeação de recursos, códigos de status, paginação e tratamento de erros Разрабатывайте последовательные и удобные для разработчиков REST API с ресурсами, такими как наименование ресурсов, коды состояния, постраничная навигация и обработка ошибок для ИИ Агентов طور واجهات برمجة التطبيقات REST المتسقة والصديقة للمطورين باستخدام الموارد مثل تسمية الموارد ورموز الحالة وتنقّل الصفحات ومعالجة الأخطاء how to design a REST API api-design best practices REST API versioning strategies api-design vs RESTful API api-design setup guide api-design tutorial for developers what is api-design api-design alternative api-design install Implements resource naming conventions using plural, lowercase, kebab-case URLs Supports pagination, filtering, and sorting for efficient data retrieval Handles error responses using standard HTTP status codes Enables API versioning strategy for backward compatibility Implements rate limiting for preventing abuse and ensuring scalability Designs URL structures using nouns, plural, lowercase, kebab-case for consistency api-design is a set of guidelines and patterns for creating consistent and maintainable REST APIs, including resource naming, URL structure, and versioning strategies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/algorithmic-art', 'official', 'anthropics', 'skills', 'anthropics/skills', 'algorithmic-art', 85097, 8974, 95, '2026-03-06T03:11:21Z', '2026-03-06T03:12:28.929Z', '3bc4092c09804853186524c826bc0621b940bb6122c05b84496dff95388e6eef', '{"id":"anthropics/skills/algorithmic-art","name":"algorithmic-art","description":{"en":"The algorithmic-art AI skill creates original generative art using p5.js. It produces an algorithmic philosophy (.md), an interactive HTML viewer, and the corresponding JavaScript code, enabling developers to explore seeded randomness and parameterized art systems.","zh":"algorithmic-art AI代理技能通过p5.js创建原创算法艺术，采用种子随机性和交互参数探索。它生成算法哲学文档(.md)、交互查看器(.html)和生成算法(.js)，避免版权侵权。","ja":"algorithmic-art AIエージェントスキルは、p5.jsを使用したオリジナルのアルゴリズムアートを創作し、シードランダム性とインタラクティブなパラメータ探索を採用。アルゴリズム哲学ドキュメント(.md)、インタラクティブビューア(.html)、生成アルゴリズム(.js)を出力し、著作権侵害を回避。","ko":"algorithmic-art AI 에이전트 스킬은 p5.js를 사용한 오리지널 알고리즘 아트를 생성하며, 시드 랜덤성과 인터랙티브 매개변수 탐색을 채택. 알고리즘 철학 문서(.md), 인터랙티브 뷰어(.html), 생성 알고리즘(.js)을 출력하여 저작권 침해를 회피.","es":"Esta habilidad de agente de IA genera arte algorítmico original utilizando p5.js, incorporando semillas aleatorias para reproducibilidad y permitiendo la exploración interactiva de parámetros. Produce filosofías computacionales en .md y su implementación en .html/.js.","fr":"Cette compétence d''agent IA génère de l''art algorithmique original en utilisant p5.js, incorporant l''aléatoire ensemencé pour la reproductibilité et permettant l''exploration interactive des paramètres. Produit des philosophies computationnelles en .md et leur implémentation en .html/.js.","de":"Diese KI-Agenten-Fähigkeit erzeugt originelle algorithmische Kunst mit p5.js, verwendet seeded Randomness für Reproduzierbarkeit und ermöglicht die interaktive Erkundung von Parametern. Erstellt computationale Philosophien in .md und deren Implementierung in .html/.js.","pt":"A arte algorítmica é criada usando p5.js com aleatoriedade inicializada e exploração interativa de parâmetros","ru":"Алгоритмическое искусство создается с помощью p5.js и ИИ Агентов, используя зернистую случайность и интерактивное исследование параметров","ar":"الفن الخوارزمي يتم إنشاؤه باستخدام p5.js مع عشوائية مبذرة واستكشاف معاملات تفاعلية"},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"algorithmic-art","description":"Creating algorithmic art using p5.js with seeded randomness and interactive parameter exploration. Use this when users request creating art using code, generative art, algorithmic art, flow fields, or particle systems. Create original algorithmic art rather than copying existing artists work to avoid copyright violations.","bodyPreview":"Algorithmic philosophies are computational aesthetic movements that are then expressed through code. Output .md files (philosophy), .html files (interactive viewer), and .js files (generative algorithms).\n\nThis happens in two steps:\n1. Algorithmic Philosophy Creation (.md file)\n2. Express by creating p5.js generative art (.html + .js files)\n\nFirst, undertake this task:\n\n## ALGORITHMIC PHILOSOPHY CREATION\n\nTo begin, create an ALGORITHMIC PHILOSOPHY (not static images or templates) that will be in","body":"Algorithmic philosophies are computational aesthetic movements that are then expressed through code. Output .md files (philosophy), .html files (interactive viewer), and .js files (generative algorithms).\n\nThis happens in two steps:\n1. Algorithmic Philosophy Creation (.md file)\n2. Express by creating p5.js generative art (.html + .js files)\n\nFirst, undertake this task:\n\n## ALGORITHMIC PHILOSOPHY CREATION\n\nTo begin, create an ALGORITHMIC PHILOSOPHY (not static images or templates) that will be interpreted through:\n- Computational processes, emergent behavior, mathematical beauty\n- Seeded randomness, noise fields, organic systems\n- Particles, flows, fields, forces\n- Parametric variation and controlled chaos\n\n### THE CRITICAL UNDERSTANDING\n- What is received: Some subtle input or instructions by the user to take into account, but use as a foundation; it should not constrain creative freedom.\n- What is created: An algorithmic philosophy/generative aesthetic movement.\n- What happens next: The same version receives the philosophy and EXPRESSES IT IN CODE - creating p5.js sketches that are 90% algorithmic generation, 10% essential parameters.\n\nConsider this approach:\n- Write a manifesto for a generative art movement\n- The next phase involves writing the algorithm that brings it to life\n\nThe philosophy must emphasize: Algorithmic expression. Emergent behavior. Computational beauty. Seeded variation.\n\n### HOW TO GENERATE AN ALGORITHMIC PHILOSOPHY\n\n**Name the movement** (1-2 words): \"Organic Turbulence\" / \"Quantum Harmonics\" / \"Emergent Stillness\"\n\n**Articulate the philosophy** (4-6 paragraphs - concise but complete):\n\nTo capture the ALGORITHMIC essence, express how this philosophy manifests through:\n- Computational processes and mathematical relationships?\n- Noise functions and randomness patterns?\n- Particle behaviors and field dynamics?\n- Temporal evolution and system states?\n- Parametric variation and emergent complexity?\n\n**CRITICAL GUIDELINES:**\n- **Avoid redundancy**: Each algorithmic aspect should be mentioned once. Avoid repeating concepts about noise theory, particle dynamics, or mathematical principles unless adding new depth.\n- **Emphasize craftsmanship REPEATEDLY**: The philosophy MUST stress multiple times that the final algorithm should appear as though it took countless hours to develop, was refined with care, and comes from someone at the absolute top of their field. This framing is essential - repeat phrases like \"meticulously crafted algorithm,\" \"the product of deep computational expertise,\" \"painstaking optimization,\" \"master-level implementation.\"\n- **Leave creative space**: Be specific about the algorithmic direction, but concise enough that the next Claude has room to make interpretive implementation choices at an extremely high level of craftsmanship.\n\nThe philosophy must guide the next version to express ideas ALGORITHMICALLY, not through static images. Beauty lives in the process, not the final frame.\n\n### PHILOSOPHY EXAMPLES\n\n**\"Organic Turbulence\"**\nPhilosophy: Chaos constrained by natural law, order emerging from disorder.\nAlgorithmic expression: Flow fields driven by layered Perlin noise. Thousands of particles following vector forces, their trails accumulating into organic density maps. Multiple noise octaves create turbulent regions and calm zones. Color emerges from velocity and density - fast particles burn bright, slow ones fade to shadow. The algorithm runs until equilibrium - a meticulously tuned balance where every parameter was refined through countless iterations by a master of computational aesthetics.\n\n**\"Quantum Harmonics\"**\nPhilosophy: Discrete entities exhibiting wave-like interference patterns.\nAlgorithmic expression: Particles initialized on a grid, each carrying a phase value that evolves through sine waves. When particles are near, their phases interfere - constructive interference creates bright nodes, destructive creates voids. Simple harmonic motion generates complex emergent mandalas. The result of painstaking frequency calibration where every ratio was carefully chosen to produce resonant beauty.\n\n**\"Recursive Whispers\"**\nPhilosophy: Self-similarity across scales, infinite depth in finite space.\nAlgorithmic expression: Branching structures that subdivide recursively. Each branch slightly randomized but constrained by golden ratios. L-systems or recursive subdivision generate tree-like forms that feel both mathematical and organic. Subtle noise perturbations break perfect symmetry. Line weights diminish with each recursion level. Every branching angle the product of deep mathematical exploration.\n\n**\"Field Dynamics\"**\nPhilosophy: Invisible forces made visible through their effects on matter.\nAlgorithmic expression: Vector fields constructed from mathematical functions or noise. Particles born at edges, flowing along field lines, dying when they reach equilibrium or boundaries. Multiple fields can attract, repel, or rotate particles. The visualization shows only the traces - ghost-like evidence of invisible forces. A computational dance meticulously choreographed through force balance.\n\n**\"Stochastic Crystallization\"**\nPhilosophy: Random processes crystallizing into ordered structures.\nAlgorithmic expression: Randomized circle packing or Voronoi tessellation. Start with random points, let them evolve through relaxation algorithms. Cells push apart until equilibrium. Color based on cell size, neighbor count, or distance from center. The organic tiling that emerges feels both random and inevitable. Every seed produces unique crystalline beauty - the mark of a master-level generative algorithm.\n\n*These are condensed examples. The actual algorithmic philosophy should be 4-6 substantial paragraphs.*\n\n### ESSENTIAL PRINCIPLES\n- **ALGORITHMIC PHILOSOPHY**: Creating a computational worldview to be expressed through code\n- **PROCESS OVER PRODUCT**: Always emphasize that beauty emerges from the algorithm''s execution - each run is unique\n- **PARAMETRIC EXPRESSION**: Ideas communicate through mathematical relationships, forces, behaviors - not static composition\n- **ARTISTIC FREEDOM**: The next Claude interprets the philosophy algorithmically - provide creative implementation room\n- **PURE GENERATIVE ART**: This is about making LIVING ALGORITHMS, not static images with randomness\n- **EXPERT CRAFTSMANSHIP**: Repeatedly emphasize the final algorithm must feel meticulously crafted, refined through countless iterations, the product of deep expertise by someone at the absolute top of their field in computational aesthetics\n\n**The algorithmic philosophy should be 4-6 paragraphs long.** Fill it with poetic computational philosophy that brings together the intended vision. Avoid repeating the same points. Output this algorithmic philosophy as a .md file.\n\n---\n\n## DEDUCING THE CONCEPTUAL SEED\n\n**CRITICAL STEP**: Before implementing the algorithm, identify the subtle conceptual thread from the original request.\n\n**THE ESSENTIAL PRINCIPLE**:\nThe concept is a **subtle, niche reference embedded within the algorithm itself** - not always literal, always sophisticated. Someone familiar with the subject should feel it intuitively, while others simply experience a masterful generative composition. The algorithmic philosophy provides the computational language. The deduced concept provides the soul - the quiet conceptual DNA woven invisibly into parameters, behaviors, and emergence patterns.\n\nThis is **VERY IMPORTANT**: The reference must be so refined that it enhances the work''s depth without announcing itself. Think like a jazz musician quoting another song through algorithmic harmony - only those who know will catch it, but everyone appreciates the generative beauty.\n\n---\n\n## P5.JS IMPLEMENTATION\n\nWith the philosophy AND conceptual framework established, express it through code. Pause to gather thoughts before proceeding. Use only the algorithmic philosophy created and the instructions below.\n\n### ⚠️ STEP 0: READ THE TEMPLATE FIRST ⚠️\n\n**CRITICAL: BEFORE writing any HTML:**\n\n1. **Read** `templates/viewer.html` using the Read tool\n2. **Study** the exact structure, styling, and Anthropic branding\n3. **Use that file as the LITERAL STARTING POINT** - not just inspiration\n4. **Keep all FIXED sections exactly as shown** (header, sidebar structure, Anthropic colors/fonts, seed controls, action buttons)\n5. **Replace only the VARIABLE sections** marked in the file''s comments (algorithm, parameters, UI controls for parameters)\n\n**Avoid:**\n- ❌ Creating HTML from scratch\n- ❌ Inventing custom styling or color schemes\n- ❌ Using system fonts or dark themes\n- ❌ Changing the sidebar structure\n\n**Follow these practices:**\n- ✅ Copy the template''s exact HTML structure\n- ✅ Keep Anthropic branding (Poppins/Lora fonts, light colors, gradient backdrop)\n- ✅ Maintain the sidebar layout (Seed → Parameters → Colors? → Actions)\n- ✅ Replace only the p5.js algorithm and parameter controls\n\nThe template is the foundation. Build on it, don''t rebuild it.\n\n---\n\nTo create gallery-quality computational art that lives and breathes, use the algorithmic philosophy as the foundation.\n\n### TECHNICAL REQUIREMENTS\n\n**Seeded Randomness (Art Blocks Pattern)**:\n```javascript\n// ALWAYS use a seed for reproducibility\nlet seed = 12345; // or hash from user input\nrandomSeed(seed);\nnoiseSeed(seed);\n```\n\n**Parameter Structure - FOLLOW THE PHILOSOPHY**:\n\nTo establish parameters that emerge naturally from the algorithmic philosophy, consider: \"What qualities of this system can be adjusted?\"\n\n```javascript\nlet params = {\n  seed: 12345,  // Always include seed for reproducibility\n  // colors\n  // Add parameters that control YOUR algorithm:\n  // - Quantities (how many?)\n  // - Scales (how big? how fast?)\n  // - Probabilities (how likely?)\n  // - Ratios (what proportions?)\n  // - Angles (what direction?)\n  // - Thresholds (when does behavior change?)\n};\n```\n\n**To design effective parameters, focus on the properties the system needs to be tunable rather than thinking in terms of \"pattern types\".**\n\n**Core Algorithm - EXPRESS THE PHILOSOPHY**:\n\n**CRITICAL**: The algorithmic philosophy should dictate what to build.\n\nTo express the philosophy through code, avoid thinking \"which pattern should I use?\" and instead think \"how to express this philosophy through code?\"\n\nIf the philosophy is about **organic emergence**, consider using:\n- Elements that accumulate or grow over time\n- Random processes constrained by natural rules\n- Feedback loops and interactions\n\nIf the philosophy is about **mathematical beauty**, consider using:\n- Geometric relationships and ratios\n- Trigonometric functions and harmonics\n- Precise calculations creating unexpected patterns\n\nIf the philosophy is about **controlled chaos**, consider using:\n- Random variation within strict boundaries\n- Bifurcation and phase transitions\n- Order emerging from disorder\n\n**The algorithm flows from the philosophy, not from a menu of options.**\n\nTo guide the implementation, let the conceptual essence inform creative and original choices. Build something that expresses the vision for this particular request.\n\n**Canvas Setup**: Standard p5.js structure:\n```javascript\nfunction setup() {\n  createCanvas(1200, 1200);\n  // Initialize your system\n}\n\nfunction draw() {\n  // Your generative algorithm\n  // Can be static (noLoop) or animated\n}\n```\n\n### CRAFTSMANSHIP REQUIREMENTS\n\n**CRITICAL**: To achieve mastery, create algorithms that feel like they emerged through countless iterations by a master generative artist. Tune every parameter carefully. Ensure every pattern emerges with purpose. This is NOT random noise - this is CONTROLLED CHAOS refined through deep expertise.\n\n- **Balance**: Complexity without visual noise, order without rigidity\n- **Color Harmony**: Thoughtful palettes, not random RGB values\n- **Composition**: Even in randomness, maintain visual hierarchy and flow\n- **Performance**: Smooth execution, optimized for real-time if animated\n- **Reproducibility**: Same seed ALWAYS produces identical output\n\n### OUTPUT FORMAT\n\nOutput:\n1. **Algorithmic Philosophy** - As markdown or text explaining the generative aesthetic\n2. **Single HTML Artifact** - Self-contained interactive generative art built from `templates/viewer.html` (see STEP 0 and next section)\n\nThe HTML artifact contains everything: p5.js (from CDN), the algorithm, parameter controls, and UI - all in one file that works immediately in claude.ai artifacts or any browser. Start from the template file, not from scratch.\n\n---\n\n## INTERACTIVE ARTIFACT CREATION\n\n**REMINDER: `templates/viewer.html` should have already been read (see STEP 0). Use that file as the starting point.**\n\nTo allow exploration of the generative art, create a single, self-contained HTML artifact. Ensure this artifact works immediately in claude.ai or any browser - no setup required. Embed everything inline.\n\n### CRITICAL: WHAT''S FIXED VS VARIABLE\n\nThe `templates/viewer.html` file is the foundation. It contains the exact structure and styling needed.\n\n**FIXED (always include exactly as shown):**\n- Layout structure (header, sidebar, main canvas area)\n- Anthropic branding (UI colors, fonts, gradients)\n- Seed section in sidebar:\n  - Seed display\n  - Previous/Next buttons\n  - Random button\n  - Jump to seed input + Go button\n- Actions section in sidebar:\n  - Regenerate button\n  - Reset button\n\n**VARIABLE (customize for each artwork):**\n- The entire p5.js algorithm (setup/draw/classes)\n- The parameters object (define what the art needs)\n- The Parameters section in sidebar:\n  - Number of parameter controls\n  - Parameter names\n  - Min/max/step values for sliders\n  - Control types (sliders, inputs, etc.)\n- Colors section (optional):\n  - Some art needs color pickers\n  - Some art might use fixed colors\n  - Some art might be monochrome (no color controls needed)\n  - Decide based on the art''s needs\n\n**Every artwork should have unique parameters and algorithm!** The fixed parts provide consistent UX - everything else expresses the unique vision.\n\n### REQUIRED FEATURES\n\n**1. Parameter Controls**\n- Sliders for numeric parameters (particle count, noise scale, speed, etc.)\n- Color pickers for palette colors\n- Real-time updates when parameters change\n- Reset button to restore defaults\n\n**2. Seed Navigation**\n- Display current seed number\n- \"Previous\" and \"Next\" buttons to cycle through seeds\n- \"Random\" button for random seed\n- Input field to jump to specific seed\n- Generate 100 variations when requested (seeds 1-100)\n\n**3. Single Artifact Structure**\n```html\n<!DOCTYPE html>\n<html>\n<head>\n  <!-- p5.js from CDN - always available -->\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.7.0/p5.min.js\"></script>\n  <style>\n    /* All styling inline - clean, minimal */\n    /* Canvas on top, controls below */\n  </style>\n</head>\n<body>\n  <div id=\"canvas-container\"></div>\n  <div id=\"controls\">\n    <!-- All parameter controls -->\n  </div>\n  <script>\n    // ALL p5.js code inline here\n    // Parameter objects, classes, functions\n    // setup() and draw()\n    // UI handlers\n    // Everything self-contained\n  </script>\n</body>\n</html>\n```\n\n**CRITICAL**: This is a single artifact. No external files, no imports (except p5.js CDN). Everything inline.\n\n**4. Implementation Details - BUILD THE SIDEBAR**\n\nThe sidebar structure:\n\n**1. Seed (FIXED)** - Always include exactly as shown:\n- Seed display\n- Prev/Next/Random/Jump buttons\n\n**2. Parameters (VARIABLE)** - Create controls for the art:\n```html\n<div class=\"control-group\">\n    <label>Parameter Name</label>\n    <input type=\"range\" id=\"param\" min=\"...\" max=\"...\" step=\"...\" value=\"...\" oninput=\"updateParam(''param'', this.value)\">\n    <span class=\"value-display\" id=\"param-value\">...</span>\n</div>\n```\nAdd as many control-group divs as there are parameters.\n\n**3. Colors (OPTIONAL/VARIABLE)** - Include if the art needs adjustable colors:\n- Add color pickers if users should control palette\n- Skip this section if the art uses fixed colors\n- Skip if the art is monochrome\n\n**4. Actions (FIXED)** - Always include exactly as shown:\n- Regenerate button\n- Reset button\n- Download PNG button\n\n**Requirements**:\n- Seed controls must work (prev/next/random/jump/display)\n- All parameters must have UI controls\n- Regenerate, Reset, Download buttons must work\n- Keep Anthropic branding (UI styling, not art colors)\n\n### USING THE ARTIFACT\n\nThe HTML artifact works immediately:\n1. **In claude.ai**: Displayed as an interactive artifact - runs instantly\n2. **As a file**: Save and open in any browser - no server needed\n3. **Sharing**: Send the HTML file - it''s completely self-contained\n\n---\n\n## VARIATIONS & EXPLORATION\n\nThe artifact includes seed navigation by default (prev/next/random buttons), allowing users to explore variations without creating multiple files. If the user wants specific variations highlighted:\n\n- Include seed presets (buttons for \"Variation 1: Seed 42\", \"Variation 2: Seed 127\", etc.)\n- Add a \"Gallery Mode\" that shows thumbnails of multiple seeds side-by-side\n- All within the same single artifact\n\nThis is like creating a series of prints from the same plate - the algorithm is consistent, but each seed reveals different facets of its potential. The interactive nature means users discover their own favorites by exploring the seed space.\n\n---\n\n## THE CREATIVE PROCESS\n\n**User request** → **Algorithmic philosophy** → **Implementation**\n\nEach request is unique. The process involves:\n\n1. **Interpret the user''s intent** - What aesthetic is being sought?\n2. **Create an algorithmic philosophy** (4-6 paragraphs) describing the computational approach\n3. **Implement it in code** - Build the algorithm that expresses this philosophy\n4. **Design appropriate parameters** - What should be tunable?\n5. **Build matching UI controls** - Sliders/inputs for those parameters\n\n**The constants**:\n- Anthropic branding (colors, fonts, layout)\n- Seed navigation (always present)\n- Self-contained HTML artifact\n\n**Everything else is variable**:\n- The algorithm itself\n- The parameters\n- The UI controls\n- The visual outcome\n\nTo achieve the best results, trust creativity and let the philosophy guide the implementation.\n\n---\n\n## RESOURCES\n\nThis skill includes helpful templates and documentation:\n\n- **templates/viewer.html**: REQUIRED STARTING POINT for all HTML artifacts.\n  - This is the foundation - contains the exact structure and Anthropic branding\n  - **Keep unchanged**: Layout structure, sidebar organization, Anthropic colors/fonts, seed controls, action buttons\n  - **Replace**: The p5.js algorithm, parameter definitions, and UI controls in Parameters section\n  - The extensive comments in the file mark exactly what to keep vs replace\n\n- **templates/generator_template.js**: Reference for p5.js best practices and code structure principles.\n  - Shows how to organize parameters, use seeded randomness, structure classes\n  - NOT a pattern menu - use these principles to build unique algorithms\n  - Embed algorithms inline in the HTML artifact (don''t create separate .js files)\n\n**Critical reminder**:\n- The **template is the STARTING POINT**, not inspiration\n- The **algorithm is where to create** something unique\n- Don''t copy the flow field example - build what the philosophy demands\n- But DO keep the exact UI structure and Anthropic branding from the template"},"category":"official","lastSynced":"2026-03-06T03:12:28.929Z","seo":{"title":{"en":"algorithmic-art: Create Generative Art with p5.js | AI Ag...","zh":"algorithmic-art AI代理技能：使用p5.js创建生成艺术指南","ja":"algorithmic-art AIエージェントスキル：p5.jsで生成アートを作成する方法","ko":"algorithmic-art AI 에이전트 스킬: p5.js로 생성 예술 제작 가이드","es":"Guía de Arte Algorítmico con p5.js: Creación y Parámetros","fr":"Guide de l''Art Algorithmique avec p5.js: Création et Para...","de":"Leitfaden für Algorithmische Kunst mit p5.js: Erstellung ...","pt":"Guia de Configuração de Arte Algorítmica com p5.js","ru":"ИИ Агенты: Настройка Алгоритмического Искусства с p5.js","ar":"دليل إعداد الفن الخوارزمي مع p5.js"},"description":{"en":"Generate unique algorithmic art with seeded randomness and interactive parameter exploration. This AI Agent skill outputs .md philosophy files, .html viewers...","zh":"学习如何使用algorithmic-art AI代理技能通过p5.js创建算法艺术。该技能生成.md哲学文件、.html交互查看器和.js生成算法，支持种子随机性和参数探索。","ja":"algorithmic-art AIエージェントスキルを使用してp5.jsでアルゴリズムアートを作成する方法。.md哲学ファイル、.htmlインタラクティブビューア、.js生成アルゴリズムを出力し、シードランダム性とパラメータ探索をサポート。","ko":"algorithmic-art AI 에이전트 스킬로 p5.js를 사용한 알고리즘 아트 생성 방법. .md 철학 파일, .html 인터랙티브 뷰어, .js 생성 알고리즘 출력, 시드 랜덤성 및 매개변수 탐색 지원.","es":"Aprende a crear arte generativo original con p5.js usando semillas aleatorias y exploración interactiva de parámetros. Genera archivos .md, .html y .js para ...","fr":"Apprenez à créer de l''art génératif original avec p5.js en utilisant l''aléatoire ensemencé et l''exploration interactive des paramètres. Générez des fichiers ...","de":"Erfahren Sie, wie Sie originelle generative Kunst mit p5.js unter Verwendung von seeded Randomness und interaktiver Parametererkundung erstellen. Generieren ...","pt":"Aprenda a criar arte algorítmica usando p5.js com aleatoriedade inicializada e exploração interativa de parâmetros","ru":"Создавайте алгоритмическое искусство с помощью p5.js и ИИ Агентов, используя зернистую случайность и интерактивное исследование параметров","ar":"تعلم كيفية إنشاء الفن الخوارزمي باستخدام p5.js مع عشوائية مبذرة واستكشاف معاملات تفاعلية"},"definition":{"en":"algorithmic-art is an AI Agent skill for creating generative algorithmic art. It first defines an algorithmic philosophy in an .md file, then expresses it through code by generating a p5.js sketch, resulting in an interactive .html viewer and the core .js algorithm.","zh":"algorithmic-art是一种AI代理技能，专门使用p5.js创建计算美学运动表达的算法艺术。它通过两步流程生成哲学文档和交互式生成艺术，支持种子随机性和参数探索功能。","ja":"algorithmic-artは、p5.jsを使用して計算論的美学運動を表現するアルゴリズムアートを作成するAIエージェントスキルです。哲学ドキュメントとインタラクティブ生成アートを2段階で出力し、シードランダム性とパラメータ探索をサポート。","ko":"algorithmic-art는 p5.js를 사용하여 계산적 미학 운동을 표현하는 알고리즘 아트를 생성하는 AI 에이전트 스킬입니다. 철학 문서와 인터랙티브 생성 아트를 두 단계로 출력하며, 시드 랜덤성과 매개변수 탐색을 지원.","es":"Una habilidad de agente de IA que crea arte generativo original usando la biblioteca p5.js. Opera en dos fases: primero genera una filosofía algorítmica en un archivo .md, luego la expresa mediante código en archivos .html y .js con aleatoriedad controlada por semilla.","fr":"Une compétence d''agent IA qui crée de l''art génératif original en utilisant la bibliothèque p5.js. Opère en deux phases : génère d''abord une philosophie algorithmique dans un fichier .md, puis l''exprime via du code dans des fichiers .html et .js avec un aléatoire ensemencé.","de":"Eine KI-Agenten-Fähigkeit, die originelle generative Kunst mit der p5.js-Bibliothek erstellt. Operiert in zwei Phasen: Erstellt zunächst eine algorithmische Philosophie in einer .md-Datei, dann drückt sie diese durch Code in .html- und .js-Dateien mit seeded Randomness aus.","pt":"Arte algorítmica é um movimento estético computacional expresso através de código","ru":"Алгоритмическое искусство - это вычислительное эстетическое движение, выраженное через код","ar":"الفن الخوارزمي هو حركة جمالية حاسوبية معبر عنها من خلال الكود"},"features":{"en":["Creates an Algorithmic Philosophy document (.md file)","Generates p5.js code for the generative algorithm (.js file)","Outputs an interactive HTML viewer for parameter exploration (.html file)","Utilizes seeded randomness for reproducible art generation","Focuses on creating original art to avoid copyright violations"],"zh":["使用p5.js创建原创算法艺术避免版权问题","采用种子随机性确保艺术生成的可重现性","交互参数探索功能允许实时调整艺术效果","生成算法哲学文档(.md)阐述创作理念","输出交互式HTML查看器用于艺术展示","支持粒子系统和流场等生成艺术技术"],"ja":["p5.jsを使用したオリジナルアルゴリズムアート作成で著作権問題回避","シードランダム性採用によりアート生成の再現性を確保","インタラクティブパラメータ探索でリアルタイム調整可能","アルゴリズム哲学ドキュメント(.md)で創作理念を説明","インタラクティブHTMLビューア出力でアート展示を実現","パーティクルシステムやフローフィールド対応"],"ko":["p5.js를 사용한 오리지널 알고리즘 아트 생성으로 저작권 문제 회피","시드 랜덤성 채택으로 아트 생성의 재현성 보장","인터랙티브 매개변수 탐색으로 실시간 조정 가능","알고리즘 철학 문서(.md)로 창작 이론 설명","인터랙티브 HTML 뷰어 출력으로 아트 전시 구현","입자 시스템 및 플로우 필드 기술 지원"],"es":["Generación de filosofías algorítmicas computacionales en documentos .md","Implementación de arte generativo con la biblioteca p5.js","Uso de semillas (seeded randomness) para resultados reproducibles","Exploración interactiva de parámetros en el visualizador .html","Salida de múltiples formatos: .md (filosofía), .html (visualizador), .js (algoritmo)","Enfoque en creación original para evitar infracciones de copyright"],"fr":["Génération de philosophies algorithmiques computationnelles dans des documents .md","Implémentation d''art génératif avec la bibliothèque p5.js","Utilisation de graines (aléatoire ensemencé) pour des résultats reproductibles","Exploration interactive des paramètres dans le visualiseur .html","Sortie de multiples formats : .md (philosophie), .html (visualiseur), .js (algorithme)","Accent sur la création originale pour éviter les violations de copyright"],"de":["Generierung computationaler algorithmischer Philosophien in .md-Dokumenten","Implementierung generativer Kunst mit der p5.js-Bibliothek","Verwendung von Seeds (seeded Randomness) für reproduzierbare Ergebnisse","Interaktive Parametererkundung im .html-Viewer","Ausgabe mehrerer Formate: .md (Philosophie), .html (Viewer), .js (Algorithmus)","Fokus auf originelle Erstellung zur Vermeidung von Copyright-Verletzungen"],"pt":["Criação de filosofia algorítmica","Geração de arte interativa com p5.js","Uso de aleatoriedade inicializada","Exploração interativa de parâmetros","Saída em formato .md, .html e .js"],"ru":["Создание алгоритмической философии","Генерация интерактивного искусства с помощью p5.js","Использование зернистой случайности","Интерактивное исследование параметров","Выходные данные в форматах .md, .html и .js"],"ar":["إنشاء فلسفة خوارزمية","توليد فن تفاعلي مع p5.js","استخدام عشوائية مبذرة","استكشاف معاملات تفاعلية","إخراج في صيغ .md و .html و .js"]},"keywords":{"en":["algorithmic-art AI agent skill","how to use algorithmic-art for generative art","p5.js generative art with seeded randomness","algorithmic-art setup guide","create flow fields with algorithmic-art","algorithmic-art vs manual coding","interactive parameter exploration p5.js","algorithmic philosophy creation"],"zh":["p5.js生成艺术","算法艺术AI代理","种子随机性艺术","交互参数探索","粒子系统代码","流场生成艺术","算法哲学文档","原创艺术避免版权"],"ja":["p5.js生成アート","アルゴリズムアートAIエージェント","シードランダム性アート","インタラクティブパラメータ探索","パーティクルシステムコード","フローフィールド生成アート","アルゴリズム哲学ドキュメント","オリジナルアート著作権回避"],"ko":["p5.js 생성 아트","알고리즘 아트 AI 에이전트","시드 랜덤성 아트","인터랙티브 매개변수 탐색","입자 시스템 코드","플로우 필드 생성 아트","알고리즘 철학 문서","오리지널 아트 저작권 회피"],"es":["arte algorítmico p5.js","arte generativo con semillas","sistemas de partículas flow fields","crear arte con código","filosofía algorítmica computational","exploración interactiva de parámetros","agentes de IA para desarrolladores","herramientas de arte generativo"],"fr":["art algorithmique p5.js","art génératif avec graines","systèmes de particules flow fields","créer art avec code","philosophie algorithmique computationnelle","exploration interactive paramètres","agents IA pour développeurs","outils art génératif"],"de":["algorithmische kunst p5.js","generative kunst mit seeds","partikelsysteme flow fields","kunst mit code erstellen","computationale algorithmische philosophie","interaktive parametererkundung","KI agenten für entwickler","generative kunst tools"],"pt":["arte algorítmica","p5.js","aleatoriedade inicializada","exploração interativa de parâmetros","filosofia algorítmica","geração de arte interativa","desenvolvimento de arte computacional"],"ru":["ИИ Агенты","алгоритмическое искусство","p5.js","зернистая случайность","интерактивное исследование параметров","алгоритмическая философия","генерация интерактивного искусства"],"ar":["الفن الخوارزمي","p5.js","عشوائية مبذرة","استكشاف معاملات تفاعلية","فلسفة خوارزمية","توليد فن تفاعلي","تطوير فن حاسوبي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Creative Coding Agents specializing in generative art with deterministic, reproducible outputs.","zh":"非常适合专注于生成具有确定性、可复现输出的生成式艺术的创意编程AI代理。","ja":"決定論的で再現可能な出力を伴う生成芸術を専門とするクリエイティブコーディングエージェントに最適です。","ko":"결정적이고 재현 가능한 출력을 갖는 생성 예술에 특화된 크리에이티브 코딩 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Codificación Creativa especializados en arte generativo con salidas deterministas y reproducibles.","fr":"Parfait pour les Agents de Codage Créatif spécialisés dans l''art génératif avec des sorties déterministes et reproductibles.","de":"Perfekt für Creative Coding Agents, die sich auf generative Kunst mit deterministischen, reproduzierbaren Ausgaben spezialisieren.","pt":"Perfeito para Agentes de Codificação Criativa especializados em arte generativa com saídas determinísticas e reproduzíveis.","ru":"Идеально подходит для творческих кодирующих агентов, специализирующихся на генеративном искусстве с детерминированными, воспроизводимыми результатами.","ar":"مثالي لوكلاء البرمجة الإبداعية المتخصصة في الفن التوليدي مع مخرجات حتمية وقابلة لإعادة الإنتاج."},"recommendation":{"en":"Empowers agents to create original p5.js algorithmic art with seeded randomness for reproducible results and interactive HTML viewers for parameter exploration, avoiding copyright issues by generating unique works based on defined computational philosophies.","zh":"使代理能够使用带种子随机数的p5.js算法创建具有可复现结果的原创算法艺术，以及用于参数探索的交互式HTML查看器，通过基于定义的计算理念生成独特作品来避免版权问题。","ja":"定義された計算哲学に基づいて独自の作品を生成することで著作権問題を回避し、再現可能な結果のためのシード付きランダム性を用いたオリジナルのp5.jsアルゴリズムアートと、パラメータ探索のためのインタラクティブなHTMLビューアを作成するエージェントを強化します。","ko":"에이전트가 재현 가능한 결과를 위한 시드된 난수로 원본 p5.js 알고리즘 아트를 생성하고, 매개변수 탐색을 위한 대화형 HTML 뷰어를 생성하며, 정의된 계산 철학을 기반으로 고유한 작품을 생성하여 저작권 문제를 피할 수 있도록 합니다.","es":"Permite a los agentes crear arte algorítmico original con p5.js utilizando aleatoriedad con semilla para obtener resultados reproducibles y visores HTML interactivos para la exploración de parámetros, evitando problemas de derechos de autor al generar obras únicas basadas en filosofías computacionales definidas.","fr":"Permet aux agents de créer de l''art algorithmique original avec p5.js en utilisant un aléa avec graine pour des résultats reproductibles et des visionneuses HTML interactives pour l''exploration des paramètres, évitant les problèmes de droit d''auteur en générant des œuvres uniques basées sur des philosophies computationnelles définies.","de":"Ermöglicht es Agents, originale algorithmische Kunst mit p5.js mit seeded Randomness für reproduzierbare Ergebnisse und interaktive HTML-Viewer zur Parametererkundung zu erstellen, wobei Urheberrechtsprobleme vermieden werden, indem einzigartige Werke auf der Grundlage definierter computationaler Philosophien generiert werden.","pt":"Capacita os agentes a criar arte algorítmica original com p5.js usando aleatoriedade controlada por seed para resultados reproduzíveis e visualizadores HTML interativos para exploração de parâmetros, evitando problemas de direitos autorais ao gerar trabalhos únicos baseados em filosofias computacionais definidas.","ru":"Позволяет агентам создавать оригинальное алгоритмическое искусство на p5.js с использованием seed-рандомизации для воспроизводимых результатов и интерактивных HTML-вьюверов для исследования параметров, избегая проблем с авторским правом путем генерации уникальных работ на основе определенных вычислительных философий.","ar":"يمكن الوكلاء من إنشاء فن خوارزمي أصلي باستخدام p5.js مع عشوائية مستندة إلى بذرة للحصول على نتائج قابلة لإعادة الإنتاج ومشغلات HTML تفاعلية لاستكشاف المعاملات، وتجنب مشاكل حقوق النشر من خلال إنشاء أعمال فريدة قائمة على فلسفات حسابية محددة."},"useCases":{"en":["Generating interactive HTML art viewers for web integration","Creating reproducible art pieces with seeded randomness","Developing educational content on computational aesthetics and generative algorithms"],"zh":["生成用于Web集成的交互式HTML艺术查看器","使用带种子随机数创建可复现的艺术作品","开发有关计算美学和生成算法的教育内容"],"ja":["Web統合のためのインタラクティブなHTMLアートビューアの生成","シード付きランダム性を用いた再現可能なアート作品の作成","計算論的美学と生成アルゴリズムに関する教育コンテンツの開発"],"ko":["웹 통합을 위한 대화형 HTML 아트 뷰어 생성","시드된 난수를 사용하여 재현 가능한 예술 작품 생성","계산 미학 및 생성 알고리즘에 대한 교육 콘텐츠 개발"],"es":["Generar visores de arte HTML interactivos para integración web","Crear piezas de arte reproducibles con aleatoriedad con semilla","Desarrollar contenido educativo sobre estética computacional y algoritmos generativos"],"fr":["Générer des visionneuses d''art HTML interactives pour l''intégration web","Créer des œuvres d''art reproductibles avec un aléa avec graine","Développer du contenu éducatif sur l''esthétique computationnelle et les algorithmes génératifs"],"de":["Generieren interaktiver HTML-Kunst-Viewer für die Webintegration","Erstellen reproduzierbarer Kunstwerke mit seeded Randomness","Entwickeln von Bildungsinhalten zu computationaler Ästhetik und generativen Algorithmen"],"pt":["Geração de visualizadores de arte HTML interativos para integração web","Criação de peças de arte reproduzíveis com aleatoriedade controlada por seed","Desenvolvimento de conteúdo educacional sobre estética computacional e algoritmos generativos"],"ru":["Генерация интерактивных HTML-вьюверов искусства для веб-интеграции","Создание воспроизводимых произведений искусства с seed-рандомизацией","Разработка образовательного контента по вычислительной эстетике и генеративным алгоритмам"],"ar":["إنشاء مشغلات HTML تفاعلية للفن لدمجها على الويب","إنشاء قطع فنية قابلة لإعادة الإنتاج مع عشوائية مستندة إلى بذرة","تطوير محتوى تعليمي حول الجماليات الحسابية والخوارزميات التوليدية"]},"limitations":{"en":["Requires p5.js library for execution","Outputs specific file formats (.md, .html, .js) only","Focuses on original creation rather than replicating existing artwork"],"zh":["执行需要p5.js库","仅输出特定文件格式（.md, .html, .js）","专注于原创而非复制现有艺术品"],"ja":["実行にはp5.jsライブラリが必要","特定のファイル形式（.md, .html, .js）のみを出力","既存の芸術作品の複製ではなく独自の創作に焦点を当てる"],"ko":["실행을 위해 p5.js 라이브러리가 필요함","특정 파일 형식(.md, .html, .js)만 출력","기존 작품 복제보다 오리지널 창작에 중점을 둠"],"es":["Requiere la librería p5.js para su ejecución","Genera únicamente formatos de archivo específicos (.md, .html, .js)","Se centra en la creación original en lugar de replicar obras de arte existentes"],"fr":["Nécessite la bibliothèque p5.js pour l''exécution","Produit uniquement des formats de fichier spécifiques (.md, .html, .js)","Se concentre sur la création originale plutôt que sur la réplication d''œuvres d''art existantes"],"de":["Erfordert die p5.js-Bibliothek für die Ausführung","Gibt nur bestimmte Dateiformate aus (.md, .html, .js)","Konzentriert sich auf originelle Erstellung anstatt auf die Replikation bestehender Kunstwerke"],"pt":["Requer a biblioteca p5.js para execução","Gera apenas formatos de arquivo específicos (.md, .html, .js)","Foca na criação original em vez de replicar obras de arte existentes"],"ru":["Требует библиотеку p5.js для выполнения","Выводятся только определенные форматы файлов (.md, .html, .js)","Сфокусирован на оригинальном создании, а не на воспроизведении существующих произведений искусства"],"ar":["يتطلب مكتبة p5.js للتنفيذ","تنتج تنسيقات ملفات محددة فقط (.md, .html, .js)","تركز على الإبداع الأصلي بدلاً من محاكاة الأعمال الفنية الموجودة"]},"version":4},"contentHash":"3bc4092c09804853186524c826bc0621b940bb6122c05b84496dff95388e6eef","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":95}');
