INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/algorithmic-art', 'algorithmic-art', 'anthropics', 'skills', 'official', 'algorithmic-art anthropics skills official agent-skills The algorithmic-art AI skill creates original generative art using p5.js. It produces an algorithmic philosophy (.md), an interactive HTML viewer, and the corresponding JavaScript code, enabling developers to explore seeded randomness and parameterized art systems. algorithmic-art AI代理技能通过p5.js创建原创算法艺术，采用种子随机性和交互参数探索。它生成算法哲学文档(.md)、交互查看器(.html)和生成算法(.js)，避免版权侵权。 algorithmic-art AIエージェントスキルは、p5.jsを使用したオリジナルのアルゴリズムアートを創作し、シードランダム性とインタラクティブなパラメータ探索を採用。アルゴリズム哲学ドキュメント(.md)、インタラクティブビューア(.html)、生成アルゴリズム(.js)を出力し、著作権侵害を回避。 algorithmic-art AI 에이전트 스킬은 p5.js를 사용한 오리지널 알고리즘 아트를 생성하며, 시드 랜덤성과 인터랙티브 매개변수 탐색을 채택. 알고리즘 철학 문서(.md), 인터랙티브 뷰어(.html), 생성 알고리즘(.js)을 출력하여 저작권 침해를 회피. Esta habilidad de agente de IA genera arte algorítmico original utilizando p5.js, incorporando semillas aleatorias para reproducibilidad y permitiendo la exploración interactiva de parámetros. Produce filosofías computacionales en .md y su implementación en .html/.js. Cette compétence d''agent IA génère de l''art algorithmique original en utilisant p5.js, incorporant l''aléatoire ensemencé pour la reproductibilité et permettant l''exploration interactive des paramètres. Produit des philosophies computationnelles en .md et leur implémentation en .html/.js. Diese KI-Agenten-Fähigkeit erzeugt originelle algorithmische Kunst mit p5.js, verwendet seeded Randomness für Reproduzierbarkeit und ermöglicht die interaktive Erkundung von Parametern. Erstellt computationale Philosophien in .md und deren Implementierung in .html/.js. A arte algorítmica é criada usando p5.js com aleatoriedade inicializada e exploração interativa de parâmetros Алгоритмическое искусство создается с помощью p5.js и ИИ Агентов, используя зернистую случайность и интерактивное исследование параметров الفن الخوارزمي يتم إنشاؤه باستخدام p5.js مع عشوائية مبذرة واستكشاف معاملات تفاعلية algorithmic-art AI agent skill how to use algorithmic-art for generative art p5.js generative art with seeded randomness algorithmic-art setup guide create flow fields with algorithmic-art algorithmic-art vs manual coding interactive parameter exploration p5.js algorithmic philosophy creation p5.js生成艺术 算法艺术AI代理 种子随机性艺术 交互参数探索 粒子系统代码 流场生成艺术 算法哲学文档 原创艺术避免版权 Creates an Algorithmic Philosophy document (.md file) Generates p5.js code for the generative algorithm (.js file) Outputs an interactive HTML viewer for parameter exploration (.html file) Utilizes seeded randomness for reproducible art generation Focuses on creating original art to avoid copyright violations algorithmic-art is an AI Agent skill for creating generative algorithmic art. It first defines an algorithmic philosophy in an .md file, then expresses it through code by generating a p5.js sketch, resulting in an interactive .html viewer and the core .js algorithm.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/writing-skills', 'official', 'obra', 'superpowers', 'obra/superpowers', 'writing-skills', 71924, 5546, 95, '2026-03-06T03:26:30Z', '2026-03-06T03:39:52.794Z', 'd83a09d6a1c6976f6cc2f40addeae653a4a6eb5903097ebc365d90242e00e379', '{"id":"obra/superpowers/writing-skills","name":"writing-skills","description":{"en":"The writing-skills framework applies Test-Driven Development principles to AI agent documentation. Developers create test cases with subagents, write skills, and verify compliance before deploying to agent-specific directories like ~/.claude/skills.","zh":"Writing Skills是测试驱动开发应用于AIエージェント文档的过程，涉及写测试用例、观察失败、编写文档和重构","ja":"Writing Skillsは、AIエージェントの文書化にテスト駆動開発を適用するプロセスで、テストケースの作成、失敗の観察、文書の作成、リファクタリングが含まれます","ko":"Writing Skills는 AI 에이전트 문서에 테스트 주도 개발을 적용하는 과정으로 테스트 케이스 작성, 실패 관찰, 문서 작성 및 리팩터링이 포함됩니다","es":"La habilidad de escritura es un enfoque de desarrollo dirigido por pruebas para la documentación de procesos, que utiliza subagentes y escenarios de presión","fr":"La compétence d''écriture est une approche de développement dirigée par des tests pour la documentation de processus, qui utilise des sous-agents et des scénarios de pression","de":"Die Schreibfähigkeit ist ein testgetriebener Ansatz für die Prozessdokumentation, der Subagenten und Druckszenarien verwendet","pt":"As habilidades de escrita aplicam o desenvolvimento orientado a testes à documentação de processos","ru":"Навыки написания применяют разработку через тестирование к документации процессов","ar":"مهارات الكتابة تطبق التطوير الموجه للاختبار على توثيق العمليات"},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"writing-skills","description":"Use when creating new skills, editing existing skills, or verifying skills work before deployment","bodyPreview":"# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Personal skills live in agent-specific directories (`~/.claude/skills` for Claude Code, `~/.agents/skills/` for Codex)** \n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn''t watch an agent fail without the sk","body":"# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Personal skills live in agent-specific directories (`~/.claude/skills` for Claude Code, `~/.agents/skills/` for Codex)** \n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn''t watch an agent fail without the skill, you don''t know if the skill teaches the right thing.\n\n**REQUIRED BACKGROUND:** You MUST understand superpowers:test-driven-development before using this skill. That skill defines the fundamental RED-GREEN-REFACTOR cycle. This skill adapts TDD to documentation.\n\n**Official guidance:** For Anthropic''s official skill authoring best practices, see anthropic-best-practices.md. This document provides additional patterns and guidelines that complement the TDD-focused approach in this skill.\n\n## What is a Skill?\n\nA **skill** is a reference guide for proven techniques, patterns, or tools. Skills help future Claude instances find and apply effective approaches.\n\n**Skills are:** Reusable techniques, patterns, tools, reference guides\n\n**Skills are NOT:** Narratives about how you solved a problem once\n\n## TDD Mapping for Skills\n\n| TDD Concept | Skill Creation |\n|-------------|----------------|\n| **Test case** | Pressure scenario with subagent |\n| **Production code** | Skill document (SKILL.md) |\n| **Test fails (RED)** | Agent violates rule without skill (baseline) |\n| **Test passes (GREEN)** | Agent complies with skill present |\n| **Refactor** | Close loopholes while maintaining compliance |\n| **Write test first** | Run baseline scenario BEFORE writing skill |\n| **Watch it fail** | Document exact rationalizations agent uses |\n| **Minimal code** | Write skill addressing those specific violations |\n| **Watch it pass** | Verify agent now complies |\n| **Refactor cycle** | Find new rationalizations → plug → re-verify |\n\nThe entire skill creation process follows RED-GREEN-REFACTOR.\n\n## When to Create a Skill\n\n**Create when:**\n- Technique wasn''t intuitively obvious to you\n- You''d reference this again across projects\n- Pattern applies broadly (not project-specific)\n- Others would benefit\n\n**Don''t create for:**\n- One-off solutions\n- Standard practices well-documented elsewhere\n- Project-specific conventions (put in CLAUDE.md)\n- Mechanical constraints (if it''s enforceable with regex/validation, automate it—save documentation for judgment calls)\n\n## Skill Types\n\n### Technique\nConcrete method with steps to follow (condition-based-waiting, root-cause-tracing)\n\n### Pattern\nWay of thinking about problems (flatten-with-flags, test-invariants)\n\n### Reference\nAPI docs, syntax guides, tool documentation (office docs)\n\n## Directory Structure\n\n\n```\nskills/\n  skill-name/\n    SKILL.md              # Main reference (required)\n    supporting-file.*     # Only if needed\n```\n\n**Flat namespace** - all skills in one searchable namespace\n\n**Separate files for:**\n1. **Heavy reference** (100+ lines) - API docs, comprehensive syntax\n2. **Reusable tools** - Scripts, utilities, templates\n\n**Keep inline:**\n- Principles and concepts\n- Code patterns (< 50 lines)\n- Everything else\n\n## SKILL.md Structure\n\n**Frontmatter (YAML):**\n- Only two fields supported: `name` and `description`\n- Max 1024 characters total\n- `name`: Use letters, numbers, and hyphens only (no parentheses, special chars)\n- `description`: Third-person, describes ONLY when to use (NOT what it does)\n  - Start with \"Use when...\" to focus on triggering conditions\n  - Include specific symptoms, situations, and contexts\n  - **NEVER summarize the skill''s process or workflow** (see CSO section for why)\n  - Keep under 500 characters if possible\n\n```markdown\n---\nname: Skill-Name-With-Hyphens\ndescription: Use when [specific triggering conditions and symptoms]\n---\n\n# Skill Name\n\n## Overview\nWhat is this? Core principle in 1-2 sentences.\n\n## When to Use\n[Small inline flowchart IF decision non-obvious]\n\nBullet list with SYMPTOMS and use cases\nWhen NOT to use\n\n## Core Pattern (for techniques/patterns)\nBefore/after code comparison\n\n## Quick Reference\nTable or bullets for scanning common operations\n\n## Implementation\nInline code for simple patterns\nLink to file for heavy reference or reusable tools\n\n## Common Mistakes\nWhat goes wrong + fixes\n\n## Real-World Impact (optional)\nConcrete results\n```\n\n\n## Claude Search Optimization (CSO)\n\n**Critical for discovery:** Future Claude needs to FIND your skill\n\n### 1. Rich Description Field\n\n**Purpose:** Claude reads description to decide which skills to load for a given task. Make it answer: \"Should I read this skill right now?\"\n\n**Format:** Start with \"Use when...\" to focus on triggering conditions\n\n**CRITICAL: Description = When to Use, NOT What the Skill Does**\n\nThe description should ONLY describe triggering conditions. Do NOT summarize the skill''s process or workflow in the description.\n\n**Why this matters:** Testing revealed that when a description summarizes the skill''s workflow, Claude may follow the description instead of reading the full skill content. A description saying \"code review between tasks\" caused Claude to do ONE review, even though the skill''s flowchart clearly showed TWO reviews (spec compliance then code quality).\n\nWhen the description was changed to just \"Use when executing implementation plans with independent tasks\" (no workflow summary), Claude correctly read the flowchart and followed the two-stage review process.\n\n**The trap:** Descriptions that summarize workflow create a shortcut Claude will take. The skill body becomes documentation Claude skips.\n\n```yaml\n# ❌ BAD: Summarizes workflow - Claude may follow this instead of reading skill\ndescription: Use when executing plans - dispatches subagent per task with code review between tasks\n\n# ❌ BAD: Too much process detail\ndescription: Use for TDD - write test first, watch it fail, write minimal code, refactor\n\n# ✅ GOOD: Just triggering conditions, no workflow summary\ndescription: Use when executing implementation plans with independent tasks in the current session\n\n# ✅ GOOD: Triggering conditions only\ndescription: Use when implementing any feature or bugfix, before writing implementation code\n```\n\n**Content:**\n- Use concrete triggers, symptoms, and situations that signal this skill applies\n- Describe the *problem* (race conditions, inconsistent behavior) not *language-specific symptoms* (setTimeout, sleep)\n- Keep triggers technology-agnostic unless the skill itself is technology-specific\n- If skill is technology-specific, make that explicit in the trigger\n- Write in third person (injected into system prompt)\n- **NEVER summarize the skill''s process or workflow**\n\n```yaml\n# ❌ BAD: Too abstract, vague, doesn''t include when to use\ndescription: For async testing\n\n# ❌ BAD: First person\ndescription: I can help you with async tests when they''re flaky\n\n# ❌ BAD: Mentions technology but skill isn''t specific to it\ndescription: Use when tests use setTimeout/sleep and are flaky\n\n# ✅ GOOD: Starts with \"Use when\", describes problem, no workflow\ndescription: Use when tests have race conditions, timing dependencies, or pass/fail inconsistently\n\n# ✅ GOOD: Technology-specific skill with explicit trigger\ndescription: Use when using React Router and handling authentication redirects\n```\n\n### 2. Keyword Coverage\n\nUse words Claude would search for:\n- Error messages: \"Hook timed out\", \"ENOTEMPTY\", \"race condition\"\n- Symptoms: \"flaky\", \"hanging\", \"zombie\", \"pollution\"\n- Synonyms: \"timeout/hang/freeze\", \"cleanup/teardown/afterEach\"\n- Tools: Actual commands, library names, file types\n\n### 3. Descriptive Naming\n\n**Use active voice, verb-first:**\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `condition-based-waiting` not `async-test-helpers`\n\n### 4. Token Efficiency (Critical)\n\n**Problem:** getting-started and frequently-referenced skills load into EVERY conversation. Every token counts.\n\n**Target word counts:**\n- getting-started workflows: <150 words each\n- Frequently-loaded skills: <200 words total\n- Other skills: <500 words (still be concise)\n\n**Techniques:**\n\n**Move details to tool help:**\n```bash\n# ❌ BAD: Document all flags in SKILL.md\nsearch-conversations supports --text, --both, --after DATE, --before DATE, --limit N\n\n# ✅ GOOD: Reference --help\nsearch-conversations supports multiple modes and filters. Run --help for details.\n```\n\n**Use cross-references:**\n```markdown\n# ❌ BAD: Repeat workflow details\nWhen searching, dispatch subagent with template...\n[20 lines of repeated instructions]\n\n# ✅ GOOD: Reference other skill\nAlways use subagents (50-100x context savings). REQUIRED: Use [other-skill-name] for workflow.\n```\n\n**Compress examples:**\n```markdown\n# ❌ BAD: Verbose example (42 words)\nyour human partner: \"How did we handle authentication errors in React Router before?\"\nYou: I''ll search past conversations for React Router authentication patterns.\n[Dispatch subagent with search query: \"React Router authentication error handling 401\"]\n\n# ✅ GOOD: Minimal example (20 words)\nPartner: \"How did we handle auth errors in React Router?\"\nYou: Searching...\n[Dispatch subagent → synthesis]\n```\n\n**Eliminate redundancy:**\n- Don''t repeat what''s in cross-referenced skills\n- Don''t explain what''s obvious from command\n- Don''t include multiple examples of same pattern\n\n**Verification:**\n```bash\nwc -w skills/path/SKILL.md\n# getting-started workflows: aim for <150 each\n# Other frequently-loaded: aim for <200 total\n```\n\n**Name by what you DO or core insight:**\n- ✅ `condition-based-waiting` > `async-test-helpers`\n- ✅ `using-skills` not `skill-usage`\n- ✅ `flatten-with-flags` > `data-structure-refactoring`\n- ✅ `root-cause-tracing` > `debugging-techniques`\n\n**Gerunds (-ing) work well for processes:**\n- `creating-skills`, `testing-skills`, `debugging-with-logs`\n- Active, describes the action you''re taking\n\n### 4. Cross-Referencing Other Skills\n\n**When writing documentation that references other skills:**\n\nUse skill name only, with explicit requirement markers:\n- ✅ Good: `**REQUIRED SUB-SKILL:** Use superpowers:test-driven-development`\n- ✅ Good: `**REQUIRED BACKGROUND:** You MUST understand superpowers:systematic-debugging`\n- ❌ Bad: `See skills/testing/test-driven-development` (unclear if required)\n- ❌ Bad: `@skills/testing/test-driven-development/SKILL.md` (force-loads, burns context)\n\n**Why no @ links:** `@` syntax force-loads files immediately, consuming 200k+ context before you need them.\n\n## Flowchart Usage\n\n```dot\ndigraph when_flowchart {\n    \"Need to show information?\" [shape=diamond];\n    \"Decision where I might go wrong?\" [shape=diamond];\n    \"Use markdown\" [shape=box];\n    \"Small inline flowchart\" [shape=box];\n\n    \"Need to show information?\" -> \"Decision where I might go wrong?\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Small inline flowchart\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Use markdown\" [label=\"no\"];\n}\n```\n\n**Use flowcharts ONLY for:**\n- Non-obvious decision points\n- Process loops where you might stop too early\n- \"When to use A vs B\" decisions\n\n**Never use flowcharts for:**\n- Reference material → Tables, lists\n- Code examples → Markdown blocks\n- Linear instructions → Numbered lists\n- Labels without semantic meaning (step1, helper2)\n\nSee @graphviz-conventions.dot for graphviz style rules.\n\n**Visualizing for your human partner:** Use `render-graphs.js` in this directory to render a skill''s flowcharts to SVG:\n```bash\n./render-graphs.js ../some-skill           # Each diagram separately\n./render-graphs.js ../some-skill --combine # All diagrams in one SVG\n```\n\n## Code Examples\n\n**One excellent example beats many mediocre ones**\n\nChoose most relevant language:\n- Testing techniques → TypeScript/JavaScript\n- System debugging → Shell/Python\n- Data processing → Python\n\n**Good example:**\n- Complete and runnable\n- Well-commented explaining WHY\n- From real scenario\n- Shows pattern clearly\n- Ready to adapt (not generic template)\n\n**Don''t:**\n- Implement in 5+ languages\n- Create fill-in-the-blank templates\n- Write contrived examples\n\nYou''re good at porting - one great example is enough.\n\n## File Organization\n\n### Self-Contained Skill\n```\ndefense-in-depth/\n  SKILL.md    # Everything inline\n```\nWhen: All content fits, no heavy reference needed\n\n### Skill with Reusable Tool\n```\ncondition-based-waiting/\n  SKILL.md    # Overview + patterns\n  example.ts  # Working helpers to adapt\n```\nWhen: Tool is reusable code, not just narrative\n\n### Skill with Heavy Reference\n```\npptx/\n  SKILL.md       # Overview + workflows\n  pptxgenjs.md   # 600 lines API reference\n  ooxml.md       # 500 lines XML structure\n  scripts/       # Executable tools\n```\nWhen: Reference material too large for inline\n\n## The Iron Law (Same as TDD)\n\n```\nNO SKILL WITHOUT A FAILING TEST FIRST\n```\n\nThis applies to NEW skills AND EDITS to existing skills.\n\nWrite skill before testing? Delete it. Start over.\nEdit skill without testing? Same violation.\n\n**No exceptions:**\n- Not for \"simple additions\"\n- Not for \"just adding a section\"\n- Not for \"documentation updates\"\n- Don''t keep untested changes as \"reference\"\n- Don''t \"adapt\" while running tests\n- Delete means delete\n\n**REQUIRED BACKGROUND:** The superpowers:test-driven-development skill explains why this matters. Same principles apply to documentation.\n\n## Testing All Skill Types\n\nDifferent skill types need different test approaches:\n\n### Discipline-Enforcing Skills (rules/requirements)\n\n**Examples:** TDD, verification-before-completion, designing-before-coding\n\n**Test with:**\n- Academic questions: Do they understand the rules?\n- Pressure scenarios: Do they comply under stress?\n- Multiple pressures combined: time + sunk cost + exhaustion\n- Identify rationalizations and add explicit counters\n\n**Success criteria:** Agent follows rule under maximum pressure\n\n### Technique Skills (how-to guides)\n\n**Examples:** condition-based-waiting, root-cause-tracing, defensive-programming\n\n**Test with:**\n- Application scenarios: Can they apply the technique correctly?\n- Variation scenarios: Do they handle edge cases?\n- Missing information tests: Do instructions have gaps?\n\n**Success criteria:** Agent successfully applies technique to new scenario\n\n### Pattern Skills (mental models)\n\n**Examples:** reducing-complexity, information-hiding concepts\n\n**Test with:**\n- Recognition scenarios: Do they recognize when pattern applies?\n- Application scenarios: Can they use the mental model?\n- Counter-examples: Do they know when NOT to apply?\n\n**Success criteria:** Agent correctly identifies when/how to apply pattern\n\n### Reference Skills (documentation/APIs)\n\n**Examples:** API documentation, command references, library guides\n\n**Test with:**\n- Retrieval scenarios: Can they find the right information?\n- Application scenarios: Can they use what they found correctly?\n- Gap testing: Are common use cases covered?\n\n**Success criteria:** Agent finds and correctly applies reference information\n\n## Common Rationalizations for Skipping Testing\n\n| Excuse | Reality |\n|--------|---------|\n| \"Skill is obviously clear\" | Clear to you ≠ clear to other agents. Test it. |\n| \"It''s just a reference\" | References can have gaps, unclear sections. Test retrieval. |\n| \"Testing is overkill\" | Untested skills have issues. Always. 15 min testing saves hours. |\n| \"I''ll test if problems emerge\" | Problems = agents can''t use skill. Test BEFORE deploying. |\n| \"Too tedious to test\" | Testing is less tedious than debugging bad skill in production. |\n| \"I''m confident it''s good\" | Overconfidence guarantees issues. Test anyway. |\n| \"Academic review is enough\" | Reading ≠ using. Test application scenarios. |\n| \"No time to test\" | Deploying untested skill wastes more time fixing it later. |\n\n**All of these mean: Test before deploying. No exceptions.**\n\n## Bulletproofing Skills Against Rationalization\n\nSkills that enforce discipline (like TDD) need to resist rationalization. Agents are smart and will find loopholes when under pressure.\n\n**Psychology note:** Understanding WHY persuasion techniques work helps you apply them systematically. See persuasion-principles.md for research foundation (Cialdini, 2021; Meincke et al., 2025) on authority, commitment, scarcity, social proof, and unity principles.\n\n### Close Every Loophole Explicitly\n\nDon''t just state the rule - forbid specific workarounds:\n\n<Bad>\n```markdown\nWrite code before test? Delete it.\n```\n</Bad>\n\n<Good>\n```markdown\nWrite code before test? Delete it. Start over.\n\n**No exceptions:**\n- Don''t keep it as \"reference\"\n- Don''t \"adapt\" it while writing tests\n- Don''t look at it\n- Delete means delete\n```\n</Good>\n\n### Address \"Spirit vs Letter\" Arguments\n\nAdd foundational principle early:\n\n```markdown\n**Violating the letter of the rules is violating the spirit of the rules.**\n```\n\nThis cuts off entire class of \"I''m following the spirit\" rationalizations.\n\n### Build Rationalization Table\n\nCapture rationalizations from baseline testing (see Testing section below). Every excuse agents make goes in the table:\n\n```markdown\n| Excuse | Reality |\n|--------|---------|\n| \"Too simple to test\" | Simple code breaks. Test takes 30 seconds. |\n| \"I''ll test after\" | Tests passing immediately prove nothing. |\n| \"Tests after achieve same goals\" | Tests-after = \"what does this do?\" Tests-first = \"what should this do?\" |\n```\n\n### Create Red Flags List\n\nMake it easy for agents to self-check when rationalizing:\n\n```markdown\n## Red Flags - STOP and Start Over\n\n- Code before test\n- \"I already manually tested it\"\n- \"Tests after achieve the same purpose\"\n- \"It''s about spirit not ritual\"\n- \"This is different because...\"\n\n**All of these mean: Delete code. Start over with TDD.**\n```\n\n### Update CSO for Violation Symptoms\n\nAdd to description: symptoms of when you''re ABOUT to violate the rule:\n\n```yaml\ndescription: use when implementing any feature or bugfix, before writing implementation code\n```\n\n## RED-GREEN-REFACTOR for Skills\n\nFollow the TDD cycle:\n\n### RED: Write Failing Test (Baseline)\n\nRun pressure scenario with subagent WITHOUT the skill. Document exact behavior:\n- What choices did they make?\n- What rationalizations did they use (verbatim)?\n- Which pressures triggered violations?\n\nThis is \"watch the test fail\" - you must see what agents naturally do before writing the skill.\n\n### GREEN: Write Minimal Skill\n\nWrite skill that addresses those specific rationalizations. Don''t add extra content for hypothetical cases.\n\nRun same scenarios WITH skill. Agent should now comply.\n\n### REFACTOR: Close Loopholes\n\nAgent found new rationalization? Add explicit counter. Re-test until bulletproof.\n\n**Testing methodology:** See @testing-skills-with-subagents.md for the complete testing methodology:\n- How to write pressure scenarios\n- Pressure types (time, sunk cost, authority, exhaustion)\n- Plugging holes systematically\n- Meta-testing techniques\n\n## Anti-Patterns\n\n### ❌ Narrative Example\n\"In session 2025-10-03, we found empty projectDir caused...\"\n**Why bad:** Too specific, not reusable\n\n### ❌ Multi-Language Dilution\nexample-js.js, example-py.py, example-go.go\n**Why bad:** Mediocre quality, maintenance burden\n\n### ❌ Code in Flowcharts\n```dot\nstep1 [label=\"import fs\"];\nstep2 [label=\"read file\"];\n```\n**Why bad:** Can''t copy-paste, hard to read\n\n### ❌ Generic Labels\nhelper1, helper2, step3, pattern4\n**Why bad:** Labels should have semantic meaning\n\n## STOP: Before Moving to Next Skill\n\n**After writing ANY skill, you MUST STOP and complete the deployment process.**\n\n**Do NOT:**\n- Create multiple skills in batch without testing each\n- Move to next skill before current one is verified\n- Skip testing because \"batching is more efficient\"\n\n**The deployment checklist below is MANDATORY for EACH skill.**\n\nDeploying untested skills = deploying untested code. It''s a violation of quality standards.\n\n## Skill Creation Checklist (TDD Adapted)\n\n**IMPORTANT: Use TodoWrite to create todos for EACH checklist item below.**\n\n**RED Phase - Write Failing Test:**\n- [ ] Create pressure scenarios (3+ combined pressures for discipline skills)\n- [ ] Run scenarios WITHOUT skill - document baseline behavior verbatim\n- [ ] Identify patterns in rationalizations/failures\n\n**GREEN Phase - Write Minimal Skill:**\n- [ ] Name uses only letters, numbers, hyphens (no parentheses/special chars)\n- [ ] YAML frontmatter with only name and description (max 1024 chars)\n- [ ] Description starts with \"Use when...\" and includes specific triggers/symptoms\n- [ ] Description written in third person\n- [ ] Keywords throughout for search (errors, symptoms, tools)\n- [ ] Clear overview with core principle\n- [ ] Address specific baseline failures identified in RED\n- [ ] Code inline OR link to separate file\n- [ ] One excellent example (not multi-language)\n- [ ] Run scenarios WITH skill - verify agents now comply\n\n**REFACTOR Phase - Close Loopholes:**\n- [ ] Identify NEW rationalizations from testing\n- [ ] Add explicit counters (if discipline skill)\n- [ ] Build rationalization table from all test iterations\n- [ ] Create red flags list\n- [ ] Re-test until bulletproof\n\n**Quality Checks:**\n- [ ] Small flowchart only if decision non-obvious\n- [ ] Quick reference table\n- [ ] Common mistakes section\n- [ ] No narrative storytelling\n- [ ] Supporting files only for tools or heavy reference\n\n**Deployment:**\n- [ ] Commit skill to git and push to your fork (if configured)\n- [ ] Consider contributing back via PR (if broadly useful)\n\n## Discovery Workflow\n\nHow future Claude finds your skill:\n\n1. **Encounters problem** (\"tests are flaky\")\n3. **Finds SKILL** (description matches)\n4. **Scans overview** (is this relevant?)\n5. **Reads patterns** (quick reference table)\n6. **Loads example** (only when implementing)\n\n**Optimize for this flow** - put searchable terms early and often.\n\n## The Bottom Line\n\n**Creating skills IS TDD for process documentation.**\n\nSame Iron Law: No skill without failing test first.\nSame cycle: RED (baseline) → GREEN (write skill) → REFACTOR (close loopholes).\nSame benefits: Better quality, fewer surprises, bulletproof results.\n\nIf you follow TDD for code, follow it for skills. It''s the same discipline applied to documentation.\n"},"category":"official","lastSynced":"2026-03-06T03:39:52.794Z","seo":{"title":{"en":"writing-skills: TDD for AI Agent Documentation | Skill Guide","zh":"Writing Skills Setup Guide - AIエージェント文档测试驱动开发","ja":"Writing Skills ベストプラクティス - AIエージェントのテスト駆動開発","ko":"Writing Skills 구축 가이드 - AI 에이전트 문서 테스트 주도 개발","es":"Guía de configuración de habilidades de escritura para Ag...","fr":"Guide de mise en place des compétences d''écriture pour le...","de":"Einrichtungsleitfaden für Schreibfähigkeiten bei KI-Agents","pt":"Guia de Configuração de Habilidades de Escrita para Ferra...","ru":"Настройка Навыков Написания для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد مهارات الكتابة للأدوات الذكية"},"description":{"en":"Master test-driven documentation for AI agents with writing-skills. Learn to create pressure scenarios, verify agent compliance, and deploy skills to ~/.clau...","zh":"了解Writing Skills的技术细节，包括测试驱动开发、压力场景和子代理，实现AIエージェント文档的自动化测试","ja":"Writing Skillsのテスト駆動開発を実践するためのガイド。AIエージェントの文書化と自動化テストを効率化する","ko":"Writing Skills를 사용하여 AI 에이전트 문서의 테스트 주도 개발을 구현하고 자동화 테스트를 효율화하는 방법을 알아보세요","es":"Aprende a crear y probar habilidades de escritura para Agentes de IA con nuestra guía paso a paso","fr":"Découvrez comment créer et tester des compétences d''écriture pour les Outils d''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Schreibfähigkeiten für KI-Agents erstellen und testen können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a criar e editar habilidades de escrita para ferramentas de IA com testes e documentação","ru":"Создавайте и редактируйте навыки написания для ИИ агентов с помощью тестирования и документации","ar":"تعلم كيفية إنشاء وتحرير مهارات الكتابة للأدوات الذكية باستخدام الاختبارات والتوثيق"},"definition":{"en":"writing-skills is Test-Driven Development applied to AI agent process documentation. It involves creating pressure scenarios with subagents, watching baseline failures, writing documentation skills, verifying agent compliance, and refactoring loopholes for Claude Code and Codex agents.","zh":"Writing Skills是AIエージェント文档的测试驱动开发方法","ja":"Writing SkillsはAIエージェントの文書化のためのテスト駆動開発手法です","ko":"Writing Skills는 AI 에이전트 문서를 위한 테스트 주도 개발 방법입니다","es":"La habilidad de escritura es un enfoque de desarrollo que aplica pruebas dirigidas para documentar procesos","fr":"La compétence d''écriture est une approche de développement qui applique des tests dirigés pour documenter les processus","de":"Die Schreibfähigkeit ist ein Entwicklungsansatz, der testgetriebene Entwicklung für die Prozessdokumentation anwendet","pt":"Habilidades de escrita são capacidades de documentação de processos para ferramentas de IA","ru":"Навыки написания - это способности документирования процессов для ИИ агентов","ar":"مهارات الكتابة هي قدرات توثيق العمليات للأدوات الذكية"},"features":{"en":["Implements Test-Driven Development for agent documentation workflows","Creates pressure scenarios using subagents for testing","Deploys skills to agent-specific directories (~/.claude/skills for Claude Code)","Supports skill verification before deployment compliance","Enables refactoring to close documentation loopholes","Works with both Claude Code and Codex agent systems"],"zh":["测试驱动开发","压力场景和子代理","自动化测试","文档重构","CLI集成","Agent-specific目录支持"],"ja":["テスト駆動開発","プレッシャーシナリオとサブエージェント","自動化テスト","文書のリファクタリング","CLI統合","エージェント固有のディレクトリサポート"],"ko":["테스트 주도 개발","압력 시나리오 및 서브 에이전트","자동화 테스트","문서 리팩터링","CLI 통합","에이전트 고유 디렉토리 지원"],"es":["Utiliza subagentes y escenarios de presión para probar habilidades","Permite la creación de habilidades personalizadas en directorios de agentes específicos","Soporta la refactorización de habilidades para cerrar brechas","Utiliza pruebas dirigidas para garantizar la calidad de la documentación","Permite la verificación de habilidades antes de la implementación"],"fr":["Utilise des sous-agents et des scénarios de pression pour tester les compétences","Permet la création de compétences personnalisées dans des répertoires d''agents spécifiques","Prend en charge la refactorisation des compétences pour fermer les lacunes","Utilise des tests dirigés pour garantir la qualité de la documentation","Permet la vérification des compétences avant la mise en production"],"de":["Verwendet Subagenten und Druckszenarien, um Fähigkeiten zu testen","Ermöglicht die Erstellung benutzerdefinierter Fähigkeiten in agentspezifischen Verzeichnissen","Unterstützt die Refaktorisierung von Fähigkeiten, um Lücken zu schließen","Verwendet testgetriebene Entwicklung, um die Qualität der Dokumentation zu gewährleisten","Ermöglicht die Überprüfung von Fähigkeiten vor der Implementierung"],"pt":["Test-Driven Development aplicado à documentação de processos","Criação de casos de teste com subagentes","Refatoração de habilidades para fechar lacunas","Uso de diretórios específicos para armazenar habilidades (por exemplo, ~/.claude/skills)","Compatibilidade com Claude Code e Codex"],"ru":["Разработка через тестирование, примененная к документации процессов","Создание тестовых случаев с субагентами","Рефакторинг навыков для закрытия лазеек","Использование специальных директорий для хранения навыков (например, ~/.agents/skills/)","Совместимость с Claude Code и Codex"],"ar":["التطوير الموجه للاختبار المطبق على توثيق العمليات","إنشاء حالات اختبار مع وكلاء فرعيين","إعادة هيكلة مهارات لسد الثغرات","استخدام دلائل محددة لتخزين مهارات (على سبيل المثال، ~/.claude/skills)","التوافق مع Claude Code و Codex"]},"keywords":{"en":["writing-skills TDD documentation","how to use writing-skills AI agents","writing-skills vs traditional documentation","install writing-skills Claude Code","writing-skills setup guide","AI agent pressure scenarios","~/.claude/skills directory setup","Codex agent skill deployment","test-driven development AI documentation"],"zh":["AIエージェント","测试驱动开发","Writing Skills","文档自动化测试","CLI","Agent-specific目录","压力场景","子代理","自动化测试"],"ja":["AIエージェント","テスト駆動開発","Writing Skills","文書自動化テスト","CLI","エージェント固有のディレクトリ","プレッシャーシナリオ","サブエージェント","自動化テスト"],"ko":["AI 에이전트","테스트 주도 개발","Writing Skills","문서 자동화 테스트","CLI","에이전트 고유 디렉토리","압력 시나리오","서브 에이전트","자동화 테스트"],"es":["habilidades de escritura para Agentes de IA","desarrollo dirigido por pruebas","documentación de procesos","subagentes","escenarios de presión","refactorización de habilidades","pruebas dirigidas","verificación de habilidades"],"fr":["compétences d''écriture pour les Outils d''IA","développement dirigé par des tests","documentation de processus","sous-agents","scénarios de pression","refactorisation des compétences","tests dirigés","vérification des compétences"],"de":["Schreibfähigkeiten für KI-Agents","testgetriebene Entwicklung","Prozessdokumentation","Subagenten","Druckszenarien","Refaktorisierung von Fähigkeiten","testgetriebene Entwicklung","Überprüfung von Fähigkeiten"],"pt":["habilidades de escrita para ferramentas de IA","desenvolvimento orientado a testes","documentação de processos","testes de unidade","refatoração de habilidades","ferramentas de IA","Claude Code","Codex"],"ru":["навыки написания для ИИ агентов","разработка через тестирование","документирование процессов","юнит-тесты","рефакторинг навыков","ИИ агенты","Claude Code","Codex"],"ar":["مهارات الكتابة للأدوات الذكية","التطوير الموجه للاختبار","توثيق العمليات","اختبارات الوحدة","إعادة هيكلة مهارات","أدوات ذكية","Claude Code","Codex"]}},"agentAnalysis":{"suitability":{"en":"Essential for Documentation Agents implementing Test-Driven Development for process documentation.","zh":"对于实施测试驱动开发以进行流程文档编写的文档代理至关重要。","ja":"プロセスドキュメンテーションのためのテスト駆動開発を実装するドキュメンテーションエージェントに不可欠です。","ko":"프로세스 문서화를 위한 테스트 주도 개발을 구현하는 문서화 에이전트에 필수적입니다.","es":"Esencial para agentes de documentación que implementan Desarrollo Guiado por Pruebas para la documentación de procesos.","fr":"Essentiel pour les agents de documentation mettant en œuvre le Développement Piloté par les Tests pour la documentation des processus.","de":"Essenziell für Dokumentationsagenten, die testgetriebene Entwicklung für die Prozessdokumentation implementieren.","pt":"Essencial para Agentes de Documentação que implementam Desenvolvimento Orientado a Testes para documentação de processos.","ru":"Необходимо для Агентов Документации, реализующих Разработку через Тестирование для документирования процессов.","ar":"أساسي لوكلاء التوثيق الذين ينفذون التطوير القائم على الاختبارات لتوثيق العمليات."},"recommendation":{"en":"Enables agents to apply TDD methodology to documentation creation by writing pressure scenarios with subagents, establishing baseline failure behavior, and refining documentation through iterative testing cycles. This transforms documentation from passive text to verified, agent-compliant processes stored in agent-specific directories (~/.claude/skills or ~/.agents/skills/).","zh":"使代理能够通过编写带有子代理的压力测试场景、建立基线失败行为以及通过迭代测试周期完善文档，将TDD方法论应用于文档创建。这将文档从被动文本转变为经过验证的、符合代理要求的流程，并存储在代理特定目录中（~/.claude/skills 或 ~/.agents/skills/）。","ja":"サブエージェントを使用したプレッシャースシナリオの作成、ベースラインの失敗動作の確立、反復的なテストサイクルによるドキュメンテーションの改良を通じて、エージェントがTDD方法論をドキュメンテーション作成に適用できるようにします。これにより、ドキュメンテーションは受動的なテキストから、検証済みでエージェント準拠のプロセスに変わり、エージェント固有のディレクトリ（~/.claude/skills または ~/.agents/skills/）に保存されます。","ko":"하위 에이전트로 압력 시나리오를 작성하고, 기준 실패 동작을 설정하며, 반복적인 테스트 주기를 통해 문서를 개선함으로써 에이전트가 문서 생성에 TDD 방법론을 적용할 수 있게 합니다. 이는 문서를 수동적인 텍스트에서 검증된 에이전트 호환 프로세스로 변환하여 에이전트 특정 디렉토리(~/.claude/skills 또는 ~/.agents/skills/)에 저장합니다.","es":"Permite a los agentes aplicar la metodología TDD a la creación de documentación mediante la escritura de escenarios de presión con subagentes, estableciendo un comportamiento de fallo de referencia y refinando la documentación a través de ciclos de prueba iterativos. Esto transforma la documentación de texto pasivo a procesos verificados y compatibles con agentes almacenados en directorios específicos de agentes (~/.claude/skills o ~/.agents/skills/).","fr":"Permet aux agents d''appliquer la méthodologie TDD à la création de documentation en écrivant des scénarios de pression avec des sous-agents, en établissant un comportement d''échec de base et en affinant la documentation grâce à des cycles de test itératifs. Cela transforme la documentation d''un texte passif en processus vérifiés et conformes aux agents stockés dans des répertoires spécifiques aux agents (~/.claude/skills ou ~/.agents/skills/).","de":"Ermöglicht es Agenten, die TDD-Methodik für die Erstellung von Dokumentation anzuwenden, indem sie Drucktestszenarien mit Subagenten schreiben, ein Baseline-Fehlverhalten festlegen und die Dokumentation durch iterative Testzyklen verfeinern. Dies verwandelt Dokumentation von passivem Text in verifizierte, agentenkonforme Prozesse, die in agentspezifischen Verzeichnissen gespeichert werden (~/.claude/skills oder ~/.agents/skills/).","pt":"Permite que os agentes apliquem a metodologia TDD à criação de documentação, escrevendo cenários de pressão com subagentes, estabelecendo comportamento de falha de linha de base e refinando a documentação através de ciclos iterativos de teste. Isso transforma a documentação de texto passivo em processos verificados e compatíveis com agentes, armazenados em diretórios específicos de agentes (~/.claude/skills ou ~/.agents/skills/).","ru":"Позволяет агентам применять методологию TDD для создания документации путем написания сценариев нагрузки с субагентами, установления базового поведения при сбоях и совершенствования документации посредством итеративных циклов тестирования. Это преобразует документацию из пассивного текста в проверенные процессы, совместимые с агентами, хранящиеся в специальных директориях агентов (~/.claude/skills или ~/.agents/skills/).","ar":"يمكن الوكلاء من تطبيق منهجية TDD لإنشاء التوثيق من خلال كتابة سيناريوهات الضغط مع الوكلاء الفرعيين، وإنشاء سلوك الفشل الأساسي، وتحسين التوثيق من خلال دورات الاختبار التكراري. هذا يحول التوثيق من نص سلبي إلى عمليات تم التحقق منها ومتوافقة مع الوكلاء، مخزنة في أدلة مخصصة للوكلاء (~/.claude/skills أو ~/.agents/skills/)."},"useCases":{"en":["Creating test-driven process documentation","Validating agent compliance through scenario testing","Refining documentation by closing loopholes identified in failure modes","Establishing baseline behavior metrics for documentation quality"],"zh":["创建测试驱动的流程文档","通过场景测试验证代理合规性","通过弥补在失败模式中发现的漏洞来完善文档","为文档质量建立基线行为指标"],"ja":["テスト駆動型のプロセスドキュメンテーションの作成","シナリオテストによるエージェントのコンプライアンス検証","失敗モードで特定された抜け穴を解消することによるドキュメンテーションの改良","ドキュメンテーション品質のためのベースライン動作指標の確立"],"ko":["테스트 주도 프로세스 문서 생성","시나리오 테스트를 통한 에이전트 준수성 검증","실패 모드에서 식별된 허점을 해결하여 문서 개선","문서 품질을 위한 기준 동작 메트릭 설정"],"es":["Creación de documentación de procesos guiada por pruebas","Validación del cumplimiento del agente mediante pruebas de escenarios","Refinamiento de la documentación mediante el cierre de lagunas identificadas en modos de fallo","Establecimiento de métricas de comportamiento de referencia para la calidad de la documentación"],"fr":["Création de documentation de processus pilotée par les tests","Validation de la conformité des agents par des tests de scénarios","Affinage de la documentation en comblant les lacunes identifiées dans les modes de défaillance","Établissement de métriques de comportement de référence pour la qualité de la documentation"],"de":["Erstellung testgetriebener Prozessdokumentation","Validierung der Agentenkonformität durch Szenariotests","Verfeinerung der Dokumentation durch Schließen von in Fehlermodi identifizierten Lücken","Etablierung von Baseline-Verhaltensmetriken für die Dokumentationsqualität"],"pt":["Criar documentação de processos orientada a testes","Validar a conformidade do agente por meio de testes de cenários","Refinar a documentação fechando lacunas identificadas em modos de falha","Estabelecer métricas de comportamento de linha de base para qualidade da documentação"],"ru":["Создание тестовой документации процессов","Проверка соответствия агентов с помощью тестирования сценариев","Совершенствование документации путем устранения выявленных недостатков в режимах сбоев","Установление базовых метрик поведения для качества документации"],"ar":["إنشاء توثيق العمليات القائم على الاختبارات","التحقق من امتثال الوكيل من خلال اختبار السيناريوهات","تحسين التوثيق من خلال سد الثغرات التي تم تحديدها في أوضاع الفشل","إنشاء مقاييس السلوك الأساسية لجودة التوثيق"]},"limitations":{"en":["Requires agent-specific directory structure knowledge","Depends on subagent capability for pressure testing","Needs iterative testing cycles for full effectiveness"],"zh":["需要了解代理特定的目录结构知识","依赖子代理的能力进行压力测试","需要迭代测试周期才能充分发挥效果"],"ja":["エージェント固有のディレクトリ構造の知識が必要","プレッシャーテストにはサブエージェントの能力に依存","完全な効果を得るには反復的なテストサイクルが必要"],"ko":["에이전트 특정 디렉토리 구조 지식 필요","압력 테스트를 위한 하위 에이전트 능력에 의존","완전한 효과를 위해 반복적인 테스트 주기 필요"],"es":["Requiere conocimiento de la estructura de directorios específica del agente","Depende de la capacidad del subagente para las pruebas de presión","Necesita ciclos de prueba iterativos para su máxima efectividad"],"fr":["Nécessite une connaissance de la structure de répertoires spécifique à l''agent","Dépend de la capacité des sous-agents pour les tests de pression","Nécessite des cycles de test itératifs pour une efficacité complète"],"de":["Erfordert Kenntnisse der agentspezifischen Verzeichnisstruktur","Hängt von der Fähigkeit des Subagenten für Drucktests ab","Benötigt iterative Testzyklen für volle Wirksamkeit"],"pt":["Requer conhecimento da estrutura de diretórios específica do agente","Depende da capacidade do subagente para testes de pressão","Requer ciclos iterativos de teste para eficácia total"],"ru":["Требует знания структуры каталогов, специфичной для агента","Зависит от возможности субагента для нагрузочного тестирования","Требует итеративных циклов тестирования для полной эффективности"],"ar":["يتطلب معرفة بهيكل الدليل المخصص للوكيل","يعتمد على قدرة الوكيل الفرعي لاختبارات الضغط","يحتاج إلى دورات اختبار تكرارية للفعالية الكاملة"]},"version":4},"contentHash":"d83a09d6a1c6976f6cc2f40addeae653a4a6eb5903097ebc365d90242e00e379","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":95}');
