INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/writing-skills', 'writing-skills', 'obra', 'superpowers', 'official', 'writing-skills obra superpowers official The writing-skills framework applies Test-Driven Development principles to AI agent documentation. Developers create test cases with subagents, write skills, and verify compliance before deploying to agent-specific directories like ~/.claude/skills. Writing Skills是测试驱动开发应用于AIエージェント文档的过程，涉及写测试用例、观察失败、编写文档和重构 Writing Skillsは、AIエージェントの文書化にテスト駆動開発を適用するプロセスで、テストケースの作成、失敗の観察、文書の作成、リファクタリングが含まれます Writing Skills는 AI 에이전트 문서에 테스트 주도 개발을 적용하는 과정으로 테스트 케이스 작성, 실패 관찰, 문서 작성 및 리팩터링이 포함됩니다 La habilidad de escritura es un enfoque de desarrollo dirigido por pruebas para la documentación de procesos, que utiliza subagentes y escenarios de presión La compétence d''écriture est une approche de développement dirigée par des tests pour la documentation de processus, qui utilise des sous-agents et des scénarios de pression Die Schreibfähigkeit ist ein testgetriebener Ansatz für die Prozessdokumentation, der Subagenten und Druckszenarien verwendet As habilidades de escrita aplicam o desenvolvimento orientado a testes à documentação de processos Навыки написания применяют разработку через тестирование к документации процессов مهارات الكتابة تطبق التطوير الموجه للاختبار على توثيق العمليات writing-skills TDD documentation how to use writing-skills AI agents writing-skills vs traditional documentation install writing-skills Claude Code writing-skills setup guide AI agent pressure scenarios ~/.claude/skills directory setup Codex agent skill deployment test-driven development AI documentation AIエージェント 测试驱动开发 Writing Skills 文档自动化测试 CLI Agent-specific目录 压力场景 子代理 自动化测试 Implements Test-Driven Development for agent documentation workflows Creates pressure scenarios using subagents for testing Deploys skills to agent-specific directories (~/.claude/skills for Claude Code) Supports skill verification before deployment compliance Enables refactoring to close documentation loopholes Works with both Claude Code and Codex agent systems writing-skills is Test-Driven Development applied to AI agent process documentation. It involves creating pressure scenarios with subagents, watching baseline failures, writing documentation skills, verifying agent compliance, and refactoring loopholes for Claude Code and Codex agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/cpp-coding-standards', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'cpp-coding-standards', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T03:57:45.841Z', '70919980c635f66db649b7eb1e426fb2098754ed6c9db22f1a7eee0935227d35', '{"id":"affaan-m/everything-claude-code/cpp-coding-standards","name":"cpp-coding-standards","description":{"en":"The cpp-coding-standards skill provides comprehensive coding standards for modern C++ based on the C++ Core Guidelines, benefiting developers who write, review, or refactor C++ code.","zh":"C++编码标准AI代理根据C++ Core Guidelines提供现代、安全、惯用的C++编码实践","ja":"C++コーディングスタンダードAIエージェントは、C++ Core Guidelinesに基づく現代的、安全、慣用的C++コードを提供します","ko":"C++ 코딩 표준 AI 에이전트는 C++ Core Guidelines 기반의 현대적이고 안전하고 관용적인 C++ 코딩 관행을 제공합니다","es":"Estándares de codificación C++ basados en las C++ Core Guidelines para un código más seguro y moderno","fr":"Normes de codage C++ basées sur les C++ Core Guidelines pour un code plus sûr et plus moderne","de":"C++-Codierstandards basierend auf den C++ Core Guidelines für sichereren und moderneren Code","pt":"Padrões de codificação C++ baseados nas Diretrizes Centrais C++ para garantir práticas modernas, seguras e idiomáticas","ru":"Стандарты кодирования C++ на основе Руководства по核心 C++ для обеспечения современных, безопасных и идиоматических практик","ar":"معايير برمجة سي++ على أساس مرجع سي++ الأساسي لضمان ممارسات حديثة وأمنية ومتوافقة"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"cpp-coding-standards","description":"C++ coding standards based on the C++ Core Guidelines (isocpp.github.io). Use when writing, reviewing, or refactoring C++ code to enforce modern, safe, and idiomatic practices.","bodyPreview":"# C++ Coding Standards (C++ Core Guidelines)\n\nComprehensive coding standards for modern C++ (C++17/20/23) derived from the [C++ Core Guidelines](https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines). Enforces type safety, resource safety, immutability, and clarity.\n\n## When to Use\n\n- Writing new C++ code (classes, functions, templates)\n- Reviewing or refactoring existing C++ code\n- Making architectural decisions in C++ projects\n- Enforcing consistent style across a C++ codebase\n- Choosin","body":"# C++ Coding Standards (C++ Core Guidelines)\n\nComprehensive coding standards for modern C++ (C++17/20/23) derived from the [C++ Core Guidelines](https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines). Enforces type safety, resource safety, immutability, and clarity.\n\n## When to Use\n\n- Writing new C++ code (classes, functions, templates)\n- Reviewing or refactoring existing C++ code\n- Making architectural decisions in C++ projects\n- Enforcing consistent style across a C++ codebase\n- Choosing between language features (e.g., `enum` vs `enum class`, raw pointer vs smart pointer)\n\n### When NOT to Use\n\n- Non-C++ projects\n- Legacy C codebases that cannot adopt modern C++ features\n- Embedded/bare-metal contexts where specific guidelines conflict with hardware constraints (adapt selectively)\n\n## Cross-Cutting Principles\n\nThese themes recur across the entire guidelines and form the foundation:\n\n1. **RAII everywhere** (P.8, R.1, E.6, CP.20): Bind resource lifetime to object lifetime\n2. **Immutability by default** (P.10, Con.1-5, ES.25): Start with `const`/`constexpr`; mutability is the exception\n3. **Type safety** (P.4, I.4, ES.46-49, Enum.3): Use the type system to prevent errors at compile time\n4. **Express intent** (P.3, F.1, NL.1-2, T.10): Names, types, and concepts should communicate purpose\n5. **Minimize complexity** (F.2-3, ES.5, Per.4-5): Simple code is correct code\n6. **Value semantics over pointer semantics** (C.10, R.3-5, F.20, CP.31): Prefer returning by value and scoped objects\n\n## Philosophy & Interfaces (P.*, I.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **P.1** | Express ideas directly in code |\n| **P.3** | Express intent |\n| **P.4** | Ideally, a program should be statically type safe |\n| **P.5** | Prefer compile-time checking to run-time checking |\n| **P.8** | Don''t leak any resources |\n| **P.10** | Prefer immutable data to mutable data |\n| **I.1** | Make interfaces explicit |\n| **I.2** | Avoid non-const global variables |\n| **I.4** | Make interfaces precisely and strongly typed |\n| **I.11** | Never transfer ownership by a raw pointer or reference |\n| **I.23** | Keep the number of function arguments low |\n\n### DO\n\n```cpp\n// P.10 + I.4: Immutable, strongly typed interface\nstruct Temperature {\n    double kelvin;\n};\n\nTemperature boil(const Temperature& water);\n```\n\n### DON''T\n\n```cpp\n// Weak interface: unclear ownership, unclear units\ndouble boil(double* temp);\n\n// Non-const global variable\nint g_counter = 0;  // I.2 violation\n```\n\n## Functions (F.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **F.1** | Package meaningful operations as carefully named functions |\n| **F.2** | A function should perform a single logical operation |\n| **F.3** | Keep functions short and simple |\n| **F.4** | If a function might be evaluated at compile time, declare it `constexpr` |\n| **F.6** | If your function must not throw, declare it `noexcept` |\n| **F.8** | Prefer pure functions |\n| **F.16** | For \"in\" parameters, pass cheaply-copied types by value and others by `const&` |\n| **F.20** | For \"out\" values, prefer return values to output parameters |\n| **F.21** | To return multiple \"out\" values, prefer returning a struct |\n| **F.43** | Never return a pointer or reference to a local object |\n\n### Parameter Passing\n\n```cpp\n// F.16: Cheap types by value, others by const&\nvoid print(int x);                           // cheap: by value\nvoid analyze(const std::string& data);       // expensive: by const&\nvoid transform(std::string s);               // sink: by value (will move)\n\n// F.20 + F.21: Return values, not output parameters\nstruct ParseResult {\n    std::string token;\n    int position;\n};\n\nParseResult parse(std::string_view input);   // GOOD: return struct\n\n// BAD: output parameters\nvoid parse(std::string_view input,\n           std::string& token, int& pos);    // avoid this\n```\n\n### Pure Functions and constexpr\n\n```cpp\n// F.4 + F.8: Pure, constexpr where possible\nconstexpr int factorial(int n) noexcept {\n    return (n <= 1) ? 1 : n * factorial(n - 1);\n}\n\nstatic_assert(factorial(5) == 120);\n```\n\n### Anti-Patterns\n\n- Returning `T&&` from functions (F.45)\n- Using `va_arg` / C-style variadics (F.55)\n- Capturing by reference in lambdas passed to other threads (F.53)\n- Returning `const T` which inhibits move semantics (F.49)\n\n## Classes & Class Hierarchies (C.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **C.2** | Use `class` if invariant exists; `struct` if data members vary independently |\n| **C.9** | Minimize exposure of members |\n| **C.20** | If you can avoid defining default operations, do (Rule of Zero) |\n| **C.21** | If you define or `=delete` any copy/move/destructor, handle them all (Rule of Five) |\n| **C.35** | Base class destructor: public virtual or protected non-virtual |\n| **C.41** | A constructor should create a fully initialized object |\n| **C.46** | Declare single-argument constructors `explicit` |\n| **C.67** | A polymorphic class should suppress public copy/move |\n| **C.128** | Virtual functions: specify exactly one of `virtual`, `override`, or `final` |\n\n### Rule of Zero\n\n```cpp\n// C.20: Let the compiler generate special members\nstruct Employee {\n    std::string name;\n    std::string department;\n    int id;\n    // No destructor, copy/move constructors, or assignment operators needed\n};\n```\n\n### Rule of Five\n\n```cpp\n// C.21: If you must manage a resource, define all five\nclass Buffer {\npublic:\n    explicit Buffer(std::size_t size)\n        : data_(std::make_unique<char[]>(size)), size_(size) {}\n\n    ~Buffer() = default;\n\n    Buffer(const Buffer& other)\n        : data_(std::make_unique<char[]>(other.size_)), size_(other.size_) {\n        std::copy_n(other.data_.get(), size_, data_.get());\n    }\n\n    Buffer& operator=(const Buffer& other) {\n        if (this != &other) {\n            auto new_data = std::make_unique<char[]>(other.size_);\n            std::copy_n(other.data_.get(), other.size_, new_data.get());\n            data_ = std::move(new_data);\n            size_ = other.size_;\n        }\n        return *this;\n    }\n\n    Buffer(Buffer&&) noexcept = default;\n    Buffer& operator=(Buffer&&) noexcept = default;\n\nprivate:\n    std::unique_ptr<char[]> data_;\n    std::size_t size_;\n};\n```\n\n### Class Hierarchy\n\n```cpp\n// C.35 + C.128: Virtual destructor, use override\nclass Shape {\npublic:\n    virtual ~Shape() = default;\n    virtual double area() const = 0;  // C.121: pure interface\n};\n\nclass Circle : public Shape {\npublic:\n    explicit Circle(double r) : radius_(r) {}\n    double area() const override { return 3.14159 * radius_ * radius_; }\n\nprivate:\n    double radius_;\n};\n```\n\n### Anti-Patterns\n\n- Calling virtual functions in constructors/destructors (C.82)\n- Using `memset`/`memcpy` on non-trivial types (C.90)\n- Providing different default arguments for virtual function and overrider (C.140)\n- Making data members `const` or references, which suppresses move/copy (C.12)\n\n## Resource Management (R.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **R.1** | Manage resources automatically using RAII |\n| **R.3** | A raw pointer (`T*`) is non-owning |\n| **R.5** | Prefer scoped objects; don''t heap-allocate unnecessarily |\n| **R.10** | Avoid `malloc()`/`free()` |\n| **R.11** | Avoid calling `new` and `delete` explicitly |\n| **R.20** | Use `unique_ptr` or `shared_ptr` to represent ownership |\n| **R.21** | Prefer `unique_ptr` over `shared_ptr` unless sharing ownership |\n| **R.22** | Use `make_shared()` to make `shared_ptr`s |\n\n### Smart Pointer Usage\n\n```cpp\n// R.11 + R.20 + R.21: RAII with smart pointers\nauto widget = std::make_unique<Widget>(\"config\");  // unique ownership\nauto cache  = std::make_shared<Cache>(1024);        // shared ownership\n\n// R.3: Raw pointer = non-owning observer\nvoid render(const Widget* w) {  // does NOT own w\n    if (w) w->draw();\n}\n\nrender(widget.get());\n```\n\n### RAII Pattern\n\n```cpp\n// R.1: Resource acquisition is initialization\nclass FileHandle {\npublic:\n    explicit FileHandle(const std::string& path)\n        : handle_(std::fopen(path.c_str(), \"r\")) {\n        if (!handle_) throw std::runtime_error(\"Failed to open: \" + path);\n    }\n\n    ~FileHandle() {\n        if (handle_) std::fclose(handle_);\n    }\n\n    FileHandle(const FileHandle&) = delete;\n    FileHandle& operator=(const FileHandle&) = delete;\n    FileHandle(FileHandle&& other) noexcept\n        : handle_(std::exchange(other.handle_, nullptr)) {}\n    FileHandle& operator=(FileHandle&& other) noexcept {\n        if (this != &other) {\n            if (handle_) std::fclose(handle_);\n            handle_ = std::exchange(other.handle_, nullptr);\n        }\n        return *this;\n    }\n\nprivate:\n    std::FILE* handle_;\n};\n```\n\n### Anti-Patterns\n\n- Naked `new`/`delete` (R.11)\n- `malloc()`/`free()` in C++ code (R.10)\n- Multiple resource allocations in a single expression (R.13 -- exception safety hazard)\n- `shared_ptr` where `unique_ptr` suffices (R.21)\n\n## Expressions & Statements (ES.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **ES.5** | Keep scopes small |\n| **ES.20** | Always initialize an object |\n| **ES.23** | Prefer `{}` initializer syntax |\n| **ES.25** | Declare objects `const` or `constexpr` unless modification is intended |\n| **ES.28** | Use lambdas for complex initialization of `const` variables |\n| **ES.45** | Avoid magic constants; use symbolic constants |\n| **ES.46** | Avoid narrowing/lossy arithmetic conversions |\n| **ES.47** | Use `nullptr` rather than `0` or `NULL` |\n| **ES.48** | Avoid casts |\n| **ES.50** | Don''t cast away `const` |\n\n### Initialization\n\n```cpp\n// ES.20 + ES.23 + ES.25: Always initialize, prefer {}, default to const\nconst int max_retries{3};\nconst std::string name{\"widget\"};\nconst std::vector<int> primes{2, 3, 5, 7, 11};\n\n// ES.28: Lambda for complex const initialization\nconst auto config = [&] {\n    Config c;\n    c.timeout = std::chrono::seconds{30};\n    c.retries = max_retries;\n    c.verbose = debug_mode;\n    return c;\n}();\n```\n\n### Anti-Patterns\n\n- Uninitialized variables (ES.20)\n- Using `0` or `NULL` as pointer (ES.47 -- use `nullptr`)\n- C-style casts (ES.48 -- use `static_cast`, `const_cast`, etc.)\n- Casting away `const` (ES.50)\n- Magic numbers without named constants (ES.45)\n- Mixing signed and unsigned arithmetic (ES.100)\n- Reusing names in nested scopes (ES.12)\n\n## Error Handling (E.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **E.1** | Develop an error-handling strategy early in a design |\n| **E.2** | Throw an exception to signal that a function can''t perform its assigned task |\n| **E.6** | Use RAII to prevent leaks |\n| **E.12** | Use `noexcept` when throwing is impossible or unacceptable |\n| **E.14** | Use purpose-designed user-defined types as exceptions |\n| **E.15** | Throw by value, catch by reference |\n| **E.16** | Destructors, deallocation, and swap must never fail |\n| **E.17** | Don''t try to catch every exception in every function |\n\n### Exception Hierarchy\n\n```cpp\n// E.14 + E.15: Custom exception types, throw by value, catch by reference\nclass AppError : public std::runtime_error {\npublic:\n    using std::runtime_error::runtime_error;\n};\n\nclass NetworkError : public AppError {\npublic:\n    NetworkError(const std::string& msg, int code)\n        : AppError(msg), status_code(code) {}\n    int status_code;\n};\n\nvoid fetch_data(const std::string& url) {\n    // E.2: Throw to signal failure\n    throw NetworkError(\"connection refused\", 503);\n}\n\nvoid run() {\n    try {\n        fetch_data(\"https://api.example.com\");\n    } catch (const NetworkError& e) {\n        log_error(e.what(), e.status_code);\n    } catch (const AppError& e) {\n        log_error(e.what());\n    }\n    // E.17: Don''t catch everything here -- let unexpected errors propagate\n}\n```\n\n### Anti-Patterns\n\n- Throwing built-in types like `int` or string literals (E.14)\n- Catching by value (slicing risk) (E.15)\n- Empty catch blocks that silently swallow errors\n- Using exceptions for flow control (E.3)\n- Error handling based on global state like `errno` (E.28)\n\n## Constants & Immutability (Con.*)\n\n### All Rules\n\n| Rule | Summary |\n|------|---------|\n| **Con.1** | By default, make objects immutable |\n| **Con.2** | By default, make member functions `const` |\n| **Con.3** | By default, pass pointers and references to `const` |\n| **Con.4** | Use `const` for values that don''t change after construction |\n| **Con.5** | Use `constexpr` for values computable at compile time |\n\n```cpp\n// Con.1 through Con.5: Immutability by default\nclass Sensor {\npublic:\n    explicit Sensor(std::string id) : id_(std::move(id)) {}\n\n    // Con.2: const member functions by default\n    const std::string& id() const { return id_; }\n    double last_reading() const { return reading_; }\n\n    // Only non-const when mutation is required\n    void record(double value) { reading_ = value; }\n\nprivate:\n    const std::string id_;  // Con.4: never changes after construction\n    double reading_{0.0};\n};\n\n// Con.3: Pass by const reference\nvoid display(const Sensor& s) {\n    std::cout << s.id() << \": \" << s.last_reading() << ''\\n'';\n}\n\n// Con.5: Compile-time constants\nconstexpr double PI = 3.14159265358979;\nconstexpr int MAX_SENSORS = 256;\n```\n\n## Concurrency & Parallelism (CP.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **CP.2** | Avoid data races |\n| **CP.3** | Minimize explicit sharing of writable data |\n| **CP.4** | Think in terms of tasks, rather than threads |\n| **CP.8** | Don''t use `volatile` for synchronization |\n| **CP.20** | Use RAII, never plain `lock()`/`unlock()` |\n| **CP.21** | Use `std::scoped_lock` to acquire multiple mutexes |\n| **CP.22** | Never call unknown code while holding a lock |\n| **CP.42** | Don''t wait without a condition |\n| **CP.44** | Remember to name your `lock_guard`s and `unique_lock`s |\n| **CP.100** | Don''t use lock-free programming unless you absolutely have to |\n\n### Safe Locking\n\n```cpp\n// CP.20 + CP.44: RAII locks, always named\nclass ThreadSafeQueue {\npublic:\n    void push(int value) {\n        std::lock_guard<std::mutex> lock(mutex_);  // CP.44: named!\n        queue_.push(value);\n        cv_.notify_one();\n    }\n\n    int pop() {\n        std::unique_lock<std::mutex> lock(mutex_);\n        // CP.42: Always wait with a condition\n        cv_.wait(lock, [this] { return !queue_.empty(); });\n        const int value = queue_.front();\n        queue_.pop();\n        return value;\n    }\n\nprivate:\n    std::mutex mutex_;             // CP.50: mutex with its data\n    std::condition_variable cv_;\n    std::queue<int> queue_;\n};\n```\n\n### Multiple Mutexes\n\n```cpp\n// CP.21: std::scoped_lock for multiple mutexes (deadlock-free)\nvoid transfer(Account& from, Account& to, double amount) {\n    std::scoped_lock lock(from.mutex_, to.mutex_);\n    from.balance_ -= amount;\n    to.balance_ += amount;\n}\n```\n\n### Anti-Patterns\n\n- `volatile` for synchronization (CP.8 -- it''s for hardware I/O only)\n- Detaching threads (CP.26 -- lifetime management becomes nearly impossible)\n- Unnamed lock guards: `std::lock_guard<std::mutex>(m);` destroys immediately (CP.44)\n- Holding locks while calling callbacks (CP.22 -- deadlock risk)\n- Lock-free programming without deep expertise (CP.100)\n\n## Templates & Generic Programming (T.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **T.1** | Use templates to raise the level of abstraction |\n| **T.2** | Use templates to express algorithms for many argument types |\n| **T.10** | Specify concepts for all template arguments |\n| **T.11** | Use standard concepts whenever possible |\n| **T.13** | Prefer shorthand notation for simple concepts |\n| **T.43** | Prefer `using` over `typedef` |\n| **T.120** | Use template metaprogramming only when you really need to |\n| **T.144** | Don''t specialize function templates (overload instead) |\n\n### Concepts (C++20)\n\n```cpp\n#include <concepts>\n\n// T.10 + T.11: Constrain templates with standard concepts\ntemplate<std::integral T>\nT gcd(T a, T b) {\n    while (b != 0) {\n        a = std::exchange(b, a % b);\n    }\n    return a;\n}\n\n// T.13: Shorthand concept syntax\nvoid sort(std::ranges::random_access_range auto& range) {\n    std::ranges::sort(range);\n}\n\n// Custom concept for domain-specific constraints\ntemplate<typename T>\nconcept Serializable = requires(const T& t) {\n    { t.serialize() } -> std::convertible_to<std::string>;\n};\n\ntemplate<Serializable T>\nvoid save(const T& obj, const std::string& path);\n```\n\n### Anti-Patterns\n\n- Unconstrained templates in visible namespaces (T.47)\n- Specializing function templates instead of overloading (T.144)\n- Template metaprogramming where `constexpr` suffices (T.120)\n- `typedef` instead of `using` (T.43)\n\n## Standard Library (SL.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **SL.1** | Use libraries wherever possible |\n| **SL.2** | Prefer the standard library to other libraries |\n| **SL.con.1** | Prefer `std::array` or `std::vector` over C arrays |\n| **SL.con.2** | Prefer `std::vector` by default |\n| **SL.str.1** | Use `std::string` to own character sequences |\n| **SL.str.2** | Use `std::string_view` to refer to character sequences |\n| **SL.io.50** | Avoid `endl` (use `''\\n''` -- `endl` forces a flush) |\n\n```cpp\n// SL.con.1 + SL.con.2: Prefer vector/array over C arrays\nconst std::array<int, 4> fixed_data{1, 2, 3, 4};\nstd::vector<std::string> dynamic_data;\n\n// SL.str.1 + SL.str.2: string owns, string_view observes\nstd::string build_greeting(std::string_view name) {\n    return \"Hello, \" + std::string(name) + \"!\";\n}\n\n// SL.io.50: Use ''\\n'' not endl\nstd::cout << \"result: \" << value << ''\\n'';\n```\n\n## Enumerations (Enum.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **Enum.1** | Prefer enumerations over macros |\n| **Enum.3** | Prefer `enum class` over plain `enum` |\n| **Enum.5** | Don''t use ALL_CAPS for enumerators |\n| **Enum.6** | Avoid unnamed enumerations |\n\n```cpp\n// Enum.3 + Enum.5: Scoped enum, no ALL_CAPS\nenum class Color { red, green, blue };\nenum class LogLevel { debug, info, warning, error };\n\n// BAD: plain enum leaks names, ALL_CAPS clashes with macros\nenum { RED, GREEN, BLUE };           // Enum.3 + Enum.5 + Enum.6 violation\n#define MAX_SIZE 100                  // Enum.1 violation -- use constexpr\n```\n\n## Source Files & Naming (SF.*, NL.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **SF.1** | Use `.cpp` for code files and `.h` for interface files |\n| **SF.7** | Don''t write `using namespace` at global scope in a header |\n| **SF.8** | Use `#include` guards for all `.h` files |\n| **SF.11** | Header files should be self-contained |\n| **NL.5** | Avoid encoding type information in names (no Hungarian notation) |\n| **NL.8** | Use a consistent naming style |\n| **NL.9** | Use ALL_CAPS for macro names only |\n| **NL.10** | Prefer `underscore_style` names |\n\n### Header Guard\n\n```cpp\n// SF.8: Include guard (or #pragma once)\n#ifndef PROJECT_MODULE_WIDGET_H\n#define PROJECT_MODULE_WIDGET_H\n\n// SF.11: Self-contained -- include everything this header needs\n#include <string>\n#include <vector>\n\nnamespace project::module {\n\nclass Widget {\npublic:\n    explicit Widget(std::string name);\n    const std::string& name() const;\n\nprivate:\n    std::string name_;\n};\n\n}  // namespace project::module\n\n#endif  // PROJECT_MODULE_WIDGET_H\n```\n\n### Naming Conventions\n\n```cpp\n// NL.8 + NL.10: Consistent underscore_style\nnamespace my_project {\n\nconstexpr int max_buffer_size = 4096;  // NL.9: not ALL_CAPS (it''s not a macro)\n\nclass tcp_connection {                 // underscore_style class\npublic:\n    void send_message(std::string_view msg);\n    bool is_connected() const;\n\nprivate:\n    std::string host_;                 // trailing underscore for members\n    int port_;\n};\n\n}  // namespace my_project\n```\n\n### Anti-Patterns\n\n- `using namespace std;` in a header at global scope (SF.7)\n- Headers that depend on inclusion order (SF.10, SF.11)\n- Hungarian notation like `strName`, `iCount` (NL.5)\n- ALL_CAPS for anything other than macros (NL.9)\n\n## Performance (Per.*)\n\n### Key Rules\n\n| Rule | Summary |\n|------|---------|\n| **Per.1** | Don''t optimize without reason |\n| **Per.2** | Don''t optimize prematurely |\n| **Per.6** | Don''t make claims about performance without measurements |\n| **Per.7** | Design to enable optimization |\n| **Per.10** | Rely on the static type system |\n| **Per.11** | Move computation from run time to compile time |\n| **Per.19** | Access memory predictably |\n\n### Guidelines\n\n```cpp\n// Per.11: Compile-time computation where possible\nconstexpr auto lookup_table = [] {\n    std::array<int, 256> table{};\n    for (int i = 0; i < 256; ++i) {\n        table[i] = i * i;\n    }\n    return table;\n}();\n\n// Per.19: Prefer contiguous data for cache-friendliness\nstd::vector<Point> points;           // GOOD: contiguous\nstd::vector<std::unique_ptr<Point>> indirect_points; // BAD: pointer chasing\n```\n\n### Anti-Patterns\n\n- Optimizing without profiling data (Per.1, Per.6)\n- Choosing \"clever\" low-level code over clear abstractions (Per.4, Per.5)\n- Ignoring data layout and cache behavior (Per.19)\n\n## Quick Reference Checklist\n\nBefore marking C++ work complete:\n\n- [ ] No raw `new`/`delete` -- use smart pointers or RAII (R.11)\n- [ ] Objects initialized at declaration (ES.20)\n- [ ] Variables are `const`/`constexpr` by default (Con.1, ES.25)\n- [ ] Member functions are `const` where possible (Con.2)\n- [ ] `enum class` instead of plain `enum` (Enum.3)\n- [ ] `nullptr` instead of `0`/`NULL` (ES.47)\n- [ ] No narrowing conversions (ES.46)\n- [ ] No C-style casts (ES.48)\n- [ ] Single-argument constructors are `explicit` (C.46)\n- [ ] Rule of Zero or Rule of Five applied (C.20, C.21)\n- [ ] Base class destructors are public virtual or protected non-virtual (C.35)\n- [ ] Templates are constrained with concepts (T.10)\n- [ ] No `using namespace` in headers at global scope (SF.7)\n- [ ] Headers have include guards and are self-contained (SF.8, SF.11)\n- [ ] Locks use RAII (`scoped_lock`/`lock_guard`) (CP.20)\n- [ ] Exceptions are custom types, thrown by value, caught by reference (E.14, E.15)\n- [ ] `''\\n''` instead of `std::endl` (SL.io.50)\n- [ ] No magic numbers (ES.45)\n"},"category":"official","lastSynced":"2026-03-06T03:57:45.841Z","seo":{"title":{"en":"cpp-coding-standards: C++ Core Guidelines Setup Guide | A...","zh":"C++编码标准设置指南 - 基于C++ Core Guidelines","ja":"C++コーディングスタンダードのベストプラクティス - C++ Core Guidelinesに基づく","ko":"C++ 코딩 표준 설정 가이드 - C++ Core Guidelines 기반","es":"Estándares de codificación C++: Guía de configuración","fr":"Normes de codage C++: Meilleures pratiques","de":"C++-Codierstandards: Einrichtungsleitfaden","pt":"Padrões de Codificação C++: Guia de Configuração","ru":"Стандарты кодирования C++: Руководство по настройке ИИ Аг...","ar":"معايير برمجة سي++: دليل الإعداد للأدوات الذكية"},"description":{"en":"Enforce modern C++ practices with cpp-coding-standards. Learn how to write safe and idiomatic code with our comprehensive guide and improve your C++ projects...","zh":"使用C++编码标准AI代理，根据C++ Core Guidelines确保现代、安全、惯用的C++编码实践","ja":"C++コーディングスタンダードAIエージェントを使用して、C++ Core Guidelinesに基づく現代的、安全、慣用的C++コードを保証する","ko":"C++ 코딩 표준 AI 에이전트를 사용하여 C++ Core Guidelines 기반의 현대적이고 안전하고 관용적인 C++ 코딩 관행을 보장합니다","es":"Aprenda a aplicar los estándares de codificación C++ basados en las C++ Core Guidelines para un código más seguro y moderno","fr":"Découvrez comment appliquer les normes de codage C++ basées sur les C++ Core Guidelines pour un code plus sûr et plus moderne","de":"Erfahren Sie, wie Sie die C++-Codierstandards basierend auf den C++ Core Guidelines anwenden, um sichereren und moderneren Code zu erstellen","pt":"Aprenda a aplicar padrões de codificação C++ modernos e seguros com base nas Diretrizes Centrais C++","ru":"Откройте для себя, как применять современные и безопасные стандарты кодирования C++ с помощью ИИ Агентов и Руководства по核心 C++","ar":"اكتشف كيفية تطبيق معايير برمجة سي++ الحديثة والأمن باستخدام الأدوات الذكية ومرجع سي++ الأساسي"},"definition":{"en":"cpp-coding-standards is a set of guidelines for writing modern, safe, and idiomatic C++ code, derived from the C++ Core Guidelines.","zh":"C++编码标准是根据C++ Core Guidelines制定的编码规范，确保C++代码的安全性、可读性和可维护性","ja":"C++コーディングスタンダードは、C++ Core Guidelinesに基づくコード規約であり、C++コードの安全性、可読性、メンテナンス性を確保する","ko":"C++ 코딩 표준은 C++ Core Guidelines 기반의 코딩 규약으로 C++ 코드의 안전성, 가독성 및 유지 보수성을 보장합니다","es":"Estándares de codificación C++ que siguen las C++ Core Guidelines para garantizar la seguridad y la modernidad del código","fr":"Normes de codage C++ qui suivent les C++ Core Guidelines pour assurer la sécurité et la modernité du code","de":"C++-Codierstandards, die den C++ Core Guidelines folgen, um die Sicherhei