ocpp.github.io cpp-coding-standards is a set of guidelines for writing modern, safe, and idiomatic C++ code, derived from the C++ Core Guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/django-verification', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'django-verification', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:05:18.892Z', 'b330cd018e559d568990f485f6ba90795e22e4b38dd68911167af88f54388674', '{"id":"affaan-m/everything-claude-code/django-verification","name":"django-verification","description":{"en":"The django-verification skill automates validation for Django projects, covering migrations, linting, tests, security scans, and deployment readiness. It benefits Django developers by ensuring application quality and security.","zh":"django-verification 是一个 Django 项目的验证循环，包括迁移、linting、测试、安全扫描和部署准备检查","ja":"django-verification は、Django プロジェクトの検証ループであり、移行、linting、テスト、セキュリティスキャン、デプロイ準備チェックを含みます","ko":"django-verification는 Django 프로젝트의 검증 루프로서, 마이그레이션, 린팅, 테스트, 보안 스캔 및 배포 준비 확인을 포함합니다","es":"django-verification es una herramienta para proyectos Django que realiza verificaciones de migraciones, linting, pruebas con cobertura, análisis de seguridad y comprobaciones de preparación para la implementación","fr":"django-verification est un outil pour les projets Django qui effectue des vérifications de migrations, de linting, de tests avec couverture, d''analyses de sécurité et de vérifications de préparation pour le déploiement","de":"django-verification ist ein Tool für Django-Projekte, das Überprüfungen von Migrationen, Linting, Tests mit Abdeckung, Sicherheitsanalysen und Bereitstellungsprüfungen durchführt","pt":"O django-verification é uma ferramenta de verificação de código que ajuda a garantir a qualidade e segurança do seu projeto Django","ru":"Django-verification - это инструмент верификации кода, который помогает обеспечить качество и безопасность вашего проекта Django","ar":"django-verification هو أداة للتحقق من الكود التي تساعد على ضمان جودة وأمان مشروع Django الخاص بك"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"django-verification","description":"Verification loop for Django projects: migrations, linting, tests with coverage, security scans, and deployment readiness checks before release or PR.","bodyPreview":"# Django Verification Loop\n\nRun before PRs, after major changes, and pre-deploy to ensure Django application quality and security.\n\n## When to Activate\n\n- Before opening a pull request for a Django project\n- After major model changes, migration updates, or dependency upgrades\n- Pre-deployment verification for staging or production\n- Running full environment → lint → test → security → deploy readiness pipeline\n- Validating migration safety and test coverage\n\n## Phase 1: Environment Check\n\n```bash","body":"# Django Verification Loop\n\nRun before PRs, after major changes, and pre-deploy to ensure Django application quality and security.\n\n## When to Activate\n\n- Before opening a pull request for a Django project\n- After major model changes, migration updates, or dependency upgrades\n- Pre-deployment verification for staging or production\n- Running full environment → lint → test → security → deploy readiness pipeline\n- Validating migration safety and test coverage\n\n## Phase 1: Environment Check\n\n```bash\n# Verify Python version\npython --version  # Should match project requirements\n\n# Check virtual environment\nwhich python\npip list --outdated\n\n# Verify environment variables\npython -c \"import os; import environ; print(''DJANGO_SECRET_KEY set'' if os.environ.get(''DJANGO_SECRET_KEY'') else ''MISSING: DJANGO_SECRET_KEY'')\"\n```\n\nIf environment is misconfigured, stop and fix.\n\n## Phase 2: Code Quality & Formatting\n\n```bash\n# Type checking\nmypy . --config-file pyproject.toml\n\n# Linting with ruff\nruff check . --fix\n\n# Formatting with black\nblack . --check\nblack .  # Auto-fix\n\n# Import sorting\nisort . --check-only\nisort .  # Auto-fix\n\n# Django-specific checks\npython manage.py check --deploy\n```\n\nCommon issues:\n- Missing type hints on public functions\n- PEP 8 formatting violations\n- Unsorted imports\n- Debug settings left in production configuration\n\n## Phase 3: Migrations\n\n```bash\n# Check for unapplied migrations\npython manage.py showmigrations\n\n# Create missing migrations\npython manage.py makemigrations --check\n\n# Dry-run migration application\npython manage.py migrate --plan\n\n# Apply migrations (test environment)\npython manage.py migrate\n\n# Check for migration conflicts\npython manage.py makemigrations --merge  # Only if conflicts exist\n```\n\nReport:\n- Number of pending migrations\n- Any migration conflicts\n- Model changes without migrations\n\n## Phase 4: Tests + Coverage\n\n```bash\n# Run all tests with pytest\npytest --cov=apps --cov-report=html --cov-report=term-missing --reuse-db\n\n# Run specific app tests\npytest apps/users/tests/\n\n# Run with markers\npytest -m \"not slow\"  # Skip slow tests\npytest -m integration  # Only integration tests\n\n# Coverage report\nopen htmlcov/index.html\n```\n\nReport:\n- Total tests: X passed, Y failed, Z skipped\n- Overall coverage: XX%\n- Per-app coverage breakdown\n\nCoverage targets:\n\n| Component | Target |\n|-----------|--------|\n| Models | 90%+ |\n| Serializers | 85%+ |\n| Views | 80%+ |\n| Services | 90%+ |\n| Overall | 80%+ |\n\n## Phase 5: Security Scan\n\n```bash\n# Dependency vulnerabilities\npip-audit\nsafety check --full-report\n\n# Django security checks\npython manage.py check --deploy\n\n# Bandit security linter\nbandit -r . -f json -o bandit-report.json\n\n# Secret scanning (if gitleaks is installed)\ngitleaks detect --source . --verbose\n\n# Environment variable check\npython -c \"from django.core.exceptions import ImproperlyConfigured; from django.conf import settings; settings.DEBUG\"\n```\n\nReport:\n- Vulnerable dependencies found\n- Security configuration issues\n- Hardcoded secrets detected\n- DEBUG mode status (should be False in production)\n\n## Phase 6: Django Management Commands\n\n```bash\n# Check for model issues\npython manage.py check\n\n# Collect static files\npython manage.py collectstatic --noinput --clear\n\n# Create superuser (if needed for tests)\necho \"from apps.users.models import User; User.objects.create_superuser(''admin@example.com'', ''admin'')\" | python manage.py shell\n\n# Database integrity\npython manage.py check --database default\n\n# Cache verification (if using Redis)\npython -c \"from django.core.cache import cache; cache.set(''test'', ''value'', 10); print(cache.get(''test''))\"\n```\n\n## Phase 7: Performance Checks\n\n```bash\n# Django Debug Toolbar output (check for N+1 queries)\n# Run in dev mode with DEBUG=True and access a page\n# Look for duplicate queries in SQL panel\n\n# Query count analysis\ndjango-admin debugsqlshell  # If django-debug-sqlshell installed\n\n# Check for missing indexes\npython manage.py shell << EOF\nfrom django.db import connection\nwith connection.cursor() as cursor:\n    cursor.execute(\"SELECT table_name, index_name FROM information_schema.statistics WHERE table_schema = ''public''\")\n    print(cursor.fetchall())\nEOF\n```\n\nReport:\n- Number of queries per page (should be < 50 for typical pages)\n- Missing database indexes\n- Duplicate queries detected\n\n## Phase 8: Static Assets\n\n```bash\n# Check for npm dependencies (if using npm)\nnpm audit\nnpm audit fix\n\n# Build static files (if using webpack/vite)\nnpm run build\n\n# Verify static files\nls -la staticfiles/\npython manage.py findstatic css/style.css\n```\n\n## Phase 9: Configuration Review\n\n```python\n# Run in Python shell to verify settings\npython manage.py shell << EOF\nfrom django.conf import settings\nimport os\n\n# Critical checks\nchecks = {\n    ''DEBUG is False'': not settings.DEBUG,\n    ''SECRET_KEY set'': bool(settings.SECRET_KEY and len(settings.SECRET_KEY) > 30),\n    ''ALLOWED_HOSTS set'': len(settings.ALLOWED_HOSTS) > 0,\n    ''HTTPS enabled'': getattr(settings, ''SECURE_SSL_REDIRECT'', False),\n    ''HSTS enabled'': getattr(settings, ''SECURE_HSTS_SECONDS'', 0) > 0,\n    ''Database configured'': settings.DATABASES[''default''][''ENGINE''] != ''django.db.backends.sqlite3'',\n}\n\nfor check, result in checks.items():\n    status = ''✓'' if result else ''✗''\n    print(f\"{status} {check}\")\nEOF\n```\n\n## Phase 10: Logging Configuration\n\n```bash\n# Test logging output\npython manage.py shell << EOF\nimport logging\nlogger = logging.getLogger(''django'')\nlogger.warning(''Test warning message'')\nlogger.error(''Test error message'')\nEOF\n\n# Check log files (if configured)\ntail -f /var/log/django/django.log\n```\n\n## Phase 11: API Documentation (if DRF)\n\n```bash\n# Generate schema\npython manage.py generateschema --format openapi-json > schema.json\n\n# Validate schema\n# Check if schema.json is valid JSON\npython -c \"import json; json.load(open(''schema.json''))\"\n\n# Access Swagger UI (if using drf-yasg)\n# Visit http://localhost:8000/swagger/ in browser\n```\n\n## Phase 12: Diff Review\n\n```bash\n# Show diff statistics\ngit diff --stat\n\n# Show actual changes\ngit diff\n\n# Show changed files\ngit diff --name-only\n\n# Check for common issues\ngit diff | grep -i \"todo\\|fixme\\|hack\\|xxx\"\ngit diff | grep \"print(\"  # Debug statements\ngit diff | grep \"DEBUG = True\"  # Debug mode\ngit diff | grep \"import pdb\"  # Debugger\n```\n\nChecklist:\n- No debugging statements (print, pdb, breakpoint())\n- No TODO/FIXME comments in critical code\n- No hardcoded secrets or credentials\n- Database migrations included for model changes\n- Configuration changes documented\n- Error handling present for external calls\n- Transaction management where needed\n\n## Output Template\n\n```\nDJANGO VERIFICATION REPORT\n==========================\n\nPhase 1: Environment Check\n  ✓ Python 3.11.5\n  ✓ Virtual environment active\n  ✓ All environment variables set\n\nPhase 2: Code Quality\n  ✓ mypy: No type errors\n  ✗ ruff: 3 issues found (auto-fixed)\n  ✓ black: No formatting issues\n  ✓ isort: Imports properly sorted\n  ✓ manage.py check: No issues\n\nPhase 3: Migrations\n  ✓ No unapplied migrations\n  ✓ No migration conflicts\n  ✓ All models have migrations\n\nPhase 4: Tests + Coverage\n  Tests: 247 passed, 0 failed, 5 skipped\n  Coverage:\n    Overall: 87%\n    users: 92%\n    products: 89%\n    orders: 85%\n    payments: 91%\n\nPhase 5: Security Scan\n  ✗ pip-audit: 2 vulnerabilities found (fix required)\n  ✓ safety check: No issues\n  ✓ bandit: No security issues\n  ✓ No secrets detected\n  ✓ DEBUG = False\n\nPhase 6: Django Commands\n  ✓ collectstatic completed\n  ✓ Database integrity OK\n  ✓ Cache backend reachable\n\nPhase 7: Performance\n  ✓ No N+1 queries detected\n  ✓ Database indexes configured\n  ✓ Query count acceptable\n\nPhase 8: Static Assets\n  ✓ npm audit: No vulnerabilities\n  ✓ Assets built successfully\n  ✓ Static files collected\n\nPhase 9: Configuration\n  ✓ DEBUG = False\n  ✓ SECRET_KEY configured\n  ✓ ALLOWED_HOSTS set\n  ✓ HTTPS enabled\n  ✓ HSTS enabled\n  ✓ Database configured\n\nPhase 10: Logging\n  ✓ Logging configured\n  ✓ Log files writable\n\nPhase 11: API Documentation\n  ✓ Schema generated\n  ✓ Swagger UI accessible\n\nPhase 12: Diff Review\n  Files changed: 12\n  +450, -120 lines\n  ✓ No debug statements\n  ✓ No hardcoded secrets\n  ✓ Migrations included\n\nRECOMMENDATION: ⚠️ Fix pip-audit vulnerabilities before deploying\n\nNEXT STEPS:\n1. Update vulnerable dependencies\n2. Re-run security scan\n3. Deploy to staging for final testing\n```\n\n## Pre-Deployment Checklist\n\n- [ ] All tests passing\n- [ ] Coverage ≥ 80%\n- [ ] No security vulnerabilities\n- [ ] No unapplied migrations\n- [ ] DEBUG = False in production settings\n- [ ] SECRET_KEY properly configured\n- [ ] ALLOWED_HOSTS set correctly\n- [ ] Database backups enabled\n- [ ] Static files collected and served\n- [ ] Logging configured and working\n- [ ] Error monitoring (Sentry, etc.) configured\n- [ ] CDN configured (if applicable)\n- [ ] Redis/cache backend configured\n- [ ] Celery workers running (if applicable)\n- [ ] HTTPS/SSL configured\n- [ ] Environment variables documented\n\n## Continuous Integration\n\n### GitHub Actions Example\n\n```yaml\n# .github/workflows/django-verification.yml\nname: Django Verification\n\non: [push, pull_request]\n\njobs:\n  verify:\n    runs-on: ubuntu-latest\n    services:\n      postgres:\n        image: postgres:14\n        env:\n          POSTGRES_PASSWORD: postgres\n        options: >-\n          --health-cmd pg_isready\n          --health-interval 10s\n          --health-timeout 5s\n          --health-retries 5\n\n    steps:\n      - uses: actions/checkout@v3\n\n      - name: Set up Python\n        uses: actions/setup-python@v4\n        with:\n          python-version: ''3.11''\n\n      - name: Cache pip\n        uses: actions/cache@v3\n        with:\n          path: ~/.cache/pip\n          key: ${{ runner.os }}-pip-${{ hashFiles(''**/requirements.txt'') }}\n\n      - name: Install dependencies\n        run: |\n          pip install -r requirements.txt\n          pip install ruff black mypy pytest pytest-django pytest-cov bandit safety pip-audit\n\n      - name: Code quality checks\n        run: |\n          ruff check .\n          black . --check\n          isort . --check-only\n          mypy .\n\n      - name: Security scan\n        run: |\n          bandit -r . -f json -o bandit-report.json\n          safety check --full-report\n          pip-audit\n\n      - name: Run tests\n        env:\n          DATABASE_URL: postgres://postgres:postgres@localhost:5432/test\n          DJANGO_SECRET_KEY: test-secret-key\n        run: |\n          pytest --cov=apps --cov-report=xml --cov-report=term-missing\n\n      - name: Upload coverage\n        uses: codecov/codecov-action@v3\n```\n\n## Quick Reference\n\n| Check | Command |\n|-------|---------|\n| Environment | `python --version` |\n| Type checking | `mypy .` |\n| Linting | `ruff check .` |\n| Formatting | `black . --check` |\n| Migrations | `python manage.py makemigrations --check` |\n| Tests | `pytest --cov=apps` |\n| Security | `pip-audit && bandit -r .` |\n| Django check | `python manage.py check --deploy` |\n| Collectstatic | `python manage.py collectstatic --noinput` |\n| Diff stats | `git diff --stat` |\n\nRemember: Automated verification catches common issues but doesn''t replace manual code review and testing in staging environment.\n"},"category":"official","lastSynced":"2026-03-06T04:05:18.892Z","seo":{"title":{"en":"django-verification: Automated Django Project Validation ...","zh":"Django 验证循环设置指南 - django-verification","ja":"Django 検証ループ設定ガイド - django-verification","ko":"Django 검증 루프 설정 가이드 - django-verification","es":"Guía de configuración de django-verification para proyect...","fr":"Configurer django-verification pour des projets Django sé...","de":"Einrichtungsleitfaden für django-verification in Django-P...","pt":"Guia de Configuração do django-verification: Ferramentas ...","ru":"Настройка django-verification: ИИ Агенты для Верификации Код","ar":"دليل إعداد django-verification: أدوات التحقق من الكود"},"description":{"en":"Streamline your Django workflow with django-verification - run checks before PRs, after major changes, and pre-deploy to ensure quality and security. Learn h...","zh":"使用 django-verification 实现 Django 项目的自动化验证，确保代码质量和安全性","ja":"Django プロジェクトの自動化検証を実現するための django-verification を使用して、コードの品質とセキュリティを確保する","ko":"Django 프로젝트의 자동화 검증을 구현하는 django-verification를 사용하여 코드의 품질과 보안을 보장합니다","es":"Aprende a utilizar django-verification para garantizar la calidad y seguridad de tus proyectos Django ante