INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/django-verification', 'django-verification', 'affaan-m', 'everything-claude-code', 'official', 'django-verification affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The django-verification skill automates validation for Django projects, covering migrations, linting, tests, security scans, and deployment readiness. It benefits Django developers by ensuring application quality and security. django-verification 是一个 Django 项目的验证循环，包括迁移、linting、测试、安全扫描和部署准备检查 django-verification は、Django プロジェクトの検証ループであり、移行、linting、テスト、セキュリティスキャン、デプロイ準備チェックを含みます django-verification는 Django 프로젝트의 검증 루프로서, 마이그레이션, 린팅, 테스트, 보안 스캔 및 배포 준비 확인을 포함합니다 django-verification es una herramienta para proyectos Django que realiza verificaciones de migraciones, linting, pruebas con cobertura, análisis de seguridad y comprobaciones de preparación para la implementación django-verification est un outil pour les projets Django qui effectue des vérifications de migrations, de linting, de tests avec couverture, d''analyses de sécurité et de vérifications de préparation pour le déploiement django-verification ist ein Tool für Django-Projekte, das Überprüfungen von Migrationen, Linting, Tests mit Abdeckung, Sicherheitsanalysen und Bereitstellungsprüfungen durchführt O django-verification é uma ferramenta de verificação de código que ajuda a garantir a qualidade e segurança do seu projeto Django Django-verification - это инструмент верификации кода, который помогает обеспечить качество и безопасность вашего проекта Django django-verification هو أداة للتحقق من الكود التي تساعد على ضمان جودة وأمان مشروع Django الخاص بك how to use django-verification django-verification setup guide django project validation automated django testing django security scans django deployment readiness Django 验证 django-verification AIエージェント 自动化验证 代码质量检查 安全扫描 部署准备检查 Runs full environment checks Executes linting and tests with coverage Performs security scans Checks deployment readiness Validates migration safety django-verification is a verification loop for Django projects that checks migrations, linting, tests with coverage, security scans, and deployment readiness before release or PR.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/foundation-models-on-device', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'foundation-models-on-device', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:10:23.044Z', '8efee7e392b39990e4ed58d85ac0783c1cbaac8e1cd87e7a4ef502f15987963e', '{"id":"affaan-m/everything-claude-code/foundation-models-on-device","name":"foundation-models-on-device","description":{"en":"This AI Agent Skill provides patterns for integrating Apple''s FoundationModels framework to run large language models directly on iOS devices. It enables developers to build AI-powered features with text generation, structured output, and tool calling that work offline and preserve user privacy.","zh":"苹果的FoundationModels框架允许开发者在iOS 26+设备上运行LLM，实现文本生成、结构化输出和快照流媒体等功能","ja":"AppleのFoundationModelsフレームワークは、iOS 26+デバイスでLLMを実行し、テキスト生成、構造化出力、スナップショットストリーミングなどの機能を実現します","ko":"FoundationModels 프레임워크를 사용하면 iOS 26+ 기기에서 LLM을 실행하여 텍스트 생성, 구조화된 출력 및 스냅샷 스트리밍 등의 기능을 구현할 수 있습니다","es":"El framework FoundationModels permite ejecutar modelos de lenguaje grande (LLM) de Apple directamente en dispositivos iOS 26+. Ofrece generación de texto, salida guiada con @Generable, tool calling y snapshot streaming, todo con privacidad y soporte offline.","fr":"Le framework FoundationModels permet d''exécuter des modèles de langage (LLM) Apple directement sur les appareils iOS 26+. Il offre génération de texte, sortie guidée avec @Generable, tool calling et snapshot streaming, avec confidentialité et hors-ligne.","de":"Das FoundationModels-Framework ermöglicht die Ausführung von Apple-Sprachmodellen (LLM) direkt auf iOS-26+-Geräten. Es bietet Textgenerierung, geführte Ausgabe mit @Generable, Tool Calling und Snapshot-Streaming bei Privatsphäre und Offline-Unterstützung.","pt":"O FoundationModels On-Device é um framework da Apple para integração de modelos de linguagem em dispositivos iOS, permitindo gerar texto e realizar tarefas de processamento de linguagem natural","ru":"FoundationModels на устройстве — это фреймворк Apple для интеграции языковых моделей на устройствах iOS, позволяющий генерировать текст и выполнять задачи обработки естественного языка","ar":"FoundationModels على الجهاز هو إطار عمل من Apple لدمج نماذج اللغة في أجهزة iOS ، مما يسمح بإنشاء نصและการ実ناج التطبيقاتات من معالجة اللغة الطبيعية"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"foundation-models-on-device","description":"Apple FoundationModels framework for on-device LLM — text generation, guided generation with @Generable, tool calling, and snapshot streaming in iOS 26+.","bodyPreview":"# FoundationModels: On-Device LLM (iOS 26)\n\nPatterns for integrating Apple''s on-device language model into apps using the FoundationModels framework. Covers text generation, structured output with `@Generable`, custom tool calling, and snapshot streaming — all running on-device for privacy and offline support.\n\n## When to Activate\n\n- Building AI-powered features using Apple Intelligence on-device\n- Generating or summarizing text without cloud dependency\n- Extracting structured data from natural","body":"# FoundationModels: On-Device LLM (iOS 26)\n\nPatterns for integrating Apple''s on-device language model into apps using the FoundationModels framework. Covers text generation, structured output with `@Generable`, custom tool calling, and snapshot streaming — all running on-device for privacy and offline support.\n\n## When to Activate\n\n- Building AI-powered features using Apple Intelligence on-device\n- Generating or summarizing text without cloud dependency\n- Extracting structured data from natural language input\n- Implementing custom tool calling for domain-specific AI actions\n- Streaming structured responses for real-time UI updates\n- Need privacy-preserving AI (no data leaves the device)\n\n## Core Pattern — Availability Check\n\nAlways check model availability before creating a session:\n\n```swift\nstruct GenerativeView: View {\n    private var model = SystemLanguageModel.default\n\n    var body: some View {\n        switch model.availability {\n        case .available:\n            ContentView()\n        case .unavailable(.deviceNotEligible):\n            Text(\"Device not eligible for Apple Intelligence\")\n        case .unavailable(.appleIntelligenceNotEnabled):\n            Text(\"Please enable Apple Intelligence in Settings\")\n        case .unavailable(.modelNotReady):\n            Text(\"Model is downloading or not ready\")\n        case .unavailable(let other):\n            Text(\"Model unavailable: \\(other)\")\n        }\n    }\n}\n```\n\n## Core Pattern — Basic Session\n\n```swift\n// Single-turn: create a new session each time\nlet session = LanguageModelSession()\nlet response = try await session.respond(to: \"What''s a good month to visit Paris?\")\nprint(response.content)\n\n// Multi-turn: reuse session for conversation context\nlet session = LanguageModelSession(instructions: \"\"\"\n    You are a cooking assistant.\n    Provide recipe suggestions based on ingredients.\n    Keep suggestions brief and practical.\n    \"\"\")\n\nlet first = try await session.respond(to: \"I have chicken and rice\")\nlet followUp = try await session.respond(to: \"What about a vegetarian option?\")\n```\n\nKey points for instructions:\n- Define the model''s role (\"You are a mentor\")\n- Specify what to do (\"Help extract calendar events\")\n- Set style preferences (\"Respond as briefly as possible\")\n- Add safety measures (\"Respond with ''I can''t help with that'' for dangerous requests\")\n\n## Core Pattern — Guided Generation with @Generable\n\nGenerate structured Swift types instead of raw strings:\n\n### 1. Define a Generable Type\n\n```swift\n@Generable(description: \"Basic profile information about a cat\")\nstruct CatProfile {\n    var name: String\n\n    @Guide(description: \"The age of the cat\", .range(0...20))\n    var age: Int\n\n    @Guide(description: \"A one sentence profile about the cat''s personality\")\n    var profile: String\n}\n```\n\n### 2. Request Structured Output\n\n```swift\nlet response = try await session.respond(\n    to: \"Generate a cute rescue cat\",\n    generating: CatProfile.self\n)\n\n// Access structured fields directly\nprint(\"Name: \\(response.content.name)\")\nprint(\"Age: \\(response.content.age)\")\nprint(\"Profile: \\(response.content.profile)\")\n```\n\n### Supported @Guide Constraints\n\n- `.range(0...20)` — numeric range\n- `.count(3)` — array element count\n- `description:` — semantic guidance for generation\n\n## Core Pattern — Tool Calling\n\nLet the model invoke custom code for domain-specific tasks:\n\n### 1. Define a Tool\n\n```swift\nstruct RecipeSearchTool: Tool {\n    let name = \"recipe_search\"\n    let description = \"Search for recipes matching a given term and return a list of results.\"\n\n    @Generable\n    struct Arguments {\n        var searchTerm: String\n        var numberOfResults: Int\n    }\n\n    func call(arguments: Arguments) async throws -> ToolOutput {\n        let recipes = await searchRecipes(\n            term: arguments.searchTerm,\n            limit: arguments.numberOfResults\n        )\n        return .string(recipes.map { \"- \\($0.name): \\($0.description)\" }.joined(separator: \"\\n\"))\n    }\n}\n```\n\n### 2. Create Session with Tools\n\n```swift\nlet session = LanguageModelSession(tools: [RecipeSearchTool()])\nlet response = try await session.respond(to: \"Find me some pasta recipes\")\n```\n\n### 3. Handle Tool Errors\n\n```swift\ndo {\n    let answer = try await session.respond(to: \"Find a recipe for tomato soup.\")\n} catch let error as LanguageModelSession.ToolCallError {\n    print(error.tool.name)\n    if case .databaseIsEmpty = error.underlyingError as? RecipeSearchToolError {\n        // Handle specific tool error\n    }\n}\n```\n\n## Core Pattern — Snapshot Streaming\n\nStream structured responses for real-time UI with `PartiallyGenerated` types:\n\n```swift\n@Generable\nstruct TripIdeas {\n    @Guide(description: \"Ideas for upcoming trips\")\n    var ideas: [String]\n}\n\nlet stream = session.streamResponse(\n    to: \"What are some exciting trip ideas?\",\n    generating: TripIdeas.self\n)\n\nfor try await partial in stream {\n    // partial: TripIdeas.PartiallyGenerated (all properties Optional)\n    print(partial)\n}\n```\n\n### SwiftUI Integration\n\n```swift\n@State private var partialResult: TripIdeas.PartiallyGenerated?\n@State private var errorMessage: String?\n\nvar body: some View {\n    List {\n        ForEach(partialResult?.ideas ?? [], id: \\.self) { idea in\n            Text(idea)\n        }\n    }\n    .overlay {\n        if let errorMessage { Text(errorMessage).foregroundStyle(.red) }\n    }\n    .task {\n        do {\n            let stream = session.streamResponse(to: prompt, generating: TripIdeas.self)\n            for try await partial in stream {\n                partialResult = partial\n            }\n        } catch {\n            errorMessage = error.localizedDescription\n        }\n    }\n}\n```\n\n## Key Design Decisions\n\n| Decision | Rationale |\n|----------|-----------|\n| On-device execution | Privacy — no data leaves the device; works offline |\n| 4,096 token limit | On-device model constraint; chunk large data across sessions |\n| Snapshot streaming (not deltas) | Structured output friendly; each snapshot is a complete partial state |\n| `@Generable` macro | Compile-time safety for structured generation; auto-generates `PartiallyGenerated` type |\n| Single request per session | `isResponding` prevents concurrent requests; create multiple sessions if needed |\n| `response.content` (not `.output`) | Correct API — always access results via `.content` property |\n\n## Best Practices\n\n- **Always check `model.availability`** before creating a session — handle all unavailability cases\n- **Use `instructions`** to guide model behavior — they take priority over prompts\n- **Check `isResponding`** before sending a new request — sessions handle one request at a time\n- **Access `response.content`** for results — not `.output`\n- **Break large inputs into chunks** — 4,096 token limit applies to instructions + prompt + output combined\n- **Use `@Generable`** for structured output — stronger guarantees than parsing raw strings\n- **Use `GenerationOptions(temperature:)`** to tune creativity (higher = more creative)\n- **Monitor with Instruments** — use Xcode Instruments to profile request performance\n\n## Anti-Patterns to Avoid\n\n- Creating sessions without checking `model.availability` first\n- Sending inputs exceeding the 4,096 token context window\n- Attempting concurrent requests on a single session\n- Using `.output` instead of `.content` to access response data\n- Parsing raw string responses when `@Generable` structured output would work\n- Building complex multi-step logic in a single prompt — break into multiple focused prompts\n- Assuming the model is always available — device eligibility and settings vary\n\n## When to Use\n\n- On-device text generation for privacy-sensitive apps\n- Structured data extraction from user input (forms, natural language commands)\n- AI-assisted features that must work offline\n- Streaming UI that progressively shows generated content\n- Domain-specific AI actions via tool calling (search, compute, lookup)\n"},"category":"official","lastSynced":"2026-03-06T04:10:23.044Z","seo":{"title":{"en":"foundation-models-on-device: On-Device LLM Setup Guide fo...","zh":"苹果FoundationModels框架：在设备上运行LLM的设置指南","ja":"FoundationModelsフレームワーク：iOS 26でのオンデバイスLLMのベストプラクティス","ko":"FoundationModels 프레임워크: iOS 26에서 온디바이스 LLM을 사용하는 방법","es":"FoundationModels On-Device: Guía de Implementación para i...","fr":"FoundationModels On-Device : Guide de Démarrage pour iOS 26","de":"FoundationModels On-Device: Einrichtungsanleitung für iOS 26","pt":"Guia de Configuração do FoundationModels On-Device para D...","ru":"Настройка FoundationModels на устройстве: Руководство для...","ar":"دليل تنصيب FoundationModels على الجهاز للمطورين"},"description":{"en":"Integrate Apple''s FoundationModels framework for private, offline LLM features. Learn to use @Generable, tool calling & snapshot streaming in iOS 26+. Build ...","zh":"了解如何使用苹果的FoundationModels框架在iOS 26+设备上实现LLM，包括文本生成、结构化输出和快照流媒体","ja":"iOS 26+デバイスでLLMを実現するために、AppleのFoundationModelsフレームワークを使用する方法について学びます","ko":"iOS 26+ 기기에서 LLM을 구현하는 방법을 알아보세요. FoundationModels 프레임워크를 사용하여 텍스트 생성, 구조화된 출력 및 스냅샷 스트리밍을 수행합니다","es":"Implementa LLM local de Apple con FoundationModels en iOS 26. Aprende generación de texto, uso de @Generable para salida estructurada, tool calling y snapsho...","fr":"Intégrez un LLM local d''Apple avec FoundationModels sur iOS 26. Apprenez la génération de texte, @Generable pour sortie structurée, tool calling et snapshot ...","de":"Integrieren Sie lokale Apple-LLMs mit FoundationModels in iOS 26. Erfahren Sie Textgenerierung, @Generable für strukturierte Ausgabe, Tool Calling und Snapsh...","pt":"Aprenda a integrar o framework FoundationModels da Apple em seus aplicativos iOS para gerar texto, realizar chamadas de ferramentas personalizadas e transmit...","ru":"Узнайте, как интегрировать фреймворк FoundationModels от Apple в свои приложения iOS для генерации текста, вызова пользовательских инструментов и передачи сн...","ar":"تعلم كيفية دمج إطار FoundationModels من Apple في تطبيقات iOS الخاصة بك لإنشاء نص ، واستدعاء أدوات مخصصة ، و بث لحظات"},"definition":{"en":"foundation-models-on-device is an AI Agent Skill that provides implementation patterns for Apple''s FoundationModels framework. It enables on-device LLM capabilities including text generation, guided generation with @Generable, custom tool calling, and snapshot streaming for iOS 26+ applications.","zh":"FoundationModels是在设备上运行LLM的框架，支持文本生成、结构化输出和快照流媒体","ja":"FoundationModelsは、オンデバイスでLLMを実行するフレームワークであり、テキスト生成、構造化出力、スナップショットストリーミングをサポートします","ko":"FoundationModels는 온디바이스에서 LLM을 실행하는 프레임워크로, 텍스트 생성, 구조화된 출력 및 스냅샷 스트리밍을 지원합니다","es":"FoundationModels es un framework de Apple para integrar modelos de lenguaje grande (LLM) que se ejecutan localmente en dispositivos iOS 26+. Proporciona capacidades de IA on-device como generación de texto, tool calling y streaming de snapshots, priorizando la privacidad y el funcionamiento offline.","fr":"FoundationModels est un framework Apple pour intégrer des modèles de langage (LLM) fonctionnant localement sur iOS 26+. Il fournit des capacités d''IA on-device comme la génération de texte, le tool calling et le streaming de snapshots, avec confidentialité et hors-ligne.","de":"FoundationModels ist ein Apple-Framework zur Integration von Sprachmodellen (LLM), die lokal auf iOS-26+-Geräten laufen. Es bietet On-Device-KI-Fähigkeiten wie Textgenerierung, Tool Calling und Snapshot-Streaming unter Priorisierung von Privatsphäre und Offline-Betrieb.","pt":"O que é FoundationModels On-Device? É um framework da Apple para integração de modelos de linguagem em dispositivos iOS","ru":"Что такое FoundationModels на устройстве? Это фреймворк Apple для интеграции языковых моделей на устройствах iOS","ar":"ما هو FoundationModels على الجهاز؟ إنه إطار عمل من Apple لدمج نماذج اللغة في أجهزة iOS"},"features":{"en":["On-device text generation using Apple FoundationModels framework","Structured output generation with @Generable annotation","Custom tool calling for extending LLM capabilities","Snapshot streaming for real-time output monitoring","Offline operation without cloud dependency","Privacy-focused execution on iOS 26+ devices"],"zh":["在设备上运行LLM","文本生成","结构化输出使用@Generable","自定义工具调用","快照流媒体"],"ja":["オンデバイスでLLMを実行","テキスト生成","構造化出力@Generableを使用","カスタムツールの呼び出し","スナップショットストリーミング"],"ko":["온디바이스에서 LLM을 실행","텍스트 생성","구조화된 출력 @Generable 사용","사용자 지정 도구 호출","스냅샷 스트리밍"],"es":["Generación de texto on-device con modelos LLM de Apple","Obtención de salida estructurada usando el atributo @Generable","Implementación de custom tool calling para extender capacidades","Snapshot streaming para respuestas en tiempo real","Funcionamiento completo offline sin dependencia de la nube","Integración con Apple Intelligence para funciones con IA"],"fr":["Génération de texte on-device avec modèles LLM Apple","Obtention de sortie structurée avec l''attribut @Generable","Mise en œuvre de custom tool calling pour étendre les capacités","Snapshot streaming pour réponses en temps réel","Fonctionnement hors-ligne complet sans dépendance cloud","Intégration avec Apple Intelligence pour fonctionnalités IA"],"de":["On-Device-Textgenerierung mit Apple-LLM-Modellen","Erzeugung strukturierter Ausgabe mit dem @Generable-Attribut","Implementierung von Custom Tool Calling zur Erweiterung von Fähigkeiten","Snapshot-Streaming für Echtzeit-Antworten","Vollständiger Offline-Betrieb ohne Cloud-Abhängigkeit","Integration mit Apple Intelligence für KI-Funktionen"],"pt":["Geração de texto com o framework FoundationModels","Chamadas de ferramentas personalizadas com @Generable","Transmissão de instantâneos com suporte a privacidade e offline","Integração com a Apple Intelligence para processamento de linguagem natural","Suporte a dispositivos iOS 26+"],"ru":["Генерация текста с помощью фреймворка FoundationModels","Вызов пользовательских инструментов с помощью @Generable","Передача снимков с поддержкой конфиденциальности и офлайн-режима","Интеграция с Apple Intelligence для обработки естественного языка","Поддержка устройств iOS 26+"],"ar":["إنشاء نص باستخدام إطار FoundationModels","استدعاء أدوات مخصصة مع @Generable","بث لحظات مع دعم للخصوصية و الوضع غير المتصل","دمج مع Apple Intelligence لمعالجة اللغة الطبيعية","دعم أجهزة iOS 26+"]},"keywords":{"en":["how to use foundation-models-on-device","what is foundation-models on device","Apple FoundationModels framework tutorial","foundation-models-on-device vs cloud LLM","on-device LLM iOS implementation","@Generable structured output guide","install foundation-models-on-device skill","foundation-models-on-device setup iOS 26","Apple Intelligence on-device development","iOS snapshot streaming implementation"],"zh":["AIエージェント","FoundationModels","LLM","iOS 26","在设备上运行LLM","文本生成","结构化输出","快照流媒体"],"ja":["AIエージェント","FoundationModels","LLM","iOS 26","オンデバイスLLM","テキスト生成","構造化出力","スナップショットストリーミング"],"ko":["AI 에이전트","FoundationModels","LLM","iOS 26","온디바이스 LLM","텍스트 생성","구조화된 출력","스냅샷 스트리밍"],"es":["foundationmodels framework ios","@Generable salida estructurada","llm on-device apple","tool calling ios 26","snapshot streaming foundationmodels","apple intelligence desarrollo","ia local privacidad ios","modelos lenguaje dispositivo"],"fr":["foundationmodels framework ios","@Generable sortie structurée","llm on-device apple","tool calling ios 26","snapshot streaming foundationmodels","apple intelligence développement","ia locale confidentialité ios","modèles langage appareil"],"de":["foundationmodels framework ios","@Generable strukturierte ausgabe","llm on-device apple","tool calling ios 26","snapshot streaming foundationmodels","apple intelligence entwicklung","lokale ki datenschutz ios","sprachmodelle gerät"],"pt":["FoundationModels On-Device","Apple Intelligence","processamento de linguagem natural","geração de texto","chamadas de ferramentas personalizadas","transmissão de instantâneos","iOS 26+","desenvolvimento de aplicativos","ferramentas de desenvolvedor"],"ru":["FoundationModels на устройстве","Apple Intelligence","обработка естественного языка","генерация текста","вызов пользовательских инструментов","передача снимков","iOS 26+","разработка приложений","инструменты разработчика"],"ar":["FoundationModels على الجهاز","Apple Intelligence","معالجة اللغة الطبيعية","إنشاء نص","استدعاء أدوات مخصصة","بث لحظات","iOS 26+","تطوير التطبيقات","أدوات المطور"]}},"agentAnalysis":{"suitability":{"en":"Ideal for iOS Privacy-First Agents requiring on-device text generation and structured data extraction.","zh":"非常适合需要设备端文本生成和结构化数据提取的、优先考虑隐私的 iOS Agent。","ja":"オンデバイスのテキスト生成と構造化データ抽出を必要とする、プライバシー第一の iOS Agent に最適です。","ko":"기기 내 텍스트 생성 및 구조화된 데이터 추출이 필요한, 프라이버시를 최우선으로 하는 iOS 에이전트에 이상적입니다.","es":"Ideal para Agents con prioridad de privacidad en iOS que requieren generación de texto en el dispositivo y extracción de datos estructurados.","fr":"Idéal pour les Agents axés sur la confidentialité iOS nécessitant une génération de texte sur l''appareil et une extraction de données structurées.","de":"Ideal für iOS-Agents mit Privatsphären-Priorität, die Textgenerierung auf dem Gerät und Extraktion strukturierter Daten erfordern.","pt":"Ideal para agentes de privacidade primeiro do iOS que exigem geração de texto no dispositivo e extração de dados estruturados.","ru":"Идеально подходит для агентов iOS с приоритетом конфиденциальности, требующих генерации текста на устройстве и извлечения структурированных данных.","ar":"مثالي لعميل iOS الأولي للخصوصية الذي يتطلب генера текст على الجهاز واستخراج بيانات منظمّة."},"recommendation":{"en":"Enables direct integration with Apple''s FoundationModels framework for offline text generation, guided structured output using @Generable, custom tool calling, and snapshot streaming capabilities without cloud dependencies.","zh":"支持与 Apple 的 FoundationModels 框架直接集成，以实现离线文本生成、使用 @Generable 的引导式结构化输出、自定义工具调用以及无需云依赖的快照流功能。","ja":"Apple の FoundationModels フレームワークとの直接統合を可能にし、オフラインでのテキスト生成、@Generable を使用したガイド付き構造化出力、カスタムツール呼び出し、およびクラウド依存関係のないスナップショットストリーミング機能を実現します。","ko":"오프라인 텍스트 생성, @Generable을 사용한 가이드 구조화 출력, 사용자 정의 도구 호출, 그리고 클라우드 종속성 없이 스냅샷 스트리밍 기능을 위해 Apple의 FoundationModels 프레임워크와의 직접적인 통합을 가능하게 합니다.","es":"Permite la integración directa con el framework FoundationModels de Apple para generación de texto sin conexión, salida estructurada guiada usando @Generable, invocación de herramientas personalizadas y capacidades de transmisión de instantáneas sin dependencias de la nube.","fr":"Permet une intégration directe avec le framework FoundationModels d''Apple pour la génération de texte hors ligne, la sortie structurée guidée en utilisant @Generable, l''appel d''outils personnalisés et les capacités de diffusion en flux de snapshots sans dépendances cloud.","de":"Ermöglicht die direkte Integration in Apples FoundationModels-Framework für Offline-Textgenerierung, geführte strukturierte Ausgabe mit @Generable, benutzerdefiniertes Tool Calling und Snapshot-Streaming-Fähigkeiten ohne Cloud-Abhängigkeiten.","pt":"Permite integração direta com o framework FoundationModels da Apple para geração de texto offline, saída estruturada orientada por @Generable, chamada de ferramentas personalizadas e capacidades de transmissão de instantâneos sem dependências de nuvem.","ru":"Позволяет直接 интегрироваться с фреймворком FoundationModels от Apple для генерации текста в автономном режиме, структурированного вывода с помощью @Generable, настройки вызова инструментов и возможностей потоковой передачи снимков без зависимостей от облака.","ar":"يمكن التكامل المباشر مع إطار FoundationModels من Apple للنص غير متصل، الإخراج المنظم بإرشاد @Generable، استدعاء أداة مخصصة، وقدرات بث لقطة دون اعتمادية على السحابة."},"useCases":{"en":["Generating privacy-sensitive text content offline","Extracting structured data from natural language using @Generable","Implementing custom tool calling for on-device workflows","Streaming text snapshots for real-time AI features"],"zh":["离线生成隐私敏感的文本内容","使用 @Generable 从自然语言中提取结构化数据","为设备端工作流实施自定义工具调用","为实时 AI 功能流式传输文本快照"],"ja":["プライバシーに敏感なテキストコンテンツのオフライン生成","@Generable を使用した自然言語からの構造化データ抽出","オンデバイスワークフローのためのカスタムツール呼び出しの実装","リアルタイム AI 機能のためのテキストスナップショットのストリーミング"],"ko":["프라이버시에 민감한 텍스트 콘텐츠 오프라인 생성","@Generable을 사용하여 자연어에서 구조화된 데이터 추출","기기 내 워크플로우를 위한 사용자 정의 도구 호출 구현","실시간 AI 기능을 위한 텍스트 스냅샷 스트리밍"],"es":["Generación de contenido de texto sensible a la privacidad sin conexión","Extracción de datos estructurados desde lenguaje natural usando @Generable","Implementación de invocación de herramientas personalizadas para flujos de trabajo en el dispositivo","Transmisión de instantáneas de texto para funciones de IA en tiempo real"],"fr":["Génération de contenu texte sensible à la confidentialité hors ligne","Extraction de données structurées à partir du langage naturel en utilisant @Generable","Mise en œuvre d''appel d''outils personnalisés pour les workflows sur l''appareil","Diffusion en flux de snapshots de texte pour les fonctionnalités IA en temps réel"],"de":["Generierung datenschutzkritischer Textinhalte offline","Extraktion strukturierter Daten aus natürlicher Sprache mit @Generable","Implementierung benutzerdefinierten Tool Callings für On-Device-Workflows","Streaming von Text-Snapshots für Echtzeit-KI-Funktionen"],"pt":["Geração de conteúdo de texto sensível à privacidade offline","Extração de dados estruturados de linguagem natural usando @Generable","Implementação de chamada de ferramentas personalizadas para fluxos de trabalho no dispositivo","Transmitir instantâneos de texto para recursos de IA em tempo real"],"ru":["Генерация текстового контента, чувствительного к конфиденциальности, в автономном режиме","Извлечение структурированных данных из естественного языка с помощью @Generable","Реализация настройки вызова инструментов для рабочих процессов на устройстве","Потоковая передача снимков текста для функций ИИ в реальном времени"],"ar":["توليد المحتوى النصي الحساس للخصوصية دون اتصال","استخراج البيانات المنظمة من اللغة الطبيعية باستخدام @Generable","تنفيذ استدعاء أداة مخصصة لسير عمل الجهاز","بث لقطة نصية لميزات الذكاء الاصطناعي في الوقت الفعلي"]},"limitations":{"en":["iOS 26+ required","Apple Intelligence on-device capability dependent","Limited to FoundationModels framework ecosystem"],"zh":["需要 iOS 26 或更高版本","依赖于 Apple Intelligence 的设备端能力","仅限于 FoundationModels 框架生态系统"],"ja":["iOS 26 以上が必要","Apple Intelligence のオンデバイス機能に依存","FoundationModels フレームワークエコシステムに限定"],"ko":["iOS 26+ 이상 필요","Apple Intelligence의 기기 내 기능에 의존","FoundationModels 프레임워크 생태계로 제한됨"],"es":["Requiere iOS 26+","Dependiente de la capacidad on-device de Apple Intelligence","Limitado al ecosistema del framework FoundationModels"],"fr":["iOS 26+ requis","Dépend de la capacité sur l''appareil Apple Intelligence","Limité à l''écosystème du framework FoundationModels"],"de":["iOS 26+ erforderlich","Abhängig von der On-Device-Fähigkeit von Apple Intelligence","Begrenzt auf das FoundationModels-Framework-Ökosystem"],"pt":["Requer iOS 26+","Dependente da capacidade de inteligência da Apple no dispositivo","Limitado ao ecossistema do framework FoundationModels"],"ru":["Требуется iOS 26+","Зависит от возможностей интеллекта Apple на устройстве","Ограничен экосистемой фреймворка FoundationModels"],"ar":["مطلوب iOS 26+","يعتمد على قدرات ذكاء Apple على الجهاز","محدود بنظام إطار FoundationModels"]},"version":4},"contentHash":"8efee7e392b39990e4ed58d85ac0783c1cbaac8e1cd87e7a4ef502f15987963e","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":95}');
DELETE FROM skills_fts WHERE id = 'affaan-m/everything-claude-code/foundation-models-on-device';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/foundation-models-on-device', 'foundation-models-on-device', 'affaan-m', 'everything-claude-code', 'official', 'foundation-models-on-device affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This AI Agent Skill provides patterns for integrating Apple''s FoundationModels framework to run large language models directly on iOS devices. It enables developers to build AI-powered features with text generation, structured output, and tool calling that work offline and preserve user privacy. 苹果的FoundationModels框架允许开发者在iOS 26+设备上运行LLM，实现文本生成、结构化输出和快照流媒体等功能 AppleのFoundationModelsフレームワークは、iOS 26+デバイスでLLMを実行し、テキスト生成、構造化出力、スナップショットストリーミングなどの機能を実現します FoundationModels 프레임워크를 사용하면 iOS 26+ 기기에서 LLM을 실행하여 텍스트 생성, 구조화된 출력 및 스냅샷 스트리밍 등의 기능을 구현할 수 있습니다 El framework FoundationModels permite ejecutar modelos de lenguaje grande (LLM) de Apple directamente en dispositivos iOS 26+. Ofrece generación de texto, salida guiada con @Generable, tool calling y snapshot streaming, todo con privacidad y soporte offline. Le framework FoundationModels permet d''exécuter des modèles de langage (LLM) Apple directement sur les appareils iOS 26+. Il offre génération de texte, sortie guidée avec @Generable, tool calling et snapshot streaming, avec confidentialité et hors-ligne. Das FoundationModels-Framework ermöglicht die Ausführung von Apple-Sprachmodellen (LLM) direkt auf iOS-26+-Geräten. Es bietet Textgenerierung, geführte Ausgabe mit @Generable, Tool Calling und Snapshot-Streaming bei Privatsphäre und Offline-Unterstützung. O FoundationModels On-Device é um framework da Apple para integração de modelos de linguagem em dispositivos iOS, permitindo gerar texto e realizar tarefas de processamento de linguagem natural FoundationModels на устройстве — это фреймворк Apple для интеграции языковых моделей на устройствах iOS, позволяющий генерировать текст и выполнять задачи обработки естественного языка FoundationModels على الجهاز هو إطار عمل من Apple لدمج نماذج اللغة في أجهزة iOS ، مما يسمح بإنشاء نصและการ実ناج التطبيقاتات من معالجة اللغة الطبيعية how to use foundation-models-on-device what is foundation-models on device Apple FoundationModels framework tutorial foundation-models-on-device vs cloud LLM on-device LLM iOS implementation @Generable structured output guide install foundation-models-on-device skill foundation-models-on-device setup iOS 26 Apple Intelligence on-device development iOS snapshot streaming implementation AIエージェント FoundationModels LLM iOS 26 在设备上运行LLM 文本生成 结构化输出 快照流媒体 On-device text generation using Apple FoundationModels framework Structured output generation with @Generable annotation Custom tool calling for extending LLM capabilities Snapshot streaming for real-time output monitoring Offline operation without cloud dependency Privacy-focused execution on iOS 26+ devices foundation-models-on-device is an AI Agent Skill that provides implementation patterns for Apple''s FoundationModels framework. It enables on-device LLM capabilities including text generation, guided generation with @Generable, custom tool calling, and snapshot streaming for iOS 26+ applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/nutrient-document-processing', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'nutrient-document-processing', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:23:34.596Z', '0a3c491ccad41aeabea783e3b42a53d1b790e5b68fcacfb62d954f81cc0c1467', '{"id":"affaan-m/everything-claude-code/nutrient-document-processing","name":"nutrient-document-processing","description":{"en":"The nutrient-document-processing skill utilizes the Nutrient DWS Processor API to process documents, supporting formats like PDF, DOCX, and XLSX. Developers can leverage this skill to streamline document workflows.","zh":"Nutrient文档处理AI代理通过Nutrient DWS Processor API提供专业的文档处理功能，支持多种格式转换、OCR识别、数据提取和安全处理，开发者可通过简单的API调用实现复杂的文档操作。","ja":"Nutrientドキュメント処理AIエージェントはNutrient DWS Processor APIを通じて専門的なドキュメント処理機能を提供し、多形式変換、OCR認識、データ抽出、セキュア処理をサポート。開発者は簡単なAPI呼び出しで複雑なドキュメント操作を実現可能。","ko":"Nutrient 문서 처리 AI 에이전트는 Nutrient DWS Processor API를 통해 전문적인 문서 처리 기능을 제공하며, 다양한 형식 변환, OCR 인식, 데이터 추출 및 보안 처리를 지원. 개발자는 간단한 API 호출로 복잡한 문서 조작 구현 가능.","es":"Skill de agente de IA que utiliza la API Nutrient DWS para procesar documentos. Permite a los desarrolladores convertir formatos, extraer texto y tablas mediante OCR, redactar información personal, añadir marcas de agua, firmar digitalmente y rellenar formularios PDF mediante solicitudes multipar...","fr":"Compétence d''agent IA exploitant l''API Nutrient DWS pour le traitement de documents. Permet aux développeurs de convertir des formats, d''extraire texte et tableaux par OCR, de masquer les données personnelles, d''ajouter des filigranes, de signer numériquement et de remplir des formulaires PDF via...","de":"Eine KI-Agenten-Fähigkeit, die die Nutrient DWS API zur Dokumentenverarbeitung nutzt. Ermöglicht Entwicklern das Konvertieren von Formaten, das Extrahieren von Text und Tabellen per OCR, das Schwärzen von personenbezogenen Daten, das Hinzufügen von Wasserzeichen, das digitale Signieren und das Au...","pt":"A skill Nutrient Document Processing permite que agentes IA processem documentos através da API Nutrient DWS. Converta formatos, faça OCR, extraia texto e tabelas, redacte PII, adicione marcas d''água, assine digitalmente e preencha formulários PDF.","ru":"Навык Nutrient Document Processing позволяет ИИ агентам обрабатывать документы через API Nutrient DWS. Конвертируйте форматы, выполняйте OCR, извлекайте текст и таблицы, редактируйте PII, добавляйте водяные знаки, подписывайте цифровые документы и заполняйте PDF формы.","ar":"تتيح مهارة Nutrient Document Processing لأدوات الذكاء الاصطناعي معالجة المستندات عبر واجهة برمجة تطبيقات Nutrient DWS. قم بتحويل الصيغ، والتعرف الضوئي على الحروف، واستخراج النصوص والجداول، وحذف البيانات الشخصية، وإضافة العلامات المائية، والتوقيع الرقمي، وملء نماذج PDF."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"nutrient-document-processing","description":"Process, convert, OCR, extract, redact, sign, and fill documents using the Nutrient DWS API. Works with PDFs, DOCX, XLSX, PPTX, HTML, and images.","bodyPreview":"# Nutrient Document Processing\n\nProcess documents with the [Nutrient DWS Processor API](https://www.nutrient.io/api/). Convert formats, extract text and tables, OCR scanned documents, redact PII, add watermarks, digitally sign, and fill PDF forms.\n\n## Setup\n\nGet a free API key at **[nutrient.io](https://dashboard.nutrient.io/sign_up/?product=processor)**\n\n```bash\nexport NUTRIENT_API_KEY=\"pdf_live_...\"\n```\n\nAll requests go to `https://api.nutrient.io/build` as multipart POST with an `instructions","body":"# Nutrient Document Processing\n\nProcess documents with the [Nutrient DWS Processor API](https://www.nutrient.io/api/). Convert formats, extract text and tables, OCR scanned documents, redact PII, add watermarks, digitally sign, and fill PDF forms.\n\n## Setup\n\nGet a free API key at **[nutrient.io](https://dashboard.nutrient.io/sign_up/?product=processor)**\n\n```bash\nexport NUTRIENT_API_KEY=\"pdf_live_...\"\n```\n\nAll requests go to `https://api.nutrient.io/build` as multipart POST with an `instructions` JSON field.\n\n## Operations\n\n### Convert Documents\n\n```bash\n# DOCX to PDF\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.docx=@document.docx\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.docx\"}]}'' \\\n  -o output.pdf\n\n# PDF to DOCX\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"output\":{\"type\":\"docx\"}}'' \\\n  -o output.docx\n\n# HTML to PDF\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"index.html=@index.html\" \\\n  -F ''instructions={\"parts\":[{\"html\":\"index.html\"}]}'' \\\n  -o output.pdf\n```\n\nSupported inputs: PDF, DOCX, XLSX, PPTX, DOC, XLS, PPT, PPS, PPSX, ODT, RTF, HTML, JPG, PNG, TIFF, HEIC, GIF, WebP, SVG, TGA, EPS.\n\n### Extract Text and Data\n\n```bash\n# Extract plain text\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"output\":{\"type\":\"text\"}}'' \\\n  -o output.txt\n\n# Extract tables as Excel\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"output\":{\"type\":\"xlsx\"}}'' \\\n  -o tables.xlsx\n```\n\n### OCR Scanned Documents\n\n```bash\n# OCR to searchable PDF (supports 100+ languages)\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"scanned.pdf=@scanned.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"scanned.pdf\"}],\"actions\":[{\"type\":\"ocr\",\"language\":\"english\"}]}'' \\\n  -o searchable.pdf\n```\n\nLanguages: Supports 100+ languages via ISO 639-2 codes (e.g., `eng`, `deu`, `fra`, `spa`, `jpn`, `kor`, `chi_sim`, `chi_tra`, `ara`, `hin`, `rus`). Full language names like `english` or `german` also work. See the [complete OCR language table](https://www.nutrient.io/guides/document-engine/ocr/language-support/) for all supported codes.\n\n### Redact Sensitive Information\n\n```bash\n# Pattern-based (SSN, email)\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"actions\":[{\"type\":\"redaction\",\"strategy\":\"preset\",\"strategyOptions\":{\"preset\":\"social-security-number\"}},{\"type\":\"redaction\",\"strategy\":\"preset\",\"strategyOptions\":{\"preset\":\"email-address\"}}]}'' \\\n  -o redacted.pdf\n\n# Regex-based\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"actions\":[{\"type\":\"redaction\",\"strategy\":\"regex\",\"strategyOptions\":{\"regex\":\"\\\\b[A-Z]{2}\\\\d{6}\\\\b\"}}]}'' \\\n  -o redacted.pdf\n```\n\nPresets: `social-security-number`, `email-address`, `credit-card-number`, `international-phone-number`, `north-american-phone-number`, `date`, `time`, `url`, `ipv4`, `ipv6`, `mac-address`, `us-zip-code`, `vin`.\n\n### Add Watermarks\n\n```bash\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"actions\":[{\"type\":\"watermark\",\"text\":\"CONFIDENTIAL\",\"fontSize\":72,\"opacity\":0.3,\"rotation\":-45}]}'' \\\n  -o watermarked.pdf\n```\n\n### Digital Signatures\n\n```bash\n# Self-signed CMS signature\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"document.pdf=@document.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"document.pdf\"}],\"actions\":[{\"type\":\"sign\",\"signatureType\":\"cms\"}]}'' \\\n  -o signed.pdf\n```\n\n### Fill PDF Forms\n\n```bash\ncurl -X POST https://api.nutrient.io/build \\\n  -H \"Authorization: Bearer $NUTRIENT_API_KEY\" \\\n  -F \"form.pdf=@form.pdf\" \\\n  -F ''instructions={\"parts\":[{\"file\":\"form.pdf\"}],\"actions\":[{\"type\":\"fillForm\",\"formFields\":{\"name\":\"Jane Smith\",\"email\":\"jane@example.com\",\"date\":\"2026-02-06\"}}]}'' \\\n  -o filled.pdf\n```\n\n## MCP Server (Alternative)\n\nFor native tool integration, use the MCP server instead of curl:\n\n```json\n{\n  \"mcpServers\": {\n    \"nutrient-dws\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@nutrient-sdk/dws-mcp-server\"],\n      \"env\": {\n        \"NUTRIENT_DWS_API_KEY\": \"YOUR_API_KEY\",\n        \"SANDBOX_PATH\": \"/path/to/working/directory\"\n      }\n    }\n  }\n}\n```\n\n## When to Use\n\n- Converting documents between formats (PDF, DOCX, XLSX, PPTX, HTML, images)\n- Extracting text, tables, or key-value pairs from PDFs\n- OCR on scanned documents or images\n- Redacting PII before sharing documents\n- Adding watermarks to drafts or confidential documents\n- Digitally signing contracts or agreements\n- Filling PDF forms programmatically\n\n## Links\n\n- [API Playground](https://dashboard.nutrient.io/processor-api/playground/)\n- [Full API Docs](https://www.nutrient.io/guides/dws-processor/)\n- [npm MCP Server](https://www.npmjs.com/package/@nutrient-sdk/dws-mcp-server)\n"},"category":"official","lastSynced":"2026-03-06T04:23:34.596Z","seo":{"title":{"en":"Nutrient-Document-Processing: API Setup Guide | AI Agent ...","zh":"Nutrient文档处理AI代理设置指南：PDF转换与OCR","ja":"Nutrientドキュメント処理AIエージェントのセットアップガイド","ko":"Nutrient 문서 처리 AI 에이전트 설정 가이드: PDF 변환 및 OCR","es":"Nutrient Document Processing: Guía de configuración para ...","fr":"Nutrient Document Processing : Guide de configuration pou...","de":"Nutrient Document Processing: Setup-Anleitung für die Dok...","pt":"Nutrient Document Processing: Guia de Integração para Age...","ru":"Nutrient Document Processing: Руководство по интеграции д...","ar":"Nutrient Document Processing: دليل الإعداد لأدوات الذكاء ..."},"description":{"en":"Unlock efficient document processing with Nutrient DWS API. Get started with our setup guide and discover how to convert, OCR, and extract data from PDFs, DO...","zh":"使用Nutrient DWS API处理PDF、DOCX、XLSX等文档。支持格式转换、OCR文字识别、表格提取、PII数据脱敏、数字签名和PDF表单填写。获取免费API密钥进行开发集成。","ja":"Nutrient DWS APIを使用してPDF、DOCX、XLSXなどのドキュメントを処理。形式変換、OCR文字認識、表抽出、PIIデータマスキング、デジタル署名、PDFフォーム入力に対応。無料APIキーで開発統合可能。","ko":"Nutrient DWS API로 PDF, DOCX, XLSX 등 문서 처리. 형식 변환, OCR 텍스트 인식, 테이블 추출, PII 데이터 마스킹, 디지털 서명 및 PDF 양식 작성 지원. 무료 API 키로 개발 통합 가능.","es":"Automatiza el procesamiento de documentos con la API Nutrient DWS. Extrae texto y tablas, convierte formatos, aplica OCR, redacta PII y firma PDFs mediante m...","fr":"Automatisez le traitement de documents avec l''API Nutrient DWS. Extrayez texte et tableaux, convertissez formats, effectuez OCR, masquez PII et signez des PD...","de":"Automatisieren Sie die Dokumentenverarbeitung mit der Nutrient DWS API. Extrahieren Sie Text und Tabellen, konvertieren Sie Formate, führen Sie OCR durch, sc...","pt":"Aprenda a integrar a API Nutrient DWS com Claude AI para processar PDFs, DOCX, imagens. Extraia texto, tabelas, redacte PII, assine digitalmente e preencha f...","ru":"Интегрируйте API Nutrient DWS с Claude AI для обработки PDF, DOCX, изображений. Извлекайте текст, таблицы, редактируйте PII, добавляйте цифровые подписи и за...","ar":"تعلم كيفية دمج واجهة برمجة تطبيقات Nutrient DWS مع Claude AI لمعالجة PDF وDOCX والصور. استخرج النصوص والجداول، واحذف البيانات الشخصية، ووقّع رقميًا، واملأ ال..."},"definition":{"en":"nutrient-document-processing is a skill that enables developers to process, convert, and extract data from documents using the Nutrient DWS API, supporting various file formats and operations","zh":"Nutrient文档处理是一款基于Nutrient DWS API的AI代理技能，专门处理PDF、DOCX、XLSX、PPTX、HTML和图像等文档格式。提供格式转换、文本提取、OCR识别、PII脱敏、数字水印、电子签名和PDF表单填充等高级文档处理功能。","ja":"Nutrientドキュメント処理はNutrient DWS APIに基づくAIエージェントスキルで、PDF、DOCX、XLSX、PPTX、HTMLおよび画像などのドキュメント形式を専門に処理。形式変換、テキスト抽出、OCR認識、PIIマスキング、デジタル透かし、電子署名、PDFフォーム入力などの高度なドキュメント処理機能を提供。","ko":"Nutrient 문서 처리는 Nutrient DWS API 기반 AI 에이전트 스킬로 PDF, DOCX, XLSX, PPTX, HTML 및 이미지 등 문서 형식을 전문적으로 처리. 형식 변환, 텍스트 추출, OCR 인식, PII 마스킹, 디지털 워터마크, 전자 서명, PDF 양식 작성 등의 고급 문서 처리 기능 제공.","es":"Nutrient Document Processing es una skill de agente de IA para desarrolladores que se integra con la API Nutrient DWS. Procesa documentos PDF, DOCX, XLSX, PPTX, HTML e imágenes mediante conversión, extracción, OCR, redacción de PII, firma digital y relleno de formularios usando solicitudes multipart POST a /build.","fr":"Nutrient Document Processing est une compétence d''agent IA pour développeurs s''intégrant à l''API Nutrient DWS. Elle traite les documents PDF, DOCX, XLSX, PPTX, HTML et images via conversion, extraction, OCR, masquage de PII, signature numérique et remplissage de formulaires à l''aide de requêtes multipart POST vers /build.","de":"Nutrient Document Processing ist eine KI-Agenten-Fähigkeit für Entwickler, die sich in die Nutrient DWS API integriert. Sie verarbeitet PDF-, DOCX-, XLSX-, PPTX-, HTML-Dokumente und Bilder durch Konvertierung, Extraktion, OCR, Schwärzung von PII, digitale Signatur und Formularausfüllung mittels Multipart-POST-Anfragen an /build.","pt":"Nutrient Document Processing é uma skill de MCP que integra a API Nutrient DWS com Claude AI para manipulação avançada de documentos. Processa PDFs, DOCX, XLSX, PPTX, HTML e imagens através de requisições multipart POST para a endpoint `/build`.","ru":"Nutrient Document Processing — это навык MCP, интегрирующий API Nutrient DWS с Claude AI для расширенной обработки документов. Обрабатывает PDF, DOCX, XLSX, PPTX, HTML и изображения через multipart POST запросы к эндпоинту `/build`.","ar":"Nutrient Document Processing هي مهارة MCP تدمج واجهة برمجة تطبيقات Nutrient DWS مع Claude AI للمعالجة المتقدمة للمستندات. تعالج PDF وDOCX وXLSX وPPTX وHTML والصور من خلال طلبات multipart POST إلى النقطة `/build`."},"features":{"en":["Converts documents between formats like PDF, DOCX, XLSX, and PPTX","Extracts text and tables from documents using OCR technology","Redacts personally identifiable information (PII) for secure document processing","Digitally signs and fills PDF forms using the Nutrient DWS Processor API","Supports multipart POST requests to https://api.nutrient.io/build","Integrates with the Nutrient DWS API using a free API key from nutrient.io"],"zh":["多格式文档转换（PDF、DOCX、XLSX、PPTX、HTML、图像）","OCR光学字符识别处理扫描文档","从文档中提取文本和表格数据","PII个人身份信息自动脱敏处理","数字水印添加和电子签名功能","PDF表单自动填写和数据处理"],"ja":["多形式ドキュメント変換（PDF、DOCX、XLSX、PPTX、HTML、画像）","OCR光学文字認識によるスキャン文書処理","ドキュメントからのテキスト及び表データ抽出","PII個人識別情報の自動マスキング処理","デジタル透かし追加及び電子署名機能","PDFフォーム自動入力及びデータ処理"],"ko":["다양 형식 문서 변환（PDF, DOCX, XLSX, PPTX, HTML, 이미지）","OCR 광학 문자 인식으로 스캔 문서 처리","문서에서 텍스트 및 테이블 데이터 추출","PII 개인식별정보 자동 마스킹 처리","디지털 워터마크 추가 및 전자 서명 기능","PDF 양식 자동 작성 및 데이터 처리"],"es":["Procesamiento de documentos mediante multipart POST a https://api.nutrient.io/build","Conversión de formatos entre PDF, DOCX, XLSX, PPTX, HTML e imágenes","OCR para extraer texto de documentos escaneados e imágenes","Extracción estructurada de texto y tablas de documentos","Redacción automática de Información de Identificación Personal (PII)","Funciones de firma digital y relleno de formularios PDF"],"fr":["Traitement de documents via multipart POST vers https://api.nutrient.io/build","Conversion de formats entre PDF, DOCX, XLSX, PPTX, HTML et images","OCR pour extraire le texte de documents scannés et d''images","Extraction structurée de texte et de tableaux à partir de documents","Masquage automatique des Informations Personnelles Identifiantes (PII)","Fonctions de signature numérique et de remplissage de formulaires PDF"],"de":["Dokumentenverarbeitung per Multipart-POST an https://api.nutrient.io/build","Formatumwandlung zwischen PDF, DOCX, XLSX, PPTX, HTML und Bildern","OCR zur Textextraktion aus gescannten Dokumenten und Bildern","Strukturierte Extraktion von Text und Tabellen aus Dokumenten","Automatische Schwärzung von personenbezogenen Daten (PII)","Funktionen für digitale Signatur und das Ausfüllen von PDF-Formularen"],"pt":["Conversão de formatos entre PDF, DOCX, XLSX, PPTX, HTML e imagens","OCR para extração de texto de documentos digitalizados","Extração estruturada de texto e tabelas de documentos","Redação automática de PII (Informação Pessoal Identificável)","Assinatura digital e preenchimento de formulários PDF","Adição de marcas d''água personalizadas em documentos"],"ru":["Конвертация форматов между PDF, DOCX, XLSX, PPTX, HTML и изображениями","OCR для извлечения текста из отсканированных документов","Структурированное извлечение текста и таблиц из документов","Автоматическое редактирование PII (Персонально Идентифицируемой Информации)","Цифровая подпись и заполнение PDF форм","Добавление пользовательских водяных знаков в документы"],"ar":["تحويل الصيغ بين PDF وDOCX وXLSX وPPTX وHTML والصور","التعرف الضوئي على الحروف (OCR) لاستخراج النصوص من المستندات الممسوحة ضوئيًا","استخراج منظم للنصوص والجداول من المستندات","حذف تلقائي للبيانات الشخصية (PII)","التوقيع الرقمي وملء نماذج PDF","إضافة علامات مائية مخصصة إلى المستندات"]},"keywords":{"en":["how to use nutrient-document-processing","nutrient-document-processing api setup","document processing with nutrient dws api","nutrient-document-processing vs other document processing tools","nutrient-document-processing install guide","what is nutrient-document-processing","nutrient-document-processing tutorial","nutrient-document-processing alternative solutions","nutrient-document-processing setup guide for developers"],"zh":["Nutrient文档处理API","PDF OCR识别","文档格式转换","PII数据脱敏","数字签名PDF","PDF表单填写","AI代理开发","多部分POST请求","Nutrient API密钥"],"ja":["Nutrientドキュメント処理API","PDF OCR認識","ドキュメント形式変換","PIIデータマスキング","デジタル署名PDF","PDFフォーム入力","AIエージェント開発","マルチパートPOSTリクエスト","Nutrient APIキー"],"ko":["Nutrient 문서 처리 API","PDF OCR 인식","문서 형식 변환","PII 데이터 마스킹","디지털 서명 PDF","PDF 양식 작성","AI 에이전트 개발","멀티파트 POST 요청","Nutrient API 키"],"es":["nutrient document processing api","procesar documentos con nutrient","extraer texto pdf nutrient api","ocr documentos python","redactar pii automáticamente","herramientas de ia para desarrolladores","llm document processing","mcp claude code","convertir docx a pdf api","api nutrient dws multipart post"],"fr":["api nutrient document processing","traiter documents avec nutrient","extraire texte pdf nutrient api","ocr documents python","masquer pii automatiquement","outils d''ia pour développeurs","llm traitement documents","mcp claude code","convertir docx en pdf api","api nutrient dws multipart post"],"de":["nutrient document processing api","dokumente verarbeiten mit nutrient","text aus pdf extrahieren nutrient api","ocr dokumente python","pii automatisch schwärzen","ki-tools für entwickler","llm dokumentenverarbeitung","mcp claude code","docx zu pdf konvertieren api","api nutrient dws multipart post"],"pt":["nutrient document processing api","integrar nutrient dws claude ai","processar pdf com agente ia","extrair texto tabelas nutrient","redactar pii documentos automaticamente","assinar digitalmente pdf nutrient api","nutrient api multipart post build","ocr documentos claude code","preencher formularios pdf programaticamente","api nutrient io developer"],"ru":["nutrient document processing api","интеграция nutrient dws claude ai","обработка pdf с ИИ агентом","извлечение текста таблиц nutrient","редактирование pii документов автоматически","цифровая подпись pdf nutrient api","nutrient api multipart post build","ocr документы claude code","заполнение pdf форм программно","api nutrient io разработчик"],"ar":["واجهة برمجة تطبيقات nutrient document processing","دمج nutrient dws مع claude ai","معالجة pdf بأداة الذكاء الاصطناعي","استخراج النصوص والجداول nutrient","حذف البيانات الشخصية تلقائيًا من المستندات","التوقيع الرقمي على pdf باستخدام nutrient api","nutrient api multipart post build","ocr المستندات claude code","ملء نماذج pdf برمجيًا","مطورو api nutrient io"]}},"agentAnalysis":{"suitability":{"en":"Essential for Document Automation Agents requiring comprehensive PDF processing, OCR, and redaction capabilities.","zh":"对于需要全面PDF处理、OCR和编辑功能的文档自动化AI Agent至关重要。","ja":"包括的なPDF処理、OCR、および墨消し機能を必要とする文書自動化エージェントに不可欠です。","ko":"포괄적인 PDF 처리, OCR 및 편집 기능이 필요한 문서 자동화 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Automatización de Documentos que requieren un procesamiento de PDF, OCR y capacidad de redacción integral.","fr":"Essentiel pour les Agents d''Automatisation de Documents nécessitant un traitement de PDF, d''OCR et de rédaction complet.","de":"Wesentlich für Dokumentautomatisierungsagenten, die umfassende PDF-Verarbeitung, OCR und Redaktionsfunktionen erfordern.","pt":"Essencial para Agentes de Automação de Documentos que requerem capacidades abrangentes de processamento de PDF, OCR e redação.","ru":"Необходим для агентов автоматизации документов, требующих комплексной обработки PDF, OCR и возможностей редактирования.","ar":"ضروري لوكلاء أتمتة المستندات التي تتطلب قدرات شاملة لمعالجة PDF والتعرف الضوئي على الحروف (OCR) وإخفاء المعلومات."},"recommendation":{"en":"Enables direct integration with Nutrient DWS Processor API for advanced document operations including OCR conversion, PII redaction, digital signing, and PDF form filling. Supports multipart POST requests to https://api.nutrient.io/build with structured instructions for processing PDFs, DOCX, XLSX, PPTX, HTML, and image formats.","zh":"支持与Nutrient DWS Processor API直接集成，以执行OCR转换、PII编辑、数字签名和PDF表单填充等高级文档操作。支持向https://api.nutrient.io/build发送多部分POST请求，并提供结构化指令以处理PDF、DOCX、XLSX、PPTX、HTML及图像格式。","ja":"OCR変換、PIIの墨消し、デジタル署名、PDFフォームへの自動入力を含む高度な文書操作のために、Nutrient DWS Processor APIとの直接統合を可能にします。PDF、DOCX、XLSX、PPTX、HTML、画像形式を処理するための構造化された指示と共に、https://api.nutrient.io/build へのマルチパートPOSTリクエストをサポートします。","ko":"OCR 변환, PII 편집, 디지털 서명 및 PDF 양식 자동 채우기를 포함한 고급 문서 작업을 위해 Nutrient DWS Processor API와의 직접 통합을 가능하게 합니다. PDF, DOCX, XLSX, PPTX, HTML 및 이미지 형식을 처리하기 위한 구조화된 지침과 함께 https://api.nutrient.io/build 로의 multipart POST 요청을 지원합니다.","es":"Permite la integración directa con la API de Nutrient DWS Processor para operaciones de documentos avanzadas, incluyendo la conversión OCR, la redacción de PII, la firma digital y el llenado de formularios PDF. Admite solicitudes POST multipart a https://api.nutrient.io/build con instrucciones estructuradas para el procesamiento de PDF, DOCX, XLSX, PPTX, HTML y formatos de imagen.","fr":"Permet l''intégration directe avec l''API de Nutrient DWS Processor pour des opérations de documents avancées, y compris la conversion OCR, la rédaction de PII, la signature numérique et le remplissage de formulaires PDF. Prend en charge les requêtes POST multipart à https://api.nutrient.io/build avec des instructions structurées pour le traitement de PDF, DOCX, XLSX, PPTX, HTML et formats d''image.","de":"Ermöglicht die direkte Integration mit der Nutrient DWS Processor API für erweiterte Dokumentenoperationen, einschließlich OCR-Konvertierung, PII-Redaktion, digitalem Signieren und PDF-Formularen. Unterstützt multipart-POST-Anfragen an https://api.nutrient.io/build mit strukturierten Anweisungen für die Verarbeitung von PDF, DOCX, XLSX, PPTX, HTML und Bildformaten.","pt":"Permite a integração direta com a API do Nutrient DWS Processor para operações avançadas de documentos, incluindo conversão OCR, redação de PII, assinatura digital e preenchimento de formulários PDF. Suporta solicitações multipart POST para https://api.nutrient.io/build com instruções estruturadas para processar formatos PDF, DOCX, XLSX, PPTX, HTML e imagens.","ru":"Обеспечивает прямую интеграцию с API Nutrient DWS Processor для расширенных операций с документами, включая преобразование OCR, редактирование PII, цифровую подпись и заполнение PDF форм. Поддерживает многокомпонентные POST запросы по https://api.nutrient.io/build со структурированными инструкциями для обработки форматов PDF, DOCX, XLSX, PPTX, HTML и изображений.","ar":"يتيح التكامل المباشر مع واجهة برمجة تطبيقات Nutrient DWS Processor للعمليات المتقدمة على المستندات، بما في ذلك التحويل بالتعرف الضوئي على الحروف (OCR)، وإخفاء المعلومات الشخصية (PII)، والتوقيع الرقمي، وملء نماذج PDF. يدعم طلبات POST متعددة الأجزاء إلى https://api.nutrient.io/build مع تعليمات منظمة لمعالجة صيغ PDF وDOCX وXLSX وPPTX وHTML والصور."},"useCases":{"en":["Converting scanned documents to searchable PDFs via OCR","Redacting sensitive PII information from legal documents","Digitally signing contracts and filling PDF forms automatically"],"zh":["通过OCR将扫描文档转换为可搜索的PDF","从法律文书中编辑敏感的PII信息","自动对合同进行数字签名并填写PDF表单"],"ja":["OCRによるスキャン文書の検索可能PDFへの変換","法的文書からの機密PII情報の墨消し","契約へのデジタル署名とPDFフォームの自動入力"],"ko":["OCR를 통해 스캔한 문서를 검색 가능한 PDF로 변환","법률 문서에서 민감한 PII 정보 편집","계약서에 디지털 서명 및 PDF 양식 자동 채우기"],"es":["Conversión de documentos escaneados a PDFs buscables a través de OCR","Redacción de información de PII sensible de documentos legales","Firma digital de contratos y llenado automático de formularios PDF"],"fr":["Conversion de documents scannés en PDF recherchables via OCR","Réduction d''informations de PII sensibles de documents juridiques","Signature numérique de contrats et remplissage automatique de formulaires PDF"],"de":["Konvertierung von gescannten Dokumenten in durchsuchbare PDFs über OCR","Redaktion von sensiblen PII-Informationen aus rechtlichen Dokumenten","Digitale Signatur von Verträgen und automatisches Ausfüllen von PDF-Formularen"],"pt":["Converter documentos digitalizados em PDFs pesquisáveis via OCR","Redatar informações confidenciais de PII de documentos legais","Assinar contratos digitalmente e preencher formulários PDF automaticamente"],"ru":["Преобразование отсканированных документов в доступные для поиска PDF с помощью OCR","Редактирование конфиденциальной информации PII из юридических документов","Цифровое подписание контрактов и автоматическое заполнение PDF форм"],"ar":["تحويل المستندات الممسوحة ضوئياً إلى ملفات PDF قابلة للبحث عبر التعرف الضوئي على الحروف (OCR)","إخفاء معلومات التعريف الشخصية الحساسة (PII) من المستندات القانونية","التوقيع الرقمي على العقود وملء نماذج PDF تلقائياً"]},"limitations":{"en":["Requires NUTRIENT_API_KEY environment variable","Dependent on external Nutrient DWS API availability","Limited to supported formats: PDF, DOCX, XLSX, PPTX, HTML, images"],"zh":["需要设置NUTRIENT_API_KEY环境变量","依赖外部Nutrient DWS API的可用性","仅限于支持的格式：PDF、DOCX、XLSX、PPTX、HTML、图像"],"ja":["NUTRIENT_API_KEY環境変数の設定が必要","外部Nutrient DWS APIの可用性に依存","サポート形式に限定: PDF、DOCX、XLSX、PPTX、HTML、画像"],"ko":["NUTRIENT_API_KEY 환경 변수 설정 필요","외부 Nutrient DWS API 가용성에 의존","지원 형식으로 제한됨: PDF, DOCX, XLSX, PPTX, HTML, 이미지"],"es":["Requiere la variable de entorno NUTRIENT_API_KEY","Dependiente de la disponibilidad externa de la API de Nutrient DWS","Limitado a formatos compatibles: PDF, DOCX, XLSX, PPTX, HTML, imágenes"],"fr":["Nécessite la variable d''environnement NUTRIENT_API_KEY","Dépend de la disponibilité externe de l''API de Nutrient DWS","Limité aux formats pris en charge : PDF, DOCX, XLSX, PPTX, HTML, images"],"de":["Erfordert die Umgebungsvariable NUTRIENT_API_KEY","Abhängig von der Verfügbarkeit der externen Nutrient DWS API","Begrenzt auf unterstützte Formate: PDF, DOCX, XLSX, PPTX, HTML, Bilder"],"pt":["Requer a variável de ambiente NUTRIENT_API_KEY","Dependente da disponibilidade externa da API Nutrient DWS","Limitado aos formatos suportados: PDF, DOCX, XLSX, PPTX, HTML, imagens"],"ru":["Требует переменную окружения NUTRIENT_API_KEY","Зависит от доступности внешнего API Nutrient DWS","Ограничено поддерживаемыми форматами: PDF, DOCX, XLSX, PPTX, HTML, изображения"],"ar":["يتطلب متغير البيئة NUTRIENT_API_KEY","يعتمد على توفر واجهة برمجة تطبيقات Nutrient DWS الخارجية","مقتصر على الصيغ المدعومة: PDF وDOCX وXLSX وPPTX وHTML والصور"]},"version":4},"contentHash":"0a3c491ccad41aeabea783e3b42a53d1b790e5b68fcacfb62d954f81cc0c1467","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":95}');
