INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/python-patterns', 'python-patterns', 'affaan-m', 'everything-claude-code', 'official', 'python-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity Python Patterns provides AI-powered guidance on Pythonic idioms, PEP 8 standards, and type hints for building robust applications. It assists developers in writing readable, efficient, and maintainable Python code during development, review, and refactoring phases. Python Patterns提供了Python开发的最佳实践，包括PEP 8标准、类型提示和可读性原则 Python パターンは、PEP 8スタンダード、タイプヒント、可読性原則などのPython開発のベストプラクティスを提供します Python Patterns는 PEP 8标准, 타입 힌트, 가독성 원칙 등을 포함한 Python 개발의 모범 사례를 제공합니다 Patrones de Python para desarrollar aplicaciones robustas y eficientes. Aprende a aplicar PEP 8 y type hints para mejorar la legibilidad y el rendimiento. Modèles Python pour développer des applications robustes et efficaces. Apprenez à appliquer PEP 8 et type hints pour améliorer la lisibilité et les performances. Python-Muster für die Entwicklung von robusten und effizienten Anwendungen. Erfahren Sie, wie Sie PEP 8 und Type-Hinweise anwenden, um die Lesbarkeit und Leistung zu verbessern. Padrões pythonicos e melhores práticas para construir aplicações Python robustas e eficientes ИИ Агенты для Python: лучшие практики и рекомендации для создания надежных и эффективных приложений نماذج بايثون وأفضل الممارسات لإنشاء تطبيقات بايثون قوية وفعالة python patterns best practices PEP 8 standards AI agent python type hints implementation python code review patterns refactoring python code with AI python package design principles python-patterns setup guide pythonic idioms for developers maintainable python applications python development productivity tools Python Patterns AIエージェント PEP 8标准 类型提示 可读性 Python开发最佳实践 高效Python应用 可维护Python应用 Enforces PEP 8 coding standards for Python development Provides type hint implementation guidance (list[User]) Offers code review patterns for existing Python projects Supports refactoring strategies for Python modules Delivers package design principles for Python applications Promotes readability-focused Pythonic idioms python-patterns is an AI agent skill that delivers idiomatic Python patterns and best practices for building robust, efficient, and maintainable applications. It emphasizes readability, PEP 8 standards, and type hints for professional Python development workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/search-first', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'search-first', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:31:11.557Z', '752b24a8a06b3df1ce35598a789af92a72b61ecbb3c73e69d9af38708015d903', '{"id":"affaan-m/everything-claude-code/search-first","name":"search-first","description":{"en":"The search-first skill systematizes the ''research before implementing'' workflow for developers. It automatically invokes a researcher agent to find existing solutions, libraries, and patterns before writing custom code, optimizing development within AI agent platforms like Claude.","zh":"Search-First 是一种研究优先的开发工作流程，通过搜索现有工具和库来减少重复工作","ja":"Search-First は、既存のツールやライブラリを検索することで重複作業を減らす開発ワークフローです","ko":"Search-First는 기존 도구와 라이브러리를 검색하여 중복 작업을 줄이는 개발 워크플로우입니다","es":"search-first es un flujo de trabajo de investigación que sistemátiza la búsqueda de soluciones existentes antes de implementar código personalizado","fr":"search-first est un flux de travail de recherche qui systématise la recherche de solutions existantes avant de mettre en œuvre du code personnalisé","de":"search-first ist ein Forschungs-Workflow, der die Suche nach vorhandenen Lösungen vor der Implementierung von benutzerdefiniertem Code systematisiert","pt":"O skill search-first sistematiza o workflow de pesquisa antes de codificar, invocando um agente pesquisador para identificar ferramentas, bibliotecas e padrões existentes. Ideal para evitar retrabalho e adotar soluções consolidadas no ecossistema dev.","ru":"Навык search-first систематизирует workflow исследования перед кодированием, запуская агента-исследователя для идентификации существующих инструментов, библиотек и паттернов. Идеален для избежания переделок и принятия проверенных решений в экосистеме разработки.","ar":"ينظم مهارة search-first workflow البحث قبل البرمجة، باستدعاء وكيل الباحث لتحديد الأدوات والمكتبات والأنماط الموجودة. مثالي لتجنب إعادة العمل واعتماد حلول مثبتة في ecosystem المطورين باستخدام أدوات الذكاء الاصطناعي."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"search-first","description":"Research-before-coding workflow. Search for existing tools, libraries, and patterns before writing custom code. Invokes the researcher agent.","bodyPreview":"# /search-first — Research Before You Code\n\nSystematizes the \"search for existing solutions before implementing\" workflow.\n\n## Trigger\n\nUse this skill when:\n- Starting a new feature that likely has existing solutions\n- Adding a dependency or integration\n- The user asks \"add X functionality\" and you''re about to write code\n- Before creating a new utility, helper, or abstraction\n\n## Workflow\n\n```\n┌─────────────────────────────────────────────┐\n│  1. NEED ANALYSIS                           │\n│     D","body":"# /search-first — Research Before You Code\n\nSystematizes the \"search for existing solutions before implementing\" workflow.\n\n## Trigger\n\nUse this skill when:\n- Starting a new feature that likely has existing solutions\n- Adding a dependency or integration\n- The user asks \"add X functionality\" and you''re about to write code\n- Before creating a new utility, helper, or abstraction\n\n## Workflow\n\n```\n┌─────────────────────────────────────────────┐\n│  1. NEED ANALYSIS                           │\n│     Define what functionality is needed      │\n│     Identify language/framework constraints  │\n├─────────────────────────────────────────────┤\n│  2. PARALLEL SEARCH (researcher agent)      │\n│     ┌──────────┐ ┌──────────┐ ┌──────────┐  │\n│     │  npm /   │ │  MCP /   │ │  GitHub / │  │\n│     │  PyPI    │ │  Skills  │ │  Web      │  │\n│     └──────────┘ └──────────┘ └──────────┘  │\n├─────────────────────────────────────────────┤\n│  3. EVALUATE                                │\n│     Score candidates (functionality, maint, │\n│     community, docs, license, deps)         │\n├─────────────────────────────────────────────┤\n│  4. DECIDE                                  │\n│     ┌─────────┐  ┌──────────┐  ┌─────────┐  │\n│     │  Adopt  │  │  Extend  │  │  Build   │  │\n│     │ as-is   │  │  /Wrap   │  │  Custom  │  │\n│     └─────────┘  └──────────┘  └─────────┘  │\n├─────────────────────────────────────────────┤\n│  5. IMPLEMENT                               │\n│     Install package / Configure MCP /       │\n│     Write minimal custom code               │\n└─────────────────────────────────────────────┘\n```\n\n## Decision Matrix\n\n| Signal | Action |\n|--------|--------|\n| Exact match, well-maintained, MIT/Apache | **Adopt** — install and use directly |\n| Partial match, good foundation | **Extend** — install + write thin wrapper |\n| Multiple weak matches | **Compose** — combine 2-3 small packages |\n| Nothing suitable found | **Build** — write custom, but informed by research |\n\n## How to Use\n\n### Quick Mode (inline)\n\nBefore writing a utility or adding functionality, mentally run through:\n\n0. Does this already exist in the repo? → `rg` through relevant modules/tests first\n1. Is this a common problem? → Search npm/PyPI\n2. Is there an MCP for this? → Check `~/.claude/settings.json` and search\n3. Is there a skill for this? → Check `~/.claude/skills/`\n4. Is there a GitHub implementation/template? → Run GitHub code search for maintained OSS before writing net-new code\n\n### Full Mode (agent)\n\nFor non-trivial functionality, launch the researcher agent:\n\n```\nTask(subagent_type=\"general-purpose\", prompt=\"\n  Research existing tools for: [DESCRIPTION]\n  Language/framework: [LANG]\n  Constraints: [ANY]\n\n  Search: npm/PyPI, MCP servers, Claude Code skills, GitHub\n  Return: Structured comparison with recommendation\n\")\n```\n\n## Search Shortcuts by Category\n\n### Development Tooling\n- Linting → `eslint`, `ruff`, `textlint`, `markdownlint`\n- Formatting → `prettier`, `black`, `gofmt`\n- Testing → `jest`, `pytest`, `go test`\n- Pre-commit → `husky`, `lint-staged`, `pre-commit`\n\n### AI/LLM Integration\n- Claude SDK → Context7 for latest docs\n- Prompt management → Check MCP servers\n- Document processing → `unstructured`, `pdfplumber`, `mammoth`\n\n### Data & APIs\n- HTTP clients → `httpx` (Python), `ky`/`got` (Node)\n- Validation → `zod` (TS), `pydantic` (Python)\n- Database → Check for MCP servers first\n\n### Content & Publishing\n- Markdown processing → `remark`, `unified`, `markdown-it`\n- Image optimization → `sharp`, `imagemin`\n\n## Integration Points\n\n### With planner agent\nThe planner should invoke researcher before Phase 1 (Architecture Review):\n- Researcher identifies available tools\n- Planner incorporates them into the implementation plan\n- Avoids \"reinventing the wheel\" in the plan\n\n### With architect agent\nThe architect should consult researcher for:\n- Technology stack decisions\n- Integration pattern discovery\n- Existing reference architectures\n\n### With iterative-retrieval skill\nCombine for progressive discovery:\n- Cycle 1: Broad search (npm, PyPI, MCP)\n- Cycle 2: Evaluate top candidates in detail\n- Cycle 3: Test compatibility with project constraints\n\n## Examples\n\n### Example 1: \"Add dead link checking\"\n```\nNeed: Check markdown files for broken links\nSearch: npm \"markdown dead link checker\"\nFound: textlint-rule-no-dead-link (score: 9/10)\nAction: ADOPT — npm install textlint-rule-no-dead-link\nResult: Zero custom code, battle-tested solution\n```\n\n### Example 2: \"Add HTTP client wrapper\"\n```\nNeed: Resilient HTTP client with retries and timeout handling\nSearch: npm \"http client retry\", PyPI \"httpx retry\"\nFound: got (Node) with retry plugin, httpx (Python) with built-in retry\nAction: ADOPT — use got/httpx directly with retry config\nResult: Zero custom code, production-proven libraries\n```\n\n### Example 3: \"Add config file linter\"\n```\nNeed: Validate project config files against a schema\nSearch: npm \"config linter schema\", \"json schema validator cli\"\nFound: ajv-cli (score: 8/10)\nAction: ADOPT + EXTEND — install ajv-cli, write project-specific schema\nResult: 1 package + 1 schema file, no custom validation logic\n```\n\n## Anti-Patterns\n\n- **Jumping to code**: Writing a utility without checking if one exists\n- **Ignoring MCP**: Not checking if an MCP server already provides the capability\n- **Over-customizing**: Wrapping a library so heavily it loses its benefits\n- **Dependency bloat**: Installing a massive package for one small feature\n"},"category":"official","lastSynced":"2026-03-06T04:31:11.557Z","seo":{"title":{"en":"search-first: Research-Before-Coding Workflow Setup Guide...","zh":"Search-First 工作流程指南 - 提高开发效率","ja":"Search-First ワークフロー設定ガイド - 開発生産性の向上","ko":"Search-First 워크플로우 설정 가이드 - 개발 생산성 향상","es":"Guía de Configuración de search-first: Flujos de Trabajo ...","fr":"Guide de Configuration de search-first: Flux de Travail d...","de":"Einrichtungsanleitung für search-first: Forschungs-Workflow","pt":"search-first: Guia de Implementação para Fluxo de Pesquis...","ru":"search-first: Руководство по внедрению workflow ''Исследов...","ar":"search-first: دليل الإعداد لاستراتيجية البحث قبل البرمجة ..."},"description":{"en":"Stop writing custom code from scratch. The search-first AI agent skill automates the research workflow, invoking a researcher agent to find existing tools & ...","zh":"了解 Search-First 技术，优化开发流程，减少重复工作，提高代码质量","ja":"Search-First 技術を活用して開発プロセスを最適化し、コード品質を向上させる","ko":"Search-First 기술을 활용하여 개발 프로세스를 최적화하고 코드 품질을 향상시키는 방법","es":"Optimice su flujo de trabajo de desarrollo con search-first, investigando soluciones existentes antes de escribir código","fr":"Optimisez votre flux de travail de développement avec search-first, en recherchant des solutions existantes avant d''écrire du code","de":"Optimieren Sie Ihren Entwicklungs-Workflow mit search-first, indem Sie vorhandene Lösungen recherchieren, bevor Sie Code schreiben","pt":"Automatize o workflow ''pesquisar antes de implementar'' com search-first. Aciona um agente pesquisador para encontrar bibliotecas e padrões existentes, evitan...","ru":"Автоматизируйте workflow ''исследовать перед реализацией'' с search-first. Запускает агента-исследователя для поиска существующих библиотек и паттернов, избега...","ar":"أتمتة workflow ''البحث قبل التنفيذ'' باستخدام search-first. يستدعي وكيل الباحث للعثور على مكتبات وأنماط موجودة، متجنبًا البرمجة المخصصة غير الضرورية. يعزز إنتا..."},"definition":{"en":"search-first is an AI agent skill that automates the research-before-coding workflow. It triggers a researcher agent to search for existing tools, libraries, and patterns, preventing redundant custom code development within MCP-compatible environments like Claude Code.","zh":"Search-First 是一种系统化的开发工作流程，优先搜索现有解决方案","ja":"Search-First は、既存の解決策を検索する優先順位の付いた開発ワークフローです","ko":"Search-First는 기존 解決方案을 검색하는 우선순위가 있는 개발 워크플로우입니다","es":"search-first es un agente de investigación que invoca al agente investigador para buscar herramientas y patrones existentes","fr":"search-first est un agent de recherche qui invoque l''agent de recherche pour trouver des outils et des modèles existants","de":"search-first ist ein Forschungsagent, der den Forschungsagenten aufruft, um vorhandene Tools und Muster zu suchen","pt":"search-first é um skill de AI Agent para MCP que automatiza o fluxo de ''pesquisar antes de codar''. Ele invoca um agente pesquisador para encontrar soluções, bibliotecas e padrões existentes, prevenindo a implementação de código customizado desnecessário.","ru":"search-first — это навык ИИ Агента для MCP, автоматизирующий workflow ''исследовать перед кодированием''. Он запускает агента-исследователя для поиска существующих решений, библиотек и паттернов, предотвращая реализацию ненужного кастомного кода.","ar":"search-first هو مهارة لوكيل الذكاء الاصطناعي لـ MCP تؤتمت workflow ''البحث قبل البرمجة''. يستدعي وكيل الباحث للعثور على حلول ومكتبات وأنماط موجودة، مما يمنع تنفيذ برمجة مخصصة غير ضرورية باستخدام أدوات الذكاء الاصطناعي."},"features":{"en":["Automatically invokes a dedicated researcher agent to find existing solutions","Triggers based on specific development intents like ''add X functionality''","Systematizes the workflow before creating new utilities, helpers, or abstractions","Integrates with MCP (Model Context Protocol) for AI agent tooling","Designed for use within Anthropic''s Claude and Claude Code environments"],"zh":["系统化的研究优先开发工作流程","减少重复工作和代码","提高代码质量和可维护性","支持快速开发和集成","优化开发者生产力"],"ja":["システム化された研究優先開発ワークフロー","重複作業とコードの削減","コード品質とメンテナンス性の向上","迅速な開発と統合のサポート","開発者生産性の最適化"],"ko":["시스템화된 연구 우선 개발 워크플로우","중복 작업과 코드의 감소","코드 품질과 유지보수성의 향상","迅速한 개발과 통합의 지원","개발자 생산성의 최적화"],"es":["Invocación del agente investigador para buscar soluciones existentes","Análisis de necesidades para identificar posibles soluciones","Integración con herramientas y bibliotecas existentes","Flujo de trabajo sistemático para evitar la duplicación de esfuerzos","Compatibilidad con tecnologías como CLI y LLM"],"fr":["Invocation de l''agent de recherche pour trouver des solutions existantes","Analyse des besoins pour identifier des solutions possibles","Intégration avec des outils et des bibliothèques existants","Flux de travail systématique pour éviter la duplication d''efforts","Compatibilité avec des technologies telles que CLI et LLM"],"de":["Aufruf des Forschungsagenten, um vorhandene Lösungen zu suchen","Analyse der Anforderungen, um mögliche Lösungen zu identifizieren","Integration mit vorhandenen Tools und Bibliotheken","Systematischer Workflow, um die Doppelarbeit zu vermeiden","Kompatibilität mit Technologien wie CLI und LLM"],"pt":["Aciona automaticamente um agente pesquisador integrado","Analisa a necessidade antes de escrever código customizado","Identifica bibliotecas e dependências existentes para novas funcionalidades","Sugere utilitários e abstrações pré-existentes do ecossistema","Optimiza integrações evitando retrabalho","Workflow sistemático para adição de dependências"],"ru":["Автоматически запускает встроенного агента-исследователя","Анализирует потребность перед написанием кастомного кода","Идентифицирует существующие библиотеки и зависимости для новых функций","Предлагает готовые утилиты и абстракции из экосистемы","Оптимизирует интеграции, избегая переделок","Системный workflow для добавления зависимостей"],"ar":["يستدعي تلقائيًا وكيل الباحث المدمج","يحلل الحاجة قبل كتابة برمجة مخصصة","يحدد المكتبات والتبعيات الموجودة للميزات الجديدة","يقترح أدوات وتجريدات موجودة مسبقًا في الـ ecosystem","يحسن التكاملات بتجنب إعادة العمل","workflow منهجي لإضافة التبعيات باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["what is search-first MCP skill","how to use search-first researcher agent","search-first vs manual code research","search-first install Claude developer tool","search-first setup guide for AI agents","research-before-coding workflow automation","Anthropic Claude Code productivity tools","MCP agent skills for developers"],"zh":["Search-First","AIエージェント","开发工具","代码优化","开发生产力","研究优先开发","代码质量","开发效率"],"ja":["Search-First","AIエージェント","開発ツール","コード最適化","開発生産性","研究優先開発","コード品質","開発効率"],"ko":["Search-First","AI 에이전트","개발 도구","코드 최적화","개발 생산성","연구 우선 개발","코드 품질","개발 효율"],"es":["agentes de investigación","herramientas de desarrollo","flujo de trabajo de investigación","search-first","CLI","LLM","desarrollo de software","productividad","optimización de código"],"fr":["agents de recherche","outils de développement","flux de travail de recherche","search-first","CLI","LLM","développement de logiciels","productivité","optimisation de code"],"de":["Forschungsagenten","Entwicklungstools","Forschungs-Workflow","search-first","CLI","LLM","Software-Entwicklung","Produktivität","Code-Optimierung"],"pt":["search-first MCP agent","pesquisar antes de codar","workflow pesquisa bibliotecas","automatizar pesquisa código","agente pesquisador AI","evitar código customizado","otimizar dependências desenvolvimento","ferramentas produtividade dev"],"ru":["search-first MCP агент","исследовать перед кодированием","workflow поиска библиотек","автоматизация поиска кода","агент-исследователь ИИ","избегать кастомного кода","оптимизация зависимостей разработки","инструменты продуктивности разработчика"],"ar":["search-first MCP agent","البحث قبل البرمجة","workflow البحث عن المكتبات","أتمتة البحث عن الكود","وكيل الباحث بالذكاء الاصطناعي","تجنب البرمجة المخصصة","تحسين تبعيات التطوير","أدوات إنتاجية المطورين باستخدام أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Essential for Code Generation Agents that prioritize efficiency and avoid reinventing the wheel.","zh":"对于优先考虑效率并避免重复造轮子的代码生成智能体至关重要。","ja":"効率を優先し、車輪の再発明を避けるコード生成エージェントにとって必須です。","ko":"효율성을 우선시하고 재발명을 피하는 코드 생성 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Generación de Código que priorizan la eficiencia y evitan reinventar la rueda.","fr":"Essentiel pour les Agents de Génération de Code qui privilégient l''efficacité et évitent de réinventer la roue.","de":"Wesentlich für Code-Generierungsagenten, die Effizienz priorisieren und das erneute Erfinden des Rades vermeiden.","pt":"Essencial para Agentes de Geração de Código que priorizam a eficiência e evitam reinventar a roda.","ru":"Необходимо для агентов генерации кода, которые уделяют приоритетное внимание эффективности и избегают изобретения велосипеда.","ar":"أساسي لوكلاء توليد التعليمات البرمجية الذين يعطون الأولوية للكفاءة ويتجنبون إعادة اختراع العجلة."},"recommendation":{"en":"Systematizes a research-before-coding workflow by invoking researcher agents to find existing tools, libraries, and patterns before writing custom code. This prevents redundant development and ensures optimal dependency integration for new features, utilities, or abstractions.","zh":"通过在编写自定义代码之前调用研究员智能体来查找现有工具、库和模式，从而系统化研究先于编码的工作流程。这可以防止冗余开发，并确保为新功能、实用程序或抽象实现最佳的依赖集成。","ja":"カスタムコードを書く前に、既存のツール、ライブラリ、パターンを見つけるためにリサーチャーエージェントを呼び出すことで、コーディング前のリサーチワークフローを体系化します。これにより、冗長な開発を防止し、新機能、ユーティリティ、または抽象化のための最適な依存関係統合を保証します。","ko":"커스텀 코드를 작성하기 전에 기존 도구, 라이브러리 및 패턴을 찾기 위해 연구원 에이전트를 호출하여 연구-후-코딩 워크플로우를 체계화합니다. 이는 중복 개발을 방지하고 새로운 기능, 유틸리티 또는 추상화를 위한 최적의 종속성 통합을 보장합니다.","es":"Sistematiza un flujo de trabajo de investigación-antes-de-codificación invocando a agentes investigadores para encontrar herramientas, bibliotecas y patrones existentes antes de escribir código personalizado. Esto evita el desarrollo redundante y garantiza una integración óptima de dependencias para nuevas características, utilidades o abstracciones.","fr":"Systématise un flux de travail de recherche-avant-codage en invoquant des agents chercheurs pour trouver des outils, des bibliothèques et des modèles existants avant d''écrire du code personnalisé. Cela empêche le développement redondant et assure une intégration optimale des dépendances pour les nouvelles fonctionnalités, utilités ou abstractions.","de":"Systematisiert einen Forschung-bevor-Codierung-Arbeitsablauf, indem Forscheragenten aufgerufen werden, um bestehende Tools, Bibliotheken und Muster zu finden, bevor benutzerdefinierter Code geschrieben wird. Dies verhindert redundante Entwicklung und gewährleistet eine optimale Abhängigkeitsintegration für neue Funktionen, Utilities oder Abstraktionen.","pt":"Sistematiza um fluxo de trabalho de pesquisa antes da codificação, invocando agentes pesquisadores para encontrar ferramentas, bibliotecas e padrões existentes antes de escrever código personalizado. Isso evita desenvolvimento redundante e garante uma integração ideal de dependências para novos recursos, utilitários ou abstrações.","ru":"Систематизирует рабочий процесс «исследование перед кодированием», вызывая агентов-исследователей для поиска существующих инструментов, библиотек и шаблонов перед написанием пользовательского кода. Это предотвращает избыточную разработку и обеспечивает оптимальную интеграцию зависимостей для новых функций, утилит или абстракций.","ar":"ينظم سير عمل يقوم على البحث قبل البرمجة من خلال استدعاء وكلاء الباحثين للعثور على الأدوات والمكتبات والأنماط الموجودة قبل كتابة التعليمات البرمجية المخصصة. وهذا يمنع التطوير الزائد ويضمن تكاملًا أمثل للتبعيات للميزات أو الأدوات المساعدة أو التجريدات الجديدة."},"useCases":{"en":["Starting new feature development with existing solutions","Adding optimized dependencies and integrations","Creating utilities by leveraging established patterns","Avoiding custom code when libraries exist"],"zh":["利用现有解决方案启动新功能开发","添加优化的依赖项和集成","利用既定模式创建实用程序","在存在库时避免编写自定义代码"],"ja":["既存のソリューションを使用した新機能開発の開始","最適化された依存関係と統合の追加","確立されたパターンを活用したユーティリティの作成","ライブラリが存在する場合のカスタムコードの回避"],"ko":["기존 솔루션으로 새로운 기능 개발 시작","최적화된 종속성 및 통합 추가","확립된 패턴을 활용하여 유틸리티 생성","라이브러리가 존재할 때 커스텀 코드 작성 회피"],"es":["Comenzar el desarrollo de nuevas características con soluciones existentes","Agregar dependencias y integraciones optimizadas","Crear utilidades aprovechando patrones establecidos","Evitar código personalizado cuando existen bibliotecas"],"fr":["Commencer le développement de nouvelles fonctionnalités avec des solutions existantes","Ajouter des dépendances et des intégrations optimisées","Créer des utilités en exploitant des modèles établis","Éviter le code personnalisé lorsque des bibliothèques existent"],"de":["Neue Features mit bestehenden Lösungen entwickeln","Optimierte Abhängigkeiten und Integrationen hinzufügen","Utilities erstellen, indem etablierte Muster genutzt werden","Benutzerdefinierten Code vermeiden, wenn Bibliotheken existieren"],"pt":["Iniciar o desenvolvimento de novas funcionalidades com soluções existentes","Adicionar dependências e integrações otimizadas","Criar utilitários aproveitando padrões estabelecidos","Evitar código personalizado quando existem bibliotecas"],"ru":["Начало разработки новых функций с использованием существующих решений","Добавление оптимизированных зависимостей и интеграций","Создание утилит с использованием established patterns","Избежание пользовательского кода, когда существуют библиотеки"],"ar":["بدء تطوير ميزات جديدة باستخدام الحلول الموجودة","إضافة تبعيات وتكاملات مُحسنة","إنشاء أدوات مساعدة بالاستفادة من الأنماط المُرسخة","تجنب التعليمات البرمجية المخصصة عندما توجد مكتبات"]},"limitations":{"en":["Requires integration with a researcher agent","Depends on quality of available search tools/libraries","May slow initial development phase for simple tasks"],"zh":["需要与研究员智能体集成","取决于可用搜索工具/库的质量","对于简单任务可能会减慢初始开发阶段"],"ja":["リサーチャーエージェントとの統合が必要","利用可能な検索ツール/ライブラリの品質に依存","単純なタスクでは初期開発フェーズを遅らせる可能性がある"],"ko":["연구원 에이전트와의 통합 필요","사용 가능한 검색 도구/라이브러리의 품질에 의존","간단한 작업의 경우 초기 개발 단계를 느리게 할 수 있음"],"es":["Requiere integración con un agente investigador","Depende de la calidad de las herramientas/bibliotecas de búsqueda disponibles","Puede ralentizar la fase inicial de desarrollo para tareas simples"],"fr":["Nécessite une intégration avec un agent chercheur","Dépend de la qualité des outils/bibliothèques de recherche disponibles","Peut ralentir la phase initiale de développement pour les tâches simples"],"de":["Benötigt Integration mit einem Forscheragenten","Hängt von der Qualität der verfügbaren Suchtools/Bibliotheken ab","Kann die anfängliche Entwicklungsphase für einfache Aufgaben verlangsamen"],"pt":["Requer integração com um agente pesquisador","Depende da qualidade das ferramentas/bibliotecas de pesquisa disponíveis","Pode retardar a fase inicial de desenvolvimento para tarefas simples"],"ru":["Требует интеграции с агентом-исследователем","Зависит от качества доступных инструментов/библиотек для поиска","Может замедлить начальную фазу разработки для простых задач"],"ar":["يتطلب التكامل مع وكيل باحث","يعتمد على جودة أدوات/مكتبات البحث المتاحة","قد يبطئ المرحلة الأولية من التطوير للمهام البسيطة"]},"version":4},"contentHash":"752b24a8a06b3df1ce35598a789af92a72b61ecbb3c73e69d9af38708015d903","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":95}');
