INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/search-first', 'search-first', 'affaan-m', 'everything-claude-code', 'official', 'search-first affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The search-first skill systematizes the ''research before implementing'' workflow for developers. It automatically invokes a researcher agent to find existing solutions, libraries, and patterns before writing custom code, optimizing development within AI agent platforms like Claude. Search-First 是一种研究优先的开发工作流程，通过搜索现有工具和库来减少重复工作 Search-First は、既存のツールやライブラリを検索することで重複作業を減らす開発ワークフローです Search-First는 기존 도구와 라이브러리를 검색하여 중복 작업을 줄이는 개발 워크플로우입니다 search-first es un flujo de trabajo de investigación que sistemátiza la búsqueda de soluciones existentes antes de implementar código personalizado search-first est un flux de travail de recherche qui systématise la recherche de solutions existantes avant de mettre en œuvre du code personnalisé search-first ist ein Forschungs-Workflow, der die Suche nach vorhandenen Lösungen vor der Implementierung von benutzerdefiniertem Code systematisiert O skill search-first sistematiza o workflow de pesquisa antes de codificar, invocando um agente pesquisador para identificar ferramentas, bibliotecas e padrões existentes. Ideal para evitar retrabalho e adotar soluções consolidadas no ecossistema dev. Навык search-first систематизирует workflow исследования перед кодированием, запуская агента-исследователя для идентификации существующих инструментов, библиотек и паттернов. Идеален для избежания переделок и принятия проверенных решений в экосистеме разработки. ينظم مهارة search-first workflow البحث قبل البرمجة، باستدعاء وكيل الباحث لتحديد الأدوات والمكتبات والأنماط الموجودة. مثالي لتجنب إعادة العمل واعتماد حلول مثبتة في ecosystem المطورين باستخدام أدوات الذكاء الاصطناعي. what is search-first MCP skill how to use search-first researcher agent search-first vs manual code research search-first install Claude developer tool search-first setup guide for AI agents research-before-coding workflow automation Anthropic Claude Code productivity tools MCP agent skills for developers Search-First AIエージェント 开发工具 代码优化 开发生产力 研究优先开发 代码质量 开发效率 Automatically invokes a dedicated researcher agent to find existing solutions Triggers based on specific development intents like ''add X functionality'' Systematizes the workflow before creating new utilities, helpers, or abstractions Integrates with MCP (Model Context Protocol) for AI agent tooling Designed for use within Anthropic''s Claude and Claude Code environments search-first is an AI agent skill that automates the research-before-coding workflow. It triggers a researcher agent to search for existing tools, libraries, and patterns, preventing redundant custom code development within MCP-compatible environments like Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/security-scan', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'security-scan', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:33:20.237Z', '6facddfa83c1c53eb02d21e0fc4cfe70d785b9fd5159ed91e918c47466bf12d8', '{"id":"affaan-m/everything-claude-code/security-scan","name":"security-scan","description":{"en":"The security-scan skill audits your Claude Code project configuration for security vulnerabilities, misconfigurations, and injection risks using AgentShield. It is designed for developers and AI agent builders who need to ensure their .claude/ directory is secure before committing changes or depl...","zh":"安全扫描技能使用 AgentShield 扫描 Claude Code 配置中的安全漏洞、错误配置和注入风险","ja":"セキュリティスキャンスキルは、AgentShield を使用して Claude Code の構成のセキュリティ脆弱性、ミスコンフィギュレーション、インジェクションリスクをスキャンします","ko":"보안 스캔 스킬은 AgentShield를 사용하여 Claude Code 구성의 보안 취약점, 잘못된 구성 및 주입 위험을 스캔합니다","es":"Security-scan es una habilidad que analiza la configuración de Claude Code para detectar vulnerabilidades y riesgos de inyección","fr":"Security-scan est une compétence qui analyse la configuration de Claude Code pour détecter les vulnérabilités et les risques d''injection","de":"Security-scan ist eine Fähigkeit, die die Konfiguration von Claude Code analysiert, um Schwachstellen und Einschleusungsrisiken zu erkennen","pt":"O security-scan é uma ferramenta que verifica a configuração do Claude Code para detectar vulnerabilidades de segurança e problemas de configuração","ru":"Security-scan - это инструмент, который проверяет конфигурацию Claude Code на наличие уязвимостей безопасности и проблем конфигурации с помощью ИИ Агентов","ar":"مسح الأمان security-scan هو أداة تفتش عن الثغرات الأمنية وتفاصيل التهيئة في مشروعك Claude Code"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"security-scan","description":"Scan your Claude Code configuration (.claude/ directory) for security vulnerabilities, misconfigurations, and injection risks using AgentShield. Checks CLAUDE.md, settings.json, MCP servers, hooks, and agent definitions.","bodyPreview":"# Security Scan Skill\n\nAudit your Claude Code configuration for security issues using [AgentShield](https://github.com/affaan-m/agentshield).\n\n## When to Activate\n\n- Setting up a new Claude Code project\n- After modifying `.claude/settings.json`, `CLAUDE.md`, or MCP configs\n- Before committing configuration changes\n- When onboarding to a new repository with existing Claude Code configs\n- Periodic security hygiene checks\n\n## What It Scans\n\n| File | Checks |\n|------|--------|\n| `CLAUDE.md` | Hardco","body":"# Security Scan Skill\n\nAudit your Claude Code configuration for security issues using [AgentShield](https://github.com/affaan-m/agentshield).\n\n## When to Activate\n\n- Setting up a new Claude Code project\n- After modifying `.claude/settings.json`, `CLAUDE.md`, or MCP configs\n- Before committing configuration changes\n- When onboarding to a new repository with existing Claude Code configs\n- Periodic security hygiene checks\n\n## What It Scans\n\n| File | Checks |\n|------|--------|\n| `CLAUDE.md` | Hardcoded secrets, auto-run instructions, prompt injection patterns |\n| `settings.json` | Overly permissive allow lists, missing deny lists, dangerous bypass flags |\n| `mcp.json` | Risky MCP servers, hardcoded env secrets, npx supply chain risks |\n| `hooks/` | Command injection via interpolation, data exfiltration, silent error suppression |\n| `agents/*.md` | Unrestricted tool access, prompt injection surface, missing model specs |\n\n## Prerequisites\n\nAgentShield must be installed. Check and install if needed:\n\n```bash\n# Check if installed\nnpx ecc-agentshield --version\n\n# Install globally (recommended)\nnpm install -g ecc-agentshield\n\n# Or run directly via npx (no install needed)\nnpx ecc-agentshield scan .\n```\n\n## Usage\n\n### Basic Scan\n\nRun against the current project''s `.claude/` directory:\n\n```bash\n# Scan current project\nnpx ecc-agentshield scan\n\n# Scan a specific path\nnpx ecc-agentshield scan --path /path/to/.claude\n\n# Scan with minimum severity filter\nnpx ecc-agentshield scan --min-severity medium\n```\n\n### Output Formats\n\n```bash\n# Terminal output (default) — colored report with grade\nnpx ecc-agentshield scan\n\n# JSON — for CI/CD integration\nnpx ecc-agentshield scan --format json\n\n# Markdown — for documentation\nnpx ecc-agentshield scan --format markdown\n\n# HTML — self-contained dark-theme report\nnpx ecc-agentshield scan --format html > security-report.html\n```\n\n### Auto-Fix\n\nApply safe fixes automatically (only fixes marked as auto-fixable):\n\n```bash\nnpx ecc-agentshield scan --fix\n```\n\nThis will:\n- Replace hardcoded secrets with environment variable references\n- Tighten wildcard permissions to scoped alternatives\n- Never modify manual-only suggestions\n\n### Opus 4.6 Deep Analysis\n\nRun the adversarial three-agent pipeline for deeper analysis:\n\n```bash\n# Requires ANTHROPIC_API_KEY\nexport ANTHROPIC_API_KEY=your-key\nnpx ecc-agentshield scan --opus --stream\n```\n\nThis runs:\n1. **Attacker (Red Team)** — finds attack vectors\n2. **Defender (Blue Team)** — recommends hardening\n3. **Auditor (Final Verdict)** — synthesizes both perspectives\n\n### Initialize Secure Config\n\nScaffold a new secure `.claude/` configuration from scratch:\n\n```bash\nnpx ecc-agentshield init\n```\n\nCreates:\n- `settings.json` with scoped permissions and deny list\n- `CLAUDE.md` with security best practices\n- `mcp.json` placeholder\n\n### GitHub Action\n\nAdd to your CI pipeline:\n\n```yaml\n- uses: affaan-m/agentshield@v1\n  with:\n    path: ''.''\n    min-severity: ''medium''\n    fail-on-findings: true\n```\n\n## Severity Levels\n\n| Grade | Score | Meaning |\n|-------|-------|---------|\n| A | 90-100 | Secure configuration |\n| B | 75-89 | Minor issues |\n| C | 60-74 | Needs attention |\n| D | 40-59 | Significant risks |\n| F | 0-39 | Critical vulnerabilities |\n\n## Interpreting Results\n\n### Critical Findings (fix immediately)\n- Hardcoded API keys or tokens in config files\n- `Bash(*)` in the allow list (unrestricted shell access)\n- Command injection in hooks via `${file}` interpolation\n- Shell-running MCP servers\n\n### High Findings (fix before production)\n- Auto-run instructions in CLAUDE.md (prompt injection vector)\n- Missing deny lists in permissions\n- Agents with unnecessary Bash access\n\n### Medium Findings (recommended)\n- Silent error suppression in hooks (`2>/dev/null`, `|| true`)\n- Missing PreToolUse security hooks\n- `npx -y` auto-install in MCP server configs\n\n### Info Findings (awareness)\n- Missing descriptions on MCP servers\n- Prohibitive instructions correctly flagged as good practice\n\n## Links\n\n- **GitHub**: [github.com/affaan-m/agentshield](https://github.com/affaan-m/agentshield)\n- **npm**: [npmjs.com/package/ecc-agentshield](https://www.npmjs.com/package/ecc-agentshield)\n"},"category":"official","lastSynced":"2026-03-06T04:33:20.237Z","seo":{"title":{"en":"security-scan: Audit Claude Code Configurations | AI Agen...","zh":"安全扫描技能：Claude Code 安全性设置指南","ja":"セキュリティスキャンスキル：Claude Code のセキュリティ設定ベストプラクティス","ko":"보안 스캔 스킬: Claude Code 보안 설정 가이드","es":"Guía de configuración de seguridad-scan para Claude Code","fr":"Guide de configuration de sécurité pour security-scan ave...","de":"Sicherheits-Scan-Setup-Leitfaden für Claude Code","pt":"Guia de Configuração de Segurança do security-scan","ru":"Руководство по настройке безопасности ИИ Агентов security...","ar":"دليل إعداد مسح الأمان security-scan"},"description":{"en":"Scan your .claude/ directory for vulnerabilities with AgentShield. This skill checks CLAUDE.md, settings.json, MCP servers, and hooks for security risks. Pro...","zh":"使用 AgentShield 扫描 Claude Code 配置中的安全漏洞、错误配置和注入风险，确保您的项目安全","ja":"AgentShield を使用して Claude Code の構成のセキュリティ脆弱性、ミスコンフィギュレーション、インジェクションリスクをスキャンし、プロジェクトのセキュリティを確保する","ko":"AgentShield를 사용하여 Claude Code 구성의 보안 취약점, 잘못된 구성 및 주입 위험을 스캔하여 프로젝트의 보안을 보장합니다","es":"Mejora la seguridad de tu proyecto Claude Code con security-scan, que analiza vulnerabilidades y configuraciones incorrectas","fr":"Améliorez la sécurité de votre projet Claude Code avec security-scan, qui analyse les vulnérabilités et les configurations incorrectes","de":"Verbessern Sie die Sicherheit Ihres Claude-Code-Projekts mit security-scan, das Schwachstellen und falsche Konfigurationen überprüft","pt":"Aprenda a configurar o security-scan para identificar vulnerabilidades de segurança em seu projeto Claude Code","ru":"Узнайте, как настроить security-scan для выявления уязвимостей безопасности в вашем проекте Claude Code с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد مسح الأمان security-scan لاكتشاف الثغرات الأمنية في مشروعك Claude Code"},"definition":{"en":"security-scan is an AI agent skill that performs security audits on Claude Code configurations. It leverages AgentShield to scan the .claude/ directory, including files like CLAUDE.md, settings.json, MCP server configs, hooks, and agent definitions for potential security issues.","zh":"安全扫描技能是一种使用 AgentShield 的 Claude Code 安全性检查工具","ja":"セキュリティスキャンスキルは、AgentShield を使用した Claude Code のセキュリティチェックツールです","ko":"보안 스캔 스킬은 AgentShield를 사용한 Claude Code 보안성 검사 도구입니다","es":"Security-scan es una herramienta de seguridad que utiliza AgentShield para auditar la configuración de Claude Code","fr":"Security-scan est un outil de sécurité qui utilise AgentShield pour auditer la configuration de Claude Code","de":"Security-scan ist ein Sicherheitstool, das AgentShield verwendet, um die Konfiguration von Claude Code zu überprüfen","pt":"O security-scan é uma ferramenta de segurança que analisa a configuração do Claude Code","ru":"Security-scan - это инструмент безопасности, анализирующий конфигурацию Claude Code","ar":"مسح الأمان security-scan هو أداة أمنية تتحليل تهيئة مشروع Claude Code"},"features":{"en":["Scans CLAUDE.md for hardcoded secrets and security misconfigurations","Audits .claude/settings.json for vulnerabilities and injection risks","Checks MCP (Model Context Protocol) server configurations for security issues","Validates agent definitions and hook scripts within the .claude/ directory","Integrates AgentShield for comprehensive security analysis","Designed for pre-commit checks and periodic security hygiene audits"],"zh":["扫描 CLAUDE.md 文件","检查 settings.json 配置","验证 MCP 服务器和钩子","分析 Agent 定义","检测安全漏洞和错误配置","识别注入风险"],"ja":["CLAUDE.md ファイルのスキャン","settings.json 構成のチェック","MCP サーバーとフックの検証","エージェント定義の分析","セキュリティ脆弱性とミスコンフィギュレーションの検出","インジェクションリスクの識別"],"ko":["CLAUDE.md 파일 스캔","settings.json 구성 확인","MCP 서버 및 후크 검증","에이전트 정의 분석","보안 취약점 및 오류 구성 검색","주입 위험 식별"],"es":["Análisis de configuraciones de Claude Code","Detección de vulnerabilidades y riesgos de inyección","Comprobación de archivos como CLAUDE.md y settings.json","Integración con AgentShield para una mayor seguridad","Análisis de servidores MCP y definiciones de agentes"],"fr":["Analyse des configurations de Claude Code","Détection des vulnérabilités et des risques d''injection","Vérification des fichiers tels que CLAUDE.md et settings.json","Intégration avec AgentShield pour une sécurité renforcée","Analyse des serveurs MCP et des définitions d''agents"],"de":["Analyse der Konfigurationen von Claude Code","Erkennung von Schwachstellen und Einschleusungsrisiken","Überprüfung von Dateien wie CLAUDE.md und settings.json","Integration mit AgentShield für erhöhte Sicherheit","Analyse von MCP-Servern und Agentendefinitionen"],"pt":["Verificação de vulnerabilidades de segurança no arquivo CLAUDE.md","Análise de configuração no arquivo settings.json","Verificação de servidores MCP","Detecção de riscos de injeção","Integração com AgentShield"],"ru":["Проверка уязвимостей безопасности в файле CLAUDE.md","Анализ конфигурации в файле settings.json","Проверка серверов MCP","Обнаружение рисков инъекции","Интеграция с AgentShield и ИИ Агентами"],"ar":["فحص الثغرات الأمنية في ملف CLAUDE.md","تحليل التهيئة في ملف settings.json","فحص خوادم MCP","اكتشاف مخاطر الحقن","التكامل مع AgentShield"]},"keywords":{"en":["security-scan claude code","how to use security-scan skill","claude code security audit","AgentShield security scan","scan .claude directory vulnerabilities","security-scan vs manual audit","install security-scan skill","claude MCP server security","CLAUDE.md security check","security-scan setup guide"],"zh":["AIエージェント","Claude Code 安全性","AgentShield","安全扫描技能","配置检查","安全漏洞检测","注入风险识别","MCP 服务器","钩子验证"],"ja":["AIエージェント","Claude Code セキュリティ","AgentShield","セキュリティスキャンスキル","構成チェック","セキュリティ脆弱性検出","インジェクションリスク識別","MCP サーバー","フック検証"],"ko":["AI 에이전트","Claude Code 보안","AgentShield","보안 스캔 스킬","구성 확인","보안 취약점 검색","주입 위험 식별","MCP 서버","후크 검증"],"es":["security-scan","Claude Code","AgentShield","seguridad de código","análisis de vulnerabilidades","herramientas de desarrollo","AI Agentes","desarrollo de software"],"fr":["security-scan","Claude Code","AgentShield","sécurité du code","analyse des vulnérabilités","outils de développement","Agents IA","développement de logiciels"],"de":["security-scan","Claude Code","AgentShield","Codesicherheit","Schwachstellenanalyse","Entwicklungstools","KI-Agenten","Softwareentwicklung"],"pt":["segurança do Claude Code","vulnerabilidades de segurança","configuração de segurança","AgentShield","Claude Code","desenvolvimento de software","ferramentas de segurança"],"ru":["безопасность Claude Code","уязвимости безопасности","настройка безопасности","AgentShield","Claude Code","разработка программного обеспечения","инструменты безопасности","ИИ Агенты"],"ar":["أمان كلود كود","ثغرات أمنية","تهيئة أمان","AgentShield","كلود كود","تطوير البرمجيات","أدوات أمنية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code, AutoGPT, and LangChain needing comprehensive security scans for vulnerability detection and configuration validation.","zh":"非常适合需要全面安全扫描以进行漏洞检测和配置验证的AI Agent，如Claude Code、AutoGPT和LangChain。","ja":"Claude Code、AutoGPT、LangChainなどの脆弱性検出と構成検証のために包括的なセキュリティスキャンを必要とするAIエージェントに最適です。","ko":"취약점 탐지 및 구성 검증을 위한 포괄적인 보안 스캔이 필요한 Claude Code, AutoGPT, LangChain과 같은 AI 에이전트에 완벽합니다.","es":"Perfecto para agentes de IA como Claude Code, AutoGPT y LangChain que necesitan análisis de seguridad exhaustivos para la detección de vulnerabilidades y validación de configuración.","fr":"Parfait pour les agents IA comme Claude Code, AutoGPT et LangChain nécessitant des analyses de sécurité complètes pour la détection de vulnérabilités et la validation de configuration.","de":"Perfekt für KI-Agents wie Claude Code, AutoGPT und LangChain, die umfassende Sicherheitsscans für die Erkennung von Schwachstellen und Konfigurationsvalidierung benötigen.","pt":"Perfeito para Agentes de IA como Claude Code, AutoGPT e LangChain que necessitam de varreduras de segurança abrangentes para detecção de vulnerabilidades e validação de configuração.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code, AutoGPT и LangChain, которым необходимы комплексные проверки безопасности для обнаружения уязвимостей и проверки конфигурации.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude Code و AutoGPT و LangChain الذين يحتاجون إلى فحص أمني شامل لاكتشاف الثغرات وأصدار التحقق من الصحة."},"recommendation":{"en":"Empowers agents to detect security vulnerabilities, misconfigurations, and injection risks in their Claude Code configurations using AgentShield, scanning critical files like CLAUDE.md, settings.json, and MCP server configurations.","zh":"使Agent能够使用AgentShield扫描其Claude Code配置中的安全漏洞、错误配置和注入风险，扫描关键文件如CLAUDE.md、settings.json和MCP服务器配置。","ja":"AgentShieldを使用して、CLAUDE.md、settings.json、MCPサーバー構成などの重要なファイルをスキャンし、Claude Code構成におけるセキュリティ上の脆弱性、設定ミス、インジェクションリスクを検出する機能をエージェントに提供します。","ko":"AgentShield를 사용하여 CLAUDE.md, settings.json, MCP 서버 구성과 같은 중요한 파일을 스캔하여 Claude Code 구성의 보안 취약점, 잘못된 구성 및 인젝션 위험을 탐지할 수 있도록 에이전트를 지원합니다.","es":"Habilita a los agentes a detectar vulnerabilidades de seguridad, malas configuraciones y riesgos de inyección en sus configuraciones de Claude Code utilizando AgentShield, analizando archivos críticos como CLAUDE.md, settings.json y configuraciones del servidor MCP.","fr":"Permet aux agents de détecter les vulnérabilités de sécurité, les mauvaises configurations et les risques d''injection dans leurs configurations Claude Code en utilisant AgentShield, en analysant des fichiers critiques comme CLAUDE.md, settings.json et les configurations du serveur MCP.","de":"Ermöglicht es Agents, Sicherheitslücken, Fehlkonfigurationen und Injektionsrisiken in ihren Claude Code-Konfigurationen mit AgentShield zu erkennen, indem kritische Dateien wie CLAUDE.md, settings.json und MCP-Serverkonfigurationen gescannt werden.","pt":"Habilita os agentes a detectar vulnerabilidades de segurança, configurações incorretas e riscos de injeção nos seus Claude Code usando o AgentShield, digitalizando arquivos críticos como CLAUDE.md, settings.json e configurações do servidor MCP.","ru":"Наделяет агентов возможностью обнаруживать уязвимости безопасности, неправильные конфигурации и риски инъекций в их конфигурациях Claude Code с помощью AgentShield, сканируя критические файлы, такие как CLAUDE.md, settings.json и конфигурации сервера MCP.","ar":"يسمح للعميل باكتشاف الثغرات الأمنية والاعدادات غير الصحيحة ومخاطر الحقن في إعدادات Claude Code الخاصة بهم باستخدام AgentShield ، ومسح الملفات الحيوية مثل CLAUDE.md و settings.json وإعدادات خادم MCP."},"useCases":{"en":["Auditing Claude Code configurations for security issues before committing changes","Scanning for potential injection risks in MCP server settings","Validating security hygiene in existing repository configurations"],"zh":["在提交更改前审计Claude Code配置中的安全问题","扫描MCP服务器设置中潜在的注入风险","验证现有仓库配置中的安全卫生状况"],"ja":["変更をコミットする前にClaude Code構成のセキュリティ問題を監査する","MCPサーバー設定における潜在的なインジェクションリスクをスキャンする","既存のリポジトリ構成におけるセキュリティ衛生状態を検証する"],"ko":["변경 사항을 커밋하기 전에 Claude Code 구성의 보안 문제 감사","MCP 서버 설정에서 잠재적인 인젝션 위험 스캔","기존 저장소 구성의 보안 상태 검증"],"es":["Auditoría de configuraciones de Claude Code para problemas de seguridad antes de realizar cambios","Análisis de posibles riesgos de inyección en la configuración del servidor MCP","Validación de la higiene de seguridad en las configuraciones del repositorio existente"],"fr":["Audit des configurations Claude Code pour les problèmes de sécurité avant d''apporter des modifications","Analyse des risques d''injection potentiels dans les paramètres du serveur MCP","Validation de l''hygiène de sécurité dans les configurations du référentiel existant"],"de":["Prüfung von Claude Code-Konfigurationen auf Sicherheitsprobleme vor der Durchführung von Änderungen","Überprüfung möglicher Injektionsrisiken in der MCP-Server-Konfiguration","Validierung der SicherheitsHygiene in den bestehenden Repository-Konfigurationen"],"pt":["Auditoria de configurações do Claude Code para problemas de segurança antes de realizar alterações","Digitalização de riscos de injeção potenciais em configurações do servidor MCP","Validação da higiene de segurança em configurações de repositório existentes"],"ru":["Проверка конфигураций Claude Code на наличие проблем безопасности перед внесением изменений","Сканирование потенциальных рисков инъекций в настройках сервера MCP","Проверка гигиены безопасности в существующих конфигурациях репозитория"],"ar":["فحص إعدادات Claude Code للقضايا الأمنية قبل إجراء التغييرات","فحص مخاطر الحقن المحتملة في إعدادات خادم MCP","التحقق من صحة النظافة الأمنية في إعدادات المستودع الحالية"]},"limitations":{"en":["Requires AgentShield installation","Specific to Claude Code configurations","Needs access to .claude/ directory and its files"],"zh":["需要安装AgentShield","特定于Claude Code配置","需要访问.claude/目录及其文件"],"ja":["AgentShieldのインストールが必要","Claude Code構成に特化",".claude/ディレクトリとそのファイルへのアクセスが必要"],"ko":["AgentShield 설치 필요","Claude Code 구성에 특화됨",".claude/ 디렉토리 및 해당 파일에 대한 액세스 필요"],"es":["Requiere la instalación de AgentShield","Específico para configuraciones de Claude Code","Necesita acceso al directorio .claude/ y sus archivos"],"fr":["Nécessite l''installation d''AgentShield","Spécifique aux configurations Claude Code","Nécessite l''accès au répertoire .claude/ et à ses fichiers"],"de":["Benötigt die Installation von AgentShield","Spezifisch für Claude Code-Konfigurationen","Benötigt den Zugriff auf das Verzeichnis .claude/ und seine Dateien"],"pt":["Requer instalação do AgentShield","Específico para configurações do Claude Code","Necessita acesso ao diretório .claude/ e seus arquivos"],"ru":["Требуется установка AgentShield","Относится конкретно к конфигурациям Claude Code","Требуется доступ к каталогу .claude/ и его файлам"],"ar":["يتطلب تثبيت AgentShield","محدد لإعدادات Claude Code","يحتاج إلى الوصول إلى الدليل .claude/ وملفاته"]},"version":4},"contentHash":"6facddfa83c1c53eb02d21e0fc4cfe70d785b9fd5159ed91e918c47466bf12d8","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":95}');
