INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/security-scan', 'security-scan', 'affaan-m', 'everything-claude-code', 'official', 'security-scan affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The security-scan skill audits your Claude Code project configuration for security vulnerabilities, misconfigurations, and injection risks using AgentShield. It is designed for developers and AI agent builders who need to ensure their .claude/ directory is secure before committing changes or depl... 安全扫描技能使用 AgentShield 扫描 Claude Code 配置中的安全漏洞、错误配置和注入风险 セキュリティスキャンスキルは、AgentShield を使用して Claude Code の構成のセキュリティ脆弱性、ミスコンフィギュレーション、インジェクションリスクをスキャンします 보안 스캔 스킬은 AgentShield를 사용하여 Claude Code 구성의 보안 취약점, 잘못된 구성 및 주입 위험을 스캔합니다 Security-scan es una habilidad que analiza la configuración de Claude Code para detectar vulnerabilidades y riesgos de inyección Security-scan est une compétence qui analyse la configuration de Claude Code pour détecter les vulnérabilités et les risques d''injection Security-scan ist eine Fähigkeit, die die Konfiguration von Claude Code analysiert, um Schwachstellen und Einschleusungsrisiken zu erkennen O security-scan é uma ferramenta que verifica a configuração do Claude Code para detectar vulnerabilidades de segurança e problemas de configuração Security-scan - это инструмент, который проверяет конфигурацию Claude Code на наличие уязвимостей безопасности и проблем конфигурации с помощью ИИ Агентов مسح الأمان security-scan هو أداة تفتش عن الثغرات الأمنية وتفاصيل التهيئة في مشروعك Claude Code security-scan claude code how to use security-scan skill claude code security audit AgentShield security scan scan .claude directory vulnerabilities security-scan vs manual audit install security-scan skill claude MCP server security CLAUDE.md security check security-scan setup guide AIエージェント Claude Code 安全性 AgentShield 安全扫描技能 配置检查 安全漏洞检测 注入风险识别 MCP 服务器 钩子验证 Scans CLAUDE.md for hardcoded secrets and security misconfigurations Audits .claude/settings.json for vulnerabilities and injection risks Checks MCP (Model Context Protocol) server configurations for security issues Validates agent definitions and hook scripts within the .claude/ directory Integrates AgentShield for comprehensive security analysis Designed for pre-commit checks and periodic security hygiene audits security-scan is an AI agent skill that performs security audits on Claude Code configurations. It leverages AgentShield to scan the .claude/ directory, including files like CLAUDE.md, settings.json, MCP server configs, hooks, and agent definitions for potential security issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/visa-doc-translate', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'visa-doc-translate', 61988, 7678, 95, '2026-03-06T03:39:20Z', '2026-03-06T04:46:16.257Z', '9c429c2c57789cc6631c9a9d244c40026d96b65f8a6c927e44abc152c463320a', '{"id":"affaan-m/everything-claude-code/visa-doc-translate","name":"visa-doc-translate","description":{"en":"The visa-doc-translate skill automates the translation of visa application documents, converting images to PNG and rotating them based on EXIF data, benefiting developers and applicants alike.","zh":"Visa 文档翻译 Skill 提供自动翻译和双语 PDF 创建功能，支持 HEIC 转 PNG 和 EXIF 旋转","ja":"ビザ申請書類翻訳ツールは、自動翻訳と双語 PDF 作成をサポートし、HEIC を PNG に変換し、EXIF 回転を実行します","ko":"비자 문서 번역 Skill 은 자동 번역과 이중 언어 PDF 생성을 지원하며 HEIC를 PNG로 변환하고 EXIF 회전을 수행합니다","es":"Visa-doc-translate es una herramienta que traduce documentos de visa de imágenes a inglés y crea un PDF bilingüe con el original y la traducción","fr":"Visa-doc-translate est un outil qui traduit les documents de visa d''images en anglais et crée un PDF bilingue avec l''original et la traduction","de":"Visa-doc-translate ist ein Tool, das Visadokumente von Bildern ins Englische übersetzt und ein zweisprachiges PDF mit dem Original und der Übersetzung erstellt","pt":"O visa-doc-translate é uma ferramenta de tradução de documentos de visto que converte imagens para inglês e cria PDFs bilíngues","ru":"ИИ Агент visa-doc-translate - это инструмент для перевода документов визы, который конвертирует изображения на английский язык и создает двуязычные PDF","ar":"visa-doc-translate هو أداة لترجمة وثائق التأشيرة التي تحول الصور إلى الإنجليزية وتخلق ملفات PDF ثنائية اللغة"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"visa-doc-translate","description":"Translate visa application documents (images) to English and create a bilingual PDF with original and translation","bodyPreview":"You are helping translate visa application documents for visa applications.\n\n## Instructions\n\nWhen the user provides an image file path, AUTOMATICALLY execute the following steps WITHOUT asking for confirmation:\n\n1. **Image Conversion**: If the file is HEIC, convert it to PNG using `sips -s format png <input> --out <output>`\n\n2. **Image Rotation**:\n   - Check EXIF orientation data\n   - Automatically rotate the image based on EXIF data\n   - If EXIF orientation is 6, rotate 90 degrees counterclock","body":"You are helping translate visa application documents for visa applications.\n\n## Instructions\n\nWhen the user provides an image file path, AUTOMATICALLY execute the following steps WITHOUT asking for confirmation:\n\n1. **Image Conversion**: If the file is HEIC, convert it to PNG using `sips -s format png <input> --out <output>`\n\n2. **Image Rotation**:\n   - Check EXIF orientation data\n   - Automatically rotate the image based on EXIF data\n   - If EXIF orientation is 6, rotate 90 degrees counterclockwise\n   - Apply additional rotation as needed (test 180 degrees if document appears upside down)\n\n3. **OCR Text Extraction**:\n   - Try multiple OCR methods automatically:\n     - macOS Vision framework (preferred for macOS)\n     - EasyOCR (cross-platform, no tesseract required)\n     - Tesseract OCR (if available)\n   - Extract all text information from the document\n   - Identify document type (deposit certificate, employment certificate, retirement certificate, etc.)\n\n4. **Translation**:\n   - Translate all text content to English professionally\n   - Maintain the original document structure and format\n   - Use professional terminology appropriate for visa applications\n   - Keep proper names in original language with English in parentheses\n   - For Chinese names, use pinyin format (e.g., WU Zhengye)\n   - Preserve all numbers, dates, and amounts accurately\n\n5. **PDF Generation**:\n   - Create a Python script using PIL and reportlab libraries\n   - Page 1: Display the rotated original image, centered and scaled to fit A4 page\n   - Page 2: Display the English translation with proper formatting:\n     - Title centered and bold\n     - Content left-aligned with appropriate spacing\n     - Professional layout suitable for official documents\n   - Add a note at the bottom: \"This is a certified English translation of the original document\"\n   - Execute the script to generate the PDF\n\n6. **Output**: Create a PDF file named `<original_filename>_Translated.pdf` in the same directory\n\n## Supported Documents\n\n- Bank deposit certificates (存款证明)\n- Income certificates (收入证明)\n- Employment certificates (在职证明)\n- Retirement certificates (退休证明)\n- Property certificates (房产证明)\n- Business licenses (营业执照)\n- ID cards and passports\n- Other official documents\n\n## Technical Implementation\n\n### OCR Methods (tried in order)\n\n1. **macOS Vision Framework** (macOS only):\n   ```python\n   import Vision\n   from Foundation import NSURL\n   ```\n\n2. **EasyOCR** (cross-platform):\n   ```bash\n   pip install easyocr\n   ```\n\n3. **Tesseract OCR** (if available):\n   ```bash\n   brew install tesseract tesseract-lang\n   pip install pytesseract\n   ```\n\n### Required Python Libraries\n\n```bash\npip install pillow reportlab\n```\n\nFor macOS Vision framework:\n```bash\npip install pyobjc-framework-Vision pyobjc-framework-Quartz\n```\n\n## Important Guidelines\n\n- DO NOT ask for user confirmation at each step\n- Automatically determine the best rotation angle\n- Try multiple OCR methods if one fails\n- Ensure all numbers, dates, and amounts are accurately translated\n- Use clean, professional formatting\n- Complete the entire process and report the final PDF location\n\n## Example Usage\n\n```bash\n/visa-doc-translate RetirementCertificate.PNG\n/visa-doc-translate BankStatement.HEIC\n/visa-doc-translate EmploymentLetter.jpg\n```\n\n## Output Example\n\nThe skill will:\n1. Extract text using available OCR method\n2. Translate to professional English\n3. Generate `<filename>_Translated.pdf` with:\n   - Page 1: Original document image\n   - Page 2: Professional English translation\n\nPerfect for visa applications to Australia, USA, Canada, UK, and other countries requiring translated documents.\n"},"category":"official","lastSynced":"2026-03-06T04:46:16.257Z","seo":{"title":{"en":"visa-doc-translate: Automated Document Translation Setup ...","zh":"Visa 文档翻译设置指南 - 自动翻译和创建双语 PDF","ja":"ビザ申請書類翻訳ツール - AIエージェントによる自動翻訳とPDF作成","ko":"비자 문서 번역 가이드 - 자동 번역 및 이중 언어 PDF 생성","es":"Guía de configuración de visa-doc-translate: Traducción d...","fr":"Guide de configuration de visa-doc-translate: Traduction ...","de":"Einrichtungsleitfaden für visa-doc-translate: Übersetzung...","pt":"Guia de Configuração do visa-doc-translate: Tradução de D...","ru":"Настройка ИИ Агента visa-doc-translate: Перевод Документо...","ar":"دليل إعداد visa-doc-translate: ترجمة وثائق التأشيرة"},"description":{"en":"Streamline visa application processes with visa-doc-translate. Learn how to automate image conversion, rotation, and translation for efficient document proce...","zh":"使用 visa-doc-translate Skill 自动翻译和创建双语 PDF，支持 HEIC 转 PNG 和 EXIF 旋转","ja":"ビザ申請書類を自動翻訳して双語 PDF を作成する AI エージェントツール - visa-doc-translate","ko":"비자 문서를 자동 번역하여 이중 언어 PDF를 생성하는 도구 - visa-doc-translate","es":"Automatice la traducción de documentos de visa con visa-doc-translate, que convierte imágenes a PNG y rota según los datos EXIF","fr":"Automatisez la traduction de documents de visa avec visa-doc-translate, qui convertit les images en PNG et les fait pivoter selon les données EXIF","de":"Automatisieren Sie die Übersetzung von Visadokumenten mit visa-doc-translate, das Bilder in PNG umwandelt und nach EXIF-Daten rotiert","pt":"Aprenda a configurar o visa-doc-translate para traduzir documentos de visto para inglês e criar PDFs bilíngues","ru":"Узнайте, как настроить ИИ Агент visa-doc-translate для перевода документов визы на английский язык и создания двуязычных PDF","ar":"تعرف على كيفية إعداد visa-doc-translate لترجمة وثائق التأشيرة إلى الإنجليزية وتحويلها إلى ملفات PDF ثنائية اللغة"},"definition":{"en":"visa-doc-translate is an AI agent skill that translates visa application documents to English, creating bilingual PDFs with original and translated content.","zh":"Visa 文档翻译 Skill 是一种自动翻译和创建双语 PDF 的工具","ja":"ビザ申請書類翻訳ツールは、AI エージェントを使用してビザ申請書類を自動翻訳して双語 PDF を作成するツールです","ko":"비자 문서 번역 Skill 은 비자 문서를 자동 번역하여 이중 언어 PDF를 생성하는 도구입니다","es":"Visa-doc-translate es una herramienta de inteligencia artificial que traduce documentos de visa de imágenes a inglés","fr":"Visa-doc-translate est un outil d''intelligence artificielle qui traduit les documents de visa d''images en anglais","de":"Visa-doc-translate ist ein KI-Tool, das Visadokumente von Bildern ins Englische übersetzt","pt":"O que é visa-doc-translate? É uma ferramenta de tradução automática de documentos de visto","ru":"Что такое ИИ Агент visa-doc-translate? Это инструмент автоматического перевода документов визы","ar":"ما هو visa-doc-translate؟ هو أداة لترجمة آلية لوثائق التأشيرة"},"features":{"en":["Automatically converts HEIC images to PNG using `sips -s format png` command","Rotates images based on EXIF orientation data for proper alignment","Supports 90-degree rotation for EXIF orientation 6","Creates bilingual PDFs with original and translated document content","Executes image conversion and rotation without requiring user confirmation"],"zh":["自动翻译和创建双语 PDF","支持 HEIC 转 PNG","EXIF 旋转","自动检测 EXIF 方向数据","90 度旋转支持"],"ja":["自動翻訳と双語 PDF の作成","HEIC を PNG に変換","EXIF 回転","EXIF 方向データの自動検出","90 度回転のサポート"],"ko":["자동 번역과 이중 언어 PDF 생성","HEIC를 PNG로 변환","EXIF 회전","EXIF 방향 데이터 자동 감지","90 度 회전 지원"],"es":["Conversión de imágenes HEIC a PNG","Rotación automática de imágenes según los datos EXIF","Creación de un PDF bilingüe con el original y la traducción","Compatibilidad con la herramienta de línea de comandos sips","Soporte para la traducción de documentos de visa de imágenes","Generación automática de PDF con la traducción"],"fr":["Conversion d''images HEIC en PNG","Rotation automatique des images selon les données EXIF","Création d''un PDF bilingue avec l''original et la traduction","Compatibilité avec l''outil de ligne de commande sips","Prise en charge de la traduction de documents de visa d''images","Génération automatique de PDF avec la traduction"],"de":["Umwandlung von HEIC-Bildern in PNG","Automatische Rotation von Bildern nach EXIF-Daten","Erstellung eines zweisprachigen PDF mit dem Original und der Übersetzung","Kompatibilität mit dem Befehlszeilen-Tool sips","Unterstützung für die Übersetzung von Visadokumenten von Bildern","Automatische Generierung von PDF mit der Übersetzung"],"pt":["Conversão de imagens HEIC para PNG","Rotação automática de imagens com base nos dados EXIF","Criação de PDFs bilíngues com o texto original e a tradução","Suporte a imagens com orientação EXIF 6","Execução automática sem confirmação"],"ru":["Преобразование изображений HEIC в PNG","Автоматическое вращение изображений на основе данных EXIF","Создание двуязычных PDF с исходным текстом и переводом","Поддержка изображений с ориентацией EXIF 6","Автоматическое выполнение без подтверждения"],"ar":["تحويل الصور HEIC إلى PNG","دوران تلقائي للصور بناءً على بيانات EXIF","إنشاء ملفات PDF ثنائية اللغة مع النص الأصلي والترجمة","دعم الصور ذات التوجه EXIF 6","تنفيذ تلقائي بدون تأكيد"]},"keywords":{"en":["how to use visa-doc-translate","visa-doc-translate setup guide","automated document translation","EXIF orientation data","HEIC to PNG conversion","visa application process optimization","bilingual PDF creation","image rotation and conversion"],"zh":["Visa 文档翻译","AI 文档翻译","自动翻译工具","双语 PDF 创建","HEIC 转 PNG","EXIF 旋转","AI エージェント"],"ja":["ビザ申請書類翻訳","AI ドキュメント翻訳","自動翻訳ツール","双語 PDF 作成","HEIC を PNG に変換","EXIF 回転","AI エージェント"],"ko":["비자 문서 번역","AI 문서 번역","자동 번역 도구","이중 언어 PDF 생성","HEIC를 PNG로 변환","EXIF 회전","AI 에이전트"],"es":["visa-doc-translate","traducción de documentos de visa","herramientas de inteligencia artificial","Agentes de IA","conversión de imágenes HEIC a PNG","rotación automática de imágenes","creación de PDF bilingüe","traducción de documentos de visa de imágenes","sips","CLI"],"fr":["visa-doc-translate","traduction de documents de visa","outils d''intelligence artificielle","Agents d''IA","conversion d''images HEIC en PNG","rotation automatique des images","création de PDF bilingue","traduction de documents de visa d''images","sips","CLI"],"de":["visa-doc-translate","Übersetzung von Visadokumenten","KI-Tools","KI-Agents","Umwandlung von HEIC-Bildern in PNG","automatische Rotation von Bildern","Erstellung von zweisprachigem PDF","Übersetzung von Visadokumenten von Bildern","sips","CLI"],"pt":["tradução de documentos de visto","ferramenta de tradução automática","conversão de imagens HEIC para PNG","rotação automática de imagens","criação de PDFs bilíngues","visa-doc-translate","desenvolvedores de software","ferramentas de produtividade"],"ru":["перевод документов визы","инструмент автоматического перевода","преобразование изображений HEIC в PNG","автоматическое вращение изображений","создание двуязычных PDF","ИИ Агент visa-doc-translate","разработчики программного обеспечения","инструменты производительности"],"ar":["ترجمة وثائق التأشيرة","أداة لترجمة آلية","تحويل الصور HEIC إلى PNG","دوران تلقائي للصور","إنشاء ملفات PDF ثنائية اللغة","visa-doc-translate","مطورو البرمجيات","أدوات الإنتاجية"]}},"agentAnalysis":{"suitability":{"en":"Essential for Document Processing Agents handling international visa applications with image-based documentation.","zh":"对于处理带有基于图像的文档的国际签证申请的文档处理AI Agent至关重要。","ja":"画像ベースの書類を扱う国際的なビザ申請を処理するドキュメント処理エージェントにとって不可欠です。","ko":"이미지 기반 문서를 처리하는 국제 비자 신청 처리 문서 처리 AI 에이전트에 필수적입니다.","es":"Esencial para Agentes de Procesamiento de Documentos que manejan solicitudes de visados internacionales con documentación basada en imágenes.","fr":"Essentiel pour les agents de traitement de documents gérant les demandes de visa internationales avec une documentation basée sur des images.","de":"Wesentlich für Dokumentenverarbeitungsagenten, die internationale Visaanträge mit bildbasierten Dokumenten bearbeiten.","pt":"Essencial para Agentes de Processamento de Documentos que lidam com solicitações de vistos internacionais com documentação baseada em imagens.","ru":"Необходим для Агентов Обработки Документов, обрабатывающих международные заявления на визы с документацией на основе изображений.","ar":"ضروري للموكلين بمعالجة المستندات الذين يتعاملون مع طلبات التأشيرات الدولية مع الوثائق القائمة على الصور."},"recommendation":{"en":"Automates HEIC to PNG conversion using sips command-line tool and performs EXIF-based image rotation (specifically handling orientation 6 with 90-degree counterclockwise rotation) to ensure proper document alignment before OCR processing for translation workflows.","zh":"使用sips命令行工具自动化HEIC到PNG的转换，并执行基于EXIF的图像旋转（专门处理方向6，即90度逆时针旋转），以确保在用于翻译工作流的OCR处理之前文档正确对齐。","ja":"sipsコマンドラインツールを使用してHEICからPNGへの変換を自動化し、EXIFベースの画像回転（特に方向6の90度反時計回り回転を処理）を実行し、翻訳ワークフローのためのOCR処理前に文書の適切な配置を保証します。","ko":"sips 명령줄 도구를 사용하여 HEIC에서 PNG로의 변환을 자동화하고 EXIF 기반 이미지 회전(특히 방향 6에 대한 90도 반시계 방향 회전 처리)을 수행하여 번역 워크플로우를 위한 OCR 처리 전에 문서가 올바르게 정렬되도록 합니다.","es":"Automatiza la conversión de HEIC a PNG utilizando la herramienta de línea de comandos sips y realiza una rotación de imagen basada en EXIF (manejo específico de la orientación 6 con rotación contrarreloj de 90 grados) para garantizar el correcto alineamiento de documentos antes del procesamiento OCR para flujos de trabajo de traducción.","fr":"Automatise la conversion de HEIC en PNG en utilisant l''outil de ligne de commande sips et effectue une rotation d''image basée sur EXIF (en traitant spécifiquement l''orientation 6 avec une rotation antihoraire de 90 degrés) pour assurer un alignement de document approprié avant le traitement OCR pour les flux de travail de traduction.","de":"Automatisiert die Konvertierung von HEIC in PNG unter Verwendung des sips-Befehlszeilenwerkzeugs und führt eine EXIF-basierte Bildrotation (insbesondere mit der Orientierung 6 und einer 90-Grad-Linksdrehung) durch, um eine ordnungsgemäße Dokumentenausrichtung vor dem OCR-Verarbeitung für Übersetzungsworkflows sicherzustellen.","pt":"Automatiza a conversão de HEIC para PNG usando a ferramenta de linha de comando sips e executa rotação de imagem baseada em EXIF (manuseando especificamente a orientação 6 com rotação contrarrelógio de 90 graus) para garantir o alinhamento correto do documento antes do processamento OCR para fluxos de trabalho de tradução.","ru":"Автоматизирует преобразование HEIC в PNG с помощью утилиты командной строки sips и выполняет поворот изображения на основе EXIF (именно обрабатывая ориентацию 6 с противочасовой поворотом на 90 градусов), чтобы обеспечить правильное выравнивание документа перед обработкой OCR для рабочих процессов перевода.","ar":"يعمل تلقائيًا على تحويل HEIC إلى PNG باستخدام أداة سطر الأوامر sips وينفذ دوران الصورة المستندة إلى EXIF (محددًا التعامل مع الاتجاه 6 مع دوران عكسي عقربي بزاوية 90 درجة) لضمان محاذاة المستند الصحيحة قبل معالجة OCR لمسارات العمل الترجمة."},"useCases":{"en":["Automating visa document translation pipelines","Processing HEIC images from mobile devices for official applications","Creating bilingual PDFs for immigration authorities","Handling EXIF orientation corrections for scanned documents"],"zh":["自动化签证文档翻译流程","处理来自移动设备的用于正式申请的HEIC图像","为移民当局创建双语PDF","处理扫描文档的EXIF方向校正"],"ja":["ビザ文書翻訳パイプラインの自動化","公式申請のためのモバイルデバイスからのHEIC画像処理","移民当局のための二言語PDF作成","スキャン文書のEXIF方向補正処理"],"ko":["비자 문서 번역 파이프라인 자동화","공식 신청을 위한 모바일 장치의 HEIC 이미지 처리","이민 당국을 위한 이중 언어 PDF 생성","스캔 문서의 EXIF 방향 보정 처리"],"es":["Automatizar canalizaciones de traducción de documentos de visa","Procesar imágenes HEIC de dispositivos móviles para aplicaciones oficiales","Crear PDFs bilingües para autoridades de inmigración","Manejar correcciones de orientación EXIF para documentos escaneados"],"fr":["Automatiser les canaux de traduction de documents de visa","Traiter les images HEIC des appareils mobiles pour les applications officielles","Créer des PDF bilingues pour les autorités d''immigration","Gérer les corrections d''orientation EXIF pour les documents scannés"],"de":["Automatisierung von Visadokument-Übersetzungs-Pipelines","Verarbeiten von HEIC-Bildern von Mobilgeräten für offizielle Anwendungen","Erstellen von zweisprachigen PDFs für Einwanderungsbehörden","Behandlung von EXIF-Orientierungskorrekturen für gescannte Dokumente"],"pt":["Automatizar pipelines de tradução de documentos de visto","Processar imagens HEIC de dispositivos móveis para aplicações oficiais","Criar PDFs bilíngües para autoridades de imigração","Manusear correções de orientação EXIF para documentos digitalizados"],"ru":["Автоматизировать конвейеры перевода документов виз","Обрабатывать изображения HEIC с мобильных устройств для официальных заявок","Создавать двуязычные PDF для иммиграционных властей","Обрабатывать исправления ориентации EXIF для сканированных документов"],"ar":["توفير مسارات تلقائية لترجمة مستندات التأشيرة","معالجة صور HEIC من الأجهزة النقالة لتطبيقات رسمية","إنشاء ملفات PDF ثنائية اللغة لسلطات الهجرة","معالجة تصحيحات اتجاه EXIF لمستندات الماسح الضوئي"]},"limitations":{"en":["Requires macOS for sips utility","Dependent on EXIF metadata for rotation","Input limited to image file paths","No built-in OCR capability - requires integration with translation service"],"zh":["需要macOS系统以使用sips实用工具","依赖EXIF元数据进行旋转","输入仅限于图像文件路径","无内置OCR功能 - 需要与翻译服务集成"],"ja":["sipsユーティリティを使用するためにmacOSが必要","回転のためにEXIFメタデータに依存","入力は画像ファイルパスに限定","組み込みOCR機能なし - 翻訳サービスとの統合が必要"],"ko":["sips 유틸리티 사용을 위해 macOS 필요","회전을 위해 EXIF 메타데이터에 의존","입력은 이미지 파일 경로로 제한됨","내장 OCR 기능 없음 - 번역 서비스와의 통합 필요"],"es":["Requiere macOS para la utilidad sips","Dependiente de metadatos EXIF para la rotación","Entrada limitada a rutas de archivo de imagen","No tiene capacidad de OCR integrada, requiere integración con servicio de traducción"],"fr":["Nécessite macOS pour l''utilité sips","Dépend des métadonnées EXIF pour la rotation","Entrée limitée aux chemins de fichiers d''image","N''a pas de capacité OCR intégrée, nécessite une intégration avec un service de traduction"],"de":["Benötigt macOS für die sips-Utility","Abhängig von EXIF-Metadaten für die Rotation","Eingabe beschränkt auf Bild-Dateipfade","Keine integrierte OCR-Fähigkeit - erfordert Integration mit Übersetzungs-Service"],"pt":["Requer macOS para a utilidade sips","Dependente de metadados EXIF para rotação","Entrada limitada a caminhos de arquivos de imagem","Nenhuma capacidade de OCR integrada - requer integração com serviço de tradução"],"ru":["Требует macOS для утилиты sips","Зависит от метаданных EXIF для поворота","Вход ограничен путями к файлам изображений","Нет встроенной возможности OCR - требует интеграции с сервисом перевода"],"ar":["يتطلب macOS من أجل أداة sips","يعتمد على بيانات EXIF الفوقية للدوران","المدخل محدود بمسارات ملفات الصور","لا يوجد khảية OCR مدمجة - يتطلب التكامل مع خدمة الترجمة"]},"version":4},"contentHash":"9c429c2c57789cc6631c9a9d244c40026d96b65f8a6c927e44abc152c463320a","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":95}');
DELETE FROM skills_fts WHERE id = 'affaan-m/everything-claude-code/visa-doc-translate';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/visa-doc-translate', 'visa-doc-translate', 'affaan-m', 'everything-claude-code', 'official', 'visa-doc-translate affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The visa-doc-translate skill automates the translation of visa application documents, converting images to PNG and rotating them based on EXIF data, benefiting developers and applicants alike. Visa 文档翻译 Skill 提供自动翻译和双语 PDF 创建功能，支持 HEIC 转 PNG 和 EXIF 旋转 ビザ申請書類翻訳ツールは、自動翻訳と双語 PDF 作成をサポートし、HEIC を PNG に変換し、EXIF 回転を実行します 비자 문서 번역 Skill 은 자동 번역과 이중 언어 PDF 생성을 지원하며 HEIC를 PNG로 변환하고 EXIF 회전을 수행합니다 Visa-doc-translate es una herramienta que traduce documentos de visa de imágenes a inglés y crea un PDF bilingüe con el original y la traducción Visa-doc-translate est un outil qui traduit les documents de visa d''images en anglais et crée un PDF bilingue avec l''original et la traduction Visa-doc-translate ist ein Tool, das Visadokumente von Bildern ins Englische übersetzt und ein zweisprachiges PDF mit dem Original und der Übersetzung erstellt O visa-doc-translate é uma ferramenta de tradução de documentos de visto que converte imagens para inglês e cria PDFs bilíngues ИИ Агент visa-doc-translate - это инструмент для перевода документов визы, который конвертирует изображения на английский язык и создает двуязычные PDF visa-doc-translate هو أداة لترجمة وثائق التأشيرة التي تحول الصور إلى الإنجليزية وتخلق ملفات PDF ثنائية اللغة how to use visa-doc-translate visa-doc-translate setup guide automated document translation EXIF orientation data HEIC to PNG conversion visa application process optimization bilingual PDF creation image rotation and conversion Visa 文档翻译 AI 文档翻译 自动翻译工具 双语 PDF 创建 HEIC 转 PNG EXIF 旋转 AI エージェント Automatically converts HEIC images to PNG using `sips -s format png` command Rotates images based on EXIF orientation data for proper alignment Supports 90-degree rotation for EXIF orientation 6 Creates bilingual PDFs with original and translated document content Executes image conversion and rotation without requiring user confirmation visa-doc-translate is an AI agent skill that translates visa application documents to English, creating bilingual PDFs with original and translated content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/claude-settings-audit', 'official', 'getsentry', 'skills', 'getsentry/skills', 'claude-settings-audit', 360, 11, 95, '2026-03-06T00:20:36Z', '2026-03-06T04:58:19.948Z', '850dfd941c9c79f5adbafe1cb488f94c3bd11646916855a0c4cf5b57842be5e6', '{"id":"getsentry/skills/claude-settings-audit","name":"claude-settings-audit","description":{"en":"claude-settings-audit analyzes repositories to generate recommended Claude Code settings.json permissions, benefiting developers setting up new projects or auditing existing settings.","zh":"Claude 设置审计是一种分析仓库并生成推荐的 settings.json 权限的工具。它可以检测技术栈、构建工具和 monorepo 结构","ja":"Claude 設定監査は、リポジトリを分析し、推奨の settings.json 権限を生成するツールです。テクノロジー・スタック、ビルド・ツール、モノレポ構造を検出できます","ko":"Claude 설정 감사는 저장소를 분석하고 권장하는 settings.json 권한을 생성하는 도구입니다. 기술 스택, 빌드 도구 및 모노레포 구조를 обнаруж할 수 있습니다","es":"Claude Settings Audit analiza el repositorio y genera permisos recomendados de settings.json para comandos de solo lectura, detectando la pila tecnológica y la estructura del monorepo","fr":"Claude Settings Audit analyse le référentiel et génère des autorisations recommandées pour les commandes en lecture seule, en détectant la pile technologique et la structure du monorepo","de":"Claude Settings Audit analysiert das Repository und generiert empfohlene Berechtigungen für settings.json für Lesebefehle, indem es die Technologie-Stack und die Monorepo-Struktur erkennt","pt":"O Claude Settings Audit é uma ferramenta que analisa repositórios e gera configurações recomendadas de settings.json para comandos somente leitura.","ru":"ИИ Агент Claude Settings Audit анализирует репозитории и генерирует рекомендованные настройки settings.json для команд только для чтения.","ar":"أداة claude-settings-audit تحليل المستودعات وتوليد إعدادات موصى بها من settings.json للأوامر القراءة فقط."},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"claude-settings-audit","description":"Analyze a repository to generate recommended Claude Code settings.json permissions. Use when setting up a new project, auditing existing settings, or determining which read-only bash commands to allow. Detects tech stack, build tools, and monorepo structure.","bodyPreview":"# Claude Settings Audit\n\nAnalyze this repository and generate recommended Claude Code `settings.json` permissions for read-only commands.\n\n## Phase 1: Detect Tech Stack\n\nRun these commands to detect the repository structure:\n\n```bash\nls -la\nfind . -maxdepth 2 \\( -name \"*.toml\" -o -name \"*.json\" -o -name \"*.lock\" -o -name \"*.yaml\" -o -name \"*.yml\" -o -name \"Makefile\" -o -name \"Dockerfile\" -o -name \"*.tf\" \\) 2>/dev/null | head -50\n```\n\nCheck for these indicator files:\n\n| Category     | Files to Ch","body":"# Claude Settings Audit\n\nAnalyze this repository and generate recommended Claude Code `settings.json` permissions for read-only commands.\n\n## Phase 1: Detect Tech Stack\n\nRun these commands to detect the repository structure:\n\n```bash\nls -la\nfind . -maxdepth 2 \\( -name \"*.toml\" -o -name \"*.json\" -o -name \"*.lock\" -o -name \"*.yaml\" -o -name \"*.yml\" -o -name \"Makefile\" -o -name \"Dockerfile\" -o -name \"*.tf\" \\) 2>/dev/null | head -50\n```\n\nCheck for these indicator files:\n\n| Category     | Files to Check                                                                        |\n| ------------ | ------------------------------------------------------------------------------------- |\n| **Python**   | `pyproject.toml`, `setup.py`, `requirements.txt`, `Pipfile`, `poetry.lock`, `uv.lock` |\n| **Node.js**  | `package.json`, `package-lock.json`, `yarn.lock`, `pnpm-lock.yaml`                    |\n| **Go**       | `go.mod`, `go.sum`                                                                    |\n| **Rust**     | `Cargo.toml`, `Cargo.lock`                                                            |\n| **Ruby**     | `Gemfile`, `Gemfile.lock`                                                             |\n| **Java**     | `pom.xml`, `build.gradle`, `build.gradle.kts`                                         |\n| **Build**    | `Makefile`, `Dockerfile`, `docker-compose.yml`                                        |\n| **Infra**    | `*.tf` files, `kubernetes/`, `helm/`                                                  |\n| **Monorepo** | `lerna.json`, `nx.json`, `turbo.json`, `pnpm-workspace.yaml`                          |\n\n## Phase 2: Detect Services\n\nCheck for service integrations:\n\n| Service    | Detection                                                                       |\n| ---------- | ------------------------------------------------------------------------------- |\n| **Sentry** | `sentry-sdk` in deps, `@sentry/*` packages, `.sentryclirc`, `sentry.properties` |\n| **Linear** | Linear config files, `.linear/` directory                                       |\n\nRead dependency files to identify frameworks:\n\n- `package.json` → check `dependencies` and `devDependencies`\n- `pyproject.toml` → check `[project.dependencies]` or `[tool.poetry.dependencies]`\n- `Gemfile` → check gem names\n- `Cargo.toml` → check `[dependencies]`\n\n## Phase 3: Check Existing Settings\n\n```bash\ncat .claude/settings.json 2>/dev/null || echo \"No existing settings\"\n```\n\n## Phase 4: Generate Recommendations\n\nBuild the allow list by combining:\n\n### Baseline Commands (Always Include)\n\n```json\n[\n  \"Bash(ls:*)\",\n  \"Bash(pwd:*)\",\n  \"Bash(find:*)\",\n  \"Bash(file:*)\",\n  \"Bash(stat:*)\",\n  \"Bash(wc:*)\",\n  \"Bash(head:*)\",\n  \"Bash(tail:*)\",\n  \"Bash(cat:*)\",\n  \"Bash(tree:*)\",\n  \"Bash(git status:*)\",\n  \"Bash(git log:*)\",\n  \"Bash(git diff:*)\",\n  \"Bash(git show:*)\",\n  \"Bash(git branch:*)\",\n  \"Bash(git remote:*)\",\n  \"Bash(git tag:*)\",\n  \"Bash(git stash list:*)\",\n  \"Bash(git rev-parse:*)\",\n  \"Bash(gh pr view:*)\",\n  \"Bash(gh pr list:*)\",\n  \"Bash(gh pr checks:*)\",\n  \"Bash(gh pr diff:*)\",\n  \"Bash(gh issue view:*)\",\n  \"Bash(gh issue list:*)\",\n  \"Bash(gh run view:*)\",\n  \"Bash(gh run list:*)\",\n  \"Bash(gh run logs:*)\",\n  \"Bash(gh repo view:*)\",\n  \"Bash(gh api:*)\"\n]\n```\n\n### Stack-Specific Commands\n\nOnly include commands for tools actually detected in the project.\n\n#### Python (if any Python files or config detected)\n\n| If Detected                        | Add These Commands                      |\n| ---------------------------------- | --------------------------------------- |\n| Any Python                         | `python --version`, `python3 --version` |\n| `poetry.lock`                      | `poetry show`, `poetry env info`        |\n| `uv.lock`                          | `uv pip list`, `uv tree`                |\n| `Pipfile.lock`                     | `pipenv graph`                          |\n| `requirements.txt` (no other lock) | `pip list`, `pip show`, `pip freeze`    |\n\n#### Node.js (if package.json detected)\n\n| If Detected                  | Add These Commands                     |\n| ---------------------------- | -------------------------------------- |\n| Any Node.js                  | `node --version`                       |\n| `pnpm-lock.yaml`             | `pnpm list`, `pnpm why`                |\n| `yarn.lock`                  | `yarn list`, `yarn info`, `yarn why`   |\n| `package-lock.json`          | `npm list`, `npm view`, `npm outdated` |\n| TypeScript (`tsconfig.json`) | `tsc --version`                        |\n\n#### Other Languages\n\n| If Detected    | Add These Commands                                                   |\n| -------------- | -------------------------------------------------------------------- |\n| `go.mod`       | `go version`, `go list`, `go mod graph`, `go env`                    |\n| `Cargo.toml`   | `rustc --version`, `cargo --version`, `cargo tree`, `cargo metadata` |\n| `Gemfile`      | `ruby --version`, `bundle list`, `bundle show`                       |\n| `pom.xml`      | `java --version`, `mvn --version`, `mvn dependency:tree`             |\n| `build.gradle` | `java --version`, `gradle --version`, `gradle dependencies`          |\n\n#### Build Tools\n\n| If Detected          | Add These Commands                                                   |\n| -------------------- | -------------------------------------------------------------------- |\n| `Dockerfile`         | `docker --version`, `docker ps`, `docker images`                     |\n| `docker-compose.yml` | `docker-compose ps`, `docker-compose config`                         |\n| `*.tf` files         | `terraform --version`, `terraform providers`, `terraform state list` |\n| `Makefile`           | `make --version`, `make -n`                                          |\n\n### Skills (for Sentry Projects)\n\nIf this is a Sentry project (or sentry-skills plugin is installed), include:\n\n```json\n[\n  \"Skill(sentry-skills:agents-md)\",\n  \"Skill(sentry-skills:blog-writing-guide)\",\n  \"Skill(sentry-skills:brand-guidelines)\",\n  \"Skill(sentry-skills:claude-settings-audit)\",\n  \"Skill(sentry-skills:code-review)\",\n  \"Skill(sentry-skills:code-simplifier)\",\n  \"Skill(sentry-skills:commit)\",\n  \"Skill(sentry-skills:create-branch)\",\n  \"Skill(sentry-skills:create-pr)\",\n  \"Skill(sentry-skills:django-access-review)\",\n  \"Skill(sentry-skills:django-perf-review)\",\n  \"Skill(sentry-skills:doc-coauthoring)\",\n  \"Skill(sentry-skills:find-bugs)\",\n  \"Skill(sentry-skills:gh-review-requests)\",\n  \"Skill(sentry-skills:gha-security-review)\",\n  \"Skill(sentry-skills:iterate-pr)\",\n  \"Skill(sentry-skills:pr-writer)\",\n  \"Skill(sentry-skills:security-review)\",\n  \"Skill(sentry-skills:skill-creator)\",\n  \"Skill(sentry-skills:skill-scanner)\",\n  \"Skill(sentry-skills:skill-writer)\",\n  \"Skill(sentry-skills:sred-project-organizer)\",\n  \"Skill(sentry-skills:sred-work-summary)\"\n]\n```\n\n### WebFetch Domains\n\n#### Always Include (Sentry Projects)\n\n```json\n[\n  \"WebFetch(domain:docs.sentry.io)\",\n  \"WebFetch(domain:develop.sentry.dev)\",\n  \"WebFetch(domain:docs.github.com)\",\n  \"WebFetch(domain:cli.github.com)\"\n]\n```\n\n#### Framework-Specific\n\n| If Detected    | Add Domains                                     |\n| -------------- | ----------------------------------------------- |\n| **Django**     | `docs.djangoproject.com`                        |\n| **Flask**      | `flask.palletsprojects.com`                     |\n| **FastAPI**    | `fastapi.tiangolo.com`                          |\n| **React**      | `react.dev`                                     |\n| **Next.js**    | `nextjs.org`                                    |\n| **Vue**        | `vuejs.org`                                     |\n| **Express**    | `expressjs.com`                                 |\n| **Rails**      | `guides.rubyonrails.org`, `api.rubyonrails.org` |\n| **Go**         | `pkg.go.dev`                                    |\n| **Rust**       | `docs.rs`, `doc.rust-lang.org`                  |\n| **Docker**     | `docs.docker.com`                               |\n| **Kubernetes** | `kubernetes.io`                                 |\n| **Terraform**  | `registry.terraform.io`                         |\n\n### MCP Server Suggestions\n\nMCP servers are configured in `.mcp.json` (not `settings.json`). Check for existing config:\n\n```bash\ncat .mcp.json 2>/dev/null || echo \"No existing .mcp.json\"\n```\n\n#### Sentry MCP (if Sentry SDK detected)\n\nAdd to `.mcp.json` (replace `{org-slug}` and `{project-slug}` with your Sentry organization and project slugs):\n\n```json\n{\n  \"mcpServers\": {\n    \"sentry\": {\n      \"type\": \"http\",\n      \"url\": \"https://mcp.sentry.dev/mcp/{org-slug}/{project-slug}\"\n    }\n  }\n}\n```\n\n#### Linear MCP (if Linear usage detected)\n\nAdd to `.mcp.json`:\n\n```json\n{\n  \"mcpServers\": {\n    \"linear\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@linear/mcp-server\"],\n      \"env\": {\n        \"LINEAR_API_KEY\": \"${LINEAR_API_KEY}\"\n      }\n    }\n  }\n}\n```\n\n**Note**: Never suggest GitHub MCP. Always use `gh` CLI commands for GitHub.\n\n## Output Format\n\nPresent your findings as:\n\n1. **Summary Table** - What was detected\n2. **Recommended settings.json** - Complete JSON ready to copy\n3. **MCP Suggestions** - If applicable\n4. **Merge Instructions** - If existing settings found\n\nExample output structure:\n\n```markdown\n## Detected Tech Stack\n\n| Category        | Found          |\n| --------------- | -------------- |\n| Languages       | Python 3.x     |\n| Package Manager | poetry         |\n| Frameworks      | Django, Celery |\n| Services        | Sentry         |\n| Build Tools     | Docker, Make   |\n\n## Recommended .claude/settings.json\n\n\\`\\`\\`json\n{\n\"permissions\": {\n\"allow\": [\n// ... grouped by category with comments\n],\n\"deny\": []\n}\n}\n\\`\\`\\`\n\n## Recommended .mcp.json (if applicable)\n\nIf you use Sentry or Linear, add the MCP config to `.mcp.json`...\n```\n\n## Important Rules\n\n### What to Include\n\n- Only READ-ONLY commands that cannot modify state\n- Only tools that are actually used by the project (detected via lock files)\n- Standard system commands (ls, cat, find, etc.)\n- The `:*` suffix allows any arguments to the base command\n\n### What to NEVER Include\n\n- **Absolute paths** - Never include user-specific paths like `/home/user/scripts/foo` or `/Users/name/bin/bar`\n- **Custom scripts** - Never include project scripts that may have side effects (e.g., `./scripts/deploy.sh`)\n- **Alternative package managers** - If the project uses pnpm, do NOT include npm/yarn commands\n- **Commands that modify state** - No install, build, run, write, or delete commands\n\n### Package Manager Rules\n\nOnly include the package manager actually used by the project:\n\n| If Detected         | Include         | Do NOT Include                         |\n| ------------------- | --------------- | -------------------------------------- |\n| `pnpm-lock.yaml`    | pnpm commands   | npm, yarn                              |\n| `yarn.lock`         | yarn commands   | npm, pnpm                              |\n| `package-lock.json` | npm commands    | yarn, pnpm                             |\n| `poetry.lock`       | poetry commands | pip (unless also has requirements.txt) |\n| `uv.lock`           | uv commands     | pip, poetry                            |\n| `Pipfile.lock`      | pipenv commands | pip, poetry                            |\n\nIf multiple lock files exist, include only the commands for each detected manager.\n"},"category":"official","lastSynced":"2026-03-06T04:58:19.948Z","seo":{"title":{"en":"claude-settings-audit: Setup Guide for AI Agents | Reposi...","zh":"Claude 设置审计指南 - 优化 settings.json 权限","ja":"Claude 設定監査ガイド - settings.json権限の最適化","ko":"Claude 설정 감사 가이드 - settings.json 권한 최적화","es":"Guía de configuración de Claude Settings Audit para proye...","fr":"Configurer Claude Settings Audit pour les projets de déve...","de":"Einrichten von Claude Settings Audit für Entwicklungsproj...","pt":"Guia de Configuração do Claude Settings Audit","ru":"Настройка ИИ Агента Claude Settings Audit: Руководство","ar":"إعداد أداة claude-settings-audit: دليل المستخدم"},"description":{"en":"Discover how to optimize your repository settings with claude-settings-audit. Get expert guidance on generating recommended Claude Code settings.json permiss...","zh":"使用 Claude 设置审计分析仓库并生成推荐的 settings.json 权限。适用于新项目设置、现有设置审计和只读 Bash 命令确定","ja":"Claude 設定監査を使用してリポジトリを分析し、推奨の settings.json 権限を生成します。新しいプロジェクトの設定、既存の設定の監査、または読み取り専用の Bash コマンドの決定に適しています","ko":"Claude 설정 감사를 사용하여 저장소를 분석하고 권장하는 settings.json 권한을生成합니다. 새 프로젝트 설정, 기존 설정 감사 또는 읽기 전용 Bash 명령어 결정에 적합합니다","es":"Descubre cómo configurar Claude Settings Audit para analizar y recomendar permisos de settings.json en tus proyectos de desarrollo con tecnologías como bash ...","fr":"Découvrez comment configurer Claude Settings Audit pour analyser et recommander des autorisations settings.json dans vos projets de développement utilisant d...","de":"Erfahren Sie, wie Sie Claude Settings Audit konfigurieren, um settings.json-Berechtigungen in Ihren Entwicklungsprojekten mit Technologien wie bash und JSON ...","pt":"Otimizar as configurações do seu projeto com o Claude Settings Audit. Descubra como detectar a pilha de tecnologia e gerar permissões de settings.json","ru":"Оптимизируйте настройки своего проекта с помощью ИИ Агента Claude Settings Audit. Узнайте, как обнаружить технологический стек и сгенерировать разрешения set...","ar":"أمثل إعدادات مشروعك باستخدام أداة claude-settings-audit. اكتشف كيفية الكشف عن مجموعة التكنولوجيا وتوليد أذونات settings.json"},"definition":{"en":"claude-settings-audit is a skill that analyzes repository structures to detect tech stacks, build tools, and monorepo structures, generating settings.json permissions for read-only commands.","zh":"Claude 设置审计是一种工具，用于分析仓库并生成推荐的 settings.json 权限","ja":"Claude 設定監査は、リポジトリを分析し、推奨の settings.json 権限を生成するツールです","ko":"Claude 설정 감사는 저장소를 분석하고 권장하는 settings.json 권한을 생성하는 도구입니다","es":"Claude Settings Audit es una herramienta de análisis de repositorios que genera permisos recomendados de settings.json para comandos de solo lectura","fr":"Claude Settings Audit est un outil d''analyse de référentiels qui génère des autorisations recommandées pour les commandes en lecture seule","de":"Claude Settings Audit ist ein Analyse-Tool für Repositorys, das empfohlene Berechtigungen für settings.json für Lesebefehle generiert","pt":"O que é Claude Settings Audit? É uma ferramenta que analisa repositórios para gerar configurações de settings.json recomendadas.","ru":"Что такое ИИ Агент Claude Settings Audit? Это инструмент, который анализирует репозитории для генерации рекомендованных настроек settings.json.","ar":"ما هي أداة claude-settings-audit؟ هي أداة تحليل المستودعات لتوليد إعدادات settings.json موصى بها."},"features":{"en":["Detects tech stack using indicator files such as *.toml, *.json, and *.yaml","Runs bash commands to analyze repository structure, including ls -la and find","Generates recommended Claude Code settings.json permissions for read-only commands","Supports monorepo structure analysis","Identifies build tools and generates corresponding settings.json permissions"],"zh":["检测技术栈","构建工具检测","monorepo 结构检测","生成推荐的 settings.json 权限","支持读写 Bash 命令"],"ja":["テクノロジー・スタックの検出","ビルド・ツールの検出","モノレポ構造の検出","推奨の settings.json 権限の生成","読み取り専用の Bash コマンドのサポート"],"ko":["기술 스택 감지","빌드 도구 감지","모노레포 구조 감지","권장하는 settings.json 권한 생성","읽기 전용 Bash 명령어 지원"],"es":["Detección de la pila tecnológica y estructura del monorepo","Análisis de archivos de configuración como JSON, TOML y YAML","Generación de permisos recomendados para comandos de solo lectura","Compatibilidad con tecnologías como bash y Docker","Soporte para la detección de indicadores de archivos como Makefile y Dockerfile"],"fr":["Détection de la pile technologique et de la structure du monorepo","Analyse de fichiers de configuration tels que JSON, TOML et YAML","Génération d''autorisations recommandées pour les commandes en lecture seule","Compatibilité avec des technologies telles que bash et Docker","Prise en charge de la détection d''indicateurs de fichiers tels que Makefile et Dockerfile"],"de":["Erkennung der Technologie-Stack und der Monorepo-Struktur","Analyse von Konfigurationsdateien wie JSON, TOML und YAML","Generierung von empfohlene Berechtigungen für Lesebefehle","Unterstützung für Technologien wie bash und Docker","Unterstützung für die Erkennung von Datei-Indikatoren wie Makefile und Dockerfile"],"pt":["Detecção da pilha de tecnologia","Geração de permissões de settings.json para comandos somente leitura","Análise da estrutura do repositório","Suporte a monorepo","Detecção de ferramentas de build","Suporte a comandos bash somente leitura"],"ru":["Обнаружение технологического стека","Генерация разрешений settings.json для команд только для чтения","Анализ структуры репозитория","Поддержка монореpositorия","Обнаружение инструментов сборки","Поддержка команд bash только для чтения"],"ar":["اكتشاف مجموعة التكنولوجيا","توليد أذونات settings.json للأوامر القراءة فقط","تحليل هيكل المستودع","دعم مونوريبوزيتوري","اكتشاف أدوات البناء","دعم أوامر bash القراءة فقط"]},"keywords":{"en":["how to use claude-settings-audit","claude-settings-audit setup guide","claude-settings-audit alternative","claude-settings-audit vs repository analysis tools","claude-settings-audit install","what is claude-settings-audit","claude-settings-audit tutorial","repository analysis with claude-settings-audit"],"zh":["Claude 设置审计","settings.json 权限","技术栈检测","构建工具检测","monorepo 结构检测","AI 工具","代码审计"],"ja":["Claude 設定監査","settings.json 権限","テクノロジー・スタックの検出","ビルド・ツールの検出","モノレポ構造の検出","AI エージェント","コード監査"],"ko":["Claude 설정 감사","settings.json 권한","기술 스택 감지","빌드 도구 감지","모노레포 구조 감지","AI 도구","코드 감사"],"es":["Claude Settings Audit","análisis de repositorios","permisos de settings.json","comandos de solo lectura","bash","JSON","TOML","YAML","monorepo","desarrollo de software"],"fr":["Claude Settings Audit","analyse de référentiels","autorisations settings.json","commandes en lecture seule","bash","JSON","TOML","YAML","monorepo","développement de logiciels"],"de":["Claude Settings Audit","Repository-Analyse","Berechtigungen für settings.json","Lesebefehle","bash","JSON","TOML","YAML","Monorepo","Software-Entwicklung"],"pt":["claude settings audit","configuração de projeto","detecção de pilha de tecnologia","geração de permissões","análise de repositório","monorepo","ferramentas de build","comandos bash","settings.json"],"ru":["ИИ Агент claude settings audit","настройка проекта","обнаружение технологического стека","генерация разрешений","анализ репозитория","монореpositorий","инструменты сборки","команды bash","settings.json"],"ar":["أداة claude-settings-audit","إعدادات المشروع","اكتشاف مجموعة التكنولوجيا","توليد أذونات","تحليل المستودع","مونوريبوزيتوري","أدوات البناء","أوامر bash","settings.json"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated repository analysis and Claude Code settings optimization.","zh":"适合需要自动化仓库分析和 Claude Code 设置优化的 AI 代理。","ja":"自動化されたリポジトリ分析と Claude Code 設定の最適化が必要な AI エージェントに適しています。","ko":"자동화 된 저장소 분석 및 Claude Code 설정 최적화가 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA que necesitan análisis de repositorios automatizados y optimización de la configuración de Claude Code.","fr":"Parfait pour les agents IA nécessitant une analyse de référentiel automatisée et une optimisation des paramètres de Claude Code.","de":"Perfekt für KI-Agents, die eine automatisierte Repository-Analyse und eine Optimierung der Claude Code-Einstellungen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de análise de repositório automatizada e otimização de configurações do Claude Code.","ru":"Идеально для агентов ИИ, которым требуется автоматический анализ репозитория и оптимизация настроек Claude Code.","ar":"مثالية لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تحليل مستودعautomated وتحسين إعدادات Claude Code."},"recommendation":{"en":"Empowers agents to generate recommended Claude Code settings.json permissions by detecting tech stacks, build tools, and monorepo structures, utilizing bash commands and file format analysis such as .toml, .json, and .yaml.","zh":"赋予代理生成推荐的 Claude Code 设置。json 权限，通过检测技术栈、构建工具和 monorepo 结构，利用 bash 命令和文件格式分析，例如 .toml、.json 和 .yaml。","ja":"エージェントに、テクノロジー・スタック、ビルド・ツール、モノレポ構造を検出することで、bash コマンドやファイル形式（.toml、.json、.yaml など）を分析して、推奨される Claude Code の設定。json 権限を生成する能力を与えます。","ko":"기술 스택, 빌드 도구 및 모노레포 구조를 감지하여 bash 명령어 및 파일 형식(.toml, .json, .yaml 등) 분석을 통해 권장되는 Claude Code 설정.json 권한을 생성할 수 있는 능력을 에이전트에 부여합니다.","es":"Habilita a los agentes a generar permisos recomendados de settings.json de Claude Code detectando pilas tecnológicas, herramientas de construcción y estructuras de monorepositorio, utilizando comandos bash y análisis de formato de archivo como .toml, .json y .yaml.","fr":"Permet aux agents de générer des paramètres recommandés de settings.json de Claude Code en détectant les piles technologiques, les outils de construction et les structures de monorepository, en utilisant des commandes bash et une analyse de format de fichier comme .toml, .json et .yaml.","de":"Ermächtigt Agents, empfohlene settings.json-Berechtigungen von Claude Code zu generieren, indem Technologiestacks, Build-Tools und Monorepo-Strukturen erkannt und bash-Befehle sowie Dateiformatanalysen wie .toml, .json und .yaml verwendet werden.","pt":"Permite que os agentes gerem configurações recomendadas de permissões do settings.json do Claude Code, detectando pilhas de tecnologia, ferramentas de compilação e estruturas de monorepo, utilizando comandos bash e análise de formato de arquivo, como .toml, .json e .yaml.","ru":"Позволяет агентам генерировать рекомендуемые настройки разрешений settings.json для Claude Code, обнаруживая технологические стеки, инструменты сборки и структуры монореpositorия, используя команды bash и анализ формата файла, такие как .toml, .json и .yaml.","ar":"تمكن الوكلاء من توليد إعدادات موصى بها لصلاحيات settings.json الخاصة ب Claude Code ، من خلال الكشف عن تقنيات الحزمة و أدوات البناء و هيكل المستودع الوحيد ، باستخدام أوامر bash و تحليل تنسيق الملفات مثل .toml و .json و .yaml."},"useCases":{"en":["Auditing existing repository settings","Setting up new projects with optimized Claude Code permissions","Determining read-only bash commands to allow"],"zh":["审计现有的仓库设置","使用优化的 Claude Code 权限设置新项目","确定允许的只读 bash 命令"],"ja":["既存のリポジトリ設定を監査する","最適化された Claude Code 権限で新しいプロジェクトを設定する","許可される読み取り専用の bash コマンドを決定する"],"ko":["기존 저장소 설정을 감사하는 것","최적화된 Claude Code 권한으로 새로운 프로젝트 설정","허용할 읽기 전용 bash 명령어를 결정"],"es":["Auditoría de la configuración de repositorios existentes","Configuración de nuevos proyectos con permisos de Claude Code optimizados","Determinación de comandos bash de solo lectura para permitir"],"fr":["Audit des paramètres de référentiel existants","Configuration de nouveaux projets avec des autorisations de Claude Code optimisées","Détermination des commandes bash en lecture seule pour autoriser"],"de":["Prüfung der Konfiguration von bestehenden Repositories","Einrichtung neuer Projekte mit optimierten Claude Code-Berechtigungen","Bestimmung von bash-Befehlen mit Lesezugriff, um zu erlauben"],"pt":["Auditoria de configurações de repositório existentes","Configuração de novos projetos com permissões otimizadas do Claude Code","Determinação de comandos bash somente leitura para permitir"],"ru":["Аудит существующих настроек репозитория","Настройка новых проектов с оптимизированными разрешениями Claude Code","Определение команд bash только для чтения для разрешения"],"ar":["مراجعة إعدادات المستودع الحالية","إعداد مشاريع جديدة مع صلاحيات مُختزلة من Claude Code","تحديد أوامر bash للقراءة فقط للسماح بها"]},"limitations":{"en":["Requires repository access","Limited to Claude Code settings.json permissions","Dependent on bash command execution"],"zh":["需要仓库访问","仅限 Claude Code 设置。json 权限","依赖于 bash 命令执行"],"ja":["リポジトリへのアクセスが必要","Claude Code の設定。json 権限のみ","bash コマンドの実行に依存"],"ko":["저장소 접근이 필요","Claude Code 설정.json 권한에만 hạn chế","bash 명령어 실행에 의존"],"es":["Requiere acceso al repositorio","Limitado a permisos de settings.json de Claude Code","Dependiente de la ejecución de comandos bash"],"fr":["Nécessite un accès au référentiel","Limité aux autorisations de settings.json de Claude Code","Dépendant de l''exécution des commandes bash"],"de":["Benötigt Zugriff auf das Repository","Begrenzt auf settings.json-Berechtigungen von Claude Code","Abhängig von der Ausführung von bash-Befehlen"],"pt":["Requer acesso ao repositório","Limitado a permissões do settings.json do Claude Code","Dependente da execução de comandos bash"],"ru":["Требует доступа к репозиторию","Ограничен разрешениями settings.json для Claude Code","Зависит от выполнения команд bash"],"ar":["يتطلب الوصول إلى المستودع","محدود بصلاحيات settings.json الخاصة ب Claude Code","يعتمد على تنفيذ أوامر bash"]},"version":4},"contentHash":"850dfd941c9c79f5adbafe1cb488f94c3bd11646916855a0c4cf5b57842be5e6","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":95}');
