INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/claude-settings-audit', 'claude-settings-audit', 'getsentry', 'skills', 'official', 'claude-settings-audit getsentry skills official tag-production claude-settings-audit analyzes repositories to generate recommended Claude Code settings.json permissions, benefiting developers setting up new projects or auditing existing settings. Claude 设置审计是一种分析仓库并生成推荐的 settings.json 权限的工具。它可以检测技术栈、构建工具和 monorepo 结构 Claude 設定監査は、リポジトリを分析し、推奨の settings.json 権限を生成するツールです。テクノロジー・スタック、ビルド・ツール、モノレポ構造を検出できます Claude 설정 감사는 저장소를 분석하고 권장하는 settings.json 권한을 생성하는 도구입니다. 기술 스택, 빌드 도구 및 모노레포 구조를 обнаруж할 수 있습니다 Claude Settings Audit analiza el repositorio y genera permisos recomendados de settings.json para comandos de solo lectura, detectando la pila tecnológica y la estructura del monorepo Claude Settings Audit analyse le référentiel et génère des autorisations recommandées pour les commandes en lecture seule, en détectant la pile technologique et la structure du monorepo Claude Settings Audit analysiert das Repository und generiert empfohlene Berechtigungen für settings.json für Lesebefehle, indem es die Technologie-Stack und die Monorepo-Struktur erkennt O Claude Settings Audit é uma ferramenta que analisa repositórios e gera configurações recomendadas de settings.json para comandos somente leitura. ИИ Агент Claude Settings Audit анализирует репозитории и генерирует рекомендованные настройки settings.json для команд только для чтения. أداة claude-settings-audit تحليل المستودعات وتوليد إعدادات موصى بها من settings.json للأوامر القراءة فقط. how to use claude-settings-audit claude-settings-audit setup guide claude-settings-audit alternative claude-settings-audit vs repository analysis tools claude-settings-audit install what is claude-settings-audit claude-settings-audit tutorial repository analysis with claude-settings-audit Claude 设置审计 settings.json 权限 技术栈检测 构建工具检测 monorepo 结构检测 AI 工具 代码审计 Detects tech stack using indicator files such as *.toml, *.json, and *.yaml Runs bash commands to analyze repository structure, including ls -la and find Generates recommended Claude Code settings.json permissions for read-only commands Supports monorepo structure analysis Identifies build tools and generates corresponding settings.json permissions claude-settings-audit is a skill that analyzes repository structures to detect tech stacks, build tools, and monorepo structures, generating settings.json permissions for read-only commands.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/security-review', 'official', 'getsentry', 'skills', 'getsentry/skills', 'security-review', 360, 11, 95, '2026-03-06T00:20:36Z', '2026-03-06T05:13:43.663Z', '6d36fa39ada88c8e66fdd4c52c3b846b0f27602d49871856d4bff90cc94719e5', '{"id":"getsentry/skills/security-review","name":"security-review","description":{"en":"The security-review skill provides systematic security code review for vulnerabilities, benefiting developers and security teams. It identifies exploitable security vulnerabilities in code with high confidence reporting","zh":"代码安全审查工具提供OWASP安全审查，检测代码中的安全漏洞，包括SQL注入、XSS、认证和授权问题","ja":"AIエージェントのセキュリティレビュー機能は、OWASPチェックシートを使用してコードのセキュリティ脆弱性を検出します","ko":"코드 보안 리뷰 도구는 OWASP 보안 리뷰를 제공하여 코드의 보안 취약점을检测합니다","es":"Security-review es una habilidad que identifica vulnerabilidades de seguridad en el código y proporciona informes de alta confianza","fr":"Security-review est une compétence qui identifie les vulnérabilités de sécurité dans le code et fournit des rapports de haute confiance","de":"Security-review ist eine Fähigkeit, die Sicherheitslücken im Code erkennt und vertrauenswürdige Berichte liefert","pt":"O security-review é uma ferramenta de análise de código que identifica vulnerabilidades de segurança, incluindo injeção, XSS e problemas de autenticação","ru":"ИИ Агент security-review - это инструмент проверки кода, который выявляет уязвимости безопасности, включая инъекции, XSS и проблемы аутентификации","ar":"أداة الأمان security-review هي أداة لمراجعة الشفرة البرمجية التي تحدد الثغرات الأمنية، بما في ذلك الحقن والكسس والمشاكل المتعلقة بالتحقق"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"security-review","description":"Security code review for vulnerabilities. Use when asked to security review, find vulnerabilities, check for security issues, audit security, OWASP review, or review code for injection, XSS, authentication, authorization, cryptography issues. Provides systematic review with confidence-based reporting.","bodyPreview":"<!--\nReference material based on OWASP Cheat Sheet Series (CC BY-SA 4.0)\nhttps://cheatsheetseries.owasp.org/\n-->\n\n# Security Review Skill\n\nIdentify exploitable security vulnerabilities in code. Report only **HIGH CONFIDENCE** findings—clear vulnerable patterns with attacker-controlled input.\n\n## Scope: Research vs. Reporting\n\n**CRITICAL DISTINCTION:**\n\n- **Report on**: Only the specific file, diff, or code provided by the user\n- **Research**: The ENTIRE codebase to build confidence before report","body":"<!--\nReference material based on OWASP Cheat Sheet Series (CC BY-SA 4.0)\nhttps://cheatsheetseries.owasp.org/\n-->\n\n# Security Review Skill\n\nIdentify exploitable security vulnerabilities in code. Report only **HIGH CONFIDENCE** findings—clear vulnerable patterns with attacker-controlled input.\n\n## Scope: Research vs. Reporting\n\n**CRITICAL DISTINCTION:**\n\n- **Report on**: Only the specific file, diff, or code provided by the user\n- **Research**: The ENTIRE codebase to build confidence before reporting\n\nBefore flagging any issue, you MUST research the codebase to understand:\n- Where does this input actually come from? (Trace data flow)\n- Is there validation/sanitization elsewhere?\n- How is this configured? (Check settings, config files, middleware)\n- What framework protections exist?\n\n**Do NOT report issues based solely on pattern matching.** Investigate first, then report only what you''re confident is exploitable.\n\n## Confidence Levels\n\n| Level | Criteria | Action |\n|-------|----------|--------|\n| **HIGH** | Vulnerable pattern + attacker-controlled input confirmed | **Report** with severity |\n| **MEDIUM** | Vulnerable pattern, input source unclear | **Note** as \"Needs verification\" |\n| **LOW** | Theoretical, best practice, defense-in-depth | **Do not report** |\n\n## Do Not Flag\n\n### General Rules\n- Test files (unless explicitly reviewing test security)\n- Dead code, commented code, documentation strings\n- Patterns using **constants** or **server-controlled configuration**\n- Code paths that require prior authentication to reach (note the auth requirement instead)\n\n### Server-Controlled Values (NOT Attacker-Controlled)\n\nThese are configured by operators, not controlled by attackers:\n\n| Source | Example | Why It''s Safe |\n|--------|---------|---------------|\n| Django settings | `settings.API_URL`, `settings.ALLOWED_HOSTS` | Set via config/env at deployment |\n| Environment variables | `os.environ.get(''DATABASE_URL'')` | Deployment configuration |\n| Config files | `config.yaml`, `app.config[''KEY'']` | Server-side files |\n| Framework constants | `django.conf.settings.*` | Not user-modifiable |\n| Hardcoded values | `BASE_URL = \"https://api.internal\"` | Compile-time constants |\n\n**SSRF Example - NOT a vulnerability:**\n```python\n# SAFE: URL comes from Django settings (server-controlled)\nresponse = requests.get(f\"{settings.SEER_AUTOFIX_URL}{path}\")\n```\n\n**SSRF Example - IS a vulnerability:**\n```python\n# VULNERABLE: URL comes from request (attacker-controlled)\nresponse = requests.get(request.GET.get(''url''))\n```\n\n### Framework-Mitigated Patterns\nCheck language guides before flagging. Common false positives:\n\n| Pattern | Why It''s Usually Safe |\n|---------|----------------------|\n| Django `{{ variable }}` | Auto-escaped by default |\n| React `{variable}` | Auto-escaped by default |\n| Vue `{{ variable }}` | Auto-escaped by default |\n| `User.objects.filter(id=input)` | ORM parameterizes queries |\n| `cursor.execute(\"...%s\", (input,))` | Parameterized query |\n| `innerHTML = \"<b>Loading...</b>\"` | Constant string, no user input |\n\n**Only flag these when:**\n- Django: `{{ var|safe }}`, `{% autoescape off %}`, `mark_safe(user_input)`\n- React: `dangerouslySetInnerHTML={{__html: userInput}}`\n- Vue: `v-html=\"userInput\"`\n- ORM: `.raw()`, `.extra()`, `RawSQL()` with string interpolation\n\n## Review Process\n\n### 1. Detect Context\n\nWhat type of code am I reviewing?\n\n| Code Type | Load These References |\n|-----------|----------------------|\n| API endpoints, routes | `authorization.md`, `authentication.md`, `injection.md` |\n| Frontend, templates | `xss.md`, `csrf.md` |\n| File handling, uploads | `file-security.md` |\n| Crypto, secrets, tokens | `cryptography.md`, `data-protection.md` |\n| Data serialization | `deserialization.md` |\n| External requests | `ssrf.md` |\n| Business workflows | `business-logic.md` |\n| GraphQL, REST design | `api-security.md` |\n| Config, headers, CORS | `misconfiguration.md` |\n| CI/CD, dependencies | `supply-chain.md` |\n| Error handling | `error-handling.md` |\n| Audit, logging | `logging.md` |\n\n### 2. Load Language Guide\n\nBased on file extension or imports:\n\n| Indicators | Guide |\n|------------|-------|\n| `.py`, `django`, `flask`, `fastapi` | `languages/python.md` |\n| `.js`, `.ts`, `express`, `react`, `vue`, `next` | `languages/javascript.md` |\n| `.go`, `go.mod` | `languages/go.md` |\n| `.rs`, `Cargo.toml` | `languages/rust.md` |\n| `.java`, `spring`, `@Controller` | `languages/java.md` |\n\n### 3. Load Infrastructure Guide (if applicable)\n\n| File Type | Guide |\n|-----------|-------|\n| `Dockerfile`, `.dockerignore` | `infrastructure/docker.md` |\n| K8s manifests, Helm charts | `infrastructure/kubernetes.md` |\n| `.tf`, Terraform | `infrastructure/terraform.md` |\n| GitHub Actions, `.gitlab-ci.yml` | `infrastructure/ci-cd.md` |\n| AWS/GCP/Azure configs, IAM | `infrastructure/cloud.md` |\n\n### 4. Research Before Flagging\n\n**For each potential issue, research the codebase to build confidence:**\n\n- Where does this value actually come from? Trace the data flow.\n- Is it configured at deployment (settings, env vars) or from user input?\n- Is there validation, sanitization, or allowlisting elsewhere?\n- What framework protections apply?\n\nOnly report issues where you have HIGH confidence after understanding the broader context.\n\n### 5. Verify Exploitability\n\nFor each potential finding, confirm:\n\n**Is the input attacker-controlled?**\n\n| Attacker-Controlled (Investigate) | Server-Controlled (Usually Safe) |\n|-----------------------------------|----------------------------------|\n| `request.GET`, `request.POST`, `request.args` | `settings.X`, `app.config[''X'']` |\n| `request.json`, `request.data`, `request.body` | `os.environ.get(''X'')` |\n| `request.headers` (most headers) | Hardcoded constants |\n| `request.cookies` (unsigned) | Internal service URLs from config |\n| URL path segments: `/users/<id>/` | Database content from admin/system |\n| File uploads (content and names) | Signed session data |\n| Database content from other users | Framework settings |\n| WebSocket messages | |\n\n**Does the framework mitigate this?**\n- Check language guide for auto-escaping, parameterization\n- Check for middleware/decorators that sanitize\n\n**Is there validation upstream?**\n- Input validation before this code\n- Sanitization libraries (DOMPurify, bleach, etc.)\n\n### 6. Report HIGH Confidence Only\n\nSkip theoretical issues. Report only what you''ve confirmed is exploitable after research.\n\n---\n\n## Severity Classification\n\n| Severity | Impact | Examples |\n|----------|--------|----------|\n| **Critical** | Direct exploit, severe impact, no auth required | RCE, SQL injection to data, auth bypass, hardcoded secrets |\n| **High** | Exploitable with conditions, significant impact | Stored XSS, SSRF to metadata, IDOR to sensitive data |\n| **Medium** | Specific conditions required, moderate impact | Reflected XSS, CSRF on state-changing actions, path traversal |\n| **Low** | Defense-in-depth, minimal direct impact | Missing headers, verbose errors, weak algorithms in non-critical context |\n\n---\n\n## Quick Patterns Reference\n\n### Always Flag (Critical)\n```\neval(user_input)           # Any language\nexec(user_input)           # Any language\npickle.loads(user_data)    # Python\nyaml.load(user_data)       # Python (not safe_load)\nunserialize($user_data)    # PHP\ndeserialize(user_data)     # Java ObjectInputStream\nshell=True + user_input    # Python subprocess\nchild_process.exec(user)   # Node.js\n```\n\n### Always Flag (High)\n```\ninnerHTML = userInput              # DOM XSS\ndangerouslySetInnerHTML={user}     # React XSS\nv-html=\"userInput\"                 # Vue XSS\nf\"SELECT * FROM x WHERE {user}\"    # SQL injection\n`SELECT * FROM x WHERE ${user}`    # SQL injection\nos.system(f\"cmd {user_input}\")     # Command injection\n```\n\n### Always Flag (Secrets)\n```\npassword = \"hardcoded\"\napi_key = \"sk-...\"\nAWS_SECRET_ACCESS_KEY = \"...\"\nprivate_key = \"-----BEGIN\"\n```\n\n### Check Context First (MUST Investigate Before Flagging)\n```\n# SSRF - ONLY if URL is from user input, NOT from settings/config\nrequests.get(request.GET[''url''])     # FLAG: User-controlled URL\nrequests.get(settings.API_URL)       # SAFE: Server-controlled config\nrequests.get(f\"{settings.BASE}/{x}\") # CHECK: Is ''x'' user input?\n\n# Path traversal - ONLY if path is from user input\nopen(request.GET[''file''])            # FLAG: User-controlled path\nopen(settings.LOG_PATH)              # SAFE: Server-controlled config\nopen(f\"{BASE_DIR}/{filename}\")       # CHECK: Is ''filename'' user input?\n\n# Open redirect - ONLY if URL is from user input\nredirect(request.GET[''next''])        # FLAG: User-controlled redirect\nredirect(settings.LOGIN_URL)         # SAFE: Server-controlled config\n\n# Weak crypto - ONLY if used for security purposes\nhashlib.md5(file_content)            # SAFE: File checksums, caching\nhashlib.md5(password)                # FLAG: Password hashing\nrandom.random()                      # SAFE: Non-security uses (UI, sampling)\nrandom.random() for token            # FLAG: Security tokens need secrets module\n```\n\n---\n\n## Output Format\n\n```markdown\n## Security Review: [File/Component Name]\n\n### Summary\n- **Findings**: X (Y Critical, Z High, ...)\n- **Risk Level**: Critical/High/Medium/Low\n- **Confidence**: High/Mixed\n\n### Findings\n\n#### [VULN-001] [Vulnerability Type] (Severity)\n- **Location**: `file.py:123`\n- **Confidence**: High\n- **Issue**: [What the vulnerability is]\n- **Impact**: [What an attacker could do]\n- **Evidence**:\n  ```python\n  [Vulnerable code snippet]\n  ```\n- **Fix**: [How to remediate]\n\n### Needs Verification\n\n#### [VERIFY-001] [Potential Issue]\n- **Location**: `file.py:456`\n- **Question**: [What needs to be verified]\n```\n\nIf no vulnerabilities found, state: \"No high-confidence vulnerabilities identified.\"\n\n---\n\n## Reference Files\n\n### Core Vulnerabilities (`references/`)\n| File | Covers |\n|------|--------|\n| `injection.md` | SQL, NoSQL, OS command, LDAP, template injection |\n| `xss.md` | Reflected, stored, DOM-based XSS |\n| `authorization.md` | Authorization, IDOR, privilege escalation |\n| `authentication.md` | Sessions, credentials, password storage |\n| `cryptography.md` | Algorithms, key management, randomness |\n| `deserialization.md` | Pickle, YAML, Java, PHP deserialization |\n| `file-security.md` | Path traversal, uploads, XXE |\n| `ssrf.md` | Server-side request forgery |\n| `csrf.md` | Cross-site request forgery |\n| `data-protection.md` | Secrets exposure, PII, logging |\n| `api-security.md` | REST, GraphQL, mass assignment |\n| `business-logic.md` | Race conditions, workflow bypass |\n| `modern-threats.md` | Prototype pollution, LLM injection, WebSocket |\n| `misconfiguration.md` | Headers, CORS, debug mode, defaults |\n| `error-handling.md` | Fail-open, information disclosure |\n| `supply-chain.md` | Dependencies, build security |\n| `logging.md` | Audit failures, log injection |\n\n### Language Guides (`languages/`)\n- `python.md` - Django, Flask, FastAPI patterns\n- `javascript.md` - Node, Express, React, Vue, Next.js\n- `go.md` - Go-specific security patterns\n- `rust.md` - Rust unsafe blocks, FFI security\n- `java.md` - Spring, Java EE patterns\n\n### Infrastructure (`infrastructure/`)\n- `docker.md` - Container security\n- `kubernetes.md` - K8s RBAC, secrets, policies\n- `terraform.md` - IaC security\n- `ci-cd.md` - Pipeline security\n- `cloud.md` - AWS/GCP/Azure security\n"},"category":"official","lastSynced":"2026-03-06T05:13:43.663Z","seo":{"title":{"en":"Security-Review: OWASP-Compliant Code Audit for AI Agents","zh":"代码安全审查工具：OWASP 安全审查指南","ja":"AIエージェントのセキュリティレビュー: OWASPチェックシートを使用した脆弱性検出","ko":"코드 보안 리뷰 도구: OWASP 보안 리뷰 가이드","es":"Guía de configuración de seguridad-review para detectar v...","fr":"Guide de configuration de sécurité-review pour détecter l...","de":"Konfigurationsleitfaden für security-review zur Erkennung...","pt":"Guia de Configuração do security-review: Análise de Códig...","ru":"Настройка ИИ Агента security-review: Проверка Кодa на Уяз...","ar":"إعداد أداة الأمان security-review: مراجعة الشفرة البرمجية..."},"description":{"en":"Discover vulnerabilities with confidence-based reporting. Learn how to setup security-review for systematic code audits and OWASP compliance","zh":"使用代码安全审查工具检测OWASP顶级10大安全风险，包括SQL注入、XSS、认证和授权漏洞","ja":"AIエージェントのセキュリティレビュー機能を使用して、OWASPトップ10の脆弱性を検出します。SQLインジェクション、XSS、認証、認可の問題など","ko":"코드 보안 리뷰 도구를 사용하여 OWASP TOP 10 보안 취약점을检测합니다. SQL 인젝션, XSS, 인증 및 인가 취약점 등","es":"Descubre cómo utilizar security-review para identificar vulnerabilidades de seguridad en tu código con informes de alta confianza","fr":"Découvrez comment utiliser security-review pour identifier les vulnérabilités de sécurité dans votre code avec des rapports de haute confiance","de":"Erfahren Sie, wie Sie security-review verwenden, um Sicherheitslücken in Ihrem Code mit vertrauenswürdigen Berichten zu erkennen","pt":"Descubra como o security-review pode ajudar a identificar vulnerabilidades de segurança no código, incluindo injeção, XSS e problemas de autenticação","ru":"Узнайте, как ИИ Агент security-review может помочь выявить уязвимости безопасности в коде, включая инъекции, XSS и проблемы аутентификации","ar":"تعرف على كيفية استخدام أداة الأمان security-review لتحديد الثغرات الأمنية في الشفرة البرمجية، بما في ذلك الحقن والكسس والمشاكل المتعلقة بالتحقق"},"definition":{"en":"security-review is a systematic code review skill for identifying exploitable security vulnerabilities with confidence-based reporting","zh":"代码安全审查工具是一种AI驱动的工具，用于检测代码中的安全漏洞和脆弱性","ja":"AIエージェントのセキュリティレビュー機能は、コードのセキュリティ脆弱性を検出するためのAI駆動のツールです","ko":"코드 보안 리뷰 도구는 코드의 보안 취약점을检测하는 AI 기반 도구입니다","es":"Security-review es una herramienta de revisión de código que busca vulnerabilidades de seguridad","fr":"Security-review est un outil de révision de code qui recherche les vulnérabilités de sécurité","de":"Security-review ist ein Tool zur Code-Überprüfung, das nach Sicherheitslücken sucht","pt":"O security-review é uma análise de código que identifica vulnerabilidades de segurança, como injeção e XSS","ru":"ИИ Агент security-review - это проверка кода, которая выявляет уязвимости безопасности, такие как инъекции и XSS","ar":"أداة الأمان security-review هي مراجعة الشفرة البرمجية التي تحدد الثغرات الأمنية، مثل الحقن والكسس"},"features":{"en":["Identifies vulnerabilities in code using OWASP Cheat Sheet Series","Provides high confidence reporting for clear vulnerable patterns","Supports systematic review of specific files, diffs, or code provided by the user","Researches the entire codebase to build confidence before reporting","Reports on attacker-controlled input vulnerabilities such as injection, XSS, authentication, and authorization issues","Utilizes cryptography issue detection for comprehensive security audits"],"zh":["OWASP安全审查","SQL注入检测","XSS检测","认证和授权漏洞检测","代码安全审查报告"],"ja":["OWASPチェックシートを使用したセキュリティレビュー","SQLインジェクションの検出","XSSの検出","認証と認可の問題の検出","コードのセキュリティレビュー報告"],"ko":["OWASP 보안 리뷰","SQL 인젝션检测","XSS检测","인증 및 인가 취약점检测","코드 보안 리뷰 보고서"],"es":["Análisis de vulnerabilidades de inyección","Detección de ataques de XSS","Verificación de autenticación y autorización","Análisis de criptografía","Informes de alta confianza basados en la serie de hojas de trucos de OWASP"],"fr":["Analyse des vulnérabilités d''injection","Détection des attaques de XSS","Vérification de l''authentification et de l''autorisation","Analyse de la cryptographie","Rapports de haute confiance basés sur la série de feuilles de truc de l''OWASP"],"de":["Analyse von Injektions-Sicherheitslücken","Erkennung von XSS-Angriffen","Überprüfung von Authentifizierung und Autorisierung","Analyse der Kryptographie","Vertrauenswürdige Berichte basierend auf der OWASP-Cheat-Sheet-Serie"],"pt":["Análise de código para vulnerabilidades de segurança","Detecção de injeção e XSS","Verificação de problemas de autenticação e autorização","Análise de criptografia","Relatórios baseados em confiança"],"ru":["Проверка кода на уязвимости безопасности","Обнаружение инъекций и XSS","Проверка проблем аутентификации и авторизации","Анализ криптографии","Отчеты на основе доверия"],"ar":["مراجعة الشفرة البرمجية للثغرات الأمنية","الكشف عن الحقن والكسس","تحقق من مشاكل التحقق والتصريح","تحليل التشفير","تقارير قائمة على الثقة"]},"keywords":{"en":["how to use security-review","what is security-review","security-review setup guide","OWASP-compliant code audit","security-review alternative","security-review vs static analysis tools","security-review install for AI agents","systematic code review for vulnerabilities","confidence-based reporting for security issues"],"zh":["代码安全审查","OWASP安全审查","SQL注入检测","XSS检测","认证和授权漏洞检测","代码安全审查工具","AI安全审查"],"ja":["AIエージェントのセキュリティレビュー","OWASPチェックシート","SQLインジェクションの検出","XSSの検出","認証と認可の問題の検出","コードのセキュリティレビュー","AI駆動のセキュリティツール"],"ko":["코드 보안 리뷰","OWASP 보안 리뷰","SQL 인젝션检测","XSS检测","인증 및 인가 취약점检测","코드 보안 리뷰 도구","AI 보안 리뷰"],"es":["herramientas de seguridad","revisión de código","vulnerabilidades de seguridad","OWASP","inyección de código","XSS","autenticación","autorización","criptografía"],"fr":["outils de sécurité","révision de code","vulnérabilités de sécurité","OWASP","injection de code","XSS","authentification","autorisation","cryptographie"],"de":["Sicherheitstools","Code-Überprüfung","Sicherheitslücken","OWASP","Code-Injektion","XSS","Authentifizierung","Autorisierung","Kryptographie"],"pt":["segurança de código","análise de vulnerabilidades","injeção de código","XSS","autenticação","autorização","criptografia","relatórios de segurança"],"ru":["безопасность кода","проверка уязвимостей","инъекция кода","XSS","аутентификация","авторизация","криптография","отчеты безопасности"],"ar":["أمان الشفرة البرمجية","مراجعة الثغرات الأمنية","حقن الشفرة","الكسس","التحقق","التصريح","التشفير","تقارير الأمان"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring advanced vulnerability detection and OWASP compliance scanning.","zh":"适合需要高级漏洞检测和OWASP合规性扫描的代码审查代理。","ja":"コードレビュー代理が高度な脆弱性検出とOWASPへの準拠スキャニングを必要とする場合に最適です。","ko":"고급 취약점 탐지 및 OWASP 규정 준수 스캔이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para agentes de revisión de código que requieren detección de vulnerabilidades avanzada y escaneo de cumplimiento de OWASP.","fr":"Idéal pour les agents de révision de code nécessitant une détection de vulnérabilités avancée et un balayage de conformité OWASP.","de":"Ideal für Code-Review-Agents, die eine erweiterte Schwachstellen-Erkennung und ein OWASP-Konformitäts-Scanning erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem detecção avançada de vulnerabilidades e varredura de conformidade OWASP.","ru":"Идеально для агентов кодового обзора, требующих продвинутого обнаружения уязвимостей и сканирования соответствия OWASP.","ar":"مثالي لعميل مراجعة الكود الذي يتطلب الكشف المتقدم عن الثغرات الأمنية وتصوير مطابقة OWASP."},"recommendation":{"en":"Empowers agents to systematically identify high-confidence security vulnerabilities, including injection, XSS, authentication, and authorization issues, using confidence-based reporting and the OWASP Cheat Sheet Series as reference material.","zh":"赋予代理系统地识别高置信度安全漏洞的能力，包括注入、XSS、身份验证和授权问题，使用基于置信度的报告和OWASP备忘录系列作为参考资料。","ja":"エージェントに、インジェクション、XSS、認証、および認可の問題を含む、高信頼性のセキュリティ脆弱性を体系的に特定する機能を提供します。信頼性ベースのレポートとOWASPチートシートシリーズを参考資料として使用します。","ko":"에이전트가 주입, XSS, 인증 및 권한 문제를 포함한 높은 신뢰도 보안 취약점을 체계적으로 식별할 수 있는 기능을 부여합니다. 신뢰도 기반 보고서와 OWASP 치트 시트 시리즈를 참조 자료로 사용합니다.","es":"Habilita a los agentes a identificar sistemáticamente vulnerabilidades de seguridad de alta confianza, incluyendo inyección, XSS, problemas de autenticación y autorización, utilizando informes basados en la confianza y la serie de hojas de trucos de OWASP como material de referencia.","fr":"Permet aux agents d''identifier systématiquement des vulnérabilités de sécurité à haute confiance, notamment les injections, les XSS, les problèmes d''authentification et d''autorisation, en utilisant des rapports basés sur la confiance et la série de feuilles de trucs OWASP comme documentation de référence.","de":"Ermächtigt die Agenten, systematisch Sicherheitsverletzungen mit hoher Zuverlässigkeit zu identifizieren, einschließlich Injection, XSS, Authentifizierungs- und Autorisierungsproblemen, unter Verwendung von vertrauensbasierten Berichterstattungen und der OWASP-Cheat-Sheet-Serie als Referenzmaterial.","pt":"Habilita os agentes a identificar sistematicamente vulnerabilidades de segurança de alta confiança, incluindo injeção, XSS, autenticação e problemas de autorização, usando relatórios baseados na confiança e a Série de Folhas de Dicas OWASP como material de referência.","ru":"Позволяет агентам систематически выявлять уязвимости безопасности с высокой степенью доверия, включая внедрение, XSS, аутентификацию и проблемы авторизации, используя отчеты, основанные на доверии, и серию листов OWASP Cheat Sheet в качестве справочного материала.","ar":"يمنح الوكيل القدرة على تحديد المخاطر الأمنية عالية الثقة بطريقة منهجية، بما في ذلك حقن، XSS، مصادقة وأمور ترخيص، باستخدام تقارير تعتمد على الثقة ومسلسلة ورقات OWASP Cheat Sheet كمرجع."},"useCases":{"en":["Automating security code reviews for vulnerabilities","Detecting OWASP Top 10 security risks in codebases","Auditing code for cryptography and authorization issues"],"zh":["自动化安全代码审查以发现漏洞","在代码库中检测OWASP前10名安全风险","审计代码中的加密和授权问题"],"ja":["脆弱性のためにセキュリティコードレビューを自動化する","コードベースでOWASPトップ10のセキュリティリスクを検出する","コードの暗号化と認可の問題を監査する"],"ko":["취약점을 찾기 위한 보안 코드 리뷰 자동화","코드베이스에서 OWASP 상위 10가지 보안 위험 탐지","코드의 암호화 및 권한 문제를 감사"],"es":["Automatización de revisiones de código de seguridad para vulnerabilidades","Detección de riesgos de seguridad del Top 10 de OWASP en codebases","Auditoría de código para problemas de criptografía y autorización"],"fr":["Automatisation des examens de code de sécurité pour les vulnérabilités","Détection des risques de sécurité du Top 10 d''OWASP dans les bases de code","Audit de code pour les problèmes de cryptographie et d''autorisation"],"de":["Automatisierung von Sicherheitscode-Reviews für Schwachstellen","Erkennung von OWASP-Top-10-Sicherheitsrisiken in Codebasen","Prüfung von Code auf Kryptographie- und Autorisierungsprobleme"],"pt":["Automatizar revisões de código de segurança para detectar vulnerabilidades","Detectar os principais riscos de segurança OWASP Top 10 nos repositórios de código","Auditar código para questões de criptografia e autorização"],"ru":["Автоматизировать обзор кода безопасности для обнаружения уязвимостей","Обнаруживать топ-10 рисков безопасности OWASP в базах кода","Провести аудит кода для проблем с криптографией и авторизацией"],"ar":["آليّة مراجعة أمان الكود للكشف عن الثغرات الأمنية","كشف المخاطر الأمنية العشر الأوائل في OWASP في قواعد بيانات الكود","مراجعة الكود للثغرات المتعلقة بالتشفير والتصريح"]},"limitations":{"en":["Requires access to specific code files or diffs for review","Limited to reporting high-confidence findings","Research scope limited to the entire codebase for confidence building"],"zh":["需要访问特定的代码文件或差异以进行审查","仅限于报告高置信度的发现","研究范围仅限于整个代码库以建立置信度"],"ja":["レビューのために特定のコードファイルまたは差分にアクセスする必要がある","高信頼性の発見のみを報告する","信頼性の構築のために研究範囲はコード全体に限定される"],"ko":["검토를 위해 특정 코드 파일이나 차이점에 액세스해야 함","높은 신뢰도 발견만 보고","신뢰도 구축을 위해 연구 범위는 전체 코드베이스로 제한"],"es":["Requiere acceso a archivos de código específicos o diffs para revisión","Limitado a la presentación de resultados de alta confianza","Alcance de la investigación limitado a la base de código completa para la creación de confianza"],"fr":["Nécessite un accès à des fichiers de code spécifiques ou des diffs pour examen","Limité à la présentation de résultats à haute confiance","Étendue de la recherche limitée à la base de code complète pour la construction de la confiance"],"de":["Erfordert Zugriff auf bestimmte Code-Dateien oder Diffs für die Überprüfung","Begrenzt auf die Meldung von Ergebnissen mit hoher Zuverlässigkeit","Forschungsumfang begrenzt auf die gesamte Codebasis für den Aufbau von Vertrauen"],"pt":["Exige acesso a arquivos de código específicos ou diffs para revisão","Limitado a relatar descobertas de alta confiança","Escopo de pesquisa limitado ao código-fonte inteiro para construção de confiança"],"ru":["Требует доступа к конкретным файлам кода или diffs для обзора","Ограничен до отчетов о высокодостоверных находках","Область исследования ограничена всем кодом для построения доверия"],"ar":["يتطلب الوصول إلى ملفات الكود الخاصة أو DIFFs من أجل المراجعة","محدود بالتقارير التي تظهر النتائج عالية الثقة","نطاق البحث محدود بالكود المصدري كله من أجل بناء الثقة"]},"version":4},"contentHash":"6d36fa39ada88c8e66fdd4c52c3b846b0f27602d49871856d4bff90cc94719e5","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":95}');
