INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/security-review', 'security-review', 'getsentry', 'skills', 'official', 'security-review getsentry skills official tag-production The security-review skill provides systematic security code review for vulnerabilities, benefiting developers and security teams. It identifies exploitable security vulnerabilities in code with high confidence reporting 代码安全审查工具提供OWASP安全审查，检测代码中的安全漏洞，包括SQL注入、XSS、认证和授权问题 AIエージェントのセキュリティレビュー機能は、OWASPチェックシートを使用してコードのセキュリティ脆弱性を検出します 코드 보안 리뷰 도구는 OWASP 보안 리뷰를 제공하여 코드의 보안 취약점을检测합니다 Security-review es una habilidad que identifica vulnerabilidades de seguridad en el código y proporciona informes de alta confianza Security-review est une compétence qui identifie les vulnérabilités de sécurité dans le code et fournit des rapports de haute confiance Security-review ist eine Fähigkeit, die Sicherheitslücken im Code erkennt und vertrauenswürdige Berichte liefert O security-review é uma ferramenta de análise de código que identifica vulnerabilidades de segurança, incluindo injeção, XSS e problemas de autenticação ИИ Агент security-review - это инструмент проверки кода, который выявляет уязвимости безопасности, включая инъекции, XSS и проблемы аутентификации أداة الأمان security-review هي أداة لمراجعة الشفرة البرمجية التي تحدد الثغرات الأمنية، بما في ذلك الحقن والكسس والمشاكل المتعلقة بالتحقق how to use security-review what is security-review security-review setup guide OWASP-compliant code audit security-review alternative security-review vs static analysis tools security-review install for AI agents systematic code review for vulnerabilities confidence-based reporting for security issues 代码安全审查 OWASP安全审查 SQL注入检测 XSS检测 认证和授权漏洞检测 代码安全审查工具 AI安全审查 Identifies vulnerabilities in code using OWASP Cheat Sheet Series Provides high confidence reporting for clear vulnerable patterns Supports systematic review of specific files, diffs, or code provided by the user Researches the entire codebase to build confidence before reporting Reports on attacker-controlled input vulnerabilities such as injection, XSS, authentication, and authorization issues Utilizes cryptography issue detection for comprehensive security audits security-review is a systematic code review skill for identifying exploitable security vulnerabilities with confidence-based reporting');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-datasets', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-datasets', 8290, 490, 95, '2026-03-06T05:28:53Z', '2026-03-06T05:34:35.621Z', 'ca8fb141e351ff7bd0ae81992d5219a23649cc7497ee012ac785f636cf233c0b', '{"id":"huggingface/skills/hugging-face-datasets","name":"hugging-face-datasets","description":{"en":"The hugging-face-datasets skill enables developers to create and manage datasets on Hugging Face Hub, supporting dataset initialization, configuration, and SQL-based querying. It complements the HF MCP server for comprehensive dataset workflows.","zh":"Hugging Face 数据集管理工具提供了数据集的创建、配置、管理和 SQL 查询等功能","ja":"Hugging Face データセット管理ツールは、データセットの作成、構成、管理、SQL クエリなどを提供","ko":"Hugging Face 데이터셋 관리도구는 데이터셋 생성, 구성, 관리 및 SQL 쿼리 등 기능을 제공","pt":"O hugging-face-datasets é uma ferramenta para criar e gerenciar conjuntos de dados no Hugging Face Hub, com recursos para inicializar repositórios e realizar consultas SQL","ru":"hugging-face-datasets - это инструмент для создания и управления наборами данных на Hugging Face Hub, с возможностями инициализации репозиториев и выполнения SQL-запросов","ar":"hugging-face-datasets هو أداة لإنشاء وإدارة مجموعات البيانات على هاب هوجينج فايس، مع ميزات لتشغيل المستودعات وتشغيل استفسارات SQL"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-datasets","description":"Create and manage datasets on Hugging Face Hub. Supports initializing repos, defining configs/system prompts, streaming row updates, and SQL-based dataset querying/transformation. Designed to work alongside HF MCP server for comprehensive dataset workflows.","bodyPreview":"# Overview\nThis skill provides tools to manage datasets on the Hugging Face Hub with a focus on creation, configuration, content management, and SQL-based data manipulation. It is designed to complement the existing Hugging Face MCP server by providing dataset editing and querying capabilities.\n\n## Integration with HF MCP Server\n- **Use HF MCP Server for**: Dataset discovery, search, and metadata retrieval\n- **Use This Skill for**: Dataset creation, content editing, SQL queries, data transformat","body":"# Overview\nThis skill provides tools to manage datasets on the Hugging Face Hub with a focus on creation, configuration, content management, and SQL-based data manipulation. It is designed to complement the existing Hugging Face MCP server by providing dataset editing and querying capabilities.\n\n## Integration with HF MCP Server\n- **Use HF MCP Server for**: Dataset discovery, search, and metadata retrieval\n- **Use This Skill for**: Dataset creation, content editing, SQL queries, data transformation, and structured data formatting\n\n# Version\n2.1.0\n\n# Dependencies\n# This skill uses PEP 723 scripts with inline dependency management\n# Scripts auto-install requirements when run with: uv run scripts/script_name.py\n\n- uv (Python package manager)\n- Getting Started: See \"Usage Instructions\" below for PEP 723 usage\n\n# Core Capabilities\n\n## 1. Dataset Lifecycle Management\n- **Initialize**: Create new dataset repositories with proper structure\n- **Configure**: Store detailed configuration including system prompts and metadata\n- **Stream Updates**: Add rows efficiently without downloading entire datasets\n\n## 2. SQL-Based Dataset Querying (NEW)\nQuery any Hugging Face dataset using DuckDB SQL via `scripts/sql_manager.py`:\n- **Direct Queries**: Run SQL on datasets using the `hf://` protocol\n- **Schema Discovery**: Describe dataset structure and column types\n- **Data Sampling**: Get random samples for exploration\n- **Aggregations**: Count, histogram, unique values analysis\n- **Transformations**: Filter, join, reshape data with SQL\n- **Export & Push**: Save results locally or push to new Hub repos\n\n## 3. Multi-Format Dataset Support\nSupports diverse dataset types through template system:\n- **Chat/Conversational**: Chat templating, multi-turn dialogues, tool usage examples\n- **Text Classification**: Sentiment analysis, intent detection, topic classification\n- **Question-Answering**: Reading comprehension, factual QA, knowledge bases\n- **Text Completion**: Language modeling, code completion, creative writing\n- **Tabular Data**: Structured data for regression/classification tasks\n- **Custom Formats**: Flexible schema definition for specialized needs\n\n## 4. Quality Assurance Features\n- **JSON Validation**: Ensures data integrity during uploads\n- **Batch Processing**: Efficient handling of large datasets\n- **Error Recovery**: Graceful handling of upload failures and conflicts\n\n# Usage Instructions\n\nThe skill includes two Python scripts that use PEP 723 inline dependency management:\n\n> **All paths are relative to the directory containing this SKILL.md\nfile.**\n> Scripts are run with: `uv run scripts/script_name.py [arguments]`\n\n- `scripts/dataset_manager.py` - Dataset creation and management\n- `scripts/sql_manager.py` - SQL-based dataset querying and transformation\n\n### Prerequisites\n- `uv` package manager installed\n- `HF_TOKEN` environment variable must be set with a Write-access token\n\n---\n\n# SQL Dataset Querying (sql_manager.py)\n\nQuery, transform, and push Hugging Face datasets using DuckDB SQL. The `hf://` protocol provides direct access to any public dataset (or private with token).\n\n## Quick Start\n\n```bash\n# Query a dataset\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT * FROM data WHERE subject=''nutrition'' LIMIT 10\"\n\n# Get dataset schema\nuv run scripts/sql_manager.py describe --dataset \"cais/mmlu\"\n\n# Sample random rows\nuv run scripts/sql_manager.py sample --dataset \"cais/mmlu\" --n 5\n\n# Count rows with filter\nuv run scripts/sql_manager.py count --dataset \"cais/mmlu\" --where \"subject=''nutrition''\"\n```\n\n## SQL Query Syntax\n\nUse `data` as the table name in your SQL - it gets replaced with the actual `hf://` path:\n\n```sql\n-- Basic select\nSELECT * FROM data LIMIT 10\n\n-- Filtering\nSELECT * FROM data WHERE subject=''nutrition''\n\n-- Aggregations\nSELECT subject, COUNT(*) as cnt FROM data GROUP BY subject ORDER BY cnt DESC\n\n-- Column selection and transformation\nSELECT question, choices[answer] AS correct_answer FROM data\n\n-- Regex matching\nSELECT * FROM data WHERE regexp_matches(question, ''nutrition|diet'')\n\n-- String functions\nSELECT regexp_replace(question, ''\\n'', '''') AS cleaned FROM data\n```\n\n## Common Operations\n\n### 1. Explore Dataset Structure\n```bash\n# Get schema\nuv run scripts/sql_manager.py describe --dataset \"cais/mmlu\"\n\n# Get unique values in column\nuv run scripts/sql_manager.py unique --dataset \"cais/mmlu\" --column \"subject\"\n\n# Get value distribution\nuv run scripts/sql_manager.py histogram --dataset \"cais/mmlu\" --column \"subject\" --bins 20\n```\n\n### 2. Filter and Transform\n```bash\n# Complex filtering with SQL\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT subject, COUNT(*) as cnt FROM data GROUP BY subject HAVING cnt > 100\"\n\n# Using transform command\nuv run scripts/sql_manager.py transform \\\n  --dataset \"cais/mmlu\" \\\n  --select \"subject, COUNT(*) as cnt\" \\\n  --group-by \"subject\" \\\n  --order-by \"cnt DESC\" \\\n  --limit 10\n```\n\n### 3. Create Subsets and Push to Hub\n```bash\n# Query and push to new dataset\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT * FROM data WHERE subject=''nutrition''\" \\\n  --push-to \"username/mmlu-nutrition-subset\" \\\n  --private\n\n# Transform and push\nuv run scripts/sql_manager.py transform \\\n  --dataset \"ibm/duorc\" \\\n  --config \"ParaphraseRC\" \\\n  --select \"question, answers\" \\\n  --where \"LENGTH(question) > 50\" \\\n  --push-to \"username/duorc-long-questions\"\n```\n\n### 4. Export to Local Files\n```bash\n# Export to Parquet\nuv run scripts/sql_manager.py export \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT * FROM data WHERE subject=''nutrition''\" \\\n  --output \"nutrition.parquet\" \\\n  --format parquet\n\n# Export to JSONL\nuv run scripts/sql_manager.py export \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT * FROM data LIMIT 100\" \\\n  --output \"sample.jsonl\" \\\n  --format jsonl\n```\n\n### 5. Working with Dataset Configs/Splits\n```bash\n# Specify config (subset)\nuv run scripts/sql_manager.py query \\\n  --dataset \"ibm/duorc\" \\\n  --config \"ParaphraseRC\" \\\n  --sql \"SELECT * FROM data LIMIT 5\"\n\n# Specify split\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --split \"test\" \\\n  --sql \"SELECT COUNT(*) FROM data\"\n\n# Query all splits\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --split \"*\" \\\n  --sql \"SELECT * FROM data LIMIT 10\"\n```\n\n### 6. Raw SQL with Full Paths\nFor complex queries or joining datasets:\n```bash\nuv run scripts/sql_manager.py raw --sql \"\n  SELECT a.*, b.* \n  FROM ''hf://datasets/dataset1@~parquet/default/train/*.parquet'' a\n  JOIN ''hf://datasets/dataset2@~parquet/default/train/*.parquet'' b\n  ON a.id = b.id\n  LIMIT 100\n\"\n```\n\n## Python API Usage\n\n```python\nfrom sql_manager import HFDatasetSQL\n\nsql = HFDatasetSQL()\n\n# Query\nresults = sql.query(\"cais/mmlu\", \"SELECT * FROM data WHERE subject=''nutrition'' LIMIT 10\")\n\n# Get schema\nschema = sql.describe(\"cais/mmlu\")\n\n# Sample\nsamples = sql.sample(\"cais/mmlu\", n=5, seed=42)\n\n# Count\ncount = sql.count(\"cais/mmlu\", where=\"subject=''nutrition''\")\n\n# Histogram\ndist = sql.histogram(\"cais/mmlu\", \"subject\")\n\n# Filter and transform\nresults = sql.filter_and_transform(\n    \"cais/mmlu\",\n    select=\"subject, COUNT(*) as cnt\",\n    group_by=\"subject\",\n    order_by=\"cnt DESC\",\n    limit=10\n)\n\n# Push to Hub\nurl = sql.push_to_hub(\n    \"cais/mmlu\",\n    \"username/nutrition-subset\",\n    sql=\"SELECT * FROM data WHERE subject=''nutrition''\",\n    private=True\n)\n\n# Export locally\nsql.export_to_parquet(\"cais/mmlu\", \"output.parquet\", sql=\"SELECT * FROM data LIMIT 100\")\n\nsql.close()\n```\n\n## HF Path Format\n\nDuckDB uses the `hf://` protocol to access datasets:\n```\nhf://datasets/{dataset_id}@{revision}/{config}/{split}/*.parquet\n```\n\nExamples:\n- `hf://datasets/cais/mmlu@~parquet/default/train/*.parquet`\n- `hf://datasets/ibm/duorc@~parquet/ParaphraseRC/test/*.parquet`\n\nThe `@~parquet` revision provides auto-converted Parquet files for any dataset format.\n\n## Useful DuckDB SQL Functions\n\n```sql\n-- String functions\nLENGTH(column)                    -- String length\nregexp_replace(col, ''\\n'', '''')     -- Regex replace\nregexp_matches(col, ''pattern'')    -- Regex match\nLOWER(col), UPPER(col)           -- Case conversion\n\n-- Array functions  \nchoices[0]                        -- Array indexing (0-based)\narray_length(choices)             -- Array length\nunnest(choices)                   -- Expand array to rows\n\n-- Aggregations\nCOUNT(*), SUM(col), AVG(col)\nGROUP BY col HAVING condition\n\n-- Sampling\nUSING SAMPLE 10                   -- Random sample\nUSING SAMPLE 10 (RESERVOIR, 42)   -- Reproducible sample\n\n-- Window functions\nROW_NUMBER() OVER (PARTITION BY col ORDER BY col2)\n```\n\n---\n\n# Dataset Creation (dataset_manager.py)\n\n### Recommended Workflow\n\n**1. Discovery (Use HF MCP Server):**\n```python\n# Use HF MCP tools to find existing datasets\nsearch_datasets(\"conversational AI training\")\nget_dataset_details(\"username/dataset-name\")\n```\n\n**2. Creation (Use This Skill):**\n```bash\n# Initialize new dataset\nuv run scripts/dataset_manager.py init --repo_id \"your-username/dataset-name\" [--private]\n\n# Configure with detailed system prompt\nuv run scripts/dataset_manager.py config --repo_id \"your-username/dataset-name\" --system_prompt \"$(cat system_prompt.txt)\"\n```\n\n**3. Content Management (Use This Skill):**\n```bash\n# Quick setup with any template\nuv run scripts/dataset_manager.py quick_setup \\\n  --repo_id \"your-username/dataset-name\" \\\n  --template classification\n\n# Add data with template validation\nuv run scripts/dataset_manager.py add_rows \\\n  --repo_id \"your-username/dataset-name\" \\\n  --template qa \\\n  --rows_json \"$(cat your_qa_data.json)\"\n```\n\n### Template-Based Data Structures\n\n**1. Chat Template (`--template chat`)**\n```json\n{\n  \"messages\": [\n    {\"role\": \"user\", \"content\": \"Natural user request\"},\n    {\"role\": \"assistant\", \"content\": \"Response with tool usage\"},\n    {\"role\": \"tool\", \"content\": \"Tool response\", \"tool_call_id\": \"call_123\"}\n  ],\n  \"scenario\": \"Description of use case\",\n  \"complexity\": \"simple|intermediate|advanced\"\n}\n```\n\n**2. Classification Template (`--template classification`)**\n```json\n{\n  \"text\": \"Input text to be classified\",\n  \"label\": \"classification_label\",\n  \"confidence\": 0.95,\n  \"metadata\": {\"domain\": \"technology\", \"language\": \"en\"}\n}\n```\n\n**3. QA Template (`--template qa`)**\n```json\n{\n  \"question\": \"What is the question being asked?\",\n  \"answer\": \"The complete answer\",\n  \"context\": \"Additional context if needed\",\n  \"answer_type\": \"factual|explanatory|opinion\",\n  \"difficulty\": \"easy|medium|hard\"\n}\n```\n\n**4. Completion Template (`--template completion`)**\n```json\n{\n  \"prompt\": \"The beginning text or context\",\n  \"completion\": \"The expected continuation\",\n  \"domain\": \"code|creative|technical|conversational\",\n  \"style\": \"description of writing style\"\n}\n```\n\n**5. Tabular Template (`--template tabular`)**\n```json\n{\n  \"columns\": [\n    {\"name\": \"feature1\", \"type\": \"numeric\", \"description\": \"First feature\"},\n    {\"name\": \"target\", \"type\": \"categorical\", \"description\": \"Target variable\"}\n  ],\n  \"data\": [\n    {\"feature1\": 123, \"target\": \"class_a\"},\n    {\"feature1\": 456, \"target\": \"class_b\"}\n  ]\n}\n```\n\n### Advanced System Prompt Template\n\nFor high-quality training data generation:\n```text\nYou are an AI assistant expert at using MCP tools effectively.\n\n## MCP SERVER DEFINITIONS\n[Define available servers and tools]\n\n## TRAINING EXAMPLE STRUCTURE\n[Specify exact JSON schema for chat templating]\n\n## QUALITY GUIDELINES\n[Detail requirements for realistic scenarios, progressive complexity, proper tool usage]\n\n## EXAMPLE CATEGORIES\n[List development workflows, debugging scenarios, data management tasks]\n```\n\n### Example Categories & Templates\n\nThe skill includes diverse training examples beyond just MCP usage:\n\n**Available Example Sets:**\n- `training_examples.json` - MCP tool usage examples (debugging, project setup, database analysis)\n- `diverse_training_examples.json` - Broader scenarios including:\n  - **Educational Chat** - Explaining programming concepts, tutorials\n  - **Git Workflows** - Feature branches, version control guidance\n  - **Code Analysis** - Performance optimization, architecture review\n  - **Content Generation** - Professional writing, creative brainstorming\n  - **Codebase Navigation** - Legacy code exploration, systematic analysis\n  - **Conversational Support** - Problem-solving, technical discussions\n\n**Using Different Example Sets:**\n```bash\n# Add MCP-focused examples\nuv run scripts/dataset_manager.py add_rows --repo_id \"your-username/dataset-name\" \\\n  --rows_json \"$(cat examples/training_examples.json)\"\n\n# Add diverse conversational examples\nuv run scripts/dataset_manager.py add_rows --repo_id \"your-username/dataset-name\" \\\n  --rows_json \"$(cat examples/diverse_training_examples.json)\"\n\n# Mix both for comprehensive training data\nuv run scripts/dataset_manager.py add_rows --repo_id \"your-username/dataset-name\" \\\n  --rows_json \"$(jq -s ''.[0] + .[1]'' examples/training_examples.json examples/diverse_training_examples.json)\"\n```\n\n### Commands Reference\n\n**List Available Templates:**\n```bash\nuv run scripts/dataset_manager.py list_templates\n```\n\n**Quick Setup (Recommended):**\n```bash\nuv run scripts/dataset_manager.py quick_setup --repo_id \"your-username/dataset-name\" --template classification\n```\n\n**Manual Setup:**\n```bash\n# Initialize repository\nuv run scripts/dataset_manager.py init --repo_id \"your-username/dataset-name\" [--private]\n\n# Configure with system prompt\nuv run scripts/dataset_manager.py config --repo_id \"your-username/dataset-name\" --system_prompt \"Your prompt here\"\n\n# Add data with validation\nuv run scripts/dataset_manager.py add_rows \\\n  --repo_id \"your-username/dataset-name\" \\\n  --template qa \\\n  --rows_json ''[{\"question\": \"What is AI?\", \"answer\": \"Artificial Intelligence...\"}]''\n```\n\n**View Dataset Statistics:**\n```bash\nuv run scripts/dataset_manager.py stats --repo_id \"your-username/dataset-name\"\n```\n\n### Error Handling\n- **Repository exists**: Script will notify and continue with configuration\n- **Invalid JSON**: Clear error message with parsing details\n- **Network issues**: Automatic retry for transient failures\n- **Token permissions**: Validation before operations begin\n\n---\n\n# Combined Workflow Examples\n\n## Example 1: Create Training Subset from Existing Dataset\n```bash\n# 1. Explore the source dataset\nuv run scripts/sql_manager.py describe --dataset \"cais/mmlu\"\nuv run scripts/sql_manager.py histogram --dataset \"cais/mmlu\" --column \"subject\"\n\n# 2. Query and create subset\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT * FROM data WHERE subject IN (''nutrition'', ''anatomy'', ''clinical_knowledge'')\" \\\n  --push-to \"username/mmlu-medical-subset\" \\\n  --private\n```\n\n## Example 2: Transform and Reshape Data\n```bash\n# Transform MMLU to QA format with correct answers extracted\nuv run scripts/sql_manager.py query \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT question, choices[answer] as correct_answer, subject FROM data\" \\\n  --push-to \"username/mmlu-qa-format\"\n```\n\n## Example 3: Merge Multiple Dataset Splits\n```bash\n# Export multiple splits and combine\nuv run scripts/sql_manager.py export \\\n  --dataset \"cais/mmlu\" \\\n  --split \"*\" \\\n  --output \"mmlu_all.parquet\"\n```\n\n## Example 4: Quality Filtering\n```bash\n# Filter for high-quality examples\nuv run scripts/sql_manager.py query \\\n  --dataset \"squad\" \\\n  --sql \"SELECT * FROM data WHERE LENGTH(context) > 500 AND LENGTH(question) > 20\" \\\n  --push-to \"username/squad-filtered\"\n```\n\n## Example 5: Create Custom Training Dataset\n```bash\n# 1. Query source data\nuv run scripts/sql_manager.py export \\\n  --dataset \"cais/mmlu\" \\\n  --sql \"SELECT question, subject FROM data WHERE subject=''nutrition''\" \\\n  --output \"nutrition_source.jsonl\" \\\n  --format jsonl\n\n# 2. Process with your pipeline (add answers, format, etc.)\n\n# 3. Push processed data\nuv run scripts/dataset_manager.py init --repo_id \"username/nutrition-training\"\nuv run scripts/dataset_manager.py add_rows \\\n  --repo_id \"username/nutrition-training\" \\\n  --template qa \\\n  --rows_json \"$(cat processed_data.json)\"\n```\n"},"category":"official","lastSynced":"2026-03-06T05:34:35.621Z","seo":{"title":{"en":"hugging-face-datasets: Comprehensive Dataset Management f...","zh":"Hugging Face 数据集管理工具 Setup Guide","ja":"Hugging Face データセット管理ツールのベストプラクティス","ko":"Hugging Face 데이터셋 관리도구 사용자 가이드","pt":"Guia de Configuração do hugging-face-datasets para Desenv...","ru":"Настройка hugging-face-datasets: Руководство для разработ...","ar":"دليل إعداد hugging-face-datasets لمنشئي الأدوات الذكية"},"description":{"en":"Unlock efficient dataset workflows with hugging-face-datasets. Discover how to create, manage, and query datasets on Hugging Face Hub. Get started now!","zh":"使用 Hugging Face 数据集管理工具，轻松创建、配置和管理数据集，并支持 SQL 查询和数据转换","ja":"Hugging Face データセット管理ツールを使用して、データセットの作成、構成、管理を簡単に行い、SQL クエリとデータ変換をサポート","ko":"Hugging Face 데이터셋 관리도구를 사용하여 데이터셋을 생성, 구성 및 관리하고 SQL 쿼리 및 데이터 변환을 지원","pt":"Aprenda a criar e gerenciar conjuntos de dados no Hugging Face Hub com o hugging-face-datasets. Descubra como inicializar repositórios e realizar consultas SQL","ru":"Узнайте, как создавать и управлять наборами данных на Hugging Face Hub с помощью hugging-face-datasets. Откройте для себя, как инициализировать репозитории и...","ar":"تعلم كيفية إنشاء وإدارة مجموعات البيانات على هاب هوجينج فايس باستخدام hugging-face-datasets. اكتشف كيفية 초기ية المستودعات وتشغيل استفسارات SQL"},"definition":{"en":"hugging-face-datasets is a skill designed to manage datasets on Hugging Face Hub, providing tools for creation, configuration, and SQL-based data manipulation.","zh":"Hugging Face 数据集管理工具是一种用于创建、管理和查询数据集的 AI エージェント","ja":"Hugging Face データセット管理ツールは、データセットの作成、管理、クエリを行う AI エージェントの一種","ko":"Hugging Face 데이터셋 관리도구는 데이터셋을 생성, 관리 및 쿼리하는 AI 도구","pt":"O que é hugging-face-datasets? É uma ferramenta para gerenciar conjuntos de dados no Hugging Face Hub","ru":"Что такое hugging-face-datasets? Это инструмент для управления наборами данных на Hugging Face Hub","ar":"ما هو hugging-face-datasets؟ هو أداة لإدارة مجموعات البيانات على هاب هوجينج فايس"},"features":{"en":["Initializes repos on Hugging Face Hub","Defines configs and system prompts for datasets","Supports streaming row updates for efficient data management","Enables SQL-based dataset querying and transformation","Integrates with HF MCP server for comprehensive dataset workflows","Allows for dataset editing and querying capabilities"],"zh":["支持数据集的创建和配置","提供 SQL 查询和数据转换功能","支持数据集的流式更新","集成 Hugging Face MCP 服务器","支持数据集的元数据管理","提供数据集的版本控制功能"],"ja":["データセットの作成と構成をサポート","SQL クエリとデータ変換機能を提供","データセットのストリーミング更新をサポート","Hugging Face MCP サーバーと統合","データセットのメタデータ管理をサポート","データセットのバージョン管理機能を提供"],"ko":["데이터셋 생성 및 구성 지원","SQL 쿼리 및 데이터 변환 기능 제공","데이터셋의 스트리밍 업데이트 지원","Hugging Face MCP 서버와 통합","데이터셋의 메타데이터 관리 지원","데이터셋의 버전 관리 기능 제공"],"pt":["Criação e gerenciamento de conjuntos de dados no Hugging Face Hub","Inicialização de repositórios","Definição de configurações e prompts de sistema","Transmissão de atualizações de linhas","Consultas SQL para transformação de dados"],"ru":["Создание и управление наборами данных на Hugging Face Hub","Инициализация репозиториев","Определение конфигураций и системных промтов","Передача обновлений строк","SQL-запросы для трансформации данных"],"ar":["إنشاء وإدارة مجموعات البيانات على هاب هوجينج فايس","تشغيل المستودعات","تحديد التهيئة والتحفيزات النظام","بث تحديثات السطور","استفسارات SQL لتحويل البيانات"]},"keywords":{"en":["hugging-face-datasets setup guide","how to use hugging-face-datasets","hugging-face-datasets vs dataset management tools","hugging-face-datasets install","what is hugging-face-datasets","hugging-face-datasets alternative","hugging-face-datasets tutorial","hugging-face-datasets documentation","hugging-face-datasets example use cases"],"zh":["Hugging Face 数据集管理","AI 数据集工具","数据集创建和配置","SQL 查询和数据转换","数据集管理和查询","Hugging Face MCP 服务器","数据集版本控制","数据集元数据管理","AIエージェント"],"ja":["Hugging Face データセット管理","AI データセットツール","データセットの作成と構成","SQL クエリとデータ変換","データセット管理とクエリ","Hugging Face MCP サーバー","データセットのバージョン管理","データセットのメタデータ管理","AI エージェント"],"ko":["Hugging Face 데이터셋 관리","AI 데이터셋 도구","데이터셋 생성과 구성","SQL 쿼리와 데이터 변환","데이터셋 관리와 쿼리","Hugging Face MCP 서버","데이터셋 버전 관리","데이터셋 메타데이터 관리","AI 도구"],"pt":["hugging face datasets","criar conjunto de dados","gerenciar conjunto de dados","Hugging Face Hub","consultas SQL","desenvolvedores de IA","ferramentas de IA","hugging face datasets tutorial"],"ru":["hugging face datasets","создать набор данных","управлять набором данных","Hugging Face Hub","SQL-запросы","разработчики ИИ","инструменты ИИ","hugging face datasets руководство"],"ar":["hugging face datasets","إنشاء مجموعة بيانات","إدارة مجموعة بيانات","هاب هوجينج فايس","استفسارات SQL","مطوّرو الأدوات الذكية","أدوات الذكاء الاصطناعي","دليل hugging face datasets"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Data Science Agents requiring advanced dataset management and SQL querying capabilities on Hugging Face Hub.","zh":"适用于需要高级数据集管理和在 Hugging Face Hub 上进行 SQL 查询的 Data Science Agents。","ja":"Hugging Face Hub で高度なデータセット管理と SQL クエリ機能を必要とする Data Science Agents に最適です。","ko":"Hugging Face Hub에서 고급 데이터셋 관리 및 SQL 쿼리 기능을 필요로 하는 Data Science Agents에 적합합니다.","es":"Ideal para Agentes de Ciencia de Datos que requieren una gestión de conjunto de datos avanzada y capacidades de consulta SQL en Hugging Face Hub.","fr":"Idéal pour les agents de science des données nécessitant une gestion de jeu de données avancée et des capacités de requête SQL sur Hugging Face Hub.","de":"Ideal für Data Science-Agents, die eine erweiterte Datenmanagement- und SQL-Abfragefunktion auf Hugging Face Hub benötigen.","pt":"Ideal para Agentes de Ciência de Dados que exigem gerenciamento avançado de conjuntos de dados e capacidades de consulta SQL no Hugging Face Hub.","ru":"Идеально подходит для агентов Data Science, требующих продвинутого управления наборами данных и возможностей запросов SQL на Hugging Face Hub.","ar":"مثالية للوكلاء العلميين الذين يحتاجون إلى إدارة متقدمة للبيانات وميزات استعلام SQL على Hugging Face Hub."},"recommendation":{"en":"Empowers agents to create and manage datasets on Hugging Face Hub, supporting dataset initialization, configuration, and SQL-based data manipulation, complementing the HF MCP server for comprehensive dataset workflows.","zh":"赋予代理创建和管理 Hugging Face Hub 上的数据集的能力，支持数据集初始化、配置和基于 SQL 的数据操作，补充 HF MCP 服务器以实现全面数据集工作流。","ja":"エージェントが Hugging Face Hub 上でデータセットを作成および管理できるようにし、データセットの初期化、構成、SQL ベースのデータ操作をサポートし、HF MCP サーバーとともに包括的なデータセットのワークフローを実現します。","ko":"에이전트가 Hugging Face Hub에서 데이터셋을 생성하고 관리할 수 있도록 하며, 데이터셋 초기화, 구성 및 SQL 기반 데이터 조작을 지원하여 HF MCP 서버와 함께 포괄적인 데이터셋 워크플ロー에 기여합니다.","es":"Habilita a los agentes a crear y gestionar conjuntos de datos en Hugging Face Hub, admitiendo la inicialización, configuración y manipulación de datos basada en SQL, complementando el servidor HF MCP para flujos de trabajo de conjunto de datos integrales.","fr":"Permet aux agents de créer et de gérer des jeux de données sur Hugging Face Hub, en prenant en charge l''initialisation, la configuration et la manipulation de données basée sur SQL, complétant le serveur HF MCP pour des flux de travail de jeu de données complets.","de":"Ermächtigt die Agents, Datenmengen auf Hugging Face Hub zu erstellen und zu verwalten, unterstützt die Initialisierung, Konfiguration und SQL-basierte Datenmanipulation, ergänzt den HF MCP-Server für umfassende Datenmengen-Workflows.","pt":"Habilita os agentes a criar e gerenciar conjuntos de dados no Hugging Face Hub, com suporte à inicialização, configuração e manipulação de dados baseada em SQL, complementando o servidor HF MCP para fluxos de trabalho de conjuntos de dados abrangentes.","ru":"Наделяет агентов возможностью создавать и управлять наборами данных на Hugging Face Hub, поддерживая инициализацию, конфигурацию и манипуляцию данными на основе SQL, дополняя сервер HF MCP для комплексных рабочих процессов наборов данных.","ar":"تمكّن الوكلاء من إنشاء وإدارة مجموعات البيانات على Hugging Face Hub، مع دعم لتخصيص الإعدادات والتهيئة والتعامل مع البيانات بالاستعلامات SQL، مما يكمّل الخادم HF MCP من أجل سير عمل شاملة لمجموعات البيانات."},"useCases":{"en":["Initializing and configuring datasets on Hugging Face Hub","Streaming row updates for dynamic dataset management","Executing SQL-based queries for dataset transformation and analysis"],"zh":["在 Hugging Face Hub 上初始化和配置数据集","流式行更新用于动态数据集管理","执行基于 SQL 的查询用于数据集转换和分析"],"ja":["Hugging Face Hub 上でデータセットを初期化および構成する","動的なデータセット管理のための行のストリーミング更新","データセットの変換および分析のための SQL ベースのクエリの実行"],"ko":["Hugging Face Hub에서 데이터셋 초기화 및 구성","동적 데이터셋 관리를 위한 행 업데이트 스트리밍","데이터셋 변환 및 분석을 위한 SQL 기반 쿼리 실행"],"es":["Inicializar y configurar conjuntos de datos en Hugging Face Hub","Transmitir actualizaciones de filas para la gestión dinámica de conjuntos de datos","Ejecutar consultas basadas en SQL para la transformación y análisis de conjuntos de datos"],"fr":["Initialiser et configurer des jeux de données sur Hugging Face Hub","Diffuser des mises à jour de lignes pour la gestion dynamique des jeux de données","Exécuter des requêtes basées sur SQL pour la transformation et l''analyse des jeux de données"],"de":["Initialisieren und Konfigurieren von Datenmengen auf Hugging Face Hub","Zeilenaktualisierungen streamen für dynamisches Datenmengen-Management","SQL-basierte Abfragen ausführen für Datenmengen-Transformation und -Analyse"],"pt":["Inicializando e configurando conjuntos de dados no Hugging Face Hub","Transmitindo atualizações de linha para gerenciamento dinâmico de conjuntos de dados","Executando consultas baseadas em SQL para transformação e análise de conjuntos de dados"],"ru":["Инициализация и конфигурация наборов данных на Hugging Face Hub","Потоковая передача обновлений строк для динамического управления наборами данных","Выполнение запросов на основе SQL для трансформации и анализа наборов данных"],"ar":["تخصيص إعدادات مجموعات البيانات وتهيئتها على Hugging Face Hub","بثّ تحديثات السطور من أجل إدارة ديناميكية لمجموعات البيانات","تنفيذ استعلامات مبنية على SQL من أجل تحويل وتحليل مجموعات البيانات"]},"limitations":{"en":["Requires Hugging Face Hub account and HF MCP server setup","Designed specifically for Hugging Face datasets and workflows"],"zh":["需要 Hugging Face Hub 账户和 HF MCP 服务器设置","专门为 Hugging Face 数据集和工作流设计"],"ja":["Hugging Face Hub アカウントと HF MCP サーバーの設定が必要","Hugging Face データセットとワークフロー専用に設計"],"ko":["Hugging Face Hub 계정 및 HF MCP 서버 설정이 필요","Hugging Face 데이터셋 및 워크플로우専용으로 설계"],"es":["Requiere una cuenta de Hugging Face Hub y configuración del servidor HF MCP","Diseñado específicamente para conjuntos de datos y flujos de trabajo de Hugging Face"],"fr":["Nécessite un compte Hugging Face Hub et une configuration du serveur HF MCP","Conçu spécifiquement pour les jeux de données et les flux de travail de Hugging Face"],"de":["Benötigt ein Hugging Face Hub-Konto und HF MCP-Server-Setup","Speziell für Hugging Face-Datenmengen und -Workflows konzipiert"],"pt":["Exige conta no Hugging Face Hub e configuração do servidor HF MCP","Projetado especificamente para conjuntos de dados e fluxos de trabalho do Hugging Face"],"ru":["Требует учетной записи Hugging Face Hub и настройки сервера HF MCP","Разработан специально для наборов данных и рабочих процессов Hugging Face"],"ar":["يتطلب حسابًا على Hugging Face Hub وإعداد الخادم HF MCP","صُمّم خصيصًا لمجموعات البيانات وسير العمل على منصة Hugging Face"]},"version":4},"contentHash":"ca8fb141e351ff7bd0ae81992d5219a23649cc7497ee012ac785f636cf233c0b","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":95}');
