INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-datasets', 'hugging-face-datasets', 'huggingface', 'skills', 'official', 'hugging-face-datasets huggingface skills official The hugging-face-datasets skill enables developers to create and manage datasets on Hugging Face Hub, supporting dataset initialization, configuration, and SQL-based querying. It complements the HF MCP server for comprehensive dataset workflows. Hugging Face 数据集管理工具提供了数据集的创建、配置、管理和 SQL 查询等功能 Hugging Face データセット管理ツールは、データセットの作成、構成、管理、SQL クエリなどを提供 Hugging Face 데이터셋 관리도구는 데이터셋 생성, 구성, 관리 및 SQL 쿼리 등 기능을 제공 O hugging-face-datasets é uma ferramenta para criar e gerenciar conjuntos de dados no Hugging Face Hub, com recursos para inicializar repositórios e realizar consultas SQL hugging-face-datasets - это инструмент для создания и управления наборами данных на Hugging Face Hub, с возможностями инициализации репозиториев и выполнения SQL-запросов hugging-face-datasets هو أداة لإنشاء وإدارة مجموعات البيانات على هاب هوجينج فايس، مع ميزات لتشغيل المستودعات وتشغيل استفسارات SQL hugging-face-datasets setup guide how to use hugging-face-datasets hugging-face-datasets vs dataset management tools hugging-face-datasets install what is hugging-face-datasets hugging-face-datasets alternative hugging-face-datasets tutorial hugging-face-datasets documentation hugging-face-datasets example use cases Hugging Face 数据集管理 AI 数据集工具 数据集创建和配置 SQL 查询和数据转换 数据集管理和查询 Hugging Face MCP 服务器 数据集版本控制 数据集元数据管理 AIエージェント Initializes repos on Hugging Face Hub Defines configs and system prompts for datasets Supports streaming row updates for efficient data management Enables SQL-based dataset querying and transformation Integrates with HF MCP server for comprehensive dataset workflows Allows for dataset editing and querying capabilities hugging-face-datasets is a skill designed to manage datasets on Hugging Face Hub, providing tools for creation, configuration, and SQL-based data manipulation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-evaluation', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-evaluation', 8290, 490, 95, '2026-03-06T05:28:53Z', '2026-03-06T05:35:51.966Z', 'a3acc51eb6df217fc6eb781f2fd58bc401d43864ae3a4b80bfd4fb62775a99d1', '{"id":"huggingface/skills/hugging-face-evaluation","name":"hugging-face-evaluation","description":{"en":"The hugging-face-evaluation skill provides tools for adding evaluation results to Hugging Face model cards, benefiting AI model developers. It supports extracting eval tables and importing benchmark scores.","zh":"Hugging Face 评估工具提供了添加结构化评估结果到 Hugging Face 模型卡的功能，支持从 README 中提取评估表、导入 Artificial Analysis API 分数和运行自定义模型评估","ja":"Hugging Face 評価ツールは、Hugging Face モデルカードに構造化された評価結果を追加する機能を提供します。README から評価表を抽出して Artificial Analysis API スコアをインポートする機能と、カスタム モデル評価を実行する機能をサポートします","ko":"Hugging Face 평가 도구는 Hugging Face 모델 카드에 구조화된 평가 결과를 추가하는 기능을 제공합니다. README에서 평가 표를 추출하고 Artificial Analysis API 점수를 가져오고 사용자 지정 모델 평가를 실행하는 기능을 지원합니다","es":"La habilidad hugging-face-evaluation permite agregar resultados de evaluación estructurados a las tarjetas de modelo de Hugging Face, admitiendo la extracción de tablas de evaluación de contenido README y la importación de puntuaciones de benchmark de Artificial Analysis","fr":"La compétence hugging-face-evaluation permet d''ajouter des résultats d''évaluation structurés aux cartes de modèle Hugging Face, prenant en charge l''extraction de tables d''évaluation de contenu README et l''importation de scores de benchmark d''Artificial Analysis","de":"Die Fähigkeit hugging-face-evaluation ermöglicht das Hinzufügen von strukturierten Bewertungsergebnissen zu Hugging Face-Modellkarten, einschließlich der Extraktion von Bewertungstabellen aus README-Inhalten und der Import von Benchmark-Scores von Artificial Analysis","pt":"O skill de avaliação do Hugging Face permite adicionar resultados de avaliação estruturados a cartões de modelo, suportando extração de tabelas de avaliação de conteúdo README e importação de pontuações de benchmark do Artificial Analysis API","ru":"ИИ Агент оценки Hugging Face позволяет добавлять структурированные результаты оценки в карты моделей, поддерживая извлечение таблиц оценки из содержимого README и импорт баллов бенчмарка из API Artificial Analysis","ar":"سمات التقييم في هوجينج فيس تسمح بإضافة نتائج تقييم منظم إلى بطاقات النموذج، وتدعم استخراج جداول التقييم من محتوى ملف README واستيراد درجات التقييم من واجهة برمجة تطبيقات التحليل الاصطناعي"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-evaluation","description":"Add and manage evaluation results in Hugging Face model cards. Supports extracting eval tables from README content, importing scores from Artificial Analysis API, and running custom model evaluations with vLLM/lighteval. Works with the model-index metadata format.","bodyPreview":"# Overview\nThis skill provides tools to add structured evaluation results to Hugging Face model cards. It supports multiple methods for adding evaluation data:\n- Extracting existing evaluation tables from README content\n- Importing benchmark scores from Artificial Analysis\n- Running custom model evaluations with vLLM or accelerate backends (lighteval/inspect-ai)\n\n## Integration with HF Ecosystem\n- **Model Cards**: Updates model-index metadata for leaderboard integration\n- **Artificial Analysis**","body":"# Overview\nThis skill provides tools to add structured evaluation results to Hugging Face model cards. It supports multiple methods for adding evaluation data:\n- Extracting existing evaluation tables from README content\n- Importing benchmark scores from Artificial Analysis\n- Running custom model evaluations with vLLM or accelerate backends (lighteval/inspect-ai)\n\n## Integration with HF Ecosystem\n- **Model Cards**: Updates model-index metadata for leaderboard integration\n- **Artificial Analysis**: Direct API integration for benchmark imports\n- **Papers with Code**: Compatible with their model-index specification\n- **Jobs**: Run evaluations directly on Hugging Face Jobs with `uv` integration\n- **vLLM**: Efficient GPU inference for custom model evaluation\n- **lighteval**: HuggingFace''s evaluation library with vLLM/accelerate backends\n- **inspect-ai**: UK AI Safety Institute''s evaluation framework\n\n# Version\n1.3.0\n\n# Dependencies\n\n## Core Dependencies\n- huggingface_hub>=0.26.0\n- markdown-it-py>=3.0.0\n- python-dotenv>=1.2.1\n- pyyaml>=6.0.3\n- requests>=2.32.5\n- re (built-in)\n\n## Inference Provider Evaluation\n- inspect-ai>=0.3.0\n- inspect-evals\n- openai\n\n## vLLM Custom Model Evaluation (GPU required)\n- lighteval[accelerate,vllm]>=0.6.0\n- vllm>=0.4.0\n- torch>=2.0.0\n- transformers>=4.40.0\n- accelerate>=0.30.0\n\nNote: vLLM dependencies are installed automatically via PEP 723 script headers when using `uv run`.\n\n# IMPORTANT: Using This Skill\n\n## ⚠️ CRITICAL: Check for Existing PRs Before Creating New Ones\n\n**Before creating ANY pull request with `--create-pr`, you MUST check for existing open PRs:**\n\n```bash\nuv run scripts/evaluation_manager.py get-prs --repo-id \"username/model-name\"\n```\n\n**If open PRs exist:**\n1. **DO NOT create a new PR** - this creates duplicate work for maintainers\n2. **Warn the user** that open PRs already exist\n3. **Show the user** the existing PR URLs so they can review them\n4. Only proceed if the user explicitly confirms they want to create another PR\n\nThis prevents spamming model repositories with duplicate evaluation PRs.\n\n---\n\n> **All paths are relative to the directory containing this SKILL.md\nfile.**\n> Before running any script, first `cd` to that directory or use the full\npath.\n\n\n**Use `--help` for the latest workflow guidance.** Works with plain Python or `uv run`:\n```bash\nuv run scripts/evaluation_manager.py --help\nuv run scripts/evaluation_manager.py inspect-tables --help\nuv run scripts/evaluation_manager.py extract-readme --help\n```\nKey workflow (matches CLI help):\n\n1) `get-prs` → check for existing open PRs first\n2) `inspect-tables` → find table numbers/columns  \n3) `extract-readme --table N` → prints YAML by default  \n4) add `--apply` (push) or `--create-pr` to write changes\n\n# Core Capabilities\n\n## 1. Inspect and Extract Evaluation Tables from README\n- **Inspect Tables**: Use `inspect-tables` to see all tables in a README with structure, columns, and sample rows\n- **Parse Markdown Tables**: Accurate parsing using markdown-it-py (ignores code blocks and examples)\n- **Table Selection**: Use `--table N` to extract from a specific table (required when multiple tables exist)\n- **Format Detection**: Recognize common formats (benchmarks as rows, columns, or comparison tables with multiple models)\n- **Column Matching**: Automatically identify model columns/rows; prefer `--model-column-index` (index from inspect output). Use `--model-name-override` only with exact column header text.\n- **YAML Generation**: Convert selected table to model-index YAML format\n- **Task Typing**: `--task-type` sets the `task.type` field in model-index output (e.g., `text-generation`, `summarization`)\n\n## 2. Import from Artificial Analysis\n- **API Integration**: Fetch benchmark scores directly from Artificial Analysis\n- **Automatic Formatting**: Convert API responses to model-index format\n- **Metadata Preservation**: Maintain source attribution and URLs\n- **PR Creation**: Automatically create pull requests with evaluation updates\n\n## 3. Model-Index Management\n- **YAML Generation**: Create properly formatted model-index entries\n- **Merge Support**: Add evaluations to existing model cards without overwriting\n- **Validation**: Ensure compliance with Papers with Code specification\n- **Batch Operations**: Process multiple models efficiently\n\n## 4. Run Evaluations on HF Jobs (Inference Providers)\n- **Inspect-AI Integration**: Run standard evaluations using the `inspect-ai` library\n- **UV Integration**: Seamlessly run Python scripts with ephemeral dependencies on HF infrastructure\n- **Zero-Config**: No Dockerfiles or Space management required\n- **Hardware Selection**: Configure CPU or GPU hardware for the evaluation job\n- **Secure Execution**: Handles API tokens safely via secrets passed through the CLI\n\n## 5. Run Custom Model Evaluations with vLLM (NEW)\n\n⚠️ **Important:** This approach is only possible on devices with `uv` installed and sufficient GPU memory.\n**Benefits:** No need to use `hf_jobs()` MCP tool, can run scripts directly in terminal\n**When to use:** User working in local device directly  when GPU is available\n\n### Before running the script\n\n- check the script path\n- check uv is installed\n- check gpu is available with `nvidia-smi`\n\n### Running the script\n\n```bash\nuv run scripts/train_sft_example.py\n```\n### Features\n\n- **vLLM Backend**: High-performance GPU inference (5-10x faster than standard HF methods)\n- **lighteval Framework**: HuggingFace''s evaluation library with Open LLM Leaderboard tasks\n- **inspect-ai Framework**: UK AI Safety Institute''s evaluation library\n- **Standalone or Jobs**: Run locally or submit to HF Jobs infrastructure\n\n# Usage Instructions\n\nThe skill includes Python scripts in `scripts/` to perform operations.\n\n### Prerequisites\n- Preferred: use `uv run` (PEP 723 header auto-installs deps)\n- Or install manually: `pip install huggingface-hub markdown-it-py python-dotenv pyyaml requests`\n- Set `HF_TOKEN` environment variable with Write-access token\n- For Artificial Analysis: Set `AA_API_KEY` environment variable\n- `.env` is loaded automatically if `python-dotenv` is installed\n\n### Method 1: Extract from README (CLI workflow)\n\nRecommended flow (matches `--help`):\n```bash\n# 1) Inspect tables to get table numbers and column hints\nuv run scripts/evaluation_manager.py inspect-tables --repo-id \"username/model\"\n\n# 2) Extract a specific table (prints YAML by default)\nuv run scripts/evaluation_manager.py extract-readme \\\n  --repo-id \"username/model\" \\\n  --table 1 \\\n  [--model-column-index <column index shown by inspect-tables>] \\\n  [--model-name-override \"<column header/model name>\"]  # use exact header text if you can''t use the index\n\n# 3) Apply changes (push or PR)\nuv run scripts/evaluation_manager.py extract-readme \\\n  --repo-id \"username/model\" \\\n  --table 1 \\\n  --apply       # push directly\n# or\nuv run scripts/evaluation_manager.py extract-readme \\\n  --repo-id \"username/model\" \\\n  --table 1 \\\n  --create-pr   # open a PR\n```\n\nValidation checklist:\n- YAML is printed by default; compare against the README table before applying.\n- Prefer `--model-column-index`; if using `--model-name-override`, the column header text must be exact.\n- For transposed tables (models as rows), ensure only one row is extracted.\n\n### Method 2: Import from Artificial Analysis\n\nFetch benchmark scores from Artificial Analysis API and add them to a model card.\n\n**Basic Usage:**\n```bash\nAA_API_KEY=\"your-api-key\" uv run scripts/evaluation_manager.py import-aa \\\n  --creator-slug \"anthropic\" \\\n  --model-name \"claude-sonnet-4\" \\\n  --repo-id \"username/model-name\"\n```\n\n**With Environment File:**\n```bash\n# Create .env file\necho \"AA_API_KEY=your-api-key\" >> .env\necho \"HF_TOKEN=your-hf-token\" >> .env\n\n# Run import\nuv run scripts/evaluation_manager.py import-aa \\\n  --creator-slug \"anthropic\" \\\n  --model-name \"claude-sonnet-4\" \\\n  --repo-id \"username/model-name\"\n```\n\n**Create Pull Request:**\n```bash\nuv run scripts/evaluation_manager.py import-aa \\\n  --creator-slug \"anthropic\" \\\n  --model-name \"claude-sonnet-4\" \\\n  --repo-id \"username/model-name\" \\\n  --create-pr\n```\n\n### Method 3: Run Evaluation Job\n\nSubmit an evaluation job on Hugging Face infrastructure using the `hf jobs uv run` CLI.\n\n**Direct CLI Usage:**\n```bash\nHF_TOKEN=$HF_TOKEN \\\nhf jobs uv run hf-evaluation/scripts/inspect_eval_uv.py \\\n  --flavor cpu-basic \\\n  --secret HF_TOKEN=$HF_TOKEN \\\n  -- --model \"meta-llama/Llama-2-7b-hf\" \\\n     --task \"mmlu\"\n```\n\n**GPU Example (A10G):**\n```bash\nHF_TOKEN=$HF_TOKEN \\\nhf jobs uv run hf-evaluation/scripts/inspect_eval_uv.py \\\n  --flavor a10g-small \\\n  --secret HF_TOKEN=$HF_TOKEN \\\n  -- --model \"meta-llama/Llama-2-7b-hf\" \\\n     --task \"gsm8k\"\n```\n\n**Python Helper (optional):**\n```bash\nuv run scripts/run_eval_job.py \\\n  --model \"meta-llama/Llama-2-7b-hf\" \\\n  --task \"mmlu\" \\\n  --hardware \"t4-small\"\n```\n\n### Method 4: Run Custom Model Evaluation with vLLM\n\nEvaluate custom HuggingFace models directly on GPU using vLLM or accelerate backends. These scripts are **separate from inference provider scripts** and run models locally on the job''s hardware.\n\n#### When to Use vLLM Evaluation (vs Inference Providers)\n\n| Feature | vLLM Scripts | Inference Provider Scripts |\n|---------|-------------|---------------------------|\n| Model access | Any HF model | Models with API endpoints |\n| Hardware | Your GPU (or HF Jobs GPU) | Provider''s infrastructure |\n| Cost | HF Jobs compute cost | API usage fees |\n| Speed | vLLM optimized | Depends on provider |\n| Offline | Yes (after download) | No |\n\n#### Option A: lighteval with vLLM Backend\n\nlighteval is HuggingFace''s evaluation library, supporting Open LLM Leaderboard tasks.\n\n**Standalone (local GPU):**\n```bash\n# Run MMLU 5-shot with vLLM\nuv run scripts/lighteval_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-1B \\\n  --tasks \"leaderboard|mmlu|5\"\n\n# Run multiple tasks\nuv run scripts/lighteval_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-1B \\\n  --tasks \"leaderboard|mmlu|5,leaderboard|gsm8k|5\"\n\n# Use accelerate backend instead of vLLM\nuv run scripts/lighteval_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-1B \\\n  --tasks \"leaderboard|mmlu|5\" \\\n  --backend accelerate\n\n# Chat/instruction-tuned models\nuv run scripts/lighteval_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-1B-Instruct \\\n  --tasks \"leaderboard|mmlu|5\" \\\n  --use-chat-template\n```\n\n**Via HF Jobs:**\n```bash\nhf jobs uv run scripts/lighteval_vllm_uv.py \\\n  --flavor a10g-small \\\n  --secrets HF_TOKEN=$HF_TOKEN \\\n  -- --model meta-llama/Llama-3.2-1B \\\n     --tasks \"leaderboard|mmlu|5\"\n```\n\n**lighteval Task Format:**\nTasks use the format `suite|task|num_fewshot`:\n- `leaderboard|mmlu|5` - MMLU with 5-shot\n- `leaderboard|gsm8k|5` - GSM8K with 5-shot\n- `lighteval|hellaswag|0` - HellaSwag zero-shot\n- `leaderboard|arc_challenge|25` - ARC-Challenge with 25-shot\n\n**Finding Available Tasks:**\nThe complete list of available lighteval tasks can be found at:\nhttps://github.com/huggingface/lighteval/blob/main/examples/tasks/all_tasks.txt\n\nThis file contains all supported tasks in the format `suite|task|num_fewshot|0` (the trailing `0` is a version flag and can be ignored). Common suites include:\n- `leaderboard` - Open LLM Leaderboard tasks (MMLU, GSM8K, ARC, HellaSwag, etc.)\n- `lighteval` - Additional lighteval tasks\n- `bigbench` - BigBench tasks\n- `original` - Original benchmark tasks\n\nTo use a task from the list, extract the `suite|task|num_fewshot` portion (without the trailing `0`) and pass it to the `--tasks` parameter. For example:\n- From file: `leaderboard|mmlu|0` → Use: `leaderboard|mmlu|0` (or change to `5` for 5-shot)\n- From file: `bigbench|abstract_narrative_understanding|0` → Use: `bigbench|abstract_narrative_understanding|0`\n- From file: `lighteval|wmt14:hi-en|0` → Use: `lighteval|wmt14:hi-en|0`\n\nMultiple tasks can be specified as comma-separated values: `--tasks \"leaderboard|mmlu|5,leaderboard|gsm8k|5\"`\n\n#### Option B: inspect-ai with vLLM Backend\n\ninspect-ai is the UK AI Safety Institute''s evaluation framework.\n\n**Standalone (local GPU):**\n```bash\n# Run MMLU with vLLM\nuv run scripts/inspect_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-1B \\\n  --task mmlu\n\n# Use HuggingFace Transformers backend\nuv run scripts/inspect_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-1B \\\n  --task mmlu \\\n  --backend hf\n\n# Multi-GPU with tensor parallelism\nuv run scripts/inspect_vllm_uv.py \\\n  --model meta-llama/Llama-3.2-70B \\\n  --task mmlu \\\n  --tensor-parallel-size 4\n```\n\n**Via HF Jobs:**\n```bash\nhf jobs uv run scripts/inspect_vllm_uv.py \\\n  --flavor a10g-small \\\n  --secrets HF_TOKEN=$HF_TOKEN \\\n  -- --model meta-llama/Llama-3.2-1B \\\n     --task mmlu\n```\n\n**Available inspect-ai Tasks:**\n- `mmlu` - Massive Multitask Language Understanding\n- `gsm8k` - Grade School Math\n- `hellaswag` - Common sense reasoning\n- `arc_challenge` - AI2 Reasoning Challenge\n- `truthfulqa` - TruthfulQA benchmark\n- `winogrande` - Winograd Schema Challenge\n- `humaneval` - Code generation\n\n#### Option C: Python Helper Script\n\nThe helper script auto-selects hardware and simplifies job submission:\n\n```bash\n# Auto-detect hardware based on model size\nuv run scripts/run_vllm_eval_job.py \\\n  --model meta-llama/Llama-3.2-1B \\\n  --task \"leaderboard|mmlu|5\" \\\n  --framework lighteval\n\n# Explicit hardware selection\nuv run scripts/run_vllm_eval_job.py \\\n  --model meta-llama/Llama-3.2-70B \\\n  --task mmlu \\\n  --framework inspect \\\n  --hardware a100-large \\\n  --tensor-parallel-size 4\n\n# Use HF Transformers backend\nuv run scripts/run_vllm_eval_job.py \\\n  --model microsoft/phi-2 \\\n  --task mmlu \\\n  --framework inspect \\\n  --backend hf\n```\n\n**Hardware Recommendations:**\n| Model Size | Recommended Hardware |\n|------------|---------------------|\n| < 3B params | `t4-small` |\n| 3B - 13B | `a10g-small` |\n| 13B - 34B | `a10g-large` |\n| 34B+ | `a100-large` |\n\n### Commands Reference\n\n**Top-level help and version:**\n```bash\nuv run scripts/evaluation_manager.py --help\nuv run scripts/evaluation_manager.py --version\n```\n\n**Inspect Tables (start here):**\n```bash\nuv run scripts/evaluation_manager.py inspect-tables --repo-id \"username/model-name\"\n```\n\n**Extract from README:**\n```bash\nuv run scripts/evaluation_manager.py extract-readme \\\n  --repo-id \"username/model-name\" \\\n  --table N \\\n  [--model-column-index N] \\\n  [--model-name-override \"Exact Column Header or Model Name\"] \\\n  [--task-type \"text-generation\"] \\\n  [--dataset-name \"Custom Benchmarks\"] \\\n  [--apply | --create-pr]\n```\n\n**Import from Artificial Analysis:**\n```bash\nAA_API_KEY=... uv run scripts/evaluation_manager.py import-aa \\\n  --creator-slug \"creator-name\" \\\n  --model-name \"model-slug\" \\\n  --repo-id \"username/model-name\" \\\n  [--create-pr]\n```\n\n**View / Validate:**\n```bash\nuv run scripts/evaluation_manager.py show --repo-id \"username/model-name\"\nuv run scripts/evaluation_manager.py validate --repo-id \"username/model-name\"\n```\n\n**Check Open PRs (ALWAYS run before --create-pr):**\n```bash\nuv run scripts/evaluation_manager.py get-prs --repo-id \"username/model-name\"\n```\nLists all open pull requests for the model repository. Shows PR number, title, author, date, and URL.\n\n**Run Evaluation Job (Inference Providers):**\n```bash\nhf jobs uv run scripts/inspect_eval_uv.py \\\n  --flavor \"cpu-basic|t4-small|...\" \\\n  --secret HF_TOKEN=$HF_TOKEN \\\n  -- --model \"model-id\" \\\n     --task \"task-name\"\n```\n\nor use the Python helper:\n\n```bash\nuv run scripts/run_eval_job.py \\\n  --model \"model-id\" \\\n  --task \"task-name\" \\\n  --hardware \"cpu-basic|t4-small|...\"\n```\n\n**Run vLLM Evaluation (Custom Models):**\n```bash\n# lighteval with vLLM\nhf jobs uv run scripts/lighteval_vllm_uv.py \\\n  --flavor \"a10g-small\" \\\n  --secrets HF_TOKEN=$HF_TOKEN \\\n  -- --model \"model-id\" \\\n     --tasks \"leaderboard|mmlu|5\"\n\n# inspect-ai with vLLM\nhf jobs uv run scripts/inspect_vllm_uv.py \\\n  --flavor \"a10g-small\" \\\n  --secrets HF_TOKEN=$HF_TOKEN \\\n  -- --model \"model-id\" \\\n     --task \"mmlu\"\n\n# Helper script (auto hardware selection)\nuv run scripts/run_vllm_eval_job.py \\\n  --model \"model-id\" \\\n  --task \"leaderboard|mmlu|5\" \\\n  --framework lighteval\n```\n\n### Model-Index Format\n\nThe generated model-index follows this structure:\n\n```yaml\nmodel-index:\n  - name: Model Name\n    results:\n      - task:\n          type: text-generation\n        dataset:\n          name: Benchmark Dataset\n          type: benchmark_type\n        metrics:\n          - name: MMLU\n            type: mmlu\n            value: 85.2\n          - name: HumanEval\n            type: humaneval\n            value: 72.5\n        source:\n          name: Source Name\n          url: https://source-url.com\n```\n\nWARNING: Do not use markdown formatting in the model name. Use the exact name from the table. Only use urls in the source.url field.\n\n### Error Handling\n- **Table Not Found**: Script will report if no evaluation tables are detected\n- **Invalid Format**: Clear error messages for malformed tables\n- **API Errors**: Retry logic for transient Artificial Analysis API failures\n- **Token Issues**: Validation before attempting updates\n- **Merge Conflicts**: Preserves existing model-index entries when adding new ones\n- **Space Creation**: Handles naming conflicts and hardware request failures gracefully\n\n### Best Practices\n\n1. **Check for existing PRs first**: Run `get-prs` before creating any new PR to avoid duplicates\n2. **Always start with `inspect-tables`**: See table structure and get the correct extraction command\n3. **Use `--help` for guidance**: Run `inspect-tables --help` to see the complete workflow\n4. **Preview first**: Default behavior prints YAML; review it before using `--apply` or `--create-pr`\n5. **Verify extracted values**: Compare YAML output against the README table manually\n6. **Use `--table N` for multi-table READMEs**: Required when multiple evaluation tables exist\n7. **Use `--model-name-override` for comparison tables**: Copy the exact column header from `inspect-tables` output\n8. **Create PRs for Others**: Use `--create-pr` when updating models you don''t own\n9. **One model per repo**: Only add the main model''s results to model-index\n10. **No markdown in YAML names**: The model name field in YAML should be plain text\n\n### Model Name Matching\n\nWhen extracting evaluation tables with multiple models (either as columns or rows), the script uses **exact normalized token matching**:\n\n- Removes markdown formatting (bold `**`, links `[]()`  )\n- Normalizes names (lowercase, replace `-` and `_` with spaces)\n- Compares token sets: `\"OLMo-3-32B\"` → `{\"olmo\", \"3\", \"32b\"}` matches `\"**Olmo 3 32B**\"` or `\"[Olmo-3-32B](...)`\n- Only extracts if tokens match exactly (handles different word orders and separators)\n- Fails if no exact match found (rather than guessing from similar names)\n\n**For column-based tables** (benchmarks as rows, models as columns):\n- Finds the column header matching the model name\n- Extracts scores from that column only\n\n**For transposed tables** (models as rows, benchmarks as columns):\n- Finds the row in the first column matching the model name\n- Extracts all benchmark scores from that row only\n\nThis ensures only the correct model''s scores are extracted, never unrelated models or training checkpoints. \n\n### Common Patterns\n\n**Update Your Own Model:**\n```bash\n# Extract from README and push directly\nuv run scripts/evaluation_manager.py extract-readme \\\n  --repo-id \"your-username/your-model\" \\\n  --task-type \"text-generation\"\n```\n\n**Update Someone Else''s Model (Full Workflow):**\n```bash\n# Step 1: ALWAYS check for existing PRs first\nuv run scripts/evaluation_manager.py get-prs \\\n  --repo-id \"other-username/their-model\"\n\n# Step 2: If NO open PRs exist, proceed with creating one\nuv run scripts/evaluation_manager.py extract-readme \\\n  --repo-id \"other-username/their-model\" \\\n  --create-pr\n\n# If open PRs DO exist:\n# - Warn the user about existing PRs\n# - Show them the PR URLs\n# - Do NOT create a new PR unless user explicitly confirms\n```\n\n**Import Fresh Benchmarks:**\n```bash\n# Step 1: Check for existing PRs\nuv run scripts/evaluation_manager.py get-prs \\\n  --repo-id \"anthropic/claude-sonnet-4\"\n\n# Step 2: If no PRs, import from Artificial Analysis\nAA_API_KEY=... uv run scripts/evaluation_manager.py import-aa \\\n  --creator-slug \"anthropic\" \\\n  --model-name \"claude-sonnet-4\" \\\n  --repo-id \"anthropic/claude-sonnet-4\" \\\n  --create-pr\n```\n\n### Troubleshooting\n\n**Issue**: \"No evaluation tables found in README\"\n- **Solution**: Check if README contains markdown tables with numeric scores\n\n**Issue**: \"Could not find model ''X'' in transposed table\"\n- **Solution**: The script will display available models. Use `--model-name-override` with the exact name from the list\n- **Example**: `--model-name-override \"**Olmo 3-32B**\"`\n\n**Issue**: \"AA_API_KEY not set\"\n- **Solution**: Set environment variable or add to .env file\n\n**Issue**: \"Token does not have write access\"\n- **Solution**: Ensure HF_TOKEN has write permissions for the repository\n\n**Issue**: \"Model not found in Artificial Analysis\"\n- **Solution**: Verify creator-slug and model-name match API values\n\n**Issue**: \"Payment required for hardware\"\n- **Solution**: Add a payment method to your Hugging Face account to use non-CPU hardware\n\n**Issue**: \"vLLM out of memory\" or CUDA OOM\n- **Solution**: Use a larger hardware flavor, reduce `--gpu-memory-utilization`, or use `--tensor-parallel-size` for multi-GPU\n\n**Issue**: \"Model architecture not supported by vLLM\"\n- **Solution**: Use `--backend hf` (inspect-ai) or `--backend accelerate` (lighteval) for HuggingFace Transformers\n\n**Issue**: \"Trust remote code required\"\n- **Solution**: Add `--trust-remote-code` flag for models with custom code (e.g., Phi-2, Qwen)\n\n**Issue**: \"Chat template not found\"\n- **Solution**: Only use `--use-chat-template` for instruction-tuned models that include a chat template\n\n### Integration Examples\n\n**Python Script Integration:**\n```python\nimport subprocess\nimport os\n\ndef update_model_evaluations(repo_id, readme_content):\n    \"\"\"Update model card with evaluations from README.\"\"\"\n    result = subprocess.run([\n        \"python\", \"scripts/evaluation_manager.py\",\n        \"extract-readme\",\n        \"--repo-id\", repo_id,\n        \"--create-pr\"\n    ], capture_output=True, text=True)\n\n    if result.returncode == 0:\n        print(f\"Successfully updated {repo_id}\")\n    else:\n        print(f\"Error: {result.stderr}\")\n```\n"},"category":"official","lastSynced":"2026-03-06T05:35:51.966Z","seo":{"title":{"en":"hugging-face-evaluation: Evaluation Results Setup Guide |...","zh":"Hugging Face 评估工具配置指南","ja":"Hugging Face 評価ツールのセットアップガイド","ko":"Hugging Face 평가 도구 설정 가이드","es":"Guía de configuración de hugging-face-evaluation para mod...","fr":"Guide de mise en route de hugging-face-evaluation pour le...","de":"Einrichtungsleitfaden für hugging-face-evaluation in Mode...","pt":"Guia de Configuração do Hugging Face Evaluation","ru":"Настройка ИИ Агента Hugging Face Evaluation","ar":"دليل إعداد هوجينج فيس للتقييم"},"description":{"en":"Discover how to add structured evaluation results to Hugging Face model cards with hugging-face-evaluation. Learn to extract eval tables and import scores fr...","zh":"使用 Hugging Face 评估工具添加和管理模型评估结果，支持多种方法，包括从 README 中提取评估表和导入 Artificial Analysis API 分数","ja":"Hugging Face 評価ツールを使用してモデル評価結果を追加および管理します。README から評価表を抽出して Artificial Analysis API スコアをインポートする機能をサポートします","ko":"Hugging Face 평가 도구를 사용하여 모델 평가 결과를 추가 및 관리합니다. README에서 평가 표를 추출하고 Artificial Analysis API 점수를 가져오는 기능을 지원합니다","es":"Aprende a agregar y administrar resultados de evaluación en las tarjetas de modelo de Hugging Face con esta habilidad de AI Agent","fr":"Découvrez comment ajouter et gérer les résultats d''évaluation dans les cartes de modèle Hugging Face avec cette compétence d''agent IA","de":"Erfahren Sie, wie Sie Bewertungsergebnisse in Hugging Face-Modellkarten mit dieser AI-Agent-Fähigkeit hinzufügen und verwalten","pt":"Aprenda a adicionar e gerenciar resultados de avaliação em cartões de modelo Hugging Face com o skill de avaliação","ru":"Узнайте, как добавить и управлять результатами оценки в картах моделей Hugging Face с помощью ИИ Агента оценки","ar":"تعرف على كيفية إضافة وإدارة نتائج التقييم في بطاقات نموذج هوجينج فيس مع مهارة التقييم"},"definition":{"en":"hugging-face-evaluation is a skill for managing evaluation results in Hugging Face model cards, supporting multiple methods for adding evaluation data","zh":"Hugging Face 评估工具是一种 AI 工具，用于添加和管理 Hugging Face 模型评估结果","ja":"Hugging Face 評価ツールは、Hugging Face モデル評価結果を追加および管理するための AI エージェントです","ko":"Hugging Face 평가 도구는 Hugging Face 모델 평가 결과를 추가 및 관리하는 AI 도구입니다","es":"hugging-face-evaluation es una habilidad de AI Agent que permite agregar y administrar resultados de evaluación en las tarjetas de modelo de Hugging Face","fr":"hugging-face-evaluation est une compétence d''agent IA qui permet d''ajouter et de gérer les résultats d''évaluation dans les cartes de modèle Hugging Face","de":"hugging-face-evaluation ist eine Fähigkeit von AI-Agenten, die das Hinzufügen und Verwalten von Bewertungsergebnissen in Hugging Face-Modellkarten ermöglicht","pt":"O que é o Hugging Face Evaluation? É um skill que permite adicionar resultados de avaliação estruturados a cartões de modelo Hugging Face","ru":"Что такое ИИ Агент оценки Hugging Face? Это ИИ Агент, который позволяет добавлять структурированные результаты оценки в карты моделей Hugging Face","ar":"ما هي سمات التقييم في هوجينج فيس؟ هي سمة تسمح بإضافة نتائج تقييم منظم إلى بطاقات نموذج هوجينج فيس"},"features":{"en":["Extracts existing evaluation tables from README content","Imports benchmark scores from Artificial Analysis API","Runs custom model evaluations with vLLM/lighteval","Works with the model-index metadata format","Updates model-index metadata for leaderboard integration","Supports integration with Artificial Analysis for benchmark scores"],"zh":["从 README 中提取评估表","导入 Artificial Analysis API 分数","运行自定义模型评估使用 vLLM/lighteval","支持 model-index 元数据格式","与 Hugging Face 生态系统集成","更新模型卡 metadata 供 leaderboard 集成使用"],"ja":["README から評価表を抽出","Artificial Analysis API スコアをインポート","vLLM/lighteval を使用したカスタム モデル評価の実行","model-index メタデータ形式のサポート","Hugging Face 生態系との統合","モデルカード metadata の更新をリーダーボード統合用にサポート"],"ko":["README에서 평가 표를 추출","Artificial Analysis API 점수를 가져오기","vLLM/lighteval을 사용한 사용자 지정 모델 평가 실행","model-index 메타데이터 형식 지원","Hugging Face 생태계와의 통합","모델 카드 metadata 업데이트 리더보드 통합 지원"],"es":["Extracción de tablas de evaluación de contenido README","Importación de puntuaciones de benchmark de Artificial Analysis","Ejecución de evaluaciones de modelo personalizadas con vLLM o accelerate","Compatibilidad con el formato de metadatos model-index","Integración con el ecosistema de Hugging Face","Actualización de metadatos de model-index para integración de leaderboard"],"fr":["Extraction de tables d''évaluation de contenu README","Importation de scores de benchmark d''Artificial Analysis","Exécution d''évaluations de modèle personnalisées avec vLLM ou accelerate","Compatibilité avec le format de métadonnées model-index","Intégration avec l''écosystème Hugging Face","Mise à jour des métadonnées model-index pour intégration de leaderboard"],"de":["Extraktion von Bewertungstabellen aus README-Inhalten","Import von Benchmark-Scores von Artificial Analysis","Ausführung von benutzerdefinierten Modellbewertungen mit vLLM oder accelerate","Kompatibilität mit dem model-index-Metadatenformat","Integration in das Hugging Face-Ökosystem","Aktualisierung der model-index-Metadaten für Leaderboard-Integration"],"pt":["Extração de tabelas de avaliação de conteúdo README","Importação de pontuações de benchmark do Artificial Analysis API","Execução de avaliações de modelo personalizadas com vLLM ou accelerate backends","Integração com o ecossistema Hugging Face","Atualização de metadados de model-index para integração de leaderboard"],"ru":["Извлечение таблиц оценки из содержимого README","Импорт баллов бенчмарка из API Artificial Analysis","Выполнение пользовательских оценок моделей с vLLM или accelerate backends","Интеграция с экосистемой Hugging Face","Обновление метаданных model-index для интеграции leaderboard"],"ar":["استخراج جداول التقييم من محتوى ملف README","استيراد درجات التقييم من واجهة برمجة تطبيقات التحليل الاصطناعي","تشغيل تقييمات نموذج مخصصة مع vLLM أو accelerate backends","التكامل مع نظام هوجينج فيس","تحديث بيانات الفهرس النموزجي لدمج لوحة القيادة"]},"keywords":{"en":["how to use hugging-face-evaluation","hugging-face-evaluation setup guide","hugging-face-evaluation alternative","hugging-face-evaluation vs model-index","hugging-face-evaluation install","what is hugging-face-evaluation","hugging-face-evaluation model cards","hugging-face-evaluation Artificial Analysis API","hugging-face-evaluation vLLM/lighteval"],"zh":["Hugging Face 评估工具","AI 工具","模型评估结果","README 评估表","Artificial Analysis API","vLLM/lighteval","model-index 元数据格式","Hugging Face 生态系统","模型卡 metadata"],"ja":["Hugging Face 評価ツール","AI エージェント","モデル評価結果","README 评価表","Artificial Analysis API","vLLM/lighteval","model-index メタデータ形式","Hugging Face 生態系","モデルカード metadata"],"ko":["Hugging Face 평가 도구","AI 도구","모델 평가 결과","README 평가 표","Artificial Analysis API","vLLM/lighteval","model-index 메타데이터 형식","Hugging Face 생태계","모델 카드 metadata"],"es":["hugging face evaluación","agentes de IA para modelos de lenguaje","evaluación de modelos de lenguaje","benchmark de modelos de lenguaje"," README evaluación","Artificial Analysis API","vLLM","accelerate","model-index","Hugging Face ecosistema"],"fr":["hugging face évaluation","agents IA pour modèles de langage","évaluation de modèles de langage","benchmark de modèles de langage","README évaluation","Artificial Analysis API","vLLM","accelerate","model-index","Hugging Face écosystème"],"de":["hugging face Bewertung","AI-Agenten für Sprachmodelle","Bewertung von Sprachmodellen","Benchmark von Sprachmodellen","README Bewertung","Artificial Analysis API","vLLM","accelerate","model-index","Hugging Face Ökosystem"],"pt":["Hugging Face Evaluation","Avaliação de modelo","Extração de tabelas de avaliação","Importação de pontuações de benchmark","vLLM","accelerate backends","Integração com Hugging Face","Model-index metadata"],"ru":["ИИ Агент оценки Hugging Face","Оценка модели","Извлечение таблиц оценки","Импорт баллов бенчмарка","vLLM","accelerate backends","Интеграция с Hugging Face","Метаданные model-index"],"ar":["سمات التقييم في هوجينج فيس","تقييم النموذج","استخراج جداول التقييم","استيراد درجات التقييم","vLLM","accelerate backends","التكامل مع هوجينج فيس","بيانات الفهرس النموزجي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced Hugging Face model evaluation and management capabilities.","zh":"适合需要高级Hugging Face模型评估和管理能力的AI代理。","ja":"Hugging Faceモデルの高度な評価および管理機能を必要とするAIエージェントに適しています。","ko":"고급 Hugging Face 모델 평가 및 관리 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades avanzadas de evaluación y administración de modelos Hugging Face.","fr":"Parfait pour les agents IA ayant besoin de fonctionnalités avancées d''évaluation et de gestion de modèles Hugging Face.","de":"Perfekt für KI-Agents, die erweiterte Hugging Face-Modellbewertungs- und Verwaltungsfunktionen benötigen.","pt":"Perfeito para Agentes de IA que necessitam de capacidades avançadas de avaliação e gerenciamento de modelos Hugging Face.","ru":"Идеально для агентов ИИ, которым необходимы расширенные возможности оценки и управления моделями Hugging Face.","ar":"مثالي للوكلاء الذكيين الذين يحتاجون إلى إمكانيات متقدمة لتقييم وإدارة نماذج Hugging Face."},"recommendation":{"en":"Empowers agents to extract eval tables from README content, import scores from Artificial Analysis API, and run custom model evaluations with vLLM/lighteval, leveraging model-index metadata format for leaderboard integration.","zh":"赋予代理从README内容中提取评估表，导入Artificial Analysis API的评分，并使用vLLM/lighteval运行自定义模型评估，利用模型索引元数据格式进行排行榜集成。","ja":"READMEコンテンツから評価テーブルを抽出する、Artificial Analysis APIからのスコアをインポートする、vLLM/lightevalを使用してカスタムモデル評価を実行するなどの機能を提供し、モデルインデックスメタデータ形式を使用してリーダーボードを統合します。","ko":"README 내용에서 평가 테이블을 추출하고, Artificial Analysis API의 점수를 가져와 vLLM/lighteval을 사용하여 사용자 지정 모델 평가를 실행하며, 모델 인덱스 메타데이터 형식을 사용하여 리더보드를 통합하여 에이전트에 권한을 부여합니다.","es":"Habilita a los agentes a extraer tablas de evaluación de contenido de README, importar puntuaciones de la API de Análisis Artificial, y ejecutar evaluaciones de modelos personalizadas con vLLM/lighteval, aprovechando el formato de metadatos de model-index para la integración de clasificaciones.","fr":"Permet aux agents d''extraire des tableaux d''évaluation de contenu de README, d''importer des scores de l''API d''Analyse Artificielle, et d''exécuter des évaluations de modèles personnalisées avec vLLM/lighteval, en exploitant le format de métadonnées de model-index pour l''intégration des classements.","de":"Ermöglicht es den Agenten, Bewertungstabellen aus README-Inhalten zu extrahieren, Scores von der Artificial Analysis API zu importieren und benutzerdefinierte Modellbewertungen mit vLLM/lighteval auszuführen, wobei das model-index-Metadatenformat für die Integration von Ranglisten verwendet wird.","pt":"Habilita os agentes a extrair tabelas de avaliação do conteúdo do README, importar pontuações da API de Análise Artificial e executar avaliações personalizadas de modelos com vLLM/lighteval, aproveitando o formato de metadados model-index para integração de leaderboard.","ru":"Наделяет агентов возможностью извлекать таблицы оценки из содержимого README, импортировать баллы из API Искусственного Анализа и запускать пользовательские оценки моделей с vLLM/lighteval, используя формат метаданных model-index для интеграции с таблицей лидеров.","ar":"يمنح الوكلاء القدرة على استخراج جداول التقييم من محتوى README، واستيراد الدرجات من واجهة برمجة تطبيقات التحليل الاصطناعي، وتشغيل تقييمات مخصصة للنماذج باستخدام vLLM/lighteval، مستفيدا من تنسيق siêu بيانات model-index لتكامل لوحة القيادة."},"useCases":{"en":["Extracting existing evaluation tables from README content for model comparison","Importing benchmark scores from Artificial Analysis for model validation","Running custom model evaluations with vLLM or accelerate backends for model optimization"],"zh":["从README内容中提取现有的评估表以进行模型比较","导入Artificial Analysis的基准得分以进行模型验证","使用vLLM或accelerate后端运行自定义模型评估以进行模型优化"],"ja":["READMEコンテンツから既存の評価テーブルを抽出してモデルを比較する","Artificial Analysisのベンチマークスコアをインポートしてモデルを検証する","vLLMまたはaccelerateバックエンドを使用してカスタムモデル評価を実行してモデルを最適化する"],"ko":["README 내용에서 기존의 평가 테이블을 추출하여 모델 비교를 수행하는 것","Artificial Analysis의 벤치마크 점수를 가져와 모델을 검증하는 것","vLLM이나 accelerate 백엔드를 사용하여 사용자 지정 모델 평가를 실행하여 모델 최적화를 수행하는 것"],"es":["Extraer tablas de evaluación existentes de contenido de README para la comparación de modelos","Importar puntuaciones de referencia de Análisis Artificial para la validación de modelos","Ejecutar evaluaciones de modelos personalizadas con vLLM o accelerate backends para la optimización de modelos"],"fr":["Extraire des tableaux d''évaluation existants de contenu de README pour la comparaison de modèles","Importer des scores de référence d''Analyse Artificielle pour la validation de modèles","Exécuter des évaluations de modèles personnalisées avec vLLM ou accelerate backends pour l''optimisation de modèles"],"de":["Vorhandene Bewertungstabellen aus README-Inhalten für den Modellvergleich extrahieren","Benchmark-Scores von Artificial Analysis für die Modellvalidierung importieren","Benutzerdefinierte Modellbewertungen mit vLLM oder accelerate-Backends für die Modelloptimierung ausführen"],"pt":["Extrair tabelas de avaliação existentes do conteúdo do README para comparação de modelos","Importar pontuações de benchmark da Análise Artificial para validação de modelos","Executar avaliações personalizadas de modelos com backends vLLM ou accelerate para otimização de modelos"],"ru":["Извлекать существующие таблицы оценки из содержимого README для сравнения моделей","Импортировать баллы бенчмарка из Искусственного Анализа для валидации моделей","Запускать пользовательские оценки моделей с бэкендами vLLM или accelerate для оптимизации моделей"],"ar":["استخراج جداول التقييم الحالية من محتوى README لمقارنة النماذج","استيراد درجات البENCHMARK من واجهة برمجة تطبيقات التحليل الاصطناعي للتحقق من النماذج","تشغيل تقييمات مخصصة للنماذج باستخدام backends vLLM أو accelerate لتحسين النماذج"]},"limitations":{"en":["Requires Hugging Face model cards setup","Dependent on Artificial Analysis API for benchmark scores","Limited to model-index metadata format"],"zh":["需要Hugging Face模型卡设置","依赖Artificial Analysis API的基准得分","仅限模型索引元数据格式"],"ja":["Hugging Faceモデルのカード設定が必要","Artificial Analysis APIのベンチマークスコアに依存している","モデルインデックスメタデータ形式に限られている"],"ko":["Hugging Face 모델 카드 설정이 필요","Artificial Analysis API의 벤치마크 점수에 의존","모델 인덱스 메타데이터 형식에만 제한"],"es":["Requiere configuración de tarjetas de modelo Hugging Face","Dependiente de la API de Análisis Artificial para puntuaciones de referencia","Limitado al formato de metadatos de model-index"],"fr":["Nécessite une configuration de cartes de modèle Hugging Face","Dépendant de l''API d''Analyse Artificielle pour les scores de référence","Limité au format de métadonnées de model-index"],"de":["Benötigt eine Einrichtung von Hugging Face-Modellkarten","Abhängig von der Artificial Analysis API für Benchmark-Scores","Begrenzt auf das model-index-Metadatenformat"],"pt":["Exige configuração de cartões de modelos Hugging Face","Dependente da API de Análise Artificial para pontuações de benchmark","Limitado ao formato de metadados model-index"],"ru":["Требует настройки карт моделей Hugging Face","Зависит от API Искусственного Анализа для баллов бенчмарка","Ограничен форматом метаданных model-index"],"ar":["يتطلب إعداد بطاقات النماذج Hugging Face","يعتمد على واجهة برمجة تطبيقات التحليل الاصطناعي لدرجات البENCHMARK","محدود بتنسيق siêu بيانات model-index"]},"version":4},"contentHash":"a3acc51eb6df217fc6eb781f2fd58bc401d43864ae3a4b80bfd4fb62775a99d1","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":95}');
