INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-evaluation', 'hugging-face-evaluation', 'huggingface', 'skills', 'official', 'hugging-face-evaluation huggingface skills official The hugging-face-evaluation skill provides tools for adding evaluation results to Hugging Face model cards, benefiting AI model developers. It supports extracting eval tables and importing benchmark scores. Hugging Face 评估工具提供了添加结构化评估结果到 Hugging Face 模型卡的功能，支持从 README 中提取评估表、导入 Artificial Analysis API 分数和运行自定义模型评估 Hugging Face 評価ツールは、Hugging Face モデルカードに構造化された評価結果を追加する機能を提供します。README から評価表を抽出して Artificial Analysis API スコアをインポートする機能と、カスタム モデル評価を実行する機能をサポートします Hugging Face 평가 도구는 Hugging Face 모델 카드에 구조화된 평가 결과를 추가하는 기능을 제공합니다. README에서 평가 표를 추출하고 Artificial Analysis API 점수를 가져오고 사용자 지정 모델 평가를 실행하는 기능을 지원합니다 La habilidad hugging-face-evaluation permite agregar resultados de evaluación estructurados a las tarjetas de modelo de Hugging Face, admitiendo la extracción de tablas de evaluación de contenido README y la importación de puntuaciones de benchmark de Artificial Analysis La compétence hugging-face-evaluation permet d''ajouter des résultats d''évaluation structurés aux cartes de modèle Hugging Face, prenant en charge l''extraction de tables d''évaluation de contenu README et l''importation de scores de benchmark d''Artificial Analysis Die Fähigkeit hugging-face-evaluation ermöglicht das Hinzufügen von strukturierten Bewertungsergebnissen zu Hugging Face-Modellkarten, einschließlich der Extraktion von Bewertungstabellen aus README-Inhalten und der Import von Benchmark-Scores von Artificial Analysis O skill de avaliação do Hugging Face permite adicionar resultados de avaliação estruturados a cartões de modelo, suportando extração de tabelas de avaliação de conteúdo README e importação de pontuações de benchmark do Artificial Analysis API ИИ Агент оценки Hugging Face позволяет добавлять структурированные результаты оценки в карты моделей, поддерживая извлечение таблиц оценки из содержимого README и импорт баллов бенчмарка из API Artificial Analysis سمات التقييم في هوجينج فيس تسمح بإضافة نتائج تقييم منظم إلى بطاقات النموذج، وتدعم استخراج جداول التقييم من محتوى ملف README واستيراد درجات التقييم من واجهة برمجة تطبيقات التحليل الاصطناعي how to use hugging-face-evaluation hugging-face-evaluation setup guide hugging-face-evaluation alternative hugging-face-evaluation vs model-index hugging-face-evaluation install what is hugging-face-evaluation hugging-face-evaluation model cards hugging-face-evaluation Artificial Analysis API hugging-face-evaluation vLLM/lighteval Hugging Face 评估工具 AI 工具 模型评估结果 README 评估表 Artificial Analysis API vLLM/lighteval model-index 元数据格式 Hugging Face 生态系统 模型卡 metadata Extracts existing evaluation tables from README content Imports benchmark scores from Artificial Analysis API Runs custom model evaluations with vLLM/lighteval Works with the model-index metadata format Updates model-index metadata for leaderboard integration Supports integration with Artificial Analysis for benchmark scores hugging-face-evaluation is a skill for managing evaluation results in Hugging Face model cards, supporting multiple methods for adding evaluation data');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-jobs', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-jobs', 8290, 490, 95, '2026-03-06T05:28:53Z', '2026-03-06T05:36:55.720Z', 'a4e697cc1d5ffa293c537473f96efc570e24d698434829c9eb430a1cf099e469', '{"id":"huggingface/skills/hugging-face-jobs","name":"hugging-face-jobs","description":{"en":"The hugging-face-jobs skill enables users to run general-purpose compute workloads on Hugging Face infrastructure, supporting tasks like data processing, batch inference, and model training. This skill benefits developers and data scientists working with Python-based tasks and cloud compute.","es":"Hugging Face Jobs permite ejecutar cargas de trabajo de AI en la nube sin configuración local, incluyendo procesamiento de datos, inferencia por lotes y experimentos","fr":"Hugging Face Jobs permet d''exécuter des charges de travail d''IA dans le cloud sans configuration locale, y compris le traitement de données, l''inférence par lots et les expériences","de":"Hugging Face Jobs ermöglicht die Ausführung von KI-Workloads in der Cloud ohne lokale Konfiguration, einschließlich Datenverarbeitung, Batch-Inferenz und Experimenten","pt":"O Hugging Face Jobs é uma infraestrutura de computação em nuvem para executar workloads de IA, incluindo processamento de dados e treinamento de modelos","ru":"ИИ Агенты Hugging Face Jobs представляют собой инфраструктуру облачного вычисления для выполнения задач ИИ, включая обработку данных и обучение моделей","ar":"هوجينغ فايس جوبز هو بنية حوسبة سحابية لتشغيل تحميلات العمل الإصطناعي، بما في ذلك معالجة البيانات ودمج النماذج"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-jobs","description":"This skill should be used when users want to run any workload on Hugging Face Jobs infrastructure. Covers UV scripts, Docker-based jobs, hardware selection, cost estimation, authentication with tokens, secrets management, timeout configuration, and result persistence. Designed for general-purpose compute workloads including data processing, inference, experiments, batch jobs, and any Python-based tasks. Should be invoked for tasks involving cloud compute, GPU workloads, or when users mention running jobs on Hugging Face infrastructure without local setup.","bodyPreview":"# Running Workloads on Hugging Face Jobs\n\n## Overview\n\nRun any workload on fully managed Hugging Face infrastructure. No local setup required—jobs run on cloud CPUs, GPUs, or TPUs and can persist results to the Hugging Face Hub.\n\n**Common use cases:**\n- **Data Processing** - Transform, filter, or analyze large datasets\n- **Batch Inference** - Run inference on thousands of samples\n- **Experiments & Benchmarks** - Reproducible ML experiments\n- **Model Training** - Fine-tune models (see `model-trai","body":"# Running Workloads on Hugging Face Jobs\n\n## Overview\n\nRun any workload on fully managed Hugging Face infrastructure. No local setup required—jobs run on cloud CPUs, GPUs, or TPUs and can persist results to the Hugging Face Hub.\n\n**Common use cases:**\n- **Data Processing** - Transform, filter, or analyze large datasets\n- **Batch Inference** - Run inference on thousands of samples\n- **Experiments & Benchmarks** - Reproducible ML experiments\n- **Model Training** - Fine-tune models (see `model-trainer` skill for TRL-specific training)\n- **Synthetic Data Generation** - Generate datasets using LLMs\n- **Development & Testing** - Test code without local GPU setup\n- **Scheduled Jobs** - Automate recurring tasks\n\n**For model training specifically:** See the `model-trainer` skill for TRL-based training workflows.\n\n## When to Use This Skill\n\nUse this skill when users want to:\n- Run Python workloads on cloud infrastructure\n- Execute jobs without local GPU/TPU setup\n- Process data at scale\n- Run batch inference or experiments\n- Schedule recurring tasks\n- Use GPUs/TPUs for any workload\n- Persist results to the Hugging Face Hub\n\n## Key Directives\n\nWhen assisting with jobs:\n\n1. **ALWAYS use `hf_jobs()` MCP tool** - Submit jobs using `hf_jobs(\"uv\", {...})` or `hf_jobs(\"run\", {...})`. The `script` parameter accepts Python code directly. Do NOT save to local files unless the user explicitly requests it. Pass the script content as a string to `hf_jobs()`.\n\n2. **Always handle authentication** - Jobs that interact with the Hub require `HF_TOKEN` via secrets. See Token Usage section below.\n\n3. **Provide job details after submission** - After submitting, provide job ID, monitoring URL, estimated time, and note that the user can request status checks later.\n\n4. **Set appropriate timeouts** - Default 30min may be insufficient for long-running tasks.\n\n## Prerequisites Checklist\n\nBefore starting any job, verify:\n\n### ✅ **Account & Authentication**\n- Hugging Face Account with [Pro](https://hf.co/pro), [Team](https://hf.co/enterprise), or [Enterprise](https://hf.co/enterprise) plan (Jobs require paid plan)\n- Authenticated login: Check with `hf_whoami()`\n- **HF_TOKEN for Hub Access** ⚠️ CRITICAL - Required for any Hub operations (push models/datasets, download private repos, etc.)\n- Token must have appropriate permissions (read for downloads, write for uploads)\n\n### ✅ **Token Usage** (See Token Usage section for details)\n\n**When tokens are required:**\n- Pushing models/datasets to Hub\n- Accessing private repositories\n- Using Hub APIs in scripts\n- Any authenticated Hub operations\n\n**How to provide tokens:**\n```python\n{\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}  # Recommended: automatic token\n}\n```\n\n**⚠️ CRITICAL:** The `$HF_TOKEN` placeholder is automatically replaced with your logged-in token. Never hardcode tokens in scripts.\n\n## Token Usage Guide\n\n### Understanding Tokens\n\n**What are HF Tokens?**\n- Authentication credentials for Hugging Face Hub\n- Required for authenticated operations (push, private repos, API access)\n- Stored securely on your machine after `hf auth login`\n\n**Token Types:**\n- **Read Token** - Can download models/datasets, read private repos\n- **Write Token** - Can push models/datasets, create repos, modify content\n- **Organization Token** - Can act on behalf of an organization\n\n### When Tokens Are Required\n\n**Always Required:**\n- Pushing models/datasets to Hub\n- Accessing private repositories\n- Creating new repositories\n- Modifying existing repositories\n- Using Hub APIs programmatically\n\n**Not Required:**\n- Downloading public models/datasets\n- Running jobs that don''t interact with Hub\n- Reading public repository information\n\n### How to Provide Tokens to Jobs\n\n#### Method 1: Automatic Token (Recommended)\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"your_script.py\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}  # ✅ Automatic replacement\n})\n```\n\n**How it works:**\n- `$HF_TOKEN` is a placeholder that gets replaced with your actual token\n- Uses the token from your logged-in session (`hf auth login`)\n- Most secure and convenient method\n- Token is encrypted server-side when passed as a secret\n\n**Benefits:**\n- No token exposure in code\n- Uses your current login session\n- Automatically updated if you re-login\n- Works seamlessly with MCP tools\n\n#### Method 2: Explicit Token (Not Recommended)\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"your_script.py\",\n    \"secrets\": {\"HF_TOKEN\": \"hf_abc123...\"}  # ⚠️ Hardcoded token\n})\n```\n\n**When to use:**\n- Only if automatic token doesn''t work\n- Testing with a specific token\n- Organization tokens (use with caution)\n\n**Security concerns:**\n- Token visible in code/logs\n- Must manually update if token rotates\n- Risk of token exposure\n\n#### Method 3: Environment Variable (Less Secure)\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"your_script.py\",\n    \"env\": {\"HF_TOKEN\": \"hf_abc123...\"}  # ⚠️ Less secure than secrets\n})\n```\n\n**Difference from secrets:**\n- `env` variables are visible in job logs\n- `secrets` are encrypted server-side\n- Always prefer `secrets` for tokens\n\n### Using Tokens in Scripts\n\n**In your Python script, tokens are available as environment variables:**\n\n```python\n# /// script\n# dependencies = [\"huggingface-hub\"]\n# ///\n\nimport os\nfrom huggingface_hub import HfApi\n\n# Token is automatically available if passed via secrets\ntoken = os.environ.get(\"HF_TOKEN\")\n\n# Use with Hub API\napi = HfApi(token=token)\n\n# Or let huggingface_hub auto-detect\napi = HfApi()  # Automatically uses HF_TOKEN env var\n```\n\n**Best practices:**\n- Don''t hardcode tokens in scripts\n- Use `os.environ.get(\"HF_TOKEN\")` to access\n- Let `huggingface_hub` auto-detect when possible\n- Verify token exists before Hub operations\n\n### Token Verification\n\n**Check if you''re logged in:**\n```python\nfrom huggingface_hub import whoami\nuser_info = whoami()  # Returns your username if authenticated\n```\n\n**Verify token in job:**\n```python\nimport os\nassert \"HF_TOKEN\" in os.environ, \"HF_TOKEN not found!\"\ntoken = os.environ[\"HF_TOKEN\"]\nprint(f\"Token starts with: {token[:7]}...\")  # Should start with \"hf_\"\n```\n\n### Common Token Issues\n\n**Error: 401 Unauthorized**\n- **Cause:** Token missing or invalid\n- **Fix:** Add `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}` to job config\n- **Verify:** Check `hf_whoami()` works locally\n\n**Error: 403 Forbidden**\n- **Cause:** Token lacks required permissions\n- **Fix:** Ensure token has write permissions for push operations\n- **Check:** Token type at https://huggingface.co/settings/tokens\n\n**Error: Token not found in environment**\n- **Cause:** `secrets` not passed or wrong key name\n- **Fix:** Use `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}` (not `env`)\n- **Verify:** Script checks `os.environ.get(\"HF_TOKEN\")`\n\n**Error: Repository access denied**\n- **Cause:** Token doesn''t have access to private repo\n- **Fix:** Use token from account with access\n- **Check:** Verify repo visibility and your permissions\n\n### Token Security Best Practices\n\n1. **Never commit tokens** - Use `$HF_TOKEN` placeholder or environment variables\n2. **Use secrets, not env** - Secrets are encrypted server-side\n3. **Rotate tokens regularly** - Generate new tokens periodically\n4. **Use minimal permissions** - Create tokens with only needed permissions\n5. **Don''t share tokens** - Each user should use their own token\n6. **Monitor token usage** - Check token activity in Hub settings\n\n### Complete Token Example\n\n```python\n# Example: Push results to Hub\nhf_jobs(\"uv\", {\n    \"script\": \"\"\"\n# /// script\n# dependencies = [\"huggingface-hub\", \"datasets\"]\n# ///\n\nimport os\nfrom huggingface_hub import HfApi\nfrom datasets import Dataset\n\n# Verify token is available\nassert \"HF_TOKEN\" in os.environ, \"HF_TOKEN required!\"\n\n# Use token for Hub operations\napi = HfApi(token=os.environ[\"HF_TOKEN\"])\n\n# Create and push dataset\ndata = {\"text\": [\"Hello\", \"World\"]}\ndataset = Dataset.from_dict(data)\ndataset.push_to_hub(\"username/my-dataset\", token=os.environ[\"HF_TOKEN\"])\n\nprint(\"✅ Dataset pushed successfully!\")\n\"\"\",\n    \"flavor\": \"cpu-basic\",\n    \"timeout\": \"30m\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}  # ✅ Token provided securely\n})\n```\n\n## Quick Start: Two Approaches\n\n### Approach 1: UV Scripts (Recommended)\n\nUV scripts use PEP 723 inline dependencies for clean, self-contained workloads.\n\n**MCP Tool:**\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"\"\"\n# /// script\n# dependencies = [\"transformers\", \"torch\"]\n# ///\n\nfrom transformers import pipeline\nimport torch\n\n# Your workload here\nclassifier = pipeline(\"sentiment-analysis\")\nresult = classifier(\"I love Hugging Face!\")\nprint(result)\n\"\"\",\n    \"flavor\": \"cpu-basic\",\n    \"timeout\": \"30m\"\n})\n```\n\n**CLI Equivalent:**\n```bash\nhf jobs uv run my_script.py --flavor cpu-basic --timeout 30m\n```\n\n**Python API:**\n```python\nfrom huggingface_hub import run_uv_job\nrun_uv_job(\"my_script.py\", flavor=\"cpu-basic\", timeout=\"30m\")\n```\n\n**Benefits:** Direct MCP tool usage, clean code, dependencies declared inline, no file saving required\n\n**When to use:** Default choice for all workloads, custom logic, any scenario requiring `hf_jobs()`\n\n#### Custom Docker Images for UV Scripts\n\nBy default, UV scripts use `ghcr.io/astral-sh/uv:python3.12-bookworm-slim`. For ML workloads with complex dependencies, use pre-built images:\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"inference.py\",\n    \"image\": \"vllm/vllm-openai:latest\",  # Pre-built image with vLLM\n    \"flavor\": \"a10g-large\"\n})\n```\n\n**CLI:**\n```bash\nhf jobs uv run --image vllm/vllm-openai:latest --flavor a10g-large inference.py\n```\n\n**Benefits:** Faster startup, pre-installed dependencies, optimized for specific frameworks\n\n#### Python Version\n\nBy default, UV scripts use Python 3.12. Specify a different version:\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"my_script.py\",\n    \"python\": \"3.11\",  # Use Python 3.11\n    \"flavor\": \"cpu-basic\"\n})\n```\n\n**Python API:**\n```python\nfrom huggingface_hub import run_uv_job\nrun_uv_job(\"my_script.py\", python=\"3.11\")\n```\n\n#### Working with Scripts\n\n⚠️ **Important:** There are *two* \"script path\" stories depending on how you run Jobs:\n\n- **Using the `hf_jobs()` MCP tool (recommended in this repo)**: the `script` value must be **inline code** (a string) or a **URL**. A local filesystem path (like `\"./scripts/foo.py\"`) won''t exist inside the remote container.\n- **Using the `hf jobs uv run` CLI**: local file paths **do work** (the CLI uploads your script).\n\n**Common mistake with `hf_jobs()` MCP tool:**\n\n```python\n# ❌ Will fail (remote container can''t see your local path)\nhf_jobs(\"uv\", {\"script\": \"./scripts/foo.py\"})\n```\n\n**Correct patterns with `hf_jobs()` MCP tool:**\n\n```python\n# ✅ Inline: read the local script file and pass its *contents*\nfrom pathlib import Path\nscript = Path(\"hf-jobs/scripts/foo.py\").read_text()\nhf_jobs(\"uv\", {\"script\": script})\n\n# ✅ URL: host the script somewhere reachable\nhf_jobs(\"uv\", {\"script\": \"https://huggingface.co/datasets/uv-scripts/.../raw/main/foo.py\"})\n\n# ✅ URL from GitHub\nhf_jobs(\"uv\", {\"script\": \"https://raw.githubusercontent.com/huggingface/trl/main/trl/scripts/sft.py\"})\n```\n\n**CLI equivalent (local paths supported):**\n\n```bash\nhf jobs uv run ./scripts/foo.py -- --your --args\n```\n\n#### Adding Dependencies at Runtime\n\nAdd extra dependencies beyond what''s in the PEP 723 header:\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"inference.py\",\n    \"dependencies\": [\"transformers\", \"torch>=2.0\"],  # Extra deps\n    \"flavor\": \"a10g-small\"\n})\n```\n\n**Python API:**\n```python\nfrom huggingface_hub import run_uv_job\nrun_uv_job(\"inference.py\", dependencies=[\"transformers\", \"torch>=2.0\"])\n```\n\n### Approach 2: Docker-Based Jobs\n\nRun jobs with custom Docker images and commands.\n\n**MCP Tool:**\n```python\nhf_jobs(\"run\", {\n    \"image\": \"python:3.12\",\n    \"command\": [\"python\", \"-c\", \"print(''Hello from HF Jobs!'')\"],\n    \"flavor\": \"cpu-basic\",\n    \"timeout\": \"30m\"\n})\n```\n\n**CLI Equivalent:**\n```bash\nhf jobs run python:3.12 python -c \"print(''Hello from HF Jobs!'')\"\n```\n\n**Python API:**\n```python\nfrom huggingface_hub import run_job\nrun_job(image=\"python:3.12\", command=[\"python\", \"-c\", \"print(''Hello!'')\"], flavor=\"cpu-basic\")\n```\n\n**Benefits:** Full Docker control, use pre-built images, run any command\n**When to use:** Need specific Docker images, non-Python workloads, complex environments\n\n**Example with GPU:**\n```python\nhf_jobs(\"run\", {\n    \"image\": \"pytorch/pytorch:2.6.0-cuda12.4-cudnn9-devel\",\n    \"command\": [\"python\", \"-c\", \"import torch; print(torch.cuda.get_device_name())\"],\n    \"flavor\": \"a10g-small\",\n    \"timeout\": \"1h\"\n})\n```\n\n**Using Hugging Face Spaces as Images:**\n\nYou can use Docker images from HF Spaces:\n```python\nhf_jobs(\"run\", {\n    \"image\": \"hf.co/spaces/lhoestq/duckdb\",  # Space as Docker image\n    \"command\": [\"duckdb\", \"-c\", \"SELECT ''Hello from DuckDB!''\"],\n    \"flavor\": \"cpu-basic\"\n})\n```\n\n**CLI:**\n```bash\nhf jobs run hf.co/spaces/lhoestq/duckdb duckdb -c \"SELECT ''Hello!''\"\n```\n\n### Finding More UV Scripts on Hub\n\nThe `uv-scripts` organization provides ready-to-use UV scripts stored as datasets on Hugging Face Hub:\n\n```python\n# Discover available UV script collections\ndataset_search({\"author\": \"uv-scripts\", \"sort\": \"downloads\", \"limit\": 20})\n\n# Explore a specific collection\nhub_repo_details([\"uv-scripts/classification\"], repo_type=\"dataset\", include_readme=True)\n```\n\n**Popular collections:** OCR, classification, synthetic-data, vLLM, dataset-creation\n\n## Hardware Selection\n\n> **Reference:** [HF Jobs Hardware Docs](https://huggingface.co/docs/hub/en/spaces-config-reference) (updated 07/2025)\n\n| Workload Type | Recommended Hardware | Use Case |\n|---------------|---------------------|----------|\n| Data processing, testing | `cpu-basic`, `cpu-upgrade` | Lightweight tasks |\n| Small models, demos | `t4-small` | <1B models, quick tests |\n| Medium models | `t4-medium`, `l4x1` | 1-7B models |\n| Large models, production | `a10g-small`, `a10g-large` | 7-13B models |\n| Very large models | `a100-large` | 13B+ models |\n| Batch inference | `a10g-large`, `a100-large` | High-throughput |\n| Multi-GPU workloads | `l4x4`, `a10g-largex2`, `a10g-largex4` | Parallel/large models |\n| TPU workloads | `v5e-1x1`, `v5e-2x2`, `v5e-2x4` | JAX/Flax, TPU-optimized |\n\n**All Available Flavors:**\n- **CPU:** `cpu-basic`, `cpu-upgrade`\n- **GPU:** `t4-small`, `t4-medium`, `l4x1`, `l4x4`, `a10g-small`, `a10g-large`, `a10g-largex2`, `a10g-largex4`, `a100-large`\n- **TPU:** `v5e-1x1`, `v5e-2x2`, `v5e-2x4`\n\n**Guidelines:**\n- Start with smaller hardware for testing\n- Scale up based on actual needs\n- Use multi-GPU for parallel workloads or large models\n- Use TPUs for JAX/Flax workloads\n- See `references/hardware_guide.md` for detailed specifications\n\n## Critical: Saving Results\n\n**⚠️ EPHEMERAL ENVIRONMENT—MUST PERSIST RESULTS**\n\nThe Jobs environment is temporary. All files are deleted when the job ends. If results aren''t persisted, **ALL WORK IS LOST**.\n\n### Persistence Options\n\n**1. Push to Hugging Face Hub (Recommended)**\n\n```python\n# Push models\nmodel.push_to_hub(\"username/model-name\", token=os.environ[\"HF_TOKEN\"])\n\n# Push datasets\ndataset.push_to_hub(\"username/dataset-name\", token=os.environ[\"HF_TOKEN\"])\n\n# Push artifacts\napi.upload_file(\n    path_or_fileobj=\"results.json\",\n    path_in_repo=\"results.json\",\n    repo_id=\"username/results\",\n    token=os.environ[\"HF_TOKEN\"]\n)\n```\n\n**2. Use External Storage**\n\n```python\n# Upload to S3, GCS, etc.\nimport boto3\ns3 = boto3.client(''s3'')\ns3.upload_file(''results.json'', ''my-bucket'', ''results.json'')\n```\n\n**3. Send Results via API**\n\n```python\n# POST results to your API\nimport requests\nrequests.post(\"https://your-api.com/results\", json=results)\n```\n\n### Required Configuration for Hub Push\n\n**In job submission:**\n```python\n{\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}  # Enables authentication\n}\n```\n\n**In script:**\n```python\nimport os\nfrom huggingface_hub import HfApi\n\n# Token automatically available from secrets\napi = HfApi(token=os.environ.get(\"HF_TOKEN\"))\n\n# Push your results\napi.upload_file(...)\n```\n\n### Verification Checklist\n\nBefore submitting:\n- [ ] Results persistence method chosen\n- [ ] `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}` if using Hub\n- [ ] Script handles missing token gracefully\n- [ ] Test persistence path works\n\n**See:** `references/hub_saving.md` for detailed Hub persistence guide\n\n## Timeout Management\n\n**⚠️ DEFAULT: 30 MINUTES**\n\nJobs automatically stop after the timeout. For long-running tasks like training, always set a custom timeout.\n\n### Setting Timeouts\n\n**MCP Tool:**\n```python\n{\n    \"timeout\": \"2h\"   # 2 hours\n}\n```\n\n**Supported formats:**\n- Integer/float: seconds (e.g., `300` = 5 minutes)\n- String with suffix: `\"5m\"` (minutes), `\"2h\"` (hours), `\"1d\"` (days)\n- Examples: `\"90m\"`, `\"2h\"`, `\"1.5h\"`, `300`, `\"1d\"`\n\n**Python API:**\n```python\nfrom huggingface_hub import run_job, run_uv_job\n\nrun_job(image=\"python:3.12\", command=[...], timeout=\"2h\")\nrun_uv_job(\"script.py\", timeout=7200)  # 2 hours in seconds\n```\n\n### Timeout Guidelines\n\n| Scenario | Recommended | Notes |\n|----------|-------------|-------|\n| Quick test | 10-30 min | Verify setup |\n| Data processing | 1-2 hours | Depends on data size |\n| Batch inference | 2-4 hours | Large batches |\n| Experiments | 4-8 hours | Multiple runs |\n| Long-running | 8-24 hours | Production workloads |\n\n**Always add 20-30% buffer** for setup, network delays, and cleanup.\n\n**On timeout:** Job killed immediately, all unsaved progress lost\n\n## Cost Estimation\n\n**General guidelines:**\n\n```\nTotal Cost = (Hours of runtime) × (Cost per hour)\n```\n\n**Example calculations:**\n\n**Quick test:**\n- Hardware: cpu-basic ($0.10/hour)\n- Time: 15 minutes (0.25 hours)\n- Cost: $0.03\n\n**Data processing:**\n- Hardware: l4x1 ($2.50/hour)\n- Time: 2 hours\n- Cost: $5.00\n\n**Batch inference:**\n- Hardware: a10g-large ($5/hour)\n- Time: 4 hours\n- Cost: $20.00\n\n**Cost optimization tips:**\n1. Start small - Test on cpu-basic or t4-small\n2. Monitor runtime - Set appropriate timeouts\n3. Use checkpoints - Resume if job fails\n4. Optimize code - Reduce unnecessary compute\n5. Choose right hardware - Don''t over-provision\n\n## Monitoring and Tracking\n\n### Check Job Status\n\n**MCP Tool:**\n```python\n# List all jobs\nhf_jobs(\"ps\")\n\n# Inspect specific job\nhf_jobs(\"inspect\", {\"job_id\": \"your-job-id\"})\n\n# View logs\nhf_jobs(\"logs\", {\"job_id\": \"your-job-id\"})\n\n# Cancel a job\nhf_jobs(\"cancel\", {\"job_id\": \"your-job-id\"})\n```\n\n**Python API:**\n```python\nfrom huggingface_hub import list_jobs, inspect_job, fetch_job_logs, cancel_job\n\n# List your jobs\njobs = list_jobs()\n\n# List running jobs only\nrunning = [j for j in list_jobs() if j.status.stage == \"RUNNING\"]\n\n# Inspect specific job\njob_info = inspect_job(job_id=\"your-job-id\")\n\n# View logs\nfor log in fetch_job_logs(job_id=\"your-job-id\"):\n    print(log)\n\n# Cancel a job\ncancel_job(job_id=\"your-job-id\")\n```\n\n**CLI:**\n```bash\nhf jobs ps                    # List jobs\nhf jobs logs <job-id>         # View logs\nhf jobs cancel <job-id>       # Cancel job\n```\n\n**Remember:** Wait for user to request status checks. Avoid polling repeatedly.\n\n### Job URLs\n\nAfter submission, jobs have monitoring URLs:\n```\nhttps://huggingface.co/jobs/username/job-id\n```\n\nView logs, status, and details in the browser.\n\n### Wait for Multiple Jobs\n\n```python\nimport time\nfrom huggingface_hub import inspect_job, run_job\n\n# Run multiple jobs\njobs = [run_job(image=img, command=cmd) for img, cmd in workloads]\n\n# Wait for all to complete\nfor job in jobs:\n    while inspect_job(job_id=job.id).status.stage not in (\"COMPLETED\", \"ERROR\"):\n        time.sleep(10)\n```\n\n## Scheduled Jobs\n\nRun jobs on a schedule using CRON expressions or predefined schedules.\n\n**MCP Tool:**\n```python\n# Schedule a UV script that runs every hour\nhf_jobs(\"scheduled uv\", {\n    \"script\": \"your_script.py\",\n    \"schedule\": \"@hourly\",\n    \"flavor\": \"cpu-basic\"\n})\n\n# Schedule with CRON syntax\nhf_jobs(\"scheduled uv\", {\n    \"script\": \"your_script.py\",\n    \"schedule\": \"0 9 * * 1\",  # 9 AM every Monday\n    \"flavor\": \"cpu-basic\"\n})\n\n# Schedule a Docker-based job\nhf_jobs(\"scheduled run\", {\n    \"image\": \"python:3.12\",\n    \"command\": [\"python\", \"-c\", \"print(''Scheduled!'')\"],\n    \"schedule\": \"@daily\",\n    \"flavor\": \"cpu-basic\"\n})\n```\n\n**Python API:**\n```python\nfrom huggingface_hub import create_scheduled_job, create_scheduled_uv_job\n\n# Schedule a Docker job\ncreate_scheduled_job(\n    image=\"python:3.12\",\n    command=[\"python\", \"-c\", \"print(''Running on schedule!'')\"],\n    schedule=\"@hourly\"\n)\n\n# Schedule a UV script\ncreate_scheduled_uv_job(\"my_script.py\", schedule=\"@daily\", flavor=\"cpu-basic\")\n\n# Schedule with GPU\ncreate_scheduled_uv_job(\n    \"ml_inference.py\",\n    schedule=\"0 */6 * * *\",  # Every 6 hours\n    flavor=\"a10g-small\"\n)\n```\n\n**Available schedules:**\n- `@annually`, `@yearly` - Once per year\n- `@monthly` - Once per month\n- `@weekly` - Once per week\n- `@daily` - Once per day\n- `@hourly` - Once per hour\n- CRON expression - Custom schedule (e.g., `\"*/5 * * * *\"` for every 5 minutes)\n\n**Manage scheduled jobs:**\n```python\n# MCP Tool\nhf_jobs(\"scheduled ps\")                              # List scheduled jobs\nhf_jobs(\"scheduled inspect\", {\"job_id\": \"...\"})     # Inspect details\nhf_jobs(\"scheduled suspend\", {\"job_id\": \"...\"})     # Pause\nhf_jobs(\"scheduled resume\", {\"job_id\": \"...\"})      # Resume\nhf_jobs(\"scheduled delete\", {\"job_id\": \"...\"})      # Delete\n```\n\n**Python API for management:**\n```python\nfrom huggingface_hub import (\n    list_scheduled_jobs,\n    inspect_scheduled_job,\n    suspend_scheduled_job,\n    resume_scheduled_job,\n    delete_scheduled_job\n)\n\n# List all scheduled jobs\nscheduled = list_scheduled_jobs()\n\n# Inspect a scheduled job\ninfo = inspect_scheduled_job(scheduled_job_id)\n\n# Suspend (pause) a scheduled job\nsuspend_scheduled_job(scheduled_job_id)\n\n# Resume a scheduled job\nresume_scheduled_job(scheduled_job_id)\n\n# Delete a scheduled job\ndelete_scheduled_job(scheduled_job_id)\n```\n\n## Webhooks: Trigger Jobs on Events\n\nTrigger jobs automatically when changes happen in Hugging Face repositories.\n\n**Python API:**\n```python\nfrom huggingface_hub import create_webhook\n\n# Create webhook that triggers a job when a repo changes\nwebhook = create_webhook(\n    job_id=job.id,\n    watched=[\n        {\"type\": \"user\", \"name\": \"your-username\"},\n        {\"type\": \"org\", \"name\": \"your-org-name\"}\n    ],\n    domains=[\"repo\", \"discussion\"],\n    secret=\"your-secret\"\n)\n```\n\n**How it works:**\n1. Webhook listens for changes in watched repositories\n2. When triggered, the job runs with `WEBHOOK_PAYLOAD` environment variable\n3. Your script can parse the payload to understand what changed\n\n**Use cases:**\n- Auto-process new datasets when uploaded\n- Trigger inference when models are updated\n- Run tests when code changes\n- Generate reports on repository activity\n\n**Access webhook payload in script:**\n```python\nimport os\nimport json\n\npayload = json.loads(os.environ.get(\"WEBHOOK_PAYLOAD\", \"{}\"))\nprint(f\"Event type: {payload.get(''event'', {}).get(''action'')}\")\n```\n\nSee [Webhooks Documentation](https://huggingface.co/docs/huggingface_hub/guides/webhooks) for more details.\n\n## Common Workload Patterns\n\nThis repository ships ready-to-run UV scripts in `hf-jobs/scripts/`. Prefer using them instead of inventing new templates.\n\n### Pattern 1: Dataset → Model Responses (vLLM) — `scripts/generate-responses.py`\n\n**What it does:** loads a Hub dataset (chat `messages` or a `prompt` column), applies a model chat template, generates responses with vLLM, and **pushes** the output dataset + dataset card back to the Hub.\n\n**Requires:** GPU + **write** token (it pushes a dataset).\n\n```python\nfrom pathlib import Path\n\nscript = Path(\"hf-jobs/scripts/generate-responses.py\").read_text()\nhf_jobs(\"uv\", {\n    \"script\": script,\n    \"script_args\": [\n        \"username/input-dataset\",\n        \"username/output-dataset\",\n        \"--messages-column\", \"messages\",\n        \"--model-id\", \"Qwen/Qwen3-30B-A3B-Instruct-2507\",\n        \"--temperature\", \"0.7\",\n        \"--top-p\", \"0.8\",\n        \"--max-tokens\", \"2048\",\n    ],\n    \"flavor\": \"a10g-large\",\n    \"timeout\": \"4h\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"},\n})\n```\n\n### Pattern 2: CoT Self-Instruct Synthetic Data — `scripts/cot-self-instruct.py`\n\n**What it does:** generates synthetic prompts/answers via CoT Self-Instruct, optionally filters outputs (answer-consistency / RIP), then **pushes** the generated dataset + dataset card to the Hub.\n\n**Requires:** GPU + **write** token (it pushes a dataset).\n\n```python\nfrom pathlib import Path\n\nscript = Path(\"hf-jobs/scripts/cot-self-instruct.py\").read_text()\nhf_jobs(\"uv\", {\n    \"script\": script,\n    \"script_args\": [\n        \"--seed-dataset\", \"davanstrien/s1k-reasoning\",\n        \"--output-dataset\", \"username/synthetic-math\",\n        \"--task-type\", \"reasoning\",\n        \"--num-samples\", \"5000\",\n        \"--filter-method\", \"answer-consistency\",\n    ],\n    \"flavor\": \"l4x4\",\n    \"timeout\": \"8h\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"},\n})\n```\n\n### Pattern 3: Streaming Dataset Stats (Polars + HF Hub) — `scripts/finepdfs-stats.py`\n\n**What it does:** scans parquet directly from Hub (no 300GB download), computes temporal stats, and (optionally) uploads results to a Hub dataset repo.\n\n**Requires:** CPU is often enough; token needed **only** if you pass `--output-repo` (upload).\n\n```python\nfrom pathlib import Path\n\nscript = Path(\"hf-jobs/scripts/finepdfs-stats.py\").read_text()\nhf_jobs(\"uv\", {\n    \"script\": script,\n    \"script_args\": [\n        \"--limit\", \"10000\",\n        \"--show-plan\",\n        \"--output-repo\", \"username/finepdfs-temporal-stats\",\n    ],\n    \"flavor\": \"cpu-upgrade\",\n    \"timeout\": \"2h\",\n    \"env\": {\"HF_XET_HIGH_PERFORMANCE\": \"1\"},\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"},\n})\n```\n\n## Common Failure Modes\n\n### Out of Memory (OOM)\n\n**Fix:**\n1. Reduce batch size or data chunk size\n2. Process data in smaller batches\n3. Upgrade hardware: cpu → t4 → a10g → a100\n\n### Job Timeout\n\n**Fix:**\n1. Check logs for actual runtime\n2. Increase timeout with buffer: `\"timeout\": \"3h\"`\n3. Optimize code for faster execution\n4. Process data in chunks\n\n### Hub Push Failures\n\n**Fix:**\n1. Add to job: `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}`\n2. Verify token in script: `assert \"HF_TOKEN\" in os.environ`\n3. Check token permissions\n4. Verify repo exists or can be created\n\n### Missing Dependencies\n\n**Fix:**\nAdd to PEP 723 header:\n```python\n# /// script\n# dependencies = [\"package1\", \"package2>=1.0.0\"]\n# ///\n```\n\n### Authentication Errors\n\n**Fix:**\n1. Check `hf_whoami()` works locally\n2. Verify `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}` in job config\n3. Re-login: `hf auth login`\n4. Check token has required permissions\n\n## Troubleshooting\n\n**Common issues:**\n- Job times out → Increase timeout, optimize code\n- Results not saved → Check persistence method, verify HF_TOKEN\n- Out of Memory → Reduce batch size, upgrade hardware\n- Import errors → Add dependencies to PEP 723 header\n- Authentication errors → Check token, verify secrets parameter\n\n**See:** `references/troubleshooting.md` for complete troubleshooting guide\n\n## Resources\n\n### References (In This Skill)\n- `references/token_usage.md` - Complete token usage guide\n- `references/hardware_guide.md` - Hardware specs and selection\n- `references/hub_saving.md` - Hub persistence guide\n- `references/troubleshooting.md` - Common issues and solutions\n\n### Scripts (In This Skill)\n- `scripts/generate-responses.py` - vLLM batch generation: dataset → responses → push to Hub\n- `scripts/cot-self-instruct.py` - CoT Self-Instruct synthetic data generation + filtering → push to Hub\n- `scripts/finepdfs-stats.py` - Polars streaming stats over `finepdfs-edu` parquet on Hub (optional push)\n\n### External Links\n\n**Official Documentation:**\n- [HF Jobs Guide](https://huggingface.co/docs/huggingface_hub/guides/jobs) - Main documentation\n- [HF Jobs CLI Reference](https://huggingface.co/docs/huggingface_hub/guides/cli#hf-jobs) - Command line interface\n- [HF Jobs API Reference](https://huggingface.co/docs/huggingface_hub/package_reference/hf_api) - Python API details\n- [Hardware Flavors Reference](https://huggingface.co/docs/hub/en/spaces-config-reference) - Available hardware\n\n**Related Tools:**\n- [UV Scripts Guide](https://docs.astral.sh/uv/guides/scripts/) - PEP 723 inline dependencies\n- [UV Scripts Organization](https://huggingface.co/uv-scripts) - Community UV script collection\n- [HF Hub Authentication](https://huggingface.co/docs/huggingface_hub/quick-start#authentication) - Token setup\n- [Webhooks Documentation](https://huggingface.co/docs/huggingface_hub/guides/webhooks) - Event triggers\n\n## Key Takeaways\n\n1. **Submit scripts inline** - The `script` parameter accepts Python code directly; no file saving required unless user requests\n2. **Jobs are asynchronous** - Don''t wait/poll; let user check when ready\n3. **Always set timeout** - Default 30 min may be insufficient; set appropriate timeout\n4. **Always persist results** - Environment is ephemeral; without persistence, all work is lost\n5. **Use tokens securely** - Always use `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}` for Hub operations\n6. **Choose appropriate hardware** - Start small, scale up based on needs (see hardware guide)\n7. **Use UV scripts** - Default to `hf_jobs(\"uv\", {...})` with inline scripts for Python workloads\n8. **Handle authentication** - Verify tokens are available before Hub operations\n9. **Monitor jobs** - Provide job URLs and status check commands\n10. **Optimize costs** - Choose right hardware, set appropriate timeouts\n\n## Quick Reference: MCP Tool vs CLI vs Python API\n\n| Operation | MCP Tool | CLI | Python API |\n|-----------|----------|-----|------------|\n| Run UV script | `hf_jobs(\"uv\", {...})` | `hf jobs uv run script.py` | `run_uv_job(\"script.py\")` |\n| Run Docker job | `hf_jobs(\"run\", {...})` | `hf jobs run image cmd` | `run_job(image, command)` |\n| List jobs | `hf_jobs(\"ps\")` | `hf jobs ps` | `list_jobs()` |\n| View logs | `hf_jobs(\"logs\", {...})` | `hf jobs logs <id>` | `fetch_job_logs(job_id)` |\n| Cancel job | `hf_jobs(\"cancel\", {...})` | `hf jobs cancel <id>` | `cancel_job(job_id)` |\n| Schedule UV | `hf_jobs(\"scheduled uv\", {...})` | - | `create_scheduled_uv_job()` |\n| Schedule Docker | `hf_jobs(\"scheduled run\", {...})` | - | `create_scheduled_job()` |\n\n"},"category":"official","lastSynced":"2026-03-06T05:36:55.720Z","seo":{"title":{"en":"hugging-face-jobs: Run Workloads on Hugging Face Infrastr...","es":"Guía de configuración de Hugging Face Jobs para cargas de...","fr":"Guide de mise en place de Hugging Face Jobs pour les char...","de":"Einrichtungsleitfaden für Hugging Face Jobs zur Ausführun...","pt":"Guia de Configuração do Hugging Face Jobs para Workloads ...","ru":"Настройка ИИ Агентов Hugging Face Jobs для Вычислительных...","ar":"دليل إعداد هوجينغ فايس جوبز لتحميلات العمل الإصطناعي"},"description":{"en":"Discover how to run any workload on Hugging Face Jobs infrastructure. Learn to leverage cloud CPUs, GPUs, and TPUs for data processing, inference, and model ...","es":"Aprende a ejecutar cargas de trabajo de AI en la infraestructura de Hugging Face Jobs, incluyendo scripts UV, trabajos basados en Docker y selección de hardware","fr":"Découvrez comment exécuter des charges de travail d''IA sur l''infrastructure Hugging Face Jobs, y compris les scripts UV, les travaux basés sur Docker et la s...","de":"Erfahren Sie, wie Sie KI-Workloads auf der Hugging Face Jobs-Infrastruktur ausführen, einschließlich UV-Skripten, Docker-basierten Jobs und Hardware-Auswahl","pt":"Execute workloads de IA no Hugging Face Jobs, incluindo processamento de dados, inferência em lote e treinamento de modelos","ru":"Выполните вычислительные задачи ИИ на инфраструктуре Hugging Face Jobs, включая обработку данных, пакетную инференцию и обучение моделей","ar":"تشغيل تحميلات العمل الإصطناعي على هوجينغ فايس جوبز، بما في ذلك معالجة البيانات والاستدلال الدفعي ودمج النماذج"},"definition":{"en":"hugging-face-jobs is a skill that allows users to run workloads on fully managed Hugging Face infrastructure, covering UV scripts, Docker-based jobs, and hardware selection.","es":"Hugging Face Jobs es una infraestructura de computación en la nube para ejecutar cargas de trabajo de AI, incluyendo scripts UV y trabajos basados en Docker","fr":"Hugging Face Jobs est une infrastructure de calcul cloud pour exécuter des charges de travail d''IA, y compris des scripts UV et des travaux basés sur Docker","de":"Hugging Face Jobs ist eine Cloud-Computing-Infrastruktur zur Ausführung von KI-Workloads, einschließlich UV-Skripten und Docker-basierten Jobs","pt":"O que é Hugging Face Jobs? Uma infraestrutura de computação em nuvem para executar workloads de IA","ru":"Что такое ИИ Агенты Hugging Face Jobs? Инфраструктура облачного вычисления для выполнения задач ИИ","ar":"ما هو هوجينغ فايس جوبز؟ بنية حوسبة سحابية لتشغيل تحميلات العمل الإصطناعي"},"features":{"en":["Supports running UV scripts and Docker-based jobs on Hugging Face infrastructure","Enables hardware selection, including cloud CPUs, GPUs, and TPUs","Allows for cost estimation, authentication with tokens, and secrets management","Provides timeout configuration and result persistence to the Hugging Face Hub","Facilitates data processing, batch inference, and model training tasks","Supports reproducible ML experiments and benchmarks"],"es":["Ejecución de scripts UV y trabajos basados en Docker","Selección de hardware para optimizar el rendimiento","Estimación de costos para controlar los gastos","Autenticación con tokens para asegurar el acceso","Gestión de secretos para proteger la información confidencial","Configuración de timeout para evitar trabajos colgados"],"fr":["Exécution de scripts UV et de travaux basés sur Docker","Sélection de matériel pour optimiser les performances","Estimation des coûts pour contrôler les dépenses","Authentification avec des tokens pour assurer l''accès","Gestion des secrets pour protéger les informations confidentielles","Configuration de timeout pour éviter les travaux bloqués"],"de":["Ausführung von UV-Skripten und Docker-basierten Jobs","Hardware-Auswahl für optimierte Leistung","Kostenabschätzung für Kostenkontrolle","Authentifizierung mit Tokens für sicheren Zugriff","Geheimnisverwaltung für den Schutz vertraulicher Informationen","Timeout-Konfiguration für verhindern von hängenden Jobs"],"pt":["Suporte a scripts UV","Suporte a jobs baseados em Docker","Seleção de hardware","Estimativa de custo","Autenticação com tokens","Gerenciamento de segredos"],"ru":["Поддержка скриптов UV","Поддержка задач на основе Docker","Выбор аппаратного обеспечения","Оценка стоимости","Аутентификация по токенам","Управление секретами"],"ar":["دعم سكريبتات UV","دعم مهام قائمة على Docker","اختيار الأجهزة","تقدير التكلفة","التحقق من الهوية بواسطة رموز","إدارة الأسرار"]},"keywords":{"en":["how to use hugging-face-jobs","hugging-face-jobs setup guide","hugging-face-jobs alternative","hugging-face-jobs vs AWS SageMaker","hugging-face-jobs install","what is hugging-face-jobs","hugging-face-jobs for data processing","hugging-face-jobs for model training","hugging-face-jobs infrastructure","hugging-face-jobs cloud compute"],"es":["Hugging Face Jobs","cargas de trabajo de AI","infraestructura de computación en la nube","scripts UV","trabajos basados en Docker","selección de hardware","estimación de costos","autenticación con tokens","gestión de secretos"],"fr":["Hugging Face Jobs","charges de travail d''IA","infrastructure de calcul cloud","scripts UV","travaux basés sur Docker","sélection de matériel","estimation des coûts","authentification avec des tokens","gestion des secrets"],"de":["Hugging Face Jobs","KI-Workloads","Cloud-Computing-Infrastruktur","UV-Skripte","Docker-basierte Jobs","Hardware-Auswahl","Kostenabschätzung","Authentifizierung mit Tokens","Geheimnisverwaltung"],"pt":["hugging face jobs","workloads de ia","processamento de dados","inferência em lote","treinamento de modelos","computação em nuvem","ia em nuvem","hugging face hub"],"ru":["ИИ Агенты Hugging Face Jobs","задачи ИИ","обработка данных","пакетная инференция","обучение моделей","облачные вычисления","ИИ в облаке","Hugging Face Hub"],"ar":["هوجينغ فايس جوبز","تحميلات العمل الإصطناعي","معالجة البيانات","الاستدلال الدفعي","دمج النماذج","حوسبة سحابية","الإصطناعي في السحابة","هوجينغ فايس هاب"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing to run general-purpose compute workloads on Hugging Face Jobs infrastructure, including data processing, inference, and model training.","zh":"适合需要在 Hugging Face Jobs 基础设施上运行通用计算工作负载的 AI Agents，包括数据处理、推理和模型训练。","ja":"Hugging Face Jobs インフラストラクチャ上で一般的なコンピュート ワークロードを実行する必要がある AI エージェントに適しています。データ処理、推論、およびモデル トレーニングが含まれます。","ko":"Hugging Face Jobs 인프라스트럭처에서 일반적인 컴퓨팅 워크로드를 실행해야 하는 AI 에이전트에 적합합니다. 데이터 처리, 추론 및 모델 훈련이 포함됩니다.","es":"Perfecto para agentes de IA que necesitan ejecutar cargas de trabajo de cómputo de propósito general en la infraestructura de Hugging Face Jobs, incluyendo el procesamiento de datos, la inferencia y el entrenamiento de modelos.","fr":"Parfait pour les agents IA qui ont besoin d''exécuter des charges de travail de calcul polyvalentes sur l''infrastructure Hugging Face Jobs, y compris le traitement de données, l''inférence et la formation de modèles.","de":"Perfekt für KI-Agents, die allgemeine Rechenworkloads auf der Hugging Face Jobs-Infrastruktur ausführen müssen, einschließlich Datenverarbeitung, Inferenz und Modelltraining.","pt":"Perfeito para Agentes de IA que precisam executar cargas de trabalho de computação de propósito geral na infraestrutura de Hugging Face Jobs, incluindo processamento de dados, inferência e treinamento de modelos.","ru":"Идеально для агентов ИИ, которым необходимо запускать вычислительные рабочие нагрузки общего назначения в инфраструктуре Hugging Face Jobs, включая обработку данных, вывод и обучение моделей.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى تشغيل حمولة من الحوسبة العامة في بنية تحتية Hugging Face Jobs، بما في ذلك معالجة البيانات والاستدلال وتدريب النماذج."},"recommendation":{"en":"Empowers agents to execute UV scripts, Docker-based jobs, and Python-based tasks on cloud CPUs, GPUs, or TPUs, with features like hardware selection, cost estimation, authentication with tokens, and result persistence to the Hugging Face Hub.","zh":"赋予代理执行 UV 脚本、基于 Docker 的作业和基于 Python 的任务的能力，使用云 CPU、GPU 或 TPU，并具有硬件选择、成本估算、使用令牌进行身份验证和结果持久性到 Hugging Face Hub 等功能。","ja":"UV スクリプト、Docker ベースのジョブ、Python ベースのタスクをクラウド CPU、GPU、または TPU 上で実行する機能をエージェントに与え、ハードウェアの選択、コストの推定、トークンによる認証、Hugging Face Hub への結果の永続化などの機能を提供します。","ko":"클라우드 CPU, GPU 또는 TPU에서 UV 스크립트, Docker 기반 작업 및 Python 기반 작업을 실행할 수 있는 기능을 에이전트에게 부여하며, 하드웨어 선택, 비용 추정, 토큰을 사용한 인증 및 Hugging Face Hub에 대한 결과 지속성 등의 기능을 제공합니다.","es":"Habilita a los agentes a ejecutar scripts UV, trabajos basados en Docker y tareas basadas en Python en CPUs, GPUs o TPUs en la nube, con características como la selección de hardware, la estimación de costos, la autenticación con tokens y la persistencia de resultados en el Hugging Face Hub.","fr":"Permet aux agents d''exécuter des scripts UV, des travaux basés sur Docker et des tâches basées sur Python sur des CPUs, GPUs ou TPUs dans le cloud, avec des fonctionnalités comme la sélection du matériel, l''estimation des coûts, l''authentification avec des tokens et la persistance des résultats vers le Hugging Face Hub.","de":"Ermöglicht es Agents, UV-Skripte, Docker-basierte Jobs und Python-basierte Aufgaben auf Cloud-CPUs, -GPUs oder -TPUs auszuführen, mit Funktionen wie Hardware-Auswahl, Kostenabschätzung, Authentifizierung mit Tokens und Ergebnispersistenz im Hugging Face Hub.","pt":"Permite que os agentes executem scripts UV, trabalhos baseados em Docker e tarefas baseadas em Python em CPUs, GPUs ou TPUs em nuvem, com recursos como seleção de hardware, estimativa de custo, autenticação com tokens e persistência de resultados para o Hugging Face Hub.","ru":"Позволяет агентам выполнять скрипты UV, задания на основе Docker и задачи на основе Python на облачных CPU, GPU или TPU, с функциями seperti выбор оборудования, оценка стоимости, аутентификация с помощью токенов и сохранение результатов в Hugging Face Hub.","ar":"يسمح للعملاء بتنفيذ سكريبتات UV ووظائف تستند إلى Docker ومهام تستند إلى Python على وحدات المعالجة المركزية السحابية أو وحدات معالجة الرسومات أو وحدات معالجة التензور، مع ميزات مثل اختيار الأجهزة وتقدير التكلفة والتحقق من الصحة باستخدام الرموز والاستمرار في النتائج إلى مركز Hugging Face."},"useCases":{"en":["Running batch inference on large datasets","Executing reproducible ML experiments and benchmarks","Fine-tuning models on Hugging Face infrastructure without local setup"],"zh":["在大型数据集上运行批处理推理","执行可复现的 ML 实验和基准测试","在 Hugging Face 基础设施上对模型进行微调而无需本地设置"],"ja":["大規模なデータセットでバッチ推論を実行する","再現可能な ML 実験およびベンチマークを実行する","ローカル設定不要で Hugging Face インフラストラクチャ上でモデルを微調整する"],"ko":["대규모 데이터셋에서 배치 추론을 실행하는 것","재현 가능한 ML 실험 및 벤치마크를 실행하는 것","로컬 설정 없이 Hugging Face 인프라스트럭처에서 모델을 미세 조정하는 것"],"es":["Ejecución de inferencia por lotes en grandes conjuntos de datos","Ejecución de experimentos y benchmarks de ML reproducibles","Ajuste fino de modelos en la infraestructura de Hugging Face sin configuración local"],"fr":["Exécution de l''inférence par lots sur de grands ensembles de données","Exécution d''expériences et de benchmarks de ML reproductibles","Réglage fin de modèles sur l''infrastructure Hugging Face sans configuration locale"],"de":["Ausführung von Batch-Inferenz auf großen Datensätzen","Ausführung von reproduzierbaren ML-Experimenten und Benchmarks","Feinabstimmung von Modellen auf der Hugging Face-Infrastruktur ohne lokale Einrichtung"],"pt":["Execução de inferência em lotes em grandes conjuntos de dados","Execução de experimentos e benchmarks de ML reprodutíveis","Ajuste fino de modelos na infraestrutura do Hugging Face sem configuração local"],"ru":["Запуск пакетной инференции на больших наборах данных","Выполнение воспроизводимых экспериментов и бенчмарков ML","Настройка моделей на инфраструктуре Hugging Face без локальной настройки"],"ar":["تشغيل الاستدلال الدفعي على مجموعات بيانات كبيرة","تنفيذ تجارب ومراجع قابلة للتكرار لتعلم الآلة","ضبط دقيق للنماذج في بنية تحتية Hugging Face دون إعداد محلي"]},"limitations":{"en":["Requires authentication with tokens","Dependent on Hugging Face Jobs infrastructure availability","Limited to Python-based tasks and UV scripts"],"zh":["需要使用令牌进行身份验证","依赖于 Hugging Face Jobs 基础设施的可用性","仅限于基于 Python 的任务和 UV 脚本"],"ja":["トークンによる認証が必要","Hugging Face Jobs インフラストラクチャの可用性に依存","Python ベースのタスクと UV スクリプトのみに限定"],"ko":["토큰을 사용한 인증이 필요합니다","Hugging Face Jobs 인프라스트럭처의 가용성에 종속됩니다","Python 기반 작업 및 UV 스크립트에만 제한됩니다"],"es":["Requiere autenticación con tokens","Depende de la disponibilidad de la infraestructura de Hugging Face Jobs","Limitado a tareas basadas en Python y scripts UV"],"fr":["Nécessite une authentification avec des tokens","Dépend de la disponibilité de l''infrastructure Hugging Face Jobs","Limité à des tâches basées sur Python et des scripts UV"],"de":["Erfordert Authentifizierung mit Tokens","Hängt von der Verfügbarkeit der Hugging Face Jobs-Infrastruktur ab","Begrenzt auf Python-basierte Aufgaben und UV-Skripte"],"pt":["Exige autenticação com tokens","Depende da disponibilidade da infraestrutura de Hugging Face Jobs","Limitado a tarefas baseadas em Python e scripts UV"],"ru":["Требует аутентификации с помощью токенов","Зависит от доступности инфраструктуры Hugging Face Jobs","Ограничен задачами на основе Python и скриптами UV"],"ar":["يتطلب التحقق من الصحة باستخدام الرموز","يعتمد على توافر بنية تحتية Hugging Face Jobs","محدود بمهام تستند إلى Python وسكريبتات UV"]},"version":4},"contentHash":"a4e697cc1d5ffa293c537473f96efc570e24d698434829c9eb430a1cf099e469","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":95}');
