INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-jobs', 'hugging-face-jobs', 'huggingface', 'skills', 'official', 'hugging-face-jobs huggingface skills official The hugging-face-jobs skill enables users to run general-purpose compute workloads on Hugging Face infrastructure, supporting tasks like data processing, batch inference, and model training. This skill benefits developers and data scientists working with Python-based tasks and cloud compute. Hugging Face Jobs permite ejecutar cargas de trabajo de AI en la nube sin configuración local, incluyendo procesamiento de datos, inferencia por lotes y experimentos Hugging Face Jobs permet d''exécuter des charges de travail d''IA dans le cloud sans configuration locale, y compris le traitement de données, l''inférence par lots et les expériences Hugging Face Jobs ermöglicht die Ausführung von KI-Workloads in der Cloud ohne lokale Konfiguration, einschließlich Datenverarbeitung, Batch-Inferenz und Experimenten O Hugging Face Jobs é uma infraestrutura de computação em nuvem para executar workloads de IA, incluindo processamento de dados e treinamento de modelos ИИ Агенты Hugging Face Jobs представляют собой инфраструктуру облачного вычисления для выполнения задач ИИ, включая обработку данных и обучение моделей هوجينغ فايس جوبز هو بنية حوسبة سحابية لتشغيل تحميلات العمل الإصطناعي، بما في ذلك معالجة البيانات ودمج النماذج how to use hugging-face-jobs hugging-face-jobs setup guide hugging-face-jobs alternative hugging-face-jobs vs AWS SageMaker hugging-face-jobs install what is hugging-face-jobs hugging-face-jobs for data processing hugging-face-jobs for model training hugging-face-jobs infrastructure hugging-face-jobs cloud compute Supports running UV scripts and Docker-based jobs on Hugging Face infrastructure Enables hardware selection, including cloud CPUs, GPUs, and TPUs Allows for cost estimation, authentication with tokens, and secrets management Provides timeout configuration and result persistence to the Hugging Face Hub Facilitates data processing, batch inference, and model training tasks Supports reproducible ML experiments and benchmarks hugging-face-jobs is a skill that allows users to run workloads on fully managed Hugging Face infrastructure, covering UV scripts, Docker-based jobs, and hardware selection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-model-trainer', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-model-trainer', 8290, 490, 95, '2026-03-06T05:28:53Z', '2026-03-06T05:37:58.999Z', '4a0d1a94f8755c9671f8addb44735d374163ecff839ffe685b8a52adcaca026e', '{"id":"huggingface/skills/hugging-face-model-trainer","name":"hugging-face-model-trainer","description":{"en":"The hugging-face-model-trainer skill enables developers to train language models using Transformer Reinforcement Learning (TRL) on Hugging Face Jobs, supporting methods like SFT, DPO, and GRPO. It benefits AI and machine learning developers seeking to fine-tune models on cloud GPUs.","es":"Entrena modelos de lenguaje con TRL en Hugging Face Jobs sin necesidad de configuración local de GPU. Aprende sobre SFT, DPO, GRPO y más","fr":"Entraînez des modèles de langage avec TRL sur Hugging Face Jobs sans configuration GPU locale. Découvrez SFT, DPO, GRPO et plus","de":"Trainieren Sie Sprachmodelle mit TRL auf Hugging Face Jobs ohne lokale GPU-Konfiguration. Erfahren Sie mehr über SFT, DPO, GRPO und mehr","pt":"O hugging-face-model-trainer é uma habilidade para treinar modelos de linguagem com TRL no Hugging Face Jobs, sem necessidade de configuração de GPU local.","ru":"Hugging-face-model-trainer - это навык для обучения языковых моделей с помощью TRL на Hugging Face Jobs без локальной настройки GPU для ИИ Агенты","ar":"هو هوجنج-فيس-مودل-تراينر مهارة لتدريب نماذج اللغة باستخدام TRL على Hugging Face Jobs بدون إعداد محلي لجهاز GPU لنماذج اللغة الإصطناعية"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-model-trainer","description":"This skill should be used when users want to train or fine-tune language models using TRL (Transformer Reinforcement Learning) on Hugging Face Jobs infrastructure. Covers SFT, DPO, GRPO and reward modeling training methods, plus GGUF conversion for local deployment. Includes guidance on the TRL Jobs package, UV scripts with PEP 723 format, dataset preparation and validation, hardware selection, cost estimation, Trackio monitoring, Hub authentication, and model persistence. Should be invoked for tasks involving cloud GPU training, GGUF conversion, or when users mention training on Hugging Face Jobs without local GPU setup.","bodyPreview":"# TRL Training on Hugging Face Jobs\n\n## Overview\n\nTrain language models using TRL (Transformer Reinforcement Learning) on fully managed Hugging Face infrastructure. No local GPU setup required—models train on cloud GPUs and results are automatically saved to the Hugging Face Hub.\n\n**TRL provides multiple training methods:**\n- **SFT** (Supervised Fine-Tuning) - Standard instruction tuning\n- **DPO** (Direct Preference Optimization) - Alignment from preference data\n- **GRPO** (Group Relative Policy","body":"# TRL Training on Hugging Face Jobs\n\n## Overview\n\nTrain language models using TRL (Transformer Reinforcement Learning) on fully managed Hugging Face infrastructure. No local GPU setup required—models train on cloud GPUs and results are automatically saved to the Hugging Face Hub.\n\n**TRL provides multiple training methods:**\n- **SFT** (Supervised Fine-Tuning) - Standard instruction tuning\n- **DPO** (Direct Preference Optimization) - Alignment from preference data\n- **GRPO** (Group Relative Policy Optimization) - Online RL training\n- **Reward Modeling** - Train reward models for RLHF\n\n**For detailed TRL method documentation:**\n```python\nhf_doc_search(\"your query\", product=\"trl\")\nhf_doc_fetch(\"https://huggingface.co/docs/trl/sft_trainer\")  # SFT\nhf_doc_fetch(\"https://huggingface.co/docs/trl/dpo_trainer\")  # DPO\n# etc.\n```\n\n**See also:** `references/training_methods.md` for method overviews and selection guidance\n\n## When to Use This Skill\n\nUse this skill when users want to:\n- Fine-tune language models on cloud GPUs without local infrastructure\n- Train with TRL methods (SFT, DPO, GRPO, etc.)\n- Run training jobs on Hugging Face Jobs infrastructure\n- Convert trained models to GGUF for local deployment (Ollama, LM Studio, llama.cpp)\n- Ensure trained models are permanently saved to the Hub\n- Use modern workflows with optimized defaults\n\n### When to Use Unsloth\n\nUse **Unsloth** (`references/unsloth.md`) instead of standard TRL when:\n- **Limited GPU memory** - Unsloth uses ~60% less VRAM\n- **Speed matters** - Unsloth is ~2x faster\n- Training **large models (>13B)** - memory efficiency is critical\n- Training **Vision-Language Models (VLMs)** - Unsloth has `FastVisionModel` support\n\nSee `references/unsloth.md` for complete Unsloth documentation and `scripts/unsloth_sft_example.py` for a production-ready training script.\n\n## Key Directives\n\nWhen assisting with training jobs:\n\n1. **ALWAYS use `hf_jobs()` MCP tool** - Submit jobs using `hf_jobs(\"uv\", {...})`, NOT bash `trl-jobs` commands. The `script` parameter accepts Python code directly. Do NOT save to local files unless the user explicitly requests it. Pass the script content as a string to `hf_jobs()`. If user asks to \"train a model\", \"fine-tune\", or similar requests, you MUST create the training script AND submit the job immediately using `hf_jobs()`.\n\n2. **Always include Trackio** - Every training script should include Trackio for real-time monitoring. Use example scripts in `scripts/` as templates.\n\n3. **Provide job details after submission** - After submitting, provide job ID, monitoring URL, estimated time, and note that the user can request status checks later.\n\n4. **Use example scripts as templates** - Reference `scripts/train_sft_example.py`, `scripts/train_dpo_example.py`, etc. as starting points.\n\n## Local Script Dependencies\n\nTo run scripts locally (like `estimate_cost.py`), install dependencies:\n```bash\npip install -r requirements.txt\n```\n\n## Prerequisites Checklist\n\nBefore starting any training job, verify:\n\n### ✅ **Account & Authentication**\n- Hugging Face Account with [Pro](https://hf.co/pro), [Team](https://hf.co/enterprise), or [Enterprise](https://hf.co/enterprise) plan (Jobs require paid plan)\n- Authenticated login: Check with `hf_whoami()`\n- **HF_TOKEN for Hub Push** ⚠️ CRITICAL - Training environment is ephemeral, must push to Hub or ALL training results are lost\n- Token must have write permissions  \n- **MUST pass `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}` in job config** to make token available (the `$HF_TOKEN` syntax\n  references your actual token value)\n\n### ✅ **Dataset Requirements**\n- Dataset must exist on Hub or be loadable via `datasets.load_dataset()`\n- Format must match training method (SFT: \"messages\"/text/prompt-completion; DPO: chosen/rejected; GRPO: prompt-only)\n- **ALWAYS validate unknown datasets** before GPU training to prevent format failures (see Dataset Validation section below)\n- Size appropriate for hardware (Demo: 50-100 examples on t4-small; Production: 1K-10K+ on a10g-large/a100-large)\n\n### ⚠️ **Critical Settings**\n- **Timeout must exceed expected training time** - Default 30min is TOO SHORT for most training. Minimum recommended: 1-2 hours. Job fails and loses all progress if timeout is exceeded.\n- **Hub push must be enabled** - Config: `push_to_hub=True`, `hub_model_id=\"username/model-name\"`; Job: `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}`\n\n## Asynchronous Job Guidelines\n\n**⚠️ IMPORTANT: Training jobs run asynchronously and can take hours**\n\n### Action Required\n\n**When user requests training:**\n1. **Create the training script** with Trackio included (use `scripts/train_sft_example.py` as template)\n2. **Submit immediately** using `hf_jobs()` MCP tool with script content inline - don''t save to file unless user requests\n3. **Report submission** with job ID, monitoring URL, and estimated time\n4. **Wait for user** to request status checks - don''t poll automatically\n\n### Ground Rules\n- **Jobs run in background** - Submission returns immediately; training continues independently\n- **Initial logs delayed** - Can take 30-60 seconds for logs to appear\n- **User checks status** - Wait for user to request status updates\n- **Avoid polling** - Check logs only on user request; provide monitoring links instead\n\n### After Submission\n\n**Provide to user:**\n- ✅ Job ID and monitoring URL\n- ✅ Expected completion time\n- ✅ Trackio dashboard URL\n- ✅ Note that user can request status checks later\n\n**Example Response:**\n```\n✅ Job submitted successfully!\n\nJob ID: abc123xyz\nMonitor: https://huggingface.co/jobs/username/abc123xyz\n\nExpected time: ~2 hours\nEstimated cost: ~$10\n\nThe job is running in the background. Ask me to check status/logs when ready!\n```\n\n## Quick Start: Three Approaches\n\n**💡 Tip for Demos:** For quick demos on smaller GPUs (t4-small), omit `eval_dataset` and `eval_strategy` to save ~40% memory. You''ll still see training loss and learning progress.\n\n### Sequence Length Configuration\n\n**TRL config classes use `max_length` (not `max_seq_length`)** to control tokenized sequence length:\n\n```python\n# ✅ CORRECT - If you need to set sequence length\nSFTConfig(max_length=512)   # Truncate sequences to 512 tokens\nDPOConfig(max_length=2048)  # Longer context (2048 tokens)\n\n# ❌ WRONG - This parameter doesn''t exist\nSFTConfig(max_seq_length=512)  # TypeError!\n```\n\n**Default behavior:** `max_length=1024` (truncates from right). This works well for most training.\n\n**When to override:**\n- **Longer context**: Set higher (e.g., `max_length=2048`)\n- **Memory constraints**: Set lower (e.g., `max_length=512`)\n- **Vision models**: Set `max_length=None` (prevents cutting image tokens)\n\n**Usually you don''t need to set this parameter at all** - the examples below use the sensible default.\n\n### Approach 1: UV Scripts (Recommended—Default Choice)\n\nUV scripts use PEP 723 inline dependencies for clean, self-contained training. **This is the primary approach for Claude Code.**\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"\"\"\n# /// script\n# dependencies = [\"trl>=0.12.0\", \"peft>=0.7.0\", \"trackio\"]\n# ///\n\nfrom datasets import load_dataset\nfrom peft import LoraConfig\nfrom trl import SFTTrainer, SFTConfig\nimport trackio\n\ndataset = load_dataset(\"trl-lib/Capybara\", split=\"train\")\n\n# Create train/eval split for monitoring\ndataset_split = dataset.train_test_split(test_size=0.1, seed=42)\n\ntrainer = SFTTrainer(\n    model=\"Qwen/Qwen2.5-0.5B\",\n    train_dataset=dataset_split[\"train\"],\n    eval_dataset=dataset_split[\"test\"],\n    peft_config=LoraConfig(r=16, lora_alpha=32),\n    args=SFTConfig(\n        output_dir=\"my-model\",\n        push_to_hub=True,\n        hub_model_id=\"username/my-model\",\n        num_train_epochs=3,\n        eval_strategy=\"steps\",\n        eval_steps=50,\n        report_to=\"trackio\",\n        project=\"meaningful_prject_name\", # project name for the training name (trackio)\n        run_name=\"meaningful_run_name\",   # descriptive name for the specific training run (trackio)\n    )\n)\n\ntrainer.train()\ntrainer.push_to_hub()\n\"\"\",\n    \"flavor\": \"a10g-large\",\n    \"timeout\": \"2h\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}\n})\n```\n\n**Benefits:** Direct MCP tool usage, clean code, dependencies declared inline (PEP 723), no file saving required, full control\n**When to use:** Default choice for all training tasks in Claude Code, custom training logic, any scenario requiring `hf_jobs()`\n\n#### Working with Scripts\n\n⚠️ **Important:** The `script` parameter accepts either inline code (as shown above) OR a URL. **Local file paths do NOT work.**\n\n**Why local paths don''t work:**\nJobs run in isolated Docker containers without access to your local filesystem. Scripts must be:\n- Inline code (recommended for custom training)\n- Publicly accessible URLs\n- Private repo URLs (with HF_TOKEN)\n\n**Common mistakes:**\n```python\n# ❌ These will all fail\nhf_jobs(\"uv\", {\"script\": \"train.py\"})\nhf_jobs(\"uv\", {\"script\": \"./scripts/train.py\"})\nhf_jobs(\"uv\", {\"script\": \"/path/to/train.py\"})\n```\n\n**Correct approaches:**\n```python\n# ✅ Inline code (recommended)\nhf_jobs(\"uv\", {\"script\": \"# /// script\\n# dependencies = [...]\\n# ///\\n\\n<your code>\"})\n\n# ✅ From Hugging Face Hub\nhf_jobs(\"uv\", {\"script\": \"https://huggingface.co/user/repo/resolve/main/train.py\"})\n\n# ✅ From GitHub\nhf_jobs(\"uv\", {\"script\": \"https://raw.githubusercontent.com/user/repo/main/train.py\"})\n\n# ✅ From Gist\nhf_jobs(\"uv\", {\"script\": \"https://gist.githubusercontent.com/user/id/raw/train.py\"})\n```\n\n**To use local scripts:** Upload to HF Hub first:\n```bash\nhuggingface-cli repo create my-training-scripts --type model\nhuggingface-cli upload my-training-scripts ./train.py train.py\n# Use: https://huggingface.co/USERNAME/my-training-scripts/resolve/main/train.py\n```\n\n### Approach 2: TRL Maintained Scripts (Official Examples)\n\nTRL provides battle-tested scripts for all methods. Can be run from URLs:\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"https://github.com/huggingface/trl/blob/main/trl/scripts/sft.py\",\n    \"script_args\": [\n        \"--model_name_or_path\", \"Qwen/Qwen2.5-0.5B\",\n        \"--dataset_name\", \"trl-lib/Capybara\",\n        \"--output_dir\", \"my-model\",\n        \"--push_to_hub\",\n        \"--hub_model_id\", \"username/my-model\"\n    ],\n    \"flavor\": \"a10g-large\",\n    \"timeout\": \"2h\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}\n})\n```\n\n**Benefits:** No code to write, maintained by TRL team, production-tested\n**When to use:** Standard TRL training, quick experiments, don''t need custom code\n**Available:** Scripts are available from https://github.com/huggingface/trl/tree/main/examples/scripts\n\n### Finding More UV Scripts on Hub\n\nThe `uv-scripts` organization provides ready-to-use UV scripts stored as datasets on Hugging Face Hub:\n\n```python\n# Discover available UV script collections\ndataset_search({\"author\": \"uv-scripts\", \"sort\": \"downloads\", \"limit\": 20})\n\n# Explore a specific collection\nhub_repo_details([\"uv-scripts/classification\"], repo_type=\"dataset\", include_readme=True)\n```\n\n**Popular collections:** ocr, classification, synthetic-data, vllm, dataset-creation\n\n### Approach 3: HF Jobs CLI (Direct Terminal Commands)\n\nWhen the `hf_jobs()` MCP tool is unavailable, use the `hf jobs` CLI directly.\n\n**⚠️ CRITICAL: CLI Syntax Rules**\n\n```bash\n# ✅ CORRECT syntax - flags BEFORE script URL\nhf jobs uv run --flavor a10g-large --timeout 2h --secrets HF_TOKEN \"https://example.com/train.py\"\n\n# ❌ WRONG - \"run uv\" instead of \"uv run\"\nhf jobs run uv \"https://example.com/train.py\" --flavor a10g-large\n\n# ❌ WRONG - flags AFTER script URL (will be ignored!)\nhf jobs uv run \"https://example.com/train.py\" --flavor a10g-large\n\n# ❌ WRONG - \"--secret\" instead of \"--secrets\" (plural)\nhf jobs uv run --secret HF_TOKEN \"https://example.com/train.py\"\n```\n\n**Key syntax rules:**\n1. Command order is `hf jobs uv run` (NOT `hf jobs run uv`)\n2. All flags (`--flavor`, `--timeout`, `--secrets`) must come BEFORE the script URL\n3. Use `--secrets` (plural), not `--secret`\n4. Script URL must be the last positional argument\n\n**Complete CLI example:**\n```bash\nhf jobs uv run \\\n  --flavor a10g-large \\\n  --timeout 2h \\\n  --secrets HF_TOKEN \\\n  \"https://huggingface.co/user/repo/resolve/main/train.py\"\n```\n\n**Check job status via CLI:**\n```bash\nhf jobs ps                        # List all jobs\nhf jobs logs <job-id>             # View logs\nhf jobs inspect <job-id>          # Job details\nhf jobs cancel <job-id>           # Cancel a job\n```\n\n### Approach 4: TRL Jobs Package (Simplified Training)\n\nThe `trl-jobs` package provides optimized defaults and one-liner training.\n\n```bash\n# Install\npip install trl-jobs\n\n# Train with SFT (simplest possible)\ntrl-jobs sft \\\n  --model_name Qwen/Qwen2.5-0.5B \\\n  --dataset_name trl-lib/Capybara\n```\n\n**Benefits:** Pre-configured settings, automatic Trackio integration, automatic Hub push, one-line commands\n**When to use:** User working in terminal directly (not Claude Code context), quick local experimentation\n**Repository:** https://github.com/huggingface/trl-jobs\n\n⚠️ **In Claude Code context, prefer using `hf_jobs()` MCP tool (Approach 1) when available.**\n\n## Hardware Selection\n\n| Model Size | Recommended Hardware | Cost (approx/hr) | Use Case |\n|------------|---------------------|------------------|----------|\n| <1B params | `t4-small` | ~$0.75 | Demos, quick tests only without eval steps |\n| 1-3B params | `t4-medium`, `l4x1` | ~$1.50-2.50 | Development |\n| 3-7B params | `a10g-small`, `a10g-large` | ~$3.50-5.00 | Production training |\n| 7-13B params | `a10g-large`, `a100-large` | ~$5-10 | Large models (use LoRA) |\n| 13B+ params | `a100-large`, `a10g-largex2` | ~$10-20 | Very large (use LoRA) |\n\n**GPU Flavors:** cpu-basic/upgrade/performance/xl, t4-small/medium, l4x1/x4, a10g-small/large/largex2/largex4, a100-large, h100/h100x8\n\n**Guidelines:**\n- Use **LoRA/PEFT** for models >7B to reduce memory\n- Multi-GPU automatically handled by TRL/Accelerate\n- Start with smaller hardware for testing\n\n**See:** `references/hardware_guide.md` for detailed specifications\n\n## Critical: Saving Results to Hub\n\n**⚠️ EPHEMERAL ENVIRONMENT—MUST PUSH TO HUB**\n\nThe Jobs environment is temporary. All files are deleted when the job ends. If the model isn''t pushed to Hub, **ALL TRAINING IS LOST**.\n\n### Required Configuration\n\n**In training script/config:**\n```python\nSFTConfig(\n    push_to_hub=True,\n    hub_model_id=\"username/model-name\",  # MUST specify\n    hub_strategy=\"every_save\",  # Optional: push checkpoints\n)\n```\n\n**In job submission:**\n```python\n{\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"}  # Enables authentication\n}\n```\n\n### Verification Checklist\n\nBefore submitting:\n- [ ] `push_to_hub=True` set in config\n- [ ] `hub_model_id` includes username/repo-name\n- [ ] `secrets` parameter includes HF_TOKEN\n- [ ] User has write access to target repo\n\n**See:** `references/hub_saving.md` for detailed troubleshooting\n\n## Timeout Management\n\n**⚠️ DEFAULT: 30 MINUTES—TOO SHORT FOR TRAINING**\n\n### Setting Timeouts\n\n```python\n{\n    \"timeout\": \"2h\"   # 2 hours (formats: \"90m\", \"2h\", \"1.5h\", or seconds as integer)\n}\n```\n\n### Timeout Guidelines\n\n| Scenario | Recommended | Notes |\n|----------|-------------|-------|\n| Quick demo (50-100 examples) | 10-30 min | Verify setup |\n| Development training | 1-2 hours | Small datasets |\n| Production (3-7B model) | 4-6 hours | Full datasets |\n| Large model with LoRA | 3-6 hours | Depends on dataset |\n\n**Always add 20-30% buffer** for model/dataset loading, checkpoint saving, Hub push operations, and network delays.\n\n**On timeout:** Job killed immediately, all unsaved progress lost, must restart from beginning\n\n## Cost Estimation\n\n**Offer to estimate cost when planning jobs with known parameters.** Use `scripts/estimate_cost.py`:\n\n```bash\nuv run scripts/estimate_cost.py \\\n  --model meta-llama/Llama-2-7b-hf \\\n  --dataset trl-lib/Capybara \\\n  --hardware a10g-large \\\n  --dataset-size 16000 \\\n  --epochs 3\n```\n\nOutput includes estimated time, cost, recommended timeout (with buffer), and optimization suggestions.\n\n**When to offer:** User planning a job, asks about cost/time, choosing hardware, job will run >1 hour or cost >$5\n\n## Example Training Scripts\n\n**Production-ready templates with all best practices:**\n\nLoad these scripts for correctly:\n\n- **`scripts/train_sft_example.py`** - Complete SFT training with Trackio, LoRA, checkpoints\n- **`scripts/train_dpo_example.py`** - DPO training for preference learning\n- **`scripts/train_grpo_example.py`** - GRPO training for online RL\n\nThese scripts demonstrate proper Hub saving, Trackio integration, checkpoint management, and optimized parameters. Pass their content inline to `hf_jobs()` or use as templates for custom scripts.\n\n## Monitoring and Tracking\n\n**Trackio** provides real-time metrics visualization. See `references/trackio_guide.md` for complete setup guide.\n\n**Key points:**\n- Add `trackio` to dependencies\n- Configure trainer with `report_to=\"trackio\" and run_name=\"meaningful_name\"`\n\n### Trackio Configuration Defaults\n\n**Use sensible defaults unless user specifies otherwise.** When generating training scripts with Trackio:\n\n**Default Configuration:**\n- **Space ID**: `{username}/trackio` (use \"trackio\" as default space name)\n- **Run naming**: Unless otherwise specified, name the run in a way the user will recognize (e.g., descriptive of the task, model, or purpose)\n- **Config**: Keep minimal - only include hyperparameters and model/dataset info\n- **Project Name**: Use a Project Name to associate runs with a particular Project \n\n**User overrides:** If user requests specific trackio configuration (custom space, run naming, grouping, or additional config), apply their preferences instead of defaults.\n\n\nThis is useful for managing multiple jobs with the same configuration or keeping training scripts portable.\n\nSee `references/trackio_guide.md` for complete documentation including grouping runs for experiments.\n\n### Check Job Status\n\n```python\n# List all jobs\nhf_jobs(\"ps\")\n\n# Inspect specific job\nhf_jobs(\"inspect\", {\"job_id\": \"your-job-id\"})\n\n# View logs\nhf_jobs(\"logs\", {\"job_id\": \"your-job-id\"})\n```\n\n**Remember:** Wait for user to request status checks. Avoid polling repeatedly.\n\n## Dataset Validation\n\n**Validate dataset format BEFORE launching GPU training to prevent the #1 cause of training failures: format mismatches.**\n\n### Why Validate\n\n- 50%+ of training failures are due to dataset format issues\n- DPO especially strict: requires exact column names (`prompt`, `chosen`, `rejected`)\n- Failed GPU jobs waste $1-10 and 30-60 minutes\n- Validation on CPU costs ~$0.01 and takes <1 minute\n\n### When to Validate\n\n**ALWAYS validate for:**\n- Unknown or custom datasets\n- DPO training (CRITICAL - 90% of datasets need mapping)\n- Any dataset not explicitly TRL-compatible\n\n**Skip validation for known TRL datasets:**\n- `trl-lib/ultrachat_200k`, `trl-lib/Capybara`, `HuggingFaceH4/ultrachat_200k`, etc.\n\n### Usage\n\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"https://huggingface.co/datasets/mcp-tools/skills/raw/main/dataset_inspector.py\",\n    \"script_args\": [\"--dataset\", \"username/dataset-name\", \"--split\", \"train\"]\n})\n```\n\nThe script is fast, and will usually complete synchronously.\n\n### Reading Results\n\nThe output shows compatibility for each training method:\n\n- **`✓ READY`** - Dataset is compatible, use directly\n- **`✗ NEEDS MAPPING`** - Compatible but needs preprocessing (mapping code provided)\n- **`✗ INCOMPATIBLE`** - Cannot be used for this method\n\nWhen mapping is needed, the output includes a **\"MAPPING CODE\"** section with copy-paste ready Python code.\n\n### Example Workflow\n\n```python\n# 1. Inspect dataset (costs ~$0.01, <1 min on CPU)\nhf_jobs(\"uv\", {\n    \"script\": \"https://huggingface.co/datasets/mcp-tools/skills/raw/main/dataset_inspector.py\",\n    \"script_args\": [\"--dataset\", \"argilla/distilabel-math-preference-dpo\", \"--split\", \"train\"]\n})\n\n# 2. Check output markers:\n#    ✓ READY → proceed with training\n#    ✗ NEEDS MAPPING → apply mapping code below\n#    ✗ INCOMPATIBLE → choose different method/dataset\n\n# 3. If mapping needed, apply before training:\ndef format_for_dpo(example):\n    return {\n        ''prompt'': example[''instruction''],\n        ''chosen'': example[''chosen_response''],\n        ''rejected'': example[''rejected_response''],\n    }\ndataset = dataset.map(format_for_dpo, remove_columns=dataset.column_names)\n\n# 4. Launch training job with confidence\n```\n\n### Common Scenario: DPO Format Mismatch\n\nMost DPO datasets use non-standard column names. Example:\n\n```\nDataset has: instruction, chosen_response, rejected_response\nDPO expects: prompt, chosen, rejected\n```\n\nThe validator detects this and provides exact mapping code to fix it.\n\n## Converting Models to GGUF\n\nAfter training, convert models to **GGUF format** for use with llama.cpp, Ollama, LM Studio, and other local inference tools.\n\n**What is GGUF:**\n- Optimized for CPU/GPU inference with llama.cpp\n- Supports quantization (4-bit, 5-bit, 8-bit) to reduce model size\n- Compatible with Ollama, LM Studio, Jan, GPT4All, llama.cpp\n- Typically 2-8GB for 7B models (vs 14GB unquantized)\n\n**When to convert:**\n- Running models locally with Ollama or LM Studio\n- Reducing model size with quantization\n- Deploying to edge devices\n- Sharing models for local-first use\n\n**See:** `references/gguf_conversion.md` for complete conversion guide, including production-ready conversion script, quantization options, hardware requirements, usage examples, and troubleshooting.\n\n**Quick conversion:**\n```python\nhf_jobs(\"uv\", {\n    \"script\": \"<see references/gguf_conversion.md for complete script>\",\n    \"flavor\": \"a10g-large\",\n    \"timeout\": \"45m\",\n    \"secrets\": {\"HF_TOKEN\": \"$HF_TOKEN\"},\n    \"env\": {\n        \"ADAPTER_MODEL\": \"username/my-finetuned-model\",\n        \"BASE_MODEL\": \"Qwen/Qwen2.5-0.5B\",\n        \"OUTPUT_REPO\": \"username/my-model-gguf\"\n    }\n})\n```\n\n## Common Training Patterns\n\nSee `references/training_patterns.md` for detailed examples including:\n- Quick demo (5-10 minutes)\n- Production with checkpoints\n- Multi-GPU training\n- DPO training (preference learning)\n- GRPO training (online RL)\n\n## Common Failure Modes\n\n### Out of Memory (OOM)\n\n**Fix (try in order):**\n1. Reduce batch size: `per_device_train_batch_size=1`, increase `gradient_accumulation_steps=8`. Effective batch size is `per_device_train_batch_size` x `gradient_accumulation_steps`. For best performance keep effective batch size close to 128. \n2. Enable: `gradient_checkpointing=True`\n3. Upgrade hardware: t4-small → l4x1, a10g-small → a10g-large etc. \n\n### Dataset Misformatted\n\n**Fix:**\n1. Validate first with dataset inspector:\n   ```bash\n   uv run https://huggingface.co/datasets/mcp-tools/skills/raw/main/dataset_inspector.py \\\n     --dataset name --split train\n   ```\n2. Check output for compatibility markers (✓ READY, ✗ NEEDS MAPPING, ✗ INCOMPATIBLE)\n3. Apply mapping code from inspector output if needed\n\n### Job Timeout\n\n**Fix:**\n1. Check logs for actual runtime: `hf_jobs(\"logs\", {\"job_id\": \"...\"})`\n2. Increase timeout with buffer: `\"timeout\": \"3h\"` (add 30% to estimated time)\n3. Or reduce training: lower `num_train_epochs`, use smaller dataset, enable `max_steps`\n4. Save checkpoints: `save_strategy=\"steps\"`, `save_steps=500`, `hub_strategy=\"every_save\"`\n\n**Note:** Default 30min is insufficient for real training. Minimum 1-2 hours.\n\n### Hub Push Failures\n\n**Fix:**\n1. Add to job: `secrets={\"HF_TOKEN\": \"$HF_TOKEN\"}`\n2. Add to config: `push_to_hub=True`, `hub_model_id=\"username/model-name\"`\n3. Verify auth: `mcp__huggingface__hf_whoami()`\n4. Check token has write permissions and repo exists (or set `hub_private_repo=True`)\n\n### Missing Dependencies\n\n**Fix:**\nAdd to PEP 723 header:\n```python\n# /// script\n# dependencies = [\"trl>=0.12.0\", \"peft>=0.7.0\", \"trackio\", \"missing-package\"]\n# ///\n```\n\n## Troubleshooting\n\n**Common issues:**\n- Job times out → Increase timeout, reduce epochs/dataset, use smaller model/LoRA\n- Model not saved to Hub → Check push_to_hub=True, hub_model_id, secrets=HF_TOKEN\n- Out of Memory (OOM) → Reduce batch size, increase gradient accumulation, enable LoRA, use larger GPU\n- Dataset format error → Validate with dataset inspector (see Dataset Validation section)\n- Import/module errors → Add PEP 723 header with dependencies, verify format\n- Authentication errors → Check `mcp__huggingface__hf_whoami()`, token permissions, secrets parameter\n\n**See:** `references/troubleshooting.md` for complete troubleshooting guide\n\n## Resources\n\n### References (In This Skill)\n- `references/training_methods.md` - Overview of SFT, DPO, GRPO, KTO, PPO, Reward Modeling\n- `references/training_patterns.md` - Common training patterns and examples\n- `references/unsloth.md` - Unsloth for fast VLM training (~2x speed, 60% less VRAM)\n- `references/gguf_conversion.md` - Complete GGUF conversion guide\n- `references/trackio_guide.md` - Trackio monitoring setup\n- `references/hardware_guide.md` - Hardware specs and selection\n- `references/hub_saving.md` - Hub authentication troubleshooting\n- `references/troubleshooting.md` - Common issues and solutions\n\n### Scripts (In This Skill)\n- `scripts/train_sft_example.py` - Production SFT template\n- `scripts/train_dpo_example.py` - Production DPO template\n- `scripts/train_grpo_example.py` - Production GRPO template\n- `scripts/unsloth_sft_example.py` - Unsloth text LLM training template (faster, less VRAM)\n- `scripts/estimate_cost.py` - Estimate time and cost (offer when appropriate)\n- `scripts/convert_to_gguf.py` - Complete GGUF conversion script\n\n### External Scripts\n- [Dataset Inspector](https://huggingface.co/datasets/mcp-tools/skills/raw/main/dataset_inspector.py) - Validate dataset format before training (use via `uv run` or `hf_jobs`)\n\n### External Links\n- [TRL Documentation](https://huggingface.co/docs/trl)\n- [TRL Jobs Training Guide](https://huggingface.co/docs/trl/en/jobs_training)\n- [TRL Jobs Package](https://github.com/huggingface/trl-jobs)\n- [HF Jobs Documentation](https://huggingface.co/docs/huggingface_hub/guides/jobs)\n- [TRL Example Scripts](https://github.com/huggingface/trl/tree/main/examples/scripts)\n- [UV Scripts Guide](https://docs.astral.sh/uv/guides/scripts/)\n- [UV Scripts Organization](https://huggingface.co/uv-scripts)\n\n## Key Takeaways\n\n1. **Submit scripts inline** - The `script` parameter accepts Python code directly; no file saving required unless user requests\n2. **Jobs are asynchronous** - Don''t wait/poll; let user check when ready\n3. **Always set timeout** - Default 30 min is insufficient; minimum 1-2 hours recommended\n4. **Always enable Hub push** - Environment is ephemeral; without push, all results lost\n5. **Include Trackio** - Use example scripts as templates for real-time monitoring\n6. **Offer cost estimation** - When parameters are known, use `scripts/estimate_cost.py`\n7. **Use UV scripts (Approach 1)** - Default to `hf_jobs(\"uv\", {...})` with inline scripts; TRL maintained scripts for standard training; avoid bash `trl-jobs` commands in Claude Code\n8. **Use hf_doc_fetch/hf_doc_search** for latest TRL documentation\n9. **Validate dataset format** before training with dataset inspector (see Dataset Validation section)\n10. **Choose appropriate hardware** for model size; use LoRA for models >7B\n"},"category":"official","lastSynced":"2026-03-06T05:37:58.999Z","seo":{"title":{"en":"hugging-face-model-trainer: TRL Training Setup Guide | AI...","es":"Guía de configuración de hugging-face-model-trainer para ...","fr":"Guide de démarrage de hugging-face-model-trainer pour les...","de":"Einrichtungsleitfaden für hugging-face-model-trainer in K...","pt":"Guia de Configuração do hugging-face-model-trainer para T...","ru":"Настройка hugging-face-model-trainer для обучения языковы...","ar":"دليل إعداد hugging-face-model-trainer لتدريب نماذج اللغة ..."},"description":{"en":"Unlock efficient language model training with hugging-face-model-trainer - discover how to leverage TRL on Hugging Face Jobs infrastructure and get started t...","es":"Aprende a entrenar modelos de lenguaje con TRL en Hugging Face Jobs. Descubre cómo configurar SFT, DPO, GRPO y más","fr":"Découvrez comment entraîner des modèles de langage avec TRL sur Hugging Face Jobs. Configurez SFT, DPO, GRPO et plus","de":"Erfahren Sie, wie Sie Sprachmodelle mit TRL auf Hugging Face Jobs trainieren. Konfigurieren Sie SFT, DPO, GRPO und mehr","pt":"Aprenda a treinar modelos de linguagem com TRL no Hugging Face Jobs, incluindo SFT, DPO e GRPO","ru":"Обучайте языковые модели с помощью TRL на Hugging Face Jobs, включая SFT, DPO и GRPO для ИИ Агенты","ar":"تعلم تدريب نماذج اللغة باستخدام TRL على Hugging Face Jobs، بما في ذلك SFT و DPO و GRPO لنماذج اللغة الإصطناعية"},"definition":{"en":"hugging-face-model-trainer is a skill that facilitates training and fine-tuning language models using TRL on Hugging Face infrastructure, covering various training methods and model persistence.","es":"Hugging Face Model Trainer es una habilidad para entrenar modelos de lenguaje con TRL en la infraestructura de Hugging Face Jobs","fr":"Hugging Face Model Trainer est une compétence pour entraîner des modèles de langage avec TRL sur l''infrastructure Hugging Face Jobs","de":"Hugging Face Model Trainer ist eine Fähigkeit zum Trainieren von Sprachmodellen mit TRL auf der Hugging Face Jobs-Infrastruktur","pt":"O que é hugging-face-model-trainer? É uma habilidade para treinar modelos de linguagem com TRL no Hugging Face Jobs","ru":"Что такое hugging-face-model-trainer? Это навык для обучения языковых моделей с помощью TRL на Hugging Face Jobs для ИИ Агенты","ar":"ما هو هوجنج-فيس-مودل-تراينر؟ هو مهارة لتدريب نماذج اللغة باستخدام TRL على Hugging Face Jobs لنماذج اللغة الإصطناعية"},"features":{"en":["Supports TRL training methods including SFT, DPO, GRPO, and reward modeling","Enables GGUF conversion for local deployment","Utilizes Hugging Face Jobs infrastructure for cloud GPU training","Includes guidance on dataset preparation, validation, and hardware selection","Provides cost estimation and Trackio monitoring capabilities","Facilitates model persistence and Hub authentication"],"es":["Entrenamiento de modelos de lenguaje con TRL","Soporte para SFT, DPO, GRPO y reward modeling","Conversión GGUF para despliegue local","Preparación y validación de conjuntos de datos","Selección de hardware y estimación de costos","Monitoreo con Trackio y autenticación de Hub"],"fr":["Entraînement de modèles de langage avec TRL","Prise en charge de SFT, DPO, GRPO et reward modeling","Conversion GGUF pour déploiement local","Préparation et validation de jeux de données","Sélection de matériel et estimation de coûts","Supervision avec Trackio et authentification de Hub"],"de":["Trainieren von Sprachmodellen mit TRL","Unterstützung für SFT, DPO, GRPO und Reward-Modellierung","GGUF-Konvertierung für lokale Bereitstellung","Datenprüfung und -validierung","Hardware-Auswahl und Kostenschätzung","Überwachung mit Trackio und Hub-Authentifizierung"],"pt":["Treinamento de modelos de linguagem com TRL","Suporte a SFT, DPO e GRPO","Integração com Hugging Face Jobs","Conversão GGUF para implantação local","Monitoramento com Trackio"],"ru":["Обучение языковых моделей с помощью TRL","Поддержка SFT, DPO и GRPO для ИИ Агенты","Интеграция с Hugging Face Jobs","Преобразование GGUF для локального развертывания","Мониторинг с помощью Trackio"],"ar":["تدريب نماذج اللغة باستخدام TRL","دعم SFT و DPO و GRPO لنماذج اللغة الإصطناعية","التكامل مع Hugging Face Jobs","تحويل GGUF لإعداد محلي","مراقبة باستخدام Trackio"]},"keywords":{"en":["hugging-face-model-trainer setup guide","TRL training on Hugging Face Jobs","how to use hugging-face-model-trainer","hugging-face-model-trainer vs traditional training methods","hugging-face-model-trainer install and configuration","fine-tuning language models with TRL","GGUF conversion for local deployment","Hugging Face Jobs infrastructure for AI development"],"es":["hugging face model trainer","entrenamiento de modelos de lenguaje","TRL","SFT","DPO","GRPO","reward modeling","GGUF","Hugging Face Jobs","despliegue de modelos de lenguaje"],"fr":["hugging face model trainer","entraînement de modèles de langage","TRL","SFT","DPO","GRPO","reward modeling","GGUF","Hugging Face Jobs","déploiement de modèles de langage"],"de":["hugging face model trainer","Trainieren von Sprachmodellen","TRL","SFT","DPO","GRPO","Reward-Modellierung","GGUF","Hugging Face Jobs","Bereitstellung von Sprachmodellen"],"pt":["hugging face model trainer","treinamento de modelos de linguagem","TRL","Hugging Face Jobs","SFT","DPO","GRPO","GGUF","Trackio"],"ru":["hugging face model trainer","обучение языковых моделей","TRL","Hugging Face Jobs","SFT","DPO","GRPO","GGUF","Trackio","ИИ Агенты"],"ar":["هوجنج-فيس-مودل-تراينر","تدريب نماذج اللغة","TRL","Hugging Face Jobs","SFT","DPO","GRPO","GGUF","Trackio","نماذج اللغة الإصطناعية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced language model training capabilities on Hugging Face infrastructure with TRL methods like SFT, DPO, and GRPO.","zh":"适合需要在Hugging Face基础设施上使用TRL方法（如SFT、DPO和GRPO）进行高级语言模型训练的AI代理。","ja":"Hugging Faceインフラストラクチャ上でTRL方法（SFT、DPO、GRPOなど）を使用した高度な言語モデルトレーニング機能が必要なAIエージェントに最適です。","ko":"Hugging Face 인프라에서 TRL 방법(SFT, DPO, GRPO 등)을 사용하여 고급 언어 모델 훈련 기능을 필요로 하는 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades de entrenamiento de modelos de lenguaje avanzados en la infraestructura de Hugging Face con métodos TRL como SFT, DPO y GRPO.","fr":"Parfait pour les agents IA ayant besoin de capacités de formation de modèles de langage avancées sur l''infrastructure Hugging Face avec des méthodes TRL comme SFT, DPO et GRPO.","de":"Perfekt für KI-Agenten, die erweiterte Sprachmodell-Trainingsfunktionen auf der Hugging Face-Infrastruktur mit TRL-Methoden wie SFT, DPO und GRPO benötigen.","pt":"Perfeito para Agentes de IA que necessitam de capacidades de treinamento de modelos de linguagem avançados na infraestrutura Hugging Face com métodos TRL como SFT, DPO e GRPO.","ru":"Идеально для ИИ-агентов, требующих передовых возможностей обучения языковых моделей на инфраструктуре Hugging Face с методами TRL, такими как SFT, DPO и GRPO.","ar":"مثالي للوكلاء الذكيين الذين يحتاجون إلى إمكانيات تدريب نموذج لغة متقدمة على بنية تحتية Hugging Face باستخدام طرق TRL مثل SFT و DPO و GRPO."},"recommendation":{"en":"Empowers agents to train language models using Transformer Reinforcement Learning on cloud GPUs, leveraging Hugging Face Jobs and supporting GGUF conversion for local deployment, while utilizing UV scripts and PEP 723 format for seamless integration.","zh":"赋予代理使用Transformer Reinforcement Learning在云GPU上训练语言模型的能力，利用Hugging Face Jobs，并支持GGUF转换以进行本地部署，同时利用UV脚本和PEP 723格式实现无缝集成。","ja":"Transformer Reinforcement Learningを使用してクラウドGPU上で言語モデルをトレーニングする機能をエージェントに与え、Hugging Face Jobsを利用し、GGUF変換をサポートしてローカルデプロイを可能にし、UVスクリプトとPEP 723形式を使用してシームレスな統合を実現します。","ko":"에이전트가 Transformer Reinforcement Learning을 사용하여 클라우드 GPU에서 언어 모델을 훈련할 수 있는 기능을 제공하며, Hugging Face Jobs를 활용하고 GGUF 변환을 지원하여 로컬 배포를 가능하게 하며, UV 스크립트와 PEP 723 형식을 사용하여 무중단 통합을 구현합니다.","es":"Habilita a los agentes a entrenar modelos de lenguaje utilizando Transformer Reinforcement Learning en GPUs en la nube, aprovechando Hugging Face Jobs y admitiendo la conversión GGUF para la implementación local, mientras utiliza scripts UV y formato PEP 723 para una integración sin problemas.","fr":"Permet aux agents de former des modèles de langage en utilisant l''apprentissage par renforcement Transformer sur les GPU cloud, en exploitant les travaux Hugging Face et en prenant en charge la conversion GGUF pour le déploiement local, tout en utilisant des scripts UV et le format PEP 723 pour une intégration transparente.","de":"Ermöglicht es Agenten, Sprachmodelle mit Transformer Reinforcement Learning auf Cloud-GPUs zu trainieren, indem es Hugging Face Jobs nutzt und die GGUF-Konvertierung für die lokale Bereitstellung unterstützt, während es UV-Skripte und PEP-723-Format für eine nahtlose Integration verwendet.","pt":"Habilita os agentes a treinarem modelos de linguagem usando Aprendizado de Reforço de Transformer em GPUs de nuvem, aproveitando os Trabalhos Hugging Face e suportando a conversão GGUF para implantação local, ao mesmo tempo em que utiliza scripts UV e formato PEP 723 para integração sem problemas.","ru":"Наделяет агентов возможностью обучать языковые модели с помощью усиления обучения Transformer в облачных GPU, используя задания Hugging Face и поддерживая преобразование GGUF для локального развертывания, а также используя скрипты UV и формат PEP 723 для бесшовной интеграции.","ar":"يمنح الوكلاء القدرة على تدريب نماذج اللغة باستخدام تعزيز التعلم للتحويل في وحدات معالجة الرسومات السحابية، مستفيدة من مهام Hugging Face ودعم تحويل GGUF للنشر المحلي، وفي الوقت نفسه استخدام سكريبتات UV وتنسيق PEP 723 من أجل التكامل السلس."},"useCases":{"en":["Training language models on Hugging Face Jobs without local GPU setup","Fine-tuning models using SFT, DPO, and GRPO training methods","Converting trained models to GGUF format for local deployment"],"zh":["在Hugging Face Jobs上训练语言模型而无需本地GPU设置","使用SFT、DPO和GRPO训练方法对模型进行微调","将训练好的模型转换为GGUF格式以进行本地部署"],"ja":["ローカルGPU設定なしでHugging Face Jobs上で言語モデルをトレーニングする","SFT、DPO、GRPOトレーニング方法を使用してモデルを微調整する","トレーニングされたモデルをGGUF形式に変換してローカルデプロイする"],"ko":["로컬 GPU 설정 없이 Hugging Face Jobs에서 언어 모델을 훈련하는 것","SFT, DPO, GRPO 훈련 방법을 사용하여 모델을 미세 조정하는 것","훈련된 모델을 GGUF 형식으로 변환하여 로컬 배포하는 것"],"es":["Entrenamiento de modelos de lenguaje en Hugging Face Jobs sin configuración de GPU local","Ajuste fino de modelos utilizando métodos de entrenamiento SFT, DPO y GRPO","Conversión de modelos entrenados al formato GGUF para la implementación local"],"fr":["Formation de modèles de langage sur les travaux Hugging Face sans configuration GPU locale","Réglage fin de modèles en utilisant les méthodes de formation SFT, DPO et GRPO","Conversion de modèles formés au format GGUF pour le déploiement local"],"de":["Trainieren von Sprachmodellen in Hugging Face Jobs ohne lokale GPU-Konfiguration","Feinabstimmung von Modellen unter Verwendung der Trainingsmethoden SFT, DPO und GRPO","Konvertierung von trainierten Modellen in das GGUF-Format für die lokale Bereitstellung"],"pt":["Treinamento de modelos de linguagem em Trabalhos Hugging Face sem configuração de GPU local","Ajuste fino de modelos usando métodos de treinamento SFT, DPO e GRPO","Conversão de modelos treinados para formato GGUF para implantação local"],"ru":["Обучение языковых моделей на заданиях Hugging Face без локальной настройки GPU","Настройка моделей с помощью методов обучения SFT, DPO и GRPO","Преобразование обученных моделей в формат GGUF для локального развертывания"],"ar":["تدريب نماذج اللغة على مهام Hugging Face دون إعداد وحدة معالجة الرسومات المحلية","ضبط دقيق للنماذج باستخدام طرق تدريب SFT و DPO و GRPO","تحويل النماذج المدربة إلى تنسيق GGUF للنشر المحلي"]},"limitations":{"en":["Requires Hugging Face Hub authentication","Dependent on Hugging Face Jobs infrastructure for cloud GPU training","Limited to TRL training methods and GGUF conversion"],"zh":["需要Hugging Face Hub身份验证","依赖Hugging Face Jobs基础设施进行云GPU训练","仅限TRL训练方法和GGUF转换"],"ja":["Hugging Face Hubの認証が必要","クラウドGPUトレーニングのためにHugging Face Jobsインフラストラクチャに依存","TRLトレーニング方法とGGUF変換のみ"],"ko":["Hugging Face Hub 인증이 필요함","클라우드 GPU 훈련을 위해 Hugging Face Jobs 인프라에 의존함","TRL 훈련 방법과 GGUF 변환만 محدود됨"],"es":["Requiere autenticación de Hugging Face Hub","Dependiente de la infraestructura de Hugging Face Jobs para el entrenamiento de GPU en la nube","Limitado a métodos de entrenamiento TRL y conversión GGUF"],"fr":["Nécessite une authentification Hugging Face Hub","Dépendant de l''infrastructure des travaux Hugging Face pour la formation GPU cloud","Limité aux méthodes de formation TRL et à la conversion GGUF"],"de":["Benötigt Hugging Face Hub-Authentifizierung","Abhängig von der Hugging Face Jobs-Infrastruktur für Cloud-GPU-Training","Begrenzt auf TRL-Trainingsmethoden und GGUF-Konvertierung"],"pt":["Exige autenticação do Hub Hugging Face","Dependente da infraestrutura de Trabalhos Hugging Face para treinamento de GPU em nuvem","Limitado a métodos de treinamento TRL e conversão GGUF"],"ru":["Требует аутентификации в Hub Hugging Face","Зависит от инфраструктуры заданий Hugging Face для облачного обучения GPU","Ограничен методами обучения TRL и преобразованием GGUF"],"ar":["يتطلب مصادقة مركز Hugging Face","يعتمد على بنية تحتية مهام Hugging Face لتدريب وحدة معالجة الرسومات السحابية","محدود بطرق تدريب TRL وتحويل GGUF"]},"version":4},"contentHash":"4a0d1a94f8755c9671f8addb44735d374163ecff839ffe685b8a52adcaca026e","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":95}');
