INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-model-trainer', 'hugging-face-model-trainer', 'huggingface', 'skills', 'official', 'hugging-face-model-trainer huggingface skills official The hugging-face-model-trainer skill enables developers to train language models using Transformer Reinforcement Learning (TRL) on Hugging Face Jobs, supporting methods like SFT, DPO, and GRPO. It benefits AI and machine learning developers seeking to fine-tune models on cloud GPUs. Entrena modelos de lenguaje con TRL en Hugging Face Jobs sin necesidad de configuración local de GPU. Aprende sobre SFT, DPO, GRPO y más Entraînez des modèles de langage avec TRL sur Hugging Face Jobs sans configuration GPU locale. Découvrez SFT, DPO, GRPO et plus Trainieren Sie Sprachmodelle mit TRL auf Hugging Face Jobs ohne lokale GPU-Konfiguration. Erfahren Sie mehr über SFT, DPO, GRPO und mehr O hugging-face-model-trainer é uma habilidade para treinar modelos de linguagem com TRL no Hugging Face Jobs, sem necessidade de configuração de GPU local. Hugging-face-model-trainer - это навык для обучения языковых моделей с помощью TRL на Hugging Face Jobs без локальной настройки GPU для ИИ Агенты هو هوجنج-فيس-مودل-تراينر مهارة لتدريب نماذج اللغة باستخدام TRL على Hugging Face Jobs بدون إعداد محلي لجهاز GPU لنماذج اللغة الإصطناعية hugging-face-model-trainer setup guide TRL training on Hugging Face Jobs how to use hugging-face-model-trainer hugging-face-model-trainer vs traditional training methods hugging-face-model-trainer install and configuration fine-tuning language models with TRL GGUF conversion for local deployment Hugging Face Jobs infrastructure for AI development Supports TRL training methods including SFT, DPO, GRPO, and reward modeling Enables GGUF conversion for local deployment Utilizes Hugging Face Jobs infrastructure for cloud GPU training Includes guidance on dataset preparation, validation, and hardware selection Provides cost estimation and Trackio monitoring capabilities Facilitates model persistence and Hub authentication hugging-face-model-trainer is a skill that facilitates training and fine-tuning language models using TRL on Hugging Face infrastructure, covering various training methods and model persistence.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-paper-publisher', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-paper-publisher', 8290, 490, 95, '2026-03-06T05:28:53Z', '2026-03-06T05:38:57.171Z', 'a9e12c89297d4085e045aa682c65f27adb456986c5cc3770cb481ce62cd6bcaa', '{"id":"huggingface/skills/hugging-face-paper-publisher","name":"hugging-face-paper-publisher","description":{"en":"The hugging-face-paper-publisher skill provides AI engineers and researchers with tools to publish and manage research papers on Hugging Face Hub, supporting paper creation, arXiv integration, and authorship management.","zh":"Hugging Face 研究论文发布器提供了一套全面的工具，用于在 Hugging Face Hub 上发布、管理和链接研究论文。它支持创建论文页面、链接论文到模型/数据集、声明作者权和生成专业的 markdown 格式研究文章","ja":"Hugging Face Paper Publisher は、Hugging Face Hub 上で研究論文を公開、管理、リンクするための包括的なツールを提供します。論文ページの作成、モデル/データセットへのリンク、著者権の申請、プロフェッショナルな markdown 形式の研究記事の生成をサポート","ko":"Hugging Face 연구 논문 발행기는 Hugging Face Hub에서 연구 논문을 발행, 관리, 링크하는 데 필요한 포괄적인 도구를 제공합니다. 논문 페이지 생성, 모델/데이터셋 링크, 저자 권한声明, 전문가급 markdown 형식 연구 기사의 생성을 지원합니다","es":"Herramienta para investigadores que permite publicar y gestionar artículos de investigación en Hugging Face Hub, con integración de modelos y datasets.","fr":"Outil pour les chercheurs qui permet de publier et de gérer des articles de recherche sur Hugging Face Hub, avec intégration de modèles et de datasets.","de":"Werkzeug für KI-Forscher, um Forschungsartikel in Hugging Face Hub zu veröffentlichen und zu verwalten, mit Integration von Modellen und Daten","pt":"O hugging-face-paper-publisher é uma ferramenta para publicar e gerenciar artigos de pesquisa no Hugging Face Hub, integrando com arXiv e modelos/datasets.","ru":"hugging-face-paper-publisher - это инструмент для публикации и управления исследовательскими статьями на Hugging Face Hub, интегрирующийся с arXiv и моделями/данными.","ar":"هو hugging-face-paper-publisher أداة لنشر وإدارة الأبحاث على منصة Hugging Face Hub، متكاملة مع arXiv والمدلسات/المجموعات البيانية"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-paper-publisher","description":"Publish and manage research papers on Hugging Face Hub. Supports creating paper pages, linking papers to models/datasets, claiming authorship, and generating professional markdown-based research articles.","bodyPreview":"# Overview\nThis skill provides comprehensive tools for AI engineers and researchers to publish, manage, and link research papers on the Hugging Face Hub. It streamlines the workflow from paper creation to publication, including integration with arXiv, model/dataset linking, and authorship management.\n\n## Integration with HF Ecosystem\n- **Paper Pages**: Index and discover papers on Hugging Face Hub\n- **arXiv Integration**: Automatic paper indexing from arXiv IDs\n- **Model/Dataset Linking**: Conne","body":"# Overview\nThis skill provides comprehensive tools for AI engineers and researchers to publish, manage, and link research papers on the Hugging Face Hub. It streamlines the workflow from paper creation to publication, including integration with arXiv, model/dataset linking, and authorship management.\n\n## Integration with HF Ecosystem\n- **Paper Pages**: Index and discover papers on Hugging Face Hub\n- **arXiv Integration**: Automatic paper indexing from arXiv IDs\n- **Model/Dataset Linking**: Connect papers to relevant artifacts through metadata\n- **Authorship Verification**: Claim and verify paper authorship\n- **Research Article Template**: Generate professional, modern scientific papers\n\n# Version\n1.0.0\n\n# Dependencies\n- huggingface_hub>=0.26.0\n- pyyaml>=6.0.3\n- requests>=2.32.5\n- markdown>=3.5.0\n- python-dotenv>=1.2.1\n\n# Core Capabilities\n\n## 1. Paper Page Management\n- **Index Papers**: Add papers to Hugging Face from arXiv\n- **Claim Authorship**: Verify and claim authorship on published papers\n- **Manage Visibility**: Control which papers appear on your profile\n- **Paper Discovery**: Find and explore papers in the HF ecosystem\n\n## 2. Link Papers to Artifacts\n- **Model Cards**: Add paper citations to model metadata\n- **Dataset Cards**: Link papers to datasets via README\n- **Automatic Tagging**: Hub auto-generates arxiv:<PAPER_ID> tags\n- **Citation Management**: Maintain proper attribution and references\n\n## 3. Research Article Creation\n- **Markdown Templates**: Generate professional paper formatting\n- **Modern Design**: Clean, readable research article layouts\n- **Dynamic TOC**: Automatic table of contents generation\n- **Section Structure**: Standard scientific paper organization\n- **LaTeX Math**: Support for equations and technical notation\n\n## 4. Metadata Management\n- **YAML Frontmatter**: Proper model/dataset card metadata\n- **Citation Tracking**: Maintain paper references across repositories\n- **Version Control**: Track paper updates and revisions\n- **Multi-Paper Support**: Link multiple papers to single artifacts\n\n# Usage Instructions\n\nThe skill includes Python scripts in `scripts/` for paper publishing operations.\n\n### Prerequisites\n- Install dependencies: `uv add huggingface_hub pyyaml requests markdown python-dotenv`\n- Set `HF_TOKEN` environment variable with Write-access token\n- Activate virtual environment: `source .venv/bin/activate`\n\n> **All paths are relative to the directory containing this SKILL.md\nfile.**\n> Before running any script, first `cd` to that directory or use the full\npath.\n\n\n### Method 1: Index Paper from arXiv\n\nAdd a paper to Hugging Face Paper Pages from arXiv.\n\n**Basic Usage:**\n```bash\nuv run scripts/paper_manager.py index \\\n  --arxiv-id \"2301.12345\"\n```\n\n**Check If Paper Exists:**\n```bash\nuv run scripts/paper_manager.py check \\\n  --arxiv-id \"2301.12345\"\n```\n\n**Direct URL Access:**\nYou can also visit `https://huggingface.co/papers/{arxiv-id}` directly to index a paper.\n\n### Method 2: Link Paper to Model/Dataset\n\nAdd paper references to model or dataset README with proper YAML metadata.\n\n**Add to Model Card:**\n```bash\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/model-name\" \\\n  --repo-type \"model\" \\\n  --arxiv-id \"2301.12345\"\n```\n\n**Add to Dataset Card:**\n```bash\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/dataset-name\" \\\n  --repo-type \"dataset\" \\\n  --arxiv-id \"2301.12345\"\n```\n\n**Add Multiple Papers:**\n```bash\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/model-name\" \\\n  --repo-type \"model\" \\\n  --arxiv-ids \"2301.12345,2302.67890,2303.11111\"\n```\n\n**With Custom Citation:**\n```bash\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/model-name\" \\\n  --repo-type \"model\" \\\n  --arxiv-id \"2301.12345\" \\\n  --citation \"$(cat citation.txt)\"\n```\n\n#### How Linking Works\n\nWhen you add an arXiv paper link to a model or dataset README:\n1. The Hub extracts the arXiv ID from the link\n2. A tag `arxiv:<PAPER_ID>` is automatically added to the repository\n3. Users can click the tag to view the Paper Page\n4. The Paper Page shows all models/datasets citing this paper\n5. Papers are discoverable through filters and search\n\n### Method 3: Claim Authorship\n\nVerify your authorship on papers published on Hugging Face.\n\n**Start Claim Process:**\n```bash\nuv run scripts/paper_manager.py claim \\\n  --arxiv-id \"2301.12345\" \\\n  --email \"your.email@institution.edu\"\n```\n\n**Manual Process:**\n1. Navigate to your paper''s page: `https://huggingface.co/papers/{arxiv-id}`\n2. Find your name in the author list\n3. Click your name and select \"Claim authorship\"\n4. Wait for admin team verification\n\n**Check Authorship Status:**\n```bash\nuv run scripts/paper_manager.py check-authorship \\\n  --arxiv-id \"2301.12345\"\n```\n\n### Method 4: Manage Paper Visibility\n\nControl which verified papers appear on your public profile.\n\n**List Your Papers:**\n```bash\nuv run scripts/paper_manager.py list-my-papers\n```\n\n**Toggle Visibility:**\n```bash\nuv run scripts/paper_manager.py toggle-visibility \\\n  --arxiv-id \"2301.12345\" \\\n  --show true\n```\n\n**Manage in Settings:**\nNavigate to your account settings → Papers section to toggle \"Show on profile\" for each paper.\n\n### Method 5: Create Research Article\n\nGenerate a professional markdown-based research paper using modern templates.\n\n**Create from Template:**\n```bash\nuv run scripts/paper_manager.py create \\\n  --template \"standard\" \\\n  --title \"Your Paper Title\" \\\n  --output \"paper.md\"\n```\n\n**Available Templates:**\n- `standard` - Traditional scientific paper structure\n- `modern` - Clean, web-friendly format inspired by Distill\n- `arxiv` - arXiv-style formatting\n- `ml-report` - Machine learning experiment report\n\n**Generate Complete Paper:**\n```bash\nuv run scripts/paper_manager.py create \\\n  --template \"modern\" \\\n  --title \"Fine-Tuning Large Language Models with LoRA\" \\\n  --authors \"Jane Doe, John Smith\" \\\n  --abstract \"$(cat abstract.txt)\" \\\n  --output \"paper.md\"\n```\n\n**Convert to HTML:**\n```bash\nuv run scripts/paper_manager.py convert \\\n  --input \"paper.md\" \\\n  --output \"paper.html\" \\\n  --style \"modern\"\n```\n\n### Paper Template Structure\n\n**Standard Research Paper Sections:**\n```markdown\n---\ntitle: Your Paper Title\nauthors: Jane Doe, John Smith\naffiliations: University X, Lab Y\ndate: 2025-01-15\narxiv: 2301.12345\ntags: [machine-learning, nlp, fine-tuning]\n---\n\n# Abstract\nBrief summary of the paper...\n\n# 1. Introduction\nBackground and motivation...\n\n# 2. Related Work\nPrevious research and context...\n\n# 3. Methodology\nApproach and implementation...\n\n# 4. Experiments\nSetup, datasets, and procedures...\n\n# 5. Results\nFindings and analysis...\n\n# 6. Discussion\nInterpretation and implications...\n\n# 7. Conclusion\nSummary and future work...\n\n# References\n```\n\n**Modern Template Features:**\n- Dynamic table of contents\n- Responsive design for web viewing\n- Code syntax highlighting\n- Interactive figures and charts\n- Math equation rendering (LaTeX)\n- Citation management\n- Author affiliation linking\n\n### Commands Reference\n\n**Index Paper:**\n```bash\nuv run scripts/paper_manager.py index --arxiv-id \"2301.12345\"\n```\n\n**Link to Repository:**\n```bash\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/repo-name\" \\\n  --repo-type \"model|dataset|space\" \\\n  --arxiv-id \"2301.12345\" \\\n  [--citation \"Full citation text\"] \\\n  [--create-pr]\n```\n\n**Claim Authorship:**\n```bash\nuv run scripts/paper_manager.py claim \\\n  --arxiv-id \"2301.12345\" \\\n  --email \"your.email@edu\"\n```\n\n**Manage Visibility:**\n```bash\nuv run scripts/paper_manager.py toggle-visibility \\\n  --arxiv-id \"2301.12345\" \\\n  --show true|false\n```\n\n**Create Research Article:**\n```bash\nuv run scripts/paper_manager.py create \\\n  --template \"standard|modern|arxiv|ml-report\" \\\n  --title \"Paper Title\" \\\n  [--authors \"Author1, Author2\"] \\\n  [--abstract \"Abstract text\"] \\\n  [--output \"filename.md\"]\n```\n\n**Convert Markdown to HTML:**\n```bash\nuv run scripts/paper_manager.py convert \\\n  --input \"paper.md\" \\\n  --output \"paper.html\" \\\n  [--style \"modern|classic\"]\n```\n\n**Check Paper Status:**\n```bash\nuv run scripts/paper_manager.py check --arxiv-id \"2301.12345\"\n```\n\n**List Your Papers:**\n```bash\nuv run scripts/paper_manager.py list-my-papers\n```\n\n**Search Papers:**\n```bash\nuv run scripts/paper_manager.py search --query \"transformer attention\"\n```\n\n### YAML Metadata Format\n\nWhen linking papers to models or datasets, proper YAML frontmatter is required:\n\n**Model Card Example:**\n```yaml\n---\nlanguage:\n  - en\nlicense: apache-2.0\ntags:\n  - text-generation\n  - transformers\n  - llm\nlibrary_name: transformers\n---\n\n# Model Name\n\nThis model is based on the approach described in [Our Paper](https://arxiv.org/abs/2301.12345).\n\n## Citation\n\n```bibtex\n@article{doe2023paper,\n  title={Your Paper Title},\n  author={Doe, Jane and Smith, John},\n  journal={arXiv preprint arXiv:2301.12345},\n  year={2023}\n}\n```\n```\n\n**Dataset Card Example:**\n```yaml\n---\nlanguage:\n  - en\nlicense: cc-by-4.0\ntask_categories:\n  - text-generation\n  - question-answering\nsize_categories:\n  - 10K<n<100K\n---\n\n# Dataset Name\n\nDataset introduced in [Our Paper](https://arxiv.org/abs/2301.12345).\n\nFor more details, see the [paper page](https://huggingface.co/papers/2301.12345).\n```\n\nThe Hub automatically extracts arXiv IDs from these links and creates `arxiv:2301.12345` tags.\n\n### Integration Examples\n\n**Workflow 1: Publish New Research**\n```bash\n# 1. Create research article\nuv run scripts/paper_manager.py create \\\n  --template \"modern\" \\\n  --title \"Novel Fine-Tuning Approach\" \\\n  --output \"paper.md\"\n\n# 2. Edit paper.md with your content\n\n# 3. Submit to arXiv (external process)\n# Upload to arxiv.org, get arXiv ID\n\n# 4. Index on Hugging Face\nuv run scripts/paper_manager.py index --arxiv-id \"2301.12345\"\n\n# 5. Link to your model\nuv run scripts/paper_manager.py link \\\n  --repo-id \"your-username/your-model\" \\\n  --repo-type \"model\" \\\n  --arxiv-id \"2301.12345\"\n\n# 6. Claim authorship\nuv run scripts/paper_manager.py claim \\\n  --arxiv-id \"2301.12345\" \\\n  --email \"your.email@edu\"\n```\n\n**Workflow 2: Link Existing Paper**\n```bash\n# 1. Check if paper exists\nuv run scripts/paper_manager.py check --arxiv-id \"2301.12345\"\n\n# 2. Index if needed\nuv run scripts/paper_manager.py index --arxiv-id \"2301.12345\"\n\n# 3. Link to multiple repositories\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/model-v1\" \\\n  --repo-type \"model\" \\\n  --arxiv-id \"2301.12345\"\n\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/training-data\" \\\n  --repo-type \"dataset\" \\\n  --arxiv-id \"2301.12345\"\n\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/demo-space\" \\\n  --repo-type \"space\" \\\n  --arxiv-id \"2301.12345\"\n```\n\n**Workflow 3: Update Model with Paper Reference**\n```bash\n# 1. Get current README\nhuggingface-cli download username/model-name README.md\n\n# 2. Add paper link\nuv run scripts/paper_manager.py link \\\n  --repo-id \"username/model-name\" \\\n  --repo-type \"model\" \\\n  --arxiv-id \"2301.12345\" \\\n  --citation \"Full citation for the paper\"\n\n# The script will:\n# - Add YAML metadata if missing\n# - Insert arXiv link in README\n# - Add formatted citation\n# - Preserve existing content\n```\n\n### Best Practices\n\n1. **Paper Indexing**\n   - Index papers as soon as they''re published on arXiv\n   - Include full citation information in model/dataset cards\n   - Use consistent paper references across related repositories\n\n2. **Metadata Management**\n   - Add YAML frontmatter to all model/dataset cards\n   - Include proper licensing information\n   - Tag with relevant task categories and domains\n\n3. **Authorship**\n   - Claim authorship on papers where you''re listed as author\n   - Use institutional email addresses for verification\n   - Keep paper visibility settings updated\n\n4. **Repository Linking**\n   - Link papers to all relevant models, datasets, and Spaces\n   - Include paper context in README descriptions\n   - Add BibTeX citations for easy reference\n\n5. **Research Articles**\n   - Use templates consistently within projects\n   - Include code and data links in papers\n   - Generate web-friendly HTML versions for sharing\n\n### Advanced Usage\n\n**Batch Link Papers:**\n```bash\n# Link multiple papers to one repository\nfor arxiv_id in \"2301.12345\" \"2302.67890\" \"2303.11111\"; do\n  uv run scripts/paper_manager.py link \\\n    --repo-id \"username/model-name\" \\\n    --repo-type \"model\" \\\n    --arxiv-id \"$arxiv_id\"\ndone\n```\n\n**Extract Paper Info:**\n```bash\n# Get paper metadata from arXiv\nuv run scripts/paper_manager.py info \\\n  --arxiv-id \"2301.12345\" \\\n  --format \"json\"\n```\n\n**Generate Citation:**\n```bash\n# Create BibTeX citation\nuv run scripts/paper_manager.py citation \\\n  --arxiv-id \"2301.12345\" \\\n  --format \"bibtex\"\n```\n\n**Validate Links:**\n```bash\n# Check all paper links in a repository\nuv run scripts/paper_manager.py validate \\\n  --repo-id \"username/model-name\" \\\n  --repo-type \"model\"\n```\n\n### Error Handling\n\n- **Paper Not Found**: arXiv ID doesn''t exist or isn''t indexed yet\n- **Permission Denied**: HF_TOKEN lacks write access to repository\n- **Invalid YAML**: Malformed metadata in README frontmatter\n- **Authorship Failed**: Email doesn''t match paper author records\n- **Already Claimed**: Another user has claimed authorship\n- **Rate Limiting**: Too many API requests in short time\n\n### Troubleshooting\n\n**Issue**: \"Paper not found on Hugging Face\"\n- **Solution**: Visit `hf.co/papers/{arxiv-id}` to trigger indexing\n\n**Issue**: \"Authorship claim not verified\"\n- **Solution**: Wait for admin review or contact HF support with proof\n\n**Issue**: \"arXiv tag not appearing\"\n- **Solution**: Ensure README includes proper arXiv URL format\n\n**Issue**: \"Cannot link to repository\"\n- **Solution**: Verify HF_TOKEN has write permissions\n\n**Issue**: \"Template rendering errors\"\n- **Solution**: Check markdown syntax and YAML frontmatter format\n\n### Resources and References\n\n- **Hugging Face Paper Pages**: [hf.co/papers](https://huggingface.co/papers)\n- **Model Cards Guide**: [hf.co/docs/hub/model-cards](https://huggingface.co/docs/hub/en/model-cards)\n- **Dataset Cards Guide**: [hf.co/docs/hub/datasets-cards](https://huggingface.co/docs/hub/en/datasets-cards)\n- **Research Article Template**: [tfrere/research-article-template](https://huggingface.co/spaces/tfrere/research-article-template)\n- **arXiv Format Guide**: [arxiv.org/help/submit](https://arxiv.org/help/submit)\n\n### Integration with tfrere''s Research Template\n\nThis skill complements [tfrere''s research article template](https://huggingface.co/spaces/tfrere/research-article-template) by providing:\n\n- Automated paper indexing workflows\n- Repository linking capabilities\n- Metadata management tools\n- Citation generation utilities\n\nYou can use tfrere''s template for writing, then use this skill to publish and link the paper on Hugging Face Hub.\n\n### Common Patterns\n\n**Pattern 1: New Paper Publication**\n```bash\n# Write → Publish → Index → Link\nuv run scripts/paper_manager.py create --template modern --output paper.md\n# (Submit to arXiv)\nuv run scripts/paper_manager.py index --arxiv-id \"2301.12345\"\nuv run scripts/paper_manager.py link --repo-id \"user/model\" --arxiv-id \"2301.12345\"\n```\n\n**Pattern 2: Existing Paper Discovery**\n```bash\n# Search → Check → Link\nuv run scripts/paper_manager.py search --query \"transformers\"\nuv run scripts/paper_manager.py check --arxiv-id \"2301.12345\"\nuv run scripts/paper_manager.py link --repo-id \"user/model\" --arxiv-id \"2301.12345\"\n```\n\n**Pattern 3: Author Portfolio Management**\n```bash\n# Claim → Verify → Organize\nuv run scripts/paper_manager.py claim --arxiv-id \"2301.12345\"\nuv run scripts/paper_manager.py list-my-papers\nuv run scripts/paper_manager.py toggle-visibility --arxiv-id \"2301.12345\" --show true\n```\n\n### API Integration\n\n**Python Script Example:**\n```python\nfrom scripts.paper_manager import PaperManager\n\npm = PaperManager(hf_token=\"your_token\")\n\n# Index paper\npm.index_paper(\"2301.12345\")\n\n# Link to model\npm.link_paper(\n    repo_id=\"username/model\",\n    repo_type=\"model\",\n    arxiv_id=\"2301.12345\",\n    citation=\"Full citation text\"\n)\n\n# Check status\nstatus = pm.check_paper(\"2301.12345\")\nprint(status)\n```\n\n### Future Enhancements\n\nPlanned features for future versions:\n- Support for non-arXiv papers (conference proceedings, journals)\n- Automatic citation formatting from DOI\n- Paper comparison and versioning tools\n- Collaborative paper writing features\n- Integration with LaTeX workflows\n- Automated figure and table extraction\n- Paper metrics and impact tracking\n"},"category":"official","lastSynced":"2026-03-06T05:38:57.171Z","seo":{"title":{"en":"hugging-face-paper-publisher: Streamlined Research Paper ...","zh":"Hugging Face 研究论文发布器设置指南","ja":"Hugging Face Paper Publisher のベストプラクティス","ko":"Hugging Face 연구 논문 발행기 사용법","es":"Guía de configuración de hugging-face-paper-publisher par...","fr":"Guide d''intégration de hugging-face-paper-publisher pour ...","de":"Einrichtungsleitfaden für hugging-face-paper-publisher fü...","pt":"Guia de Configuração do hugging-face-paper-publisher","ru":"Настройка hugging-face-paper-publisher: ИИ Агенты для исс...","ar":"دليل إعداد hugging-face-paper-publisher لأدوات الذكاء الا..."},"description":{"en":"Discover how hugging-face-paper-publisher simplifies research paper publication and management on Hugging Face Hub. Learn how to integrate with arXiv and lin...","zh":"使用 Hugging Face 研究论文发布器简化您的研究论文管理和发布流程，支持 arXiv 集成和模型/数据集链接","ja":"Hugging Face Paper Publisher を使って研究論文の管理と公開を効率化しよう。arXiv 統合やモデル/データセットのリンクもサポート","ko":"Hugging Face 연구 논문 발행기를 사용하여 연구 논문 관리와 발행을 간소화하십시오. arXiv 통합 및 모델/데이터셋 링크도 지원됩니다","es":"Descubre cómo publicar y gestionar artículos de investigación en Hugging Face Hub con hugging-face-paper-publisher. Integra modelos, datasets y más","fr":"Découvrez comment publier et gérer des articles de recherche sur Hugging Face Hub avec hugging-face-paper-publisher. Intégrez des modèles, des datasets et plus","de":"Erfahren Sie, wie Sie Forschungsartikel in Hugging Face Hub mit hugging-face-paper-publisher veröffentlichen und verwalten. Integrieren Sie Modelle, Daten un...","pt":"Aprenda a publicar e gerenciar artigos de pesquisa no Hugging Face Hub com o hugging-face-paper-publisher","ru":"Опубликуйте и управляйте исследовательскими статьями на Hugging Face Hub с помощью hugging-face-paper-publisher и ИИ Агентов","ar":"تعلم نشر وإدارة الأبحاث على منصة Hugging Face Hub باستخدام hugging-face-paper-publisher وأدوات الذكاء الاصطناعي"},"definition":{"en":"hugging-face-paper-publisher is a comprehensive tool for publishing, managing, and linking research papers on Hugging Face Hub, integrating with arXiv and supporting model/dataset linking.","zh":"Hugging Face 研究论文发布器是一种 AI 工具，用于简化研究论文的管理和发布流程","ja":"Hugging Face Paper Publisher は、研究論文の管理と公開を効率化するための AI エージェントです","ko":"Hugging Face 연구 논문 발행기는 연구 논문의 관리와 발행을 간소화하는 AI 도구입니다","es":"hugging-face-paper-publisher es una herramienta de publicación de artículos de investigación en Hugging Face Hub","fr":"hugging-face-paper-publisher est un outil de publication d''articles de recherche sur Hugging Face Hub","de":"hugging-face-paper-publisher ist ein Werkzeug zur Veröffentlichung von Forschungsartikeln in Hugging Face Hub","pt":"O hugging-face-paper-publisher é uma ferramenta de publicação de artigos de pesquisa que integra com o Hugging Face Hub.","ru":"hugging-face-paper-publisher - это инструмент для публикации исследовательских статей, интегрирующийся с Hugging Face Hub.","ar":"هو hugging-face-paper-publisher أداة لنشر الأبحاث متكاملة مع منصة Hugging Face Hub"},"features":{"en":["Creates paper pages on Hugging Face Hub","Supports arXiv integration via automatic paper indexing from arXiv IDs","Enables model/dataset linking for research papers","Generates professional markdown-based research articles","Allows claiming authorship for published papers","Streamlines workflow from paper creation to publication"],"zh":["支持创建论文页面","支持 arXiv 集成","支持模型/数据集链接","支持声明作者权","支持生成专业的 markdown 格式研究文章"],"ja":["論文ページの作成をサポート","arXiv 統合をサポート","モデル/データセットへのリンクをサポート","著者権の申請をサポート","プロフェッショナルな markdown 形式の研究記事の生成をサポート"],"ko":["논문 페이지 생성 지원","arXiv 통합 지원","모델/데이터셋 링크 지원","저자 권한声明 지원","전문가급 markdown 형식 연구 기사 생성 지원"],"es":["Creación de páginas de artículos de investigación","Integración con arXiv","Conexión de artículos con modelos y datasets","Gestión de autorías","Generación de artículos de investigación en formato Markdown"],"fr":["Création de pages d''articles de recherche","Intégration avec arXiv","Connexion d''articles avec des modèles et des datasets","Gestion des autorités","Génération d''articles de recherche au format Markdown"],"de":["Erstellung von Forschungsartikelseiten","Integration mit arXiv","Verbindung von Artikeln mit Modellen und Daten","Verwaltung von Autorenschaften","Generierung von Forschungsartikeln im Markdown-Format"],"pt":["Criação de páginas de artigos de pesquisa","Integração com arXiv","Linkagem de modelos e datasets","Gerenciamento de autorias","Geração de artigos de pesquisa em markdown"],"ru":["Создание страниц исследовательских статей","Интеграция с arXiv","Связь моделей и данных","Управление авторством","Генерация исследовательских статей в markdown"],"ar":["إنشاء صفحات لأبحاث","التكامل مع arXiv","ربط النماذج والمجموعات البيانية","إدارة تأليف","توليد مقالات البحث بالتنسيق markdown"]},"keywords":{"en":["hugging-face-paper-publisher setup guide","how to use hugging-face-paper-publisher","hugging-face-paper-publisher alternative","hugging-face-paper-publisher vs arXiv","hugging-face-paper-publisher install","research paper management on Hugging Face Hub","arXiv integration with hugging-face-paper-publisher","model/dataset linking with hugging-face-paper-publisher"],"zh":["Hugging Face 研究论文发布器","AI 工具","研究论文管理","论文发布","arXiv 集成","模型/数据集链接","声明作者权","markdown 格式研究文章"],"ja":["Hugging Face Paper Publisher","AI エージェント","研究論文の管理","論文の公開","arXiv 統合","モデル/データセットへのリンク","著者権の申請","markdown 形式の研究記事"],"ko":["Hugging Face 연구 논문 발행기","AI 도구","연구 논문 관리","논문 발행","arXiv 통합","모델/데이터셋 링크","저자 권한声明","markdown 형식 연구 기사"],"es":["hugging face paper publisher","publicación de artículos de investigación","Hugging Face Hub","integración con arXiv","conexión de artículos con modelos","gestión de autorías","generación de artículos de investigación","herramientas de investigación","agentes de IA para investigación"],"fr":["hugging face paper publisher","publication d''articles de recherche","Hugging Face Hub","intégration avec arXiv","connexion d''articles avec des modèles","gestion des autorités","génération d''articles de recherche","outils de recherche","agents d''IA pour la recherche"],"de":["hugging face paper publisher","Veröffentlichung von Forschungsartikeln","Hugging Face Hub","Integration mit arXiv","Verbindung von Artikeln mit Modellen","Verwaltung von Autorenschaften","Generierung von Forschungsartikeln","Forschungstools","KI-Agents für die Forschung"],"pt":["hugging face paper publisher","publicação de artigos de pesquisa","gerenciamento de artigos de pesquisa","integração com arXiv","linkagem de modelos e datasets","gerenciamento de autorias","geração de artigos de pesquisa em markdown","ferramentas de pesquisa","hugging face hub"],"ru":["hugging face paper publisher","публикация исследовательских статей","управление исследовательскими статьями","интеграция с arXiv","связь моделей и данных","управление авторством","генерация исследовательских статей в markdown","инструменты для исследователей","hugging face hub","ИИ Агенты"],"ar":["hugging face paper publisher","نشر الأبحاث","إدارة الأبحاث","التكامل مع arXiv","ربط النماذج والمجموعات البيانية","إدارة تأليف","توليد مقالات البحث بالتنسيق markdown","أدوات البحث","منصة Hugging Face Hub","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Research Agents needing streamlined publication and management of research papers on Hugging Face Hub.","zh":"适合需要在 Hugging Face Hub 上简化研究论文发布和管理的 AI 研究代理。","ja":"Hugging Face Hub で研究論文の公開と管理をストリームライン化する必要がある AI 研究エージェントに最適です。","ko":"Hugging Face Hub 에서 연구 논문의 출판 및 관리를 간소화해야 하는 AI 연구 에이전트에게 적합합니다.","es":"Perfecto para agentes de investigación de IA que necesitan una publicación y gestión simplificadas de artículos de investigación en Hugging Face Hub.","fr":"Parfait pour les agents de recherche en IA ayant besoin d''une publication et d''une gestion simplifiées des articles de recherche sur Hugging Face Hub.","de":"Perfekt für KI-Forschungsagenten, die eine vereinfachte Veröffentlichung und Verwaltung von Forschungsarbeiten auf Hugging Face Hub benötigen.","pt":"Perfeito para Agentes de Pesquisa de IA que precisam de publicação e gestão de artigos de pesquisa otimizadas no Hugging Face Hub.","ru":"Идеально для агентов-исследователей ИИ, которым необходима упрощенная публикация и управление исследовательскими работами на Hugging Face Hub.","ar":"مثالي لعميل البحث بالذكاء الاصطناعي الذي يحتاج إلى نشر و إدارة مقالات البحث على منصة Hugging Face Hub بسهولة."},"recommendation":{"en":"Empowers agents to publish and manage research papers, linking them to models and datasets, and generating professional markdown-based research articles, leveraging arXiv integration and authorship management.","zh":"赋予代理发布和管理研究论文的能力，将其链接到模型和数据集，并生成基于 markdown 的专业研究文章，利用 arXiv 集成和作者管理。","ja":"エージェントが研究論文を公開・管理し、それらをモデルやデータセットにリンクし、プロフェッショナルな markdown ベースの研究記事を生成する能力を付与します。また、arXiv 統合や著者管理も利用できます。","ko":"에이전트가 연구 논문을 출판하고 관리하고, 모델 및 데이터셋에 연결하고, 전문가용 markdown 기반 연구 기사를 생성하는 기능을 제공하며, arXiv 통합 및 저자 관리도 활용할 수 있습니다.","es":"Habilita a los agentes a publicar y gestionar artículos de investigación, enlazándolos con modelos y conjuntos de datos, y generando artículos de investigación profesionales basados en markdown, aprovechando la integración con arXiv y la gestión de autorías.","fr":"Permet aux agents de publier et de gérer des articles de recherche, en les liant à des modèles et à des jeux de données, et en générant des articles de recherche professionnels basés sur markdown, en exploitant l''intégration avec arXiv et la gestion des auteurs.","de":"Ermächtigt Agenten, Forschungsarbeiten zu veröffentlichen und zu verwalten, indem sie diese mit Modellen und Datensätzen verknüpfen und professionelle markdown-basierte Forschungsartikel generieren, die arXiv-Integration und Autorenverwaltung nutzend.","pt":"Habilita os agentes a publicar e gerenciar artigos de pesquisa, vinculando-os a modelos e conjuntos de dados, e gerando artigos de pesquisa profissionais baseados em markdown, aproveitando a integração com arXiv e gerenciamento de autorias.","ru":"Наделяет агентов возможностью публиковать и управлять исследовательскими работами, связывая их с моделями и наборами данных, и генерируя профессиональные статьи исследования на основе markdown, используя интеграцию с arXiv и управление авторством.","ar":"يسمح للوكيل بنشر و إدارة مقالات البحث و ربطها بالنماذج و مجموعات البيانات و إنتاج مقالات بحث احترافية تعتمد على markdown، مستفيداً من التكامل مع arXiv و إدارة المؤلفين."},"useCases":{"en":["Publishing research papers on Hugging Face Hub","Linking papers to models and datasets for enhanced discoverability","Generating markdown-based research articles for professional publication"],"zh":["在 Hugging Face Hub 上发布研究论文","将论文链接到模型和数据集以提高发现度","生成基于 markdown 的研究文章用于专业出版"],"ja":["Hugging Face Hub で研究論文を公開する","論文をモデルやデータセットにリンクして発見性を高める","プロフェッショナルな出版のための markdown ベースの研究記事を生成する"],"ko":["Hugging Face Hub 에서 연구 논문을 출판하는 것","논문을 모델 및 데이터셋에 연결하여 발견성을 높이는 것","전문가용 출판을 위한 markdown 기반 연구 기사를 생성하는 것"],"es":["Publicar artículos de investigación en Hugging Face Hub","Enlazar artículos con modelos y conjuntos de datos para una mayor capacidad de descubrimiento","Generar artículos de investigación basados en markdown para publicación profesional"],"fr":["Publier des articles de recherche sur Hugging Face Hub","Lier les articles à des modèles et à des jeux de données pour une meilleure découverte","Générer des articles de recherche basés sur markdown pour publication professionnelle"],"de":["Veröffentlichen von Forschungsarbeiten auf Hugging Face Hub","Verknüpfen von Artikeln mit Modellen und Datensätzen für eine verbesserte Auffindbarkeit","Generieren von markdown-basierten Forschungsartikeln für professionelle Veröffentlichung"],"pt":["Publicação de artigos de pesquisa no Hugging Face Hub","Vinculação de artigos a modelos e conjuntos de dados para melhor descoberta","Geração de artigos de pesquisa baseados em markdown para publicação profissional"],"ru":["Публикация исследовательских работ на Hugging Face Hub","Связывание статей с моделями и наборами данных для улучшения обнаружения","Генерация статей исследования на основе markdown для профессиональной публикации"],"ar":["نشر مقالات البحث على منصة Hugging Face Hub","ربط المقالات بالنماذج و مجموعات البيانات لتسهيل الوصول إليها","إنتاج مقالات بحث تعتمد على markdown للنشر المهني"]},"limitations":{"en":["Requires Hugging Face Hub account","arXiv integration requires valid arXiv IDs"],"zh":["需要 Hugging Face Hub 账户","arXiv 集成需要有效的 arXiv ID"],"ja":["Hugging Face Hub アカウントが必要","arXiv 統合には有効な arXiv ID が必要"],"ko":["Hugging Face Hub 계정이 필요함","arXiv 통합을 위해 유효한 arXiv ID 가 필요함"],"es":["Requiere una cuenta de Hugging Face Hub","La integración con arXiv requiere IDs de arXiv válidos"],"fr":["Nécessite un compte Hugging Face Hub","L''intégration avec arXiv nécessite des IDs arXiv valides"],"de":["Benötigt ein Konto auf Hugging Face Hub","Die Integration mit arXiv erfordert gültige arXiv-IDs"],"pt":["Exige conta no Hugging Face Hub","Integração com arXiv exige IDs de arXiv válidos"],"ru":["Требует учетной записи на Hugging Face Hub","Интеграция с arXiv требует действительных идентификаторов arXiv"],"ar":["يتطلب حساب على منصة Hugging Face Hub","التكامل مع arXiv يتطلب معرفات arXiv صالحة"]},"version":4},"contentHash":"a9e12c89297d4085e045aa682c65f27adb456986c5cc3770cb481ce62cd6bcaa","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":95}');
