INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-paper-publisher', 'hugging-face-paper-publisher', 'huggingface', 'skills', 'official', 'hugging-face-paper-publisher huggingface skills official The hugging-face-paper-publisher skill provides AI engineers and researchers with tools to publish and manage research papers on Hugging Face Hub, supporting paper creation, arXiv integration, and authorship management. Hugging Face 研究论文发布器提供了一套全面的工具，用于在 Hugging Face Hub 上发布、管理和链接研究论文。它支持创建论文页面、链接论文到模型/数据集、声明作者权和生成专业的 markdown 格式研究文章 Hugging Face Paper Publisher は、Hugging Face Hub 上で研究論文を公開、管理、リンクするための包括的なツールを提供します。論文ページの作成、モデル/データセットへのリンク、著者権の申請、プロフェッショナルな markdown 形式の研究記事の生成をサポート Hugging Face 연구 논문 발행기는 Hugging Face Hub에서 연구 논문을 발행, 관리, 링크하는 데 필요한 포괄적인 도구를 제공합니다. 논문 페이지 생성, 모델/데이터셋 링크, 저자 권한声明, 전문가급 markdown 형식 연구 기사의 생성을 지원합니다 Herramienta para investigadores que permite publicar y gestionar artículos de investigación en Hugging Face Hub, con integración de modelos y datasets. Outil pour les chercheurs qui permet de publier et de gérer des articles de recherche sur Hugging Face Hub, avec intégration de modèles et de datasets. Werkzeug für KI-Forscher, um Forschungsartikel in Hugging Face Hub zu veröffentlichen und zu verwalten, mit Integration von Modellen und Daten O hugging-face-paper-publisher é uma ferramenta para publicar e gerenciar artigos de pesquisa no Hugging Face Hub, integrando com arXiv e modelos/datasets. hugging-face-paper-publisher - это инструмент для публикации и управления исследовательскими статьями на Hugging Face Hub, интегрирующийся с arXiv и моделями/данными. هو hugging-face-paper-publisher أداة لنشر وإدارة الأبحاث على منصة Hugging Face Hub، متكاملة مع arXiv والمدلسات/المجموعات البيانية hugging-face-paper-publisher setup guide how to use hugging-face-paper-publisher hugging-face-paper-publisher alternative hugging-face-paper-publisher vs arXiv hugging-face-paper-publisher install research paper management on Hugging Face Hub arXiv integration with hugging-face-paper-publisher model/dataset linking with hugging-face-paper-publisher Hugging Face 研究论文发布器 AI 工具 研究论文管理 论文发布 arXiv 集成 模型/数据集链接 声明作者权 markdown 格式研究文章 Creates paper pages on Hugging Face Hub Supports arXiv integration via automatic paper indexing from arXiv IDs Enables model/dataset linking for research papers Generates professional markdown-based research articles Allows claiming authorship for published papers Streamlines workflow from paper creation to publication hugging-face-paper-publisher is a comprehensive tool for publishing, managing, and linking research papers on Hugging Face Hub, integrating with arXiv and supporting model/dataset linking.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('google-labs-code/stitch-skills/design-md', 'official', 'google-labs-code', 'stitch-skills', 'google-labs-code/stitch-skills', 'design-md', 2204, 256, 95, '2026-03-06T05:29:41Z', '2026-03-06T05:43:16.876Z', 'eb15f44646528f3a087ce023329ae699c1b6e803662af68338e1eb1c0406b59b', '{"id":"google-labs-code/stitch-skills/design-md","name":"design-md","description":{"en":"The design-md skill analyzes Stitch projects and generates DESIGN.md files, serving as the source of truth for prompting Stitch to create new screens. It benefits Design Systems Leads and developers working with Stitch.","zh":"设计-md 技术能够分析 Stitch 项目并生成 DESIGN.md 文件，实现semantic design system。","ja":"design-md 技術は Stitch プロジェクトを分析し、DESIGN.md ファイルを生成してセマンティック デザイン システムを実現します。","ko":"디자인-md 기술은 Stitch 프로젝트를 분석하여 DESIGN.md 파일을 생성하고 시맨틱 디자인 시스템을 구현합니다.","es":"La habilidad design-md analiza proyectos Stitch y crea sistemas de diseño semánticos en archivos DESIGN.md. Ayuda a generar nuevas pantallas que se ajustan a la lengua de diseño existente.","fr":"La compétence design-md analyse les projets Stitch et crée des systèmes de conception sémantiques dans des fichiers DESIGN.md. Elle aide à générer de nouveaux écrans qui s''alignent sur la langue de conception existante.","de":"Die Fähigkeit design-md analysiert Stitch-Projekte und erstellt semantische Designsysteme in DESIGN.md-Dateien. Sie hilft bei der Generierung neuer Bildschirme, die sich an die bestehende Designsprache anpassen.","pt":"O design-md é uma habilidade que analisa projetos Stitch e sintetiza um sistema de design semântico em arquivos DESIGN.md","ru":"ИИ Агент design-md анализирует проекты Stitch и синтезирует семантическую систему дизайна в файлах DESIGN.md","ar":"الوكيل الذكي design-md يقوم بتحليل مشاريع Stitch ودمج نظام ديزاين семантиكي في ملفات DESIGN.md"},"owner":"google-labs-code","repo":"stitch-skills","repoPath":"google-labs-code/stitch-skills","stars":2204,"forks":256,"updatedAt":"2026-03-06T05:29:41Z","topics":[],"skillMd":{"name":"design-md","description":"Analyze Stitch projects and synthesize a semantic design system into DESIGN.md files","bodyPreview":"# Stitch DESIGN.md Skill\n\nYou are an expert Design Systems Lead. Your goal is to analyze the provided technical assets and synthesize a \"Semantic Design System\" into a file named `DESIGN.md`.\n\n## Overview\n\nThis skill helps you create `DESIGN.md` files that serve as the \"source of truth\" for prompting Stitch to generate new screens that align perfectly with existing design language. Stitch interprets design through \"Visual Descriptions\" supported by specific color values.\n\n## Prerequisites\n\n- Acc","body":"# Stitch DESIGN.md Skill\n\nYou are an expert Design Systems Lead. Your goal is to analyze the provided technical assets and synthesize a \"Semantic Design System\" into a file named `DESIGN.md`.\n\n## Overview\n\nThis skill helps you create `DESIGN.md` files that serve as the \"source of truth\" for prompting Stitch to generate new screens that align perfectly with existing design language. Stitch interprets design through \"Visual Descriptions\" supported by specific color values.\n\n## Prerequisites\n\n- Access to the Stitch MCP Server\n- A Stitch project with at least one designed screen\n- Access to the Stitch Effective Prompting Guide: https://stitch.withgoogle.com/docs/learn/prompting/\n\n## The Goal\n\nThe `DESIGN.md` file will serve as the \"source of truth\" for prompting Stitch to generate new screens that align perfectly with the existing design language. Stitch interprets design through \"Visual Descriptions\" supported by specific color values.\n\n## Retrieval and Networking\n\nTo analyze a Stitch project, you must retrieve screen metadata and design assets using the Stitch MCP Server tools:\n\n1. **Namespace discovery**: Run `list_tools` to find the Stitch MCP prefix. Use this prefix (e.g., `mcp_stitch:`) for all subsequent calls.\n\n2. **Project lookup** (if Project ID is not provided):\n   - Call `[prefix]:list_projects` with `filter: \"view=owned\"` to retrieve all user projects\n   - Identify the target project by title or URL pattern\n   - Extract the Project ID from the `name` field (e.g., `projects/13534454087919359824`)\n\n3. **Screen lookup** (if Screen ID is not provided):\n   - Call `[prefix]:list_screens` with the `projectId` (just the numeric ID, not the full path)\n   - Review screen titles to identify the target screen (e.g., \"Home\", \"Landing Page\")\n   - Extract the Screen ID from the screen''s `name` field\n\n4. **Metadata fetch**: \n   - Call `[prefix]:get_screen` with both `projectId` and `screenId` (both as numeric IDs only)\n   - This returns the complete screen object including:\n     - `screenshot.downloadUrl` - Visual reference of the design\n     - `htmlCode.downloadUrl` - Full HTML/CSS source code\n     - `width`, `height`, `deviceType` - Screen dimensions and target platform\n     - Project metadata including `designTheme` with color and style information\n\n5. **Asset download**:\n   - Use `web_fetch` or `read_url_content` to download the HTML code from `htmlCode.downloadUrl`\n   - Optionally download the screenshot from `screenshot.downloadUrl` for visual reference\n   - Parse the HTML to extract Tailwind classes, custom CSS, and component patterns\n\n6. **Project metadata extraction**:\n   - Call `[prefix]:get_project` with the project `name` (full path: `projects/{id}`) to get:\n     - `designTheme` object with color mode, fonts, roundness, custom colors\n     - Project-level design guidelines and descriptions\n     - Device type preferences and layout principles\n\n## Analysis & Synthesis Instructions\n\n### 1. Extract Project Identity (JSON)\n- Locate the Project Title\n- Locate the specific Project ID (e.g., from the `name` field in the JSON)\n\n### 2. Define the Atmosphere (Image/HTML)\nEvaluate the screenshot and HTML structure to capture the overall \"vibe.\" Use evocative adjectives to describe the mood (e.g., \"Airy,\" \"Dense,\" \"Minimalist,\" \"Utilitarian\").\n\n### 3. Map the Color Palette (Tailwind Config/JSON)\nIdentify the key colors in the system. For each color, provide:\n- A descriptive, natural language name that conveys its character (e.g., \"Deep Muted Teal-Navy\")\n- The specific hex code in parentheses for precision (e.g., \"#294056\")\n- Its specific functional role (e.g., \"Used for primary actions\")\n\n### 4. Translate Geometry & Shape (CSS/Tailwind)\nConvert technical `border-radius` and layout values into physical descriptions:\n- Describe `rounded-full` as \"Pill-shaped\"\n- Describe `rounded-lg` as \"Subtly rounded corners\"\n- Describe `rounded-none` as \"Sharp, squared-off edges\"\n\n### 5. Describe Depth & Elevation\nExplain how the UI handles layers. Describe the presence and quality of shadows (e.g., \"Flat,\" \"Whisper-soft diffused shadows,\" or \"Heavy, high-contrast drop shadows\").\n\n## Output Guidelines\n\n- **Language:** Use descriptive design terminology and natural language exclusively\n- **Format:** Generate a clean Markdown file following the structure below\n- **Precision:** Include exact hex codes for colors while using descriptive names\n- **Context:** Explain the \"why\" behind design decisions, not just the \"what\"\n\n## Output Format (DESIGN.md Structure)\n\n```markdown\n# Design System: [Project Title]\n**Project ID:** [Insert Project ID Here]\n\n## 1. Visual Theme & Atmosphere\n(Description of the mood, density, and aesthetic philosophy.)\n\n## 2. Color Palette & Roles\n(List colors by Descriptive Name + Hex Code + Functional Role.)\n\n## 3. Typography Rules\n(Description of font family, weight usage for headers vs. body, and letter-spacing character.)\n\n## 4. Component Stylings\n* **Buttons:** (Shape description, color assignment, behavior).\n* **Cards/Containers:** (Corner roundness description, background color, shadow depth).\n* **Inputs/Forms:** (Stroke style, background).\n\n## 5. Layout Principles\n(Description of whitespace strategy, margins, and grid alignment.)\n```\n\n## Usage Example\n\nTo use this skill for the Furniture Collection project:\n\n1. **Retrieve project information:**\n   ```\n   Use the Stitch MCP Server to get the Furniture Collection project\n   ```\n\n2. **Get the Home page screen details:**\n   ```\n   Retrieve the Home page screen''s code, image, and screen object information\n   ```\n\n3. **Reference best practices:**\n   ```\n   Review the Stitch Effective Prompting Guide at:\n   https://stitch.withgoogle.com/docs/learn/prompting/\n   ```\n\n4. **Analyze and synthesize:**\n   - Extract all relevant design tokens from the screen\n   - Translate technical values into descriptive language\n   - Organize information according to the DESIGN.md structure\n\n5. **Generate the file:**\n   - Create `DESIGN.md` in the project directory\n   - Follow the prescribed format exactly\n   - Ensure all color codes are accurate\n   - Use evocative, designer-friendly language\n\n## Best Practices\n\n- **Be Descriptive:** Avoid generic terms like \"blue\" or \"rounded.\" Use \"Ocean-deep Cerulean (#0077B6)\" or \"Gently curved edges\"\n- **Be Functional:** Always explain what each design element is used for\n- **Be Consistent:** Use the same terminology throughout the document\n- **Be Visual:** Help readers visualize the design through your descriptions\n- **Be Precise:** Include exact values (hex codes, pixel values) in parentheses after natural language descriptions\n\n## Tips for Success\n\n1. **Start with the big picture:** Understand the overall aesthetic before diving into details\n2. **Look for patterns:** Identify consistent spacing, sizing, and styling patterns\n3. **Think semantically:** Name colors by their purpose, not just their appearance\n4. **Consider hierarchy:** Document how visual weight and importance are communicated\n5. **Reference the guide:** Use language and patterns from the Stitch Effective Prompting Guide\n\n## Common Pitfalls to Avoid\n\n- ❌ Using technical jargon without translation (e.g., \"rounded-xl\" instead of \"generously rounded corners\")\n- ❌ Omitting color codes or using only descriptive names\n- ❌ Forgetting to explain functional roles of design elements\n- ❌ Being too vague in atmosphere descriptions\n- ❌ Ignoring subtle design details like shadows or spacing patterns\n"},"category":"official","lastSynced":"2026-03-06T05:43:16.876Z","seo":{"title":{"en":"design-md: Semantic Design System Setup Guide | AI Agent ...","zh":"设计-md 技术指南：AIエージェント集成","ja":"design-md Setup Guide: AIエージェントによるデザインシステム","ko":"디자인-md 설정 가이드: AI 에이전트를 사용한 시맨틱 디자인 시스템","es":"Guía de configuración de design-md para sistemas de diseñ...","fr":"Configurer design-md pour les systèmes de conception séma...","de":"Einrichtungsleitfaden für design-md und semantische Desig...","pt":"Guia de Configuração do design-md: Criando Sistemas de De...","ru":"Настройка ИИ Агента design-md: Создание Семантических Сис...","ar":"دليل إعداد design-md: إنشاء أنظمة ديزاين семантиكية باستخ..."},"description":{"en":"Unlock the power of design-md and discover how to synthesize a semantic design system into DESIGN.md files. Learn more and get started today!","zh":"了解设计-md 技术的工作原理，学习如何使用 AIエージェント创建 DESIGN.md 文件","ja":"design-md の機能と設定方法について詳しく学び、AIエージェントを活用してデザインシステムを構築する","ko":"디자인-md 기술의 기능과 설정 방법을 알아보고 AI 에이전트를 사용하여 DESIGN.md 파일을 생성하는 방법을 배우세요","es":"Aprende a analizar proyectos Stitch y sintetizar sistemas de diseño semánticos en archivos DESIGN.md con la habilidad design-md","fr":"Découvrez comment analyser les projets Stitch et synthétiser des systèmes de conception sémantiques dans des fichiers DESIGN.md avec la compétence design-md","de":"Erfahren Sie, wie Sie Stitch-Projekte analysieren und semantische Designsysteme in DESIGN.md-Dateien synthetisieren können mit der Fähigkeit design-md","pt":"Aprenda a configurar o design-md para criar sistemas de design semânticos e gerar telas alinhadas com a linguagem de design existente","ru":"Узнайте, как настроить ИИ Агент design-md для создания семантических систем дизайна и генерации экранов, соответствующих существующему языку дизайна","ar":"تعلم كيفية إعداد design-md لإنشاء أنظمة ديزاين семантиكية وتوليد شاشات متوافقة مع لغة التصميم الحالية باستخدام أدوات ذكاء اصطناعي"},"definition":{"en":"design-md is a skill that synthesizes a semantic design system into DESIGN.md files, interpreting design through visual descriptions supported by specific color values.","zh":"设计-md 是一种 AIエージェント技术，用于创建 DESIGN.md 文件以实现semantic design system。","ja":"design-md は、AIエージェント技術の一種で、DESIGN.md ファイルを生成してセマンティック デザイン システムを実現するものです。","ko":"디자인-md는 DESIGN.md 파일을 생성하여 시맨틱 디자인 시스템을 구현하는 AI 에이전트 기술입니다.","es":"La habilidad design-md es una herramienta de inteligencia artificial que analiza proyectos Stitch y sintetiza sistemas de diseño semánticos","fr":"La compétence design-md est un outil d''intelligence artificielle qui analyse les projets Stitch et synthétise des systèmes de conception sémantiques","de":"Die Fähigkeit design-md ist ein KI-Tool, das Stitch-Projekte analysiert und semantische Designsysteme synthetisiert","pt":"O que é design-md? É uma habilidade que cria sistemas de design semânticos em arquivos DESIGN.md","ru":"Что такое ИИ Агент design-md? Это habilidade, создающая семантические системы дизайна в файлах DESIGN.md","ar":"ما هو design-md؟ هو وكيل ذكي يخلق أنظمة ديزاين семантиكية في ملفات DESIGN.md"},"features":{"en":["Analyzes Stitch projects to synthesize a semantic design system","Generates DESIGN.md files as the source of truth for Stitch","Interprets design through visual descriptions supported by specific color values","Creates files that prompt Stitch to generate new screens aligned with existing design language"],"zh":["分析 Stitch 项目","生成 DESIGN.md 文件","实现semantic design system","支持 Visual Descriptions","使用特定颜色值","创建设计语言的源头"],"ja":["Stitch プロジェクトの分析","DESIGN.md ファイルの生成","セマンティック デザイン システムの実現","Visual Descriptions のサポート","特定の色値の使用","デザイン言語の源となるファイルの作成"],"ko":["Stitch 프로젝트 분석","DESIGN.md 파일 생성","시맨틱 디자인 시스템 구현","Visual Descriptions 지원","특정 색상 값 사용","디자인 언어의 원천 파일 생성"],"es":["Análisis de proyectos Stitch","Síntesis de sistemas de diseño semánticos","Creación de archivos DESIGN.md","Generación de nuevas pantallas que se ajustan a la lengua de diseño existente","Soporte para descripciones visuales y valores de color específicos"],"fr":["Analyse de projets Stitch","Synthèse de systèmes de conception sémantiques","Création de fichiers DESIGN.md","Génération de nouveaux écrans qui s''alignent sur la langue de conception existante","Prise en charge de descriptions visuelles et de valeurs de couleur spécifiques"],"de":["Analyse von Stitch-Projekten","Synthese von semantischen Designsystemen","Erstellung von DESIGN.md-Dateien","Generierung neuer Bildschirme, die sich an die bestehende Designsprache anpassen","Unterstützung für visuelle Beschreibungen und spezifische Farbwerte"],"pt":["Análise de projetos Stitch","Criação de sistemas de design semânticos","Geração de telas alinhadas com a linguagem de design existente","Suporte a descrições visuais específicas","Interpretação de design por meio de valores de cor"],"ru":["Анализ проектов Stitch","Создание семантических систем дизайна","Генерация экранов, соответствующих существующему языку дизайна","Поддержка специфических визуальных описаний","Интерпретация дизайна через значения цвета"],"ar":["تحليل مشاريع Stitch","إنشاء أنظمة ديزاين семантиكية","توليد شاشات متوافقة مع لغة التصميم الحالية","دعم وصفات بصرية محددة","تفسير التصميم من خلال قيم اللون"]},"keywords":{"en":["how to use design-md","what is design-md","design-md setup guide","design-md alternative","design-md vs Stitch","design-md install","semantic design system","Stitch design language","DESIGN.md file generation"],"zh":["设计-md","AIエージェント","Stitch 项目","DESIGN.md 文件","semantic design system","Visual Descriptions","特定颜色值","设计语言"],"ja":["design-md","AIエージェント","Stitch プロジェクト","DESIGN.md ファイル","セマンティック デザイン システム","Visual Descriptions","特定の色値","デザイン言語"],"ko":["디자인-md","AI 에이전트","Stitch 프로젝트","DESIGN.md 파일","시맨틱 디자인 시스템","Visual Descriptions","특정 색상 값","디자인 언어"],"es":["design-md","sistemas de diseño semánticos","Stitch","DESIGN.md","herramientas de inteligencia artificial","desarrollo de software","diseño de interfaz de usuario","generación de pantallas"],"fr":["design-md","systèmes de conception sémantiques","Stitch","DESIGN.md","outils d''intelligence artificielle","développement de logiciels","conception d''interface utilisateur","génération d''écrans"],"de":["design-md","semantische Designsysteme","Stitch","DESIGN.md","KI-Tools","Softwareentwicklung","Benutzeroberflächendesign","Bildschirmgenerierung"],"pt":["design-md","sistemas de design semânticos","Stitch","DESIGN.md","descrições visuais","valores de cor","linguagem de design","geração de telas","configuração do design-md"],"ru":["ИИ Агент design-md","семантические системы дизайна","Stitch","DESIGN.md","визуальные описания","значения цвета","язык дизайна","генерация экранов","настройка ИИ Агента design-md"],"ar":["الوكيل الذكي design-md","أنظمة ديزاين семантиكية","Stitch","DESIGN.md","وصفات بصرية","قيم اللون","لغة التصميم","توليد الشاشات","إعداد الوكيل الذكي design-md"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Visual Design Agents needing to generate semantic design systems through DESIGN.md files","zh":"适合于需要通过 DESIGN.md 文件生成语义设计系统的视觉设计代理","ja":"DESIGN.md ファイルを介してセマンティックデザインシステムを生成する必要があるビジュアルデザインエージェントに最適","ko":"DESIGN.md 파일을 통해 의미적 디자인 시스템을 생성해야 하는 시각 디자인 에이전트에 적합","es":"Perfecto para Agentes de Diseño Visual que necesitan generar sistemas de diseño semánticos a través de archivos DESIGN.md","fr":"Parfait pour les agents de conception visuelle ayant besoin de générer des systèmes de conception sémantiques via des fichiers DESIGN.md","de":"Perfekt für Visuelle Design-Agenten, die semantische Designsysteme über DESIGN.md-Dateien generieren müssen","pt":"Perfeito para Agentes de Design Visual que precisam gerar sistemas de design semântico através de arquivos DESIGN.md","ru":"Идеально для Визуальных Дизайн Агентов, которым необходимо создавать семантические системы дизайна через файлы DESIGN.md","ar":"مثالي لوكلاء التصميم المرئي الذين يحتاجون إلى生成 أنظمة تصميم دلالية من خلال ملفات DESIGN.md"},"recommendation":{"en":"Empowers agents to synthesize comprehensive content analysis into semantic design systems, utilizing DESIGN.md files as the source of truth, supported by specific color values and visual descriptions","zh":"赋予代理合成综合内容分析为语义设计系统的能力，利用 DESIGN.md 文件作为真实来源，并支持特定的颜色值和视觉描述","ja":"エージェントに、DESIGN.md ファイルを真実の源として使用し、特定の色値や視覚的説明をサポートすることで、包括的なコンテンツ分析をセマンティックデザインシステムに合成する能力を提供する","ko":"에이전트가 DESIGN.md 파일을 진실의 근원으로 사용하여 포괄적인 콘텐츠 분석을 의미적 디자인 시스템으로 합성할 수 있는 능력을 부여하며, 특정 색상 값과 시각적 설명을 지원","es":"Habilita a los agentes a sintetizar un análisis de contenido integral en sistemas de diseño semánticos, utilizando archivos DESIGN.md como fuente de verdad, respaldados por valores de color específicos y descripciones visuales","fr":"Permet aux agents de synthétiser une analyse de contenu complète en systèmes de conception sémantiques, en utilisant des fichiers DESIGN.md comme source de vérité, étayés par des valeurs de couleur spécifiques et des descriptions visuelles","de":"Ermächtigt Agenten, eine umfassende Inhaltsanalyse in semantische Designsysteme zu synthetisieren, die DESIGN.md-Dateien als Wahrheitsquelle verwenden, unterstützt durch spezifische Farbwerte und visuelle Beschreibungen","pt":"Habilita os agentes a sintetizar uma análise abrangente de conteúdo em sistemas de design semântico, utilizando arquivos DESIGN.md como fonte de verdade, apoiados por valores de cor específicos e descrições visuais","ru":"Наделяет агентов возможностью синтезировать комплексный анализ контента в семантические системы дизайна, используя файлы DESIGN.md в качестве источника правды, поддерживаемые конкретными цветовыми значениями и визуальными описаниями","ar":"يمكّن الوكلاء من تحليل المحتوى الشامل وتحويله إلى أنظمة تصميم دلالية، باستخدام ملفات DESIGN.md كمصدر للحقيقة، مدعومة بقيم الألوان المحددة والوصف المرئي"},"useCases":{"en":["Analyzing Stitch projects to create unified design languages","Generating DESIGN.md files for consistent visual descriptions","Synthesizing semantic design systems for new screen generation"],"zh":["分析 Stitch 项目以创建统一的设计语言","生成 DESIGN.md 文件以获得一致的视觉描述","合成语义设计系统以用于新屏幕生成"],"ja":["Stitch プロジェクトを分析して統一されたデザイン言語を作成する","DESIGN.md ファイルを生成して一貫した視覚的説明を得る","新しい画面生成のためにセマンティックデザインシステムを合成する"],"ko":["統一된 디자인 언어를 생성하기 위해 Stitch 프로젝트를 분석","일관된 시각적 설명을 얻기 위해 DESIGN.md 파일을 생성","새로운 화면 생성을 위해 의미적 디자인 시스템을 합성"],"es":["Analizar proyectos Stitch para crear lenguajes de diseño unificados","Generar archivos DESIGN.md para descripciones visuales consistentes","Sintetizar sistemas de diseño semánticos para la generación de nuevas pantallas"],"fr":["Analyser les projets Stitch pour créer des langages de conception unifiés","Générer des fichiers DESIGN.md pour des descriptions visuelles cohérentes","Synthétiser des systèmes de conception sémantiques pour la génération d''écrans nouveaux"],"de":["Stitch-Projekte analysieren, um einheitliche Designsprachen zu erstellen","DESIGN.md-Dateien generieren, um konsistente visuelle Beschreibungen zu erstellen","Semantische Designsysteme synthetisieren, um neue Bildschirme zu generieren"],"pt":["Analisar projetos Stitch para criar linguagens de design unificadas","Gerar arquivos DESIGN.md para descrições visuais consistentes","Sintetizar sistemas de design semântico para geração de novas telas"],"ru":["Анализ проектов Stitch для создания унифицированных языков дизайна","Генерация файлов DESIGN.md для последовательных визуальных описаний","Синтез семантических систем дизайна для генерации новых экранов"],"ar":["تحليل مشاريع Stitch لإنشاء لغات تصميم موحدة","генерация ملفات DESIGN.md لوصف مرئي متسق","تحليل أنظمة تصميم دلالية لإنشاء شاشات جديدة"]},"limitations":{"en":["Requires access to Stitch projects and technical assets","Limited to DESIGN.md file format"],"zh":["需要访问 Stitch 项目和技术资产","仅限 DESIGN.md 文件格式"],"ja":["Stitch プロジェクトおよび技術アセットへのアクセスが必要","DESIGN.md ファイル形式のみに限定"],"ko":["Stitch 프로젝트와 기술 자산에 대한 액세스가 필요","DESIGN.md 파일 형식만으로 제한"],"es":["Requiere acceso a proyectos Stitch y activos técnicos","Limitado al formato de archivo DESIGN.md"],"fr":["Nécessite l''accès aux projets Stitch et aux ressources techniques","Limité au format de fichier DESIGN.md"],"de":["Erfordert Zugriff auf Stitch-Projekte und technische Assets","Begrenzt auf das DESIGN.md-Dateiformat"],"pt":["Requer acesso a projetos e ativos técnicos Stitch","Limitado ao formato de arquivo DESIGN.md"],"ru":["Требует доступа к проектам и техническим активам Stitch","Ограничен форматом файла DESIGN.md"],"ar":["يتطلب الوصول إلى مشاريع Stitch والassets الفنية","محدود بتنسيق ملف DESIGN.md"]},"version":4},"contentHash":"eb15f44646528f3a087ce023329ae699c1b6e803662af68338e1eb1c0406b59b","repoEtag":"W/\"bb47617e3029a9b4385327f9dc9702c508cf6c4fbacc7fed320cabd4b144bac3\"","qualityScore":95}');
