INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-labs-code/stitch-skills/design-md', 'design-md', 'google-labs-code', 'stitch-skills', 'official', 'design-md google-labs-code stitch-skills official The design-md skill analyzes Stitch projects and generates DESIGN.md files, serving as the source of truth for prompting Stitch to create new screens. It benefits Design Systems Leads and developers working with Stitch. 设计-md 技术能够分析 Stitch 项目并生成 DESIGN.md 文件，实现semantic design system。 design-md 技術は Stitch プロジェクトを分析し、DESIGN.md ファイルを生成してセマンティック デザイン システムを実現します。 디자인-md 기술은 Stitch 프로젝트를 분석하여 DESIGN.md 파일을 생성하고 시맨틱 디자인 시스템을 구현합니다. La habilidad design-md analiza proyectos Stitch y crea sistemas de diseño semánticos en archivos DESIGN.md. Ayuda a generar nuevas pantallas que se ajustan a la lengua de diseño existente. La compétence design-md analyse les projets Stitch et crée des systèmes de conception sémantiques dans des fichiers DESIGN.md. Elle aide à générer de nouveaux écrans qui s''alignent sur la langue de conception existante. Die Fähigkeit design-md analysiert Stitch-Projekte und erstellt semantische Designsysteme in DESIGN.md-Dateien. Sie hilft bei der Generierung neuer Bildschirme, die sich an die bestehende Designsprache anpassen. O design-md é uma habilidade que analisa projetos Stitch e sintetiza um sistema de design semântico em arquivos DESIGN.md ИИ Агент design-md анализирует проекты Stitch и синтезирует семантическую систему дизайна в файлах DESIGN.md الوكيل الذكي design-md يقوم بتحليل مشاريع Stitch ودمج نظام ديزاين семантиكي في ملفات DESIGN.md how to use design-md what is design-md design-md setup guide design-md alternative design-md vs Stitch design-md install semantic design system Stitch design language DESIGN.md file generation 设计-md AIエージェント Stitch 项目 DESIGN.md 文件 semantic design system Visual Descriptions 特定颜色值 设计语言 Analyzes Stitch projects to synthesize a semantic design system Generates DESIGN.md files as the source of truth for Stitch Interprets design through visual descriptions supported by specific color values Creates files that prompt Stitch to generate new screens aligned with existing design language design-md is a skill that synthesizes a semantic design system into DESIGN.md files, interpreting design through visual descriptions supported by specific color values.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/web-perf', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'web-perf', 535, 66, 95, '2026-03-06T05:33:24Z', '2026-03-06T05:57:48.050Z', '746b3490d401c8020900f0a62ece846c22d3df15782ee843c082acfa89f26703', '{"id":"cloudflare/skills/web-perf","name":"web-perf","description":{"en":"The web-perf skill analyzes web performance using Chrome DevTools MCP, measuring Core Web Vitals and identifying optimization opportunities for developers. It helps optimize page load performance, Lighthouse scores, and site speed.","zh":"web-perf技能使用Chrome DevTools MCP分析网页性能，测量Core Web Vitals，优化页面加载速度","ja":"web-perfスキルはChrome DevTools MCPを使用してWebパフォーマンスを分析し、Core Web Vitalsを測定してページロード速度を最適化します","ko":"web-perf 스킬은 Chrome DevTools MCP를 사용하여 웹 성능을 분석하고 Core Web Vitals를 측정하여 페이지 로드 속도를 최적화합니다","es":"web-perf analiza el rendimiento web utilizando Chrome DevTools MCP y mide Core Web Vitals como FCP, LCP, TBT, CLS y Speed Index","fr":"web-perf analyse les performances web à l''aide de Chrome DevTools MCP et mesure les Core Web Vitals tels que FCP, LCP, TBT, CLS et Speed Index","de":"web-perf analysiert die Webleistung mit Chrome DevTools MCP und misst Core Web Vitals wie FCP, LCP, TBT, CLS und Speed Index","pt":"O web-perf analisa o desempenho web usando Chrome DevTools MCP, medindo Core Web Vitals e identificando problemas de renderização e caching","ru":"ИИ Агент web-perf анализирует производительность веб-сайта с помощью Chrome DevTools MCP, измеряя основные веб-витали и выявляя проблемы рендеринга и кэширования","ar":"أداة web-perf تحلل أداء الويب باستخدام Chrome DevTools MCP، وتقيس معايير الويب الأساسية وتحدد مشاكل العرض والتخزين المؤقت"},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"web-perf","description":"Analyzes web performance using Chrome DevTools MCP. Measures Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index), identifies render-blocking resources, network dependency chains, layout shifts, caching issues, and accessibility gaps. Use when asked to audit, profile, debug, or optimize page load performance, Lighthouse scores, or site speed. Biases towards retrieval from current documentation over pre-trained knowledge.","bodyPreview":"# Web Performance Audit\n\nYour knowledge of web performance metrics, thresholds, and tooling APIs may be outdated. **Prefer retrieval over pre-training** when citing specific numbers or recommendations.\n\n## Retrieval Sources\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| web.dev | `https://web.dev/articles/vitals` | Core Web Vitals thresholds, definitions |\n| Chrome DevTools docs | `https://developer.chrome.com/docs/devtools/performance` | Tooling APIs, trace anal","body":"# Web Performance Audit\n\nYour knowledge of web performance metrics, thresholds, and tooling APIs may be outdated. **Prefer retrieval over pre-training** when citing specific numbers or recommendations.\n\n## Retrieval Sources\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| web.dev | `https://web.dev/articles/vitals` | Core Web Vitals thresholds, definitions |\n| Chrome DevTools docs | `https://developer.chrome.com/docs/devtools/performance` | Tooling APIs, trace analysis |\n| Lighthouse scoring | `https://developer.chrome.com/docs/lighthouse/performance/performance-scoring` | Score weights, metric thresholds |\n\n## FIRST: Verify MCP Tools Available\n\n**Run this before starting.** Try calling `navigate_page` or `performance_start_trace`. If unavailable, STOP—the chrome-devtools MCP server isn''t configured.\n\nAsk the user to add this to their MCP config:\n\n```json\n\"chrome-devtools\": {\n  \"type\": \"local\",\n  \"command\": [\"npx\", \"-y\", \"chrome-devtools-mcp@latest\"]\n}\n```\n\n## Key Guidelines\n\n- **Be assertive**: Verify claims by checking network requests, DOM, or codebase—then state findings definitively.\n- **Verify before recommending**: Confirm something is unused before suggesting removal.\n- **Quantify impact**: Use estimated savings from insights. Don''t prioritize changes with 0ms impact.\n- **Skip non-issues**: If render-blocking resources have 0ms estimated impact, note but don''t recommend action.\n- **Be specific**: Say \"compress hero.png (450KB) to WebP\" not \"optimize images\".\n- **Prioritize ruthlessly**: A site with 200ms LCP and 0 CLS is already excellent—say so.\n\n## Quick Reference\n\n| Task | Tool Call |\n|------|-----------|\n| Load page | `navigate_page(url: \"...\")` |\n| Start trace | `performance_start_trace(autoStop: true, reload: true)` |\n| Analyze insight | `performance_analyze_insight(insightSetId: \"...\", insightName: \"...\")` |\n| List requests | `list_network_requests(resourceTypes: [\"Script\", \"Stylesheet\", ...])` |\n| Request details | `get_network_request(reqid: <id>)` |\n| A11y snapshot | `take_snapshot(verbose: true)` |\n\n## Workflow\n\nCopy this checklist to track progress:\n\n```\nAudit Progress:\n- [ ] Phase 1: Performance trace (navigate + record)\n- [ ] Phase 2: Core Web Vitals analysis (includes CLS culprits)\n- [ ] Phase 3: Network analysis\n- [ ] Phase 4: Accessibility snapshot\n- [ ] Phase 5: Codebase analysis (skip if third-party site)\n```\n\n### Phase 1: Performance Trace\n\n1. Navigate to the target URL:\n   ```\n   navigate_page(url: \"<target-url>\")\n   ```\n\n2. Start a performance trace with reload to capture cold-load metrics:\n   ```\n   performance_start_trace(autoStop: true, reload: true)\n   ```\n\n3. Wait for trace completion, then retrieve results.\n\n**Troubleshooting:**\n- If trace returns empty or fails, verify the page loaded correctly with `navigate_page` first\n- If insight names don''t match, inspect the trace response to list available insights\n\n### Phase 2: Core Web Vitals Analysis\n\nUse `performance_analyze_insight` to extract key metrics.\n\n**Note:** Insight names may vary across Chrome DevTools versions. If an insight name doesn''t work, check the `insightSetId` from the trace response to discover available insights.\n\nCommon insight names:\n\n| Metric | Insight Name | What to Look For |\n|--------|--------------|------------------|\n| LCP | `LCPBreakdown` | Time to largest contentful paint; breakdown of TTFB, resource load, render delay |\n| CLS | `CLSCulprits` | Elements causing layout shifts (images without dimensions, injected content, font swaps) |\n| Render Blocking | `RenderBlocking` | CSS/JS blocking first paint |\n| Document Latency | `DocumentLatency` | Server response time issues |\n| Network Dependencies | `NetworkRequestsDepGraph` | Request chains delaying critical resources |\n\nExample:\n```\nperformance_analyze_insight(insightSetId: \"<id-from-trace>\", insightName: \"LCPBreakdown\")\n```\n\n**Key thresholds (good/needs-improvement/poor):**\n- TTFB: < 800ms / < 1.8s / > 1.8s\n- FCP: < 1.8s / < 3s / > 3s\n- LCP: < 2.5s / < 4s / > 4s\n- INP: < 200ms / < 500ms / > 500ms\n- TBT: < 200ms / < 600ms / > 600ms\n- CLS: < 0.1 / < 0.25 / > 0.25\n- Speed Index: < 3.4s / < 5.8s / > 5.8s\n\n### Phase 3: Network Analysis\n\nList all network requests to identify optimization opportunities:\n```\nlist_network_requests(resourceTypes: [\"Script\", \"Stylesheet\", \"Document\", \"Font\", \"Image\"])\n```\n\n**Look for:**\n\n1. **Render-blocking resources**: JS/CSS in `<head>` without `async`/`defer`/`media` attributes\n2. **Network chains**: Resources discovered late because they depend on other resources loading first (e.g., CSS imports, JS-loaded fonts)\n3. **Missing preloads**: Critical resources (fonts, hero images, key scripts) not preloaded\n4. **Caching issues**: Missing or weak `Cache-Control`, `ETag`, or `Last-Modified` headers\n5. **Large payloads**: Uncompressed or oversized JS/CSS bundles\n6. **Unused preconnects**: If flagged, verify by checking if ANY requests went to that origin. If zero requests, it''s definitively unused—recommend removal. If requests exist but loaded late, the preconnect may still be valuable.\n\nFor detailed request info:\n```\nget_network_request(reqid: <id>)\n```\n\n### Phase 4: Accessibility Snapshot\n\nTake an accessibility tree snapshot:\n```\ntake_snapshot(verbose: true)\n```\n\n**Flag high-level gaps:**\n- Missing or duplicate ARIA IDs\n- Elements with poor contrast ratios (check against WCAG AA: 4.5:1 for normal text, 3:1 for large text)\n- Focus traps or missing focus indicators\n- Interactive elements without accessible names\n\n## Phase 5: Codebase Analysis\n\n**Skip if auditing a third-party site without codebase access.**\n\nAnalyze the codebase to understand where improvements can be made.\n\n### Detect Framework & Bundler\n\nSearch for configuration files to identify the stack:\n\n| Tool | Config Files |\n|------|--------------|\n| Webpack | `webpack.config.js`, `webpack.*.js` |\n| Vite | `vite.config.js`, `vite.config.ts` |\n| Rollup | `rollup.config.js`, `rollup.config.mjs` |\n| esbuild | `esbuild.config.js`, build scripts with `esbuild` |\n| Parcel | `.parcelrc`, `package.json` (parcel field) |\n| Next.js | `next.config.js`, `next.config.mjs` |\n| Nuxt | `nuxt.config.js`, `nuxt.config.ts` |\n| SvelteKit | `svelte.config.js` |\n| Astro | `astro.config.mjs` |\n\nAlso check `package.json` for framework dependencies and build scripts.\n\n### Tree-Shaking & Dead Code\n\n- **Webpack**: Check for `mode: ''production''`, `sideEffects` in package.json, `usedExports` optimization\n- **Vite/Rollup**: Tree-shaking enabled by default; check for `treeshake` options\n- **Look for**: Barrel files (`index.js` re-exports), large utility libraries imported wholesale (lodash, moment)\n\n### Unused JS/CSS\n\n- Check for CSS-in-JS vs. static CSS extraction\n- Look for PurgeCSS/UnCSS configuration (Tailwind''s `content` config)\n- Identify dynamic imports vs. eager loading\n\n### Polyfills\n\n- Check for `@babel/preset-env` targets and `useBuiltIns` setting\n- Look for `core-js` imports (often oversized)\n- Check `browserslist` config for overly broad targeting\n\n### Compression & Minification\n\n- Check for `terser`, `esbuild`, or `swc` minification\n- Look for gzip/brotli compression in build output or server config\n- Check for source maps in production builds (should be external or disabled)\n\n## Output Format\n\nPresent findings as:\n\n1. **Core Web Vitals Summary** - Table with metric, value, and rating (good/needs-improvement/poor)\n2. **Top Issues** - Prioritized list of problems with estimated impact (high/medium/low)\n3. **Recommendations** - Specific, actionable fixes with code snippets or config changes\n4. **Codebase Findings** - Framework/bundler detected, optimization opportunities (omit if no codebase access)\n"},"category":"official","lastSynced":"2026-03-06T05:57:48.050Z","seo":{"title":{"en":"web-perf: Web Performance Optimization Guide | AI Agent S...","zh":"web-perf_SETUP指南：优化网页性能和Core Web Vitals","ja":"web-perfセットアップガイド：WebパフォーマンスとCore Web Vitalsの最適化","ko":"web-perf 설정 가이드: 웹 성능과 Core Web Vitals 최적화","es":"Guía de configuración de web-perf para optimizar el rendi...","fr":"Guide de configuration de web-perf pour optimiser les per...","de":"Einrichtungsleitfaden für web-perf zur Optimierung der We...","pt":"Guia de Configuração do web-perf: Otimização de Desempenh...","ru":"ИИ Агент web-perf: Руководство по Настройке и Оптимизации","ar":"دليل إعداد أداة الويب المثالية web-perf: تحسين أداء الويب"},"description":{"en":"Unlock faster page loads with web-perf! Discover how to audit, profile, and debug your website''s performance using Chrome DevTools MCP and optimize Core Web ...","zh":"使用web-perf技能分析网页性能，识别渲染阻塞资源，网络依赖链和布局偏移，优化页面加载速度和Lighthouse评分","ja":"web-perfスキルを使用してWebパフォーマンスを分析し、レンダリングブロッキングリソース、ネットワーク依存チェーン、レイアウトシフトを特定し、ページロード速度とLighthouseスコアを最適化します","ko":"web-perf 스킬을 사용하여 웹 성능을 분석하고 렌더링 블록 리소스, 네트워크 종속 체인 및 레이아웃 시프트를 식별하여 페이지 로드 속도와 라이트하우스 점수를 최적화합니다","es":"Aprende a utilizar web-perf para analizar y optimizar el rendimiento web con Chrome DevTools MCP y Core Web Vitals","fr":"Découvrez comment utiliser web-perf pour analyser et optimiser les performances web avec Chrome DevTools MCP et Core Web Vitals","de":"Erfahren Sie, wie Sie web-perf verwenden, um die Webleistung mit Chrome DevTools MCP und Core Web Vitals zu analysieren und zu optimieren","pt":"Aprenda a configurar e otimizar o desempenho web com o web-perf, analisando Core Web Vitals e identificando problemas de renderização e caching","ru":"Узнайте, как настроить и оптимизировать производительность веб-сайта с помощью ИИ Агента web-perf, анализируя основные веб-витали и выявляя проблемы рендерин...","ar":"تعلم كيفية ضبط أداء الويب مع أداة web-perf، وتحليل معايير الويب الأساسية وتحديد مشاكل العرض والتخزين المؤقت"},"definition":{"en":"web-perf is a skill that analyzes web performance using Chrome DevTools MCP, providing insights into Core Web Vitals, render-blocking resources, and caching issues to optimize page load performance","zh":"web-perf是AIエージェント的一种技能，用于分析和优化网页性能","ja":"web-perfはAIエージェントのスキルの一種で、Webパフォーマンスを分析して最適化するために使用されます","ko":"web-perf는 AI 에이전트의 스킬 중 하나로, 웹 성능을 분석하고 최적화하는 데 사용됩니다","es":"web-perf es una habilidad que analiza y optimiza el rendimiento web utilizando tecnologías como Chrome DevTools MCP","fr":"web-perf est une compétence qui analyse et optimise les performances web en utilisant des technologies telles que Chrome DevTools MCP","de":"web-perf ist eine Fähigkeit, die die Webleistung mit Technologien wie Chrome DevTools MCP analysiert und optimiert","pt":"O web-perf é uma ferramenta de análise de desempenho web que usa Chrome DevTools MCP para medir Core Web Vitals","ru":"ИИ Агент web-perf - это инструмент анализа производительности веб-сайта, использующий Chrome DevTools MCP для измерения основных веб-витали","ar":"أداة web-perf هي أداة تحليل أداء الويب التي تستخدم Chrome DevTools MCP لقياس معايير الويب الأساسية"},"features":{"en":["Measures Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) using Chrome DevTools MCP","Identifies render-blocking resources, network dependency chains, and layout shifts","Detects caching issues and accessibility gaps","Provides optimization recommendations based on web.dev and Chrome DevTools documentation","Supports retrieval of current documentation for accurate metrics and thresholds"],"zh":["使用Chrome DevTools MCP分析网页性能","测量Core Web Vitals（FCP、LCP、TBT、CLS、Speed Index）","识别渲染阻塞资源、网络依赖链和布局偏移","优化页面加载速度和Lighthouse评分","支持web.dev和Chrome DevTools文档的检索"],"ja":["Chrome DevTools MCPを使用してWebパフォーマンスを分析","Core Web Vitals（FCP、LCP、TBT、CLS、Speed Index）を測定","レンダリングブロッキングリソース、ネットワーク依存チェーン、レイアウトシフトを特定","ページロード速度とLighthouseスコアを最適化","web.devとChrome DevToolsドキュメントのリトリーブをサポート"],"ko":["Chrome DevTools MCP를 사용하여 웹 성능을 분석","Core Web Vitals（FCP、LCP、TBT、CLS、Speed Index）를 측정","렌더링 블록 리소스, 네트워크 종속 체인 및 레이아웃 시프트를 식별","페이지 로드 속도와 라이트하우스 점수를 최적화","web.dev와 Chrome DevTools 문서의 리트리브를 지원"],"es":["Análisis de rendimiento web con Chrome DevTools MCP","Medición de Core Web Vitals como FCP, LCP, TBT, CLS y Speed Index","Identificación de recursos que bloquean el renderizado","Detección de cadenas de dependencias de red y cambios de diseño","Análisis de problemas de caché y accesibilidad"],"fr":["Analyse des performances web avec Chrome DevTools MCP","Mesure des Core Web Vitals tels que FCP, LCP, TBT, CLS et Speed Index","Identification des ressources qui bloquent le rendu","Détection des chaînes de dépendances de réseau et des changements de conception","Analyse des problèmes de cache et d''accessibilité"],"de":["Analyse der Webleistung mit Chrome DevTools MCP","Messung von Core Web Vitals wie FCP, LCP, TBT, CLS und Speed Index","Identifizierung von Ressourcen, die das Rendering blockieren","Erkennung von Netzwerkabhängigkeitsketten und Layout-Änderungen","Analyse von Cach- und Zugriffsproblemen"],"pt":["Análise de Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index)","Identificação de recursos de bloqueio de renderização","Análise de cadeias de dependência de rede","Detecção de problemas de caching","Análise de acessibilidade"],"ru":["Анализ основных веб-витали (FCP, LCP, TBT, CLS, Speed Index)","Выявление ресурсов, блокирующих рендеринг","Анализ цепочек зависимости сети","Обнаружение проблем кэширования","Анализ доступности"],"ar":["تحليل معايير الويب الأساسية (FCP, LCP, TBT, CLS, Speed Index)","تحديد موارد العرض المحظور","تحليل سلاسل الاعتماد الشبكية","كشف مشاكل التخزين المؤقت","تحليل إمكانية الوصول"]},"keywords":{"en":["how to use web-perf","web performance optimization","Core Web Vitals","Chrome DevTools MCP","web-perf setup guide","web-perf vs Lighthouse","web performance audit","optimize page load speed","web-perf install","web development tools"],"zh":["web-perf","网页性能优化","Core Web Vitals","Chrome DevTools","Lighthouse评分","页面加载速度","AIエージェント","web开发"],"ja":["web-perf","Webパフォーマンス最適化","Core Web Vitals","Chrome DevTools","Lighthouseスコア","ページロード速度","AIエージェント","Web開発"],"ko":["web-perf","웹 성능 최적화","Core Web Vitals","Chrome DevTools","라이트하우스 점수","페이지 로드 속도","AI 에이전트","웹 개발"],"es":["web-perf","rendimiento web","Core Web Vitals","Chrome DevTools MCP","optimización de rendimiento","análisis de rendimiento web","herramientas de desarrollo web","agentes de IA para desarrolladores","herramientas de optimización de sitio web"],"fr":["web-perf","performances web","Core Web Vitals","Chrome DevTools MCP","optimisation des performances","analyse des performances web","outils de développement web","agents d''IA pour les développeurs","outils d''optimisation de site web"],"de":["web-perf","Webleistung","Core Web Vitals","Chrome DevTools MCP","Leistungsoptimierung","Webleistungsanalyse","Webentwicklungstools","KI-Agents für Entwickler","Webseiten-Optimierungstools"],"pt":["web-perf","análise de desempenho web","Core Web Vitals","Chrome DevTools MCP","otimização de desempenho web","renderização de páginas","caching","acessibilidade"],"ru":["ИИ Агент web-perf","анализ производительности веб-сайта","основные веб-витали","Chrome DevTools MCP","оптимизация производительности веб-сайта","рендеринг страниц","кэширование","доступность"],"ar":["أداة web-perf","تحليل أداء الويب","معايير الويب الأساسية","Chrome DevTools MCP","تحسين أداء الويب","عرض الصفحات","التخزين المؤقت","إمكانية الوصول"]}},"agentAnalysis":{"suitability":{"en":"Essential for Web Performance Analysis Agents conducting comprehensive Core Web Vitals audits using Chrome DevTools Protocol.","zh":"适用于进行全面Core Web Vitals审计的Web性能分析代理，使用Chrome DevTools Protocol。","ja":"Chrome DevTools Protocolを使用して包括的なCore Web Vitals監査を実施するWebパフォーマンス分析エージェントに不可欠です。","ko":"Chrome DevTools Protocol을 사용하여 종합적인 Core Web Vitals 감사를 수행하는 웹 성능 분석 에이전트에 필수적입니다.","es":"Esencial para los Agentes de Análisis de Rendimiento Web que realizan auditorías integrales de Core Web Vitals utilizando el Protocolo de Chrome DevTools.","fr":"Essentiel pour les Agents d''Analyse de Performance Web effectuant des audits complets de Core Web Vitals à l''aide du Protocole Chrome DevTools.","de":"Wesentlich für Web-Performance-Analyse-Agents, die umfassende Core-Web-Vitals-Audits mit dem Chrome-DevTools-Protokoll durchführen.","pt":"Essencial para Agentes de Análise de Desempenho da Web que realizam auditorias abrangentes de Core Web Vitals usando o Protocolo Chrome DevTools.","ru":"Необходим для Агентов анализа веб-производительности, проводящих комплексные аудиты Core Web Vitals с помощью протокола Chrome DevTools.","ar":"ضروري للموكلين تحليل أداء الويب الذين يقومون بعمليات تدقيق شاملة لأساسيات الويب الأساسية باستخدام بروتوكول أدوات تطوير كروم."},"recommendation":{"en":"Enables direct measurement of Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) through Chrome DevTools MCP integration. Identifies critical performance bottlenecks including render-blocking resources, network dependency chains, layout shifts, and caching issues with bias toward current documentation retrieval over pre-trained knowledge.","zh":"通过Chrome DevTools MCP集成，能够直接测量Core Web Vitals（FCP、LCP、TBT、CLS、Speed Index）。它能够识别出关键的性能瓶颈，包括阻塞渲染的资源、网络依赖链、布局偏移以及缓存问题，偏向当前文档检索而非预训练知识。","ja":"Chrome DevTools MCP統合を通じて、Core Web Vitals（FCP、LCP、TBT、CLS、Speed Index）を直接測定できます。レンダリングをブロックするリソース、ネットワーク依存チェーン、レイアウトシフト、キャッシング問題など、パフォーマンスのボトルネックを特定し、現在のドキュメントの取得を重視して、事前トレーニング済みの知識よりも優先します。","ko":"Chrome DevTools MCP 통합을 통해 Core Web Vitals(FCP, LCP, TBT, CLS, Speed Index)을 직접 측정할 수 있습니다. 렌더링을 차단하는 리소스, 네트워크 종속 체인, 레이아웃 시프트 및 캐싱 문제와 같은 중요한 성능 병목 현상을 식별하며, 사전 교육된 지식보다 현재 문서 검색을 우선합니다.","es":"Permite la medición directa de Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) a través de la integración de Chrome DevTools MCP. Identifica cuellos de botella críticos de rendimiento, incluidos recursos que bloquean el renderizado, cadenas de dependencia de red, cambios de diseño y problemas de caché con sesgo hacia la recuperación de documentación actual en lugar de conocimientos preentrenados.","fr":"Permet la mesure directe de Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) via l''intégration de Chrome DevTools MCP. Identifie les goulets d''étranglement critiques de performances, y compris les ressources bloquant le rendu, les chaînes de dépendance réseau, les changements de disposition et les problèmes de mise en cache avec un biais vers la récupération de documentation actuelle plutôt que des connaissances pré-entraînées.","de":"Ermöglicht die direkte Messung von Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) durch die Integration von Chrome DevTools MCP. Identifiziert kritische Leistungsengpässe, einschließlich render-blockierender Ressourcen, Netzwerk-Abhängigkeitsketten, Layout-Shifts und Caching-Probleme mit Voreingenommenheit gegenüber der aktuellen Dokumentenrückgewinnung anstelle von vorgefertigtem Wissen.","pt":"Permite a medição direta das Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) por meio da integração do MCP do Chrome DevTools. Identifica gargalos críticos de desempenho, incluindo recursos que bloqueiam a renderização, cadeias de dependência de rede, mudanças de layout e problemas de cache com viés para a recuperação de documentação atual em vez de conhecimento pré-treinado.","ru":"Позволяет直接 измерять Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) через интеграцию MCP Chrome DevTools. Выявляет критические узкие места производительности, включая ресурсы, блокирующие рендеринг, цепочки сетевой зависимости, сдвиги макета и проблемы с кэшем с偏ением в сторону получения текущей документации над предварительно обученной знаниями.","ar":"يمكّن القياس المباشر لأساسيات الويب الأساسية (FCP، LCP، TBT، CLS، فهرس السرعة) من خلال تكامل MCP من أدوات تطوير كروم. يحدد العوائق الحرجة لأداء الويب، بما في ذلك الموارد التي تعيق العرض، وسلاسل الاعتماد الشبكي، وتغييرات تخطيط الشاشة، ومشاكل الذاكرة المؤقتة مع تحيز لاسترجاع الوثائق الحالية على معرفة مُسبق التدريب."},"useCases":{"en":["Auditing page load performance against Web Vitals thresholds","Debugging render-blocking resource chains","Optimizing Lighthouse scores through trace analysis","Profiling network dependency waterfalls","Identifying accessibility gaps in performance metrics"],"zh":["对页面加载性能进行Web Vital门槛值审计","调试阻塞渲染的资源链","通过追踪分析优化Lighthouse评分","分析网络依赖的瀑布流","识别性能指标中的无障碍差距"],"ja":["Web Vitalのしきい値に対するページロードパフォーマンスの監査","レンダリングをブロックするリソースチェーンのデバッグ","トレース分析によるLighthouseスコアの最適化","ネットワーク依存のウォーターフォールのプロファイリング","パフォーマンスメトリクスのアクセシビリティギャップの特定"],"ko":["Web Vital 임계값에 대한 페이지 로드 성능 감사","렌더링을 차단하는 리소스 체인의 디버깅","추적 분석을 통한 Lighthouse 점수 최적화","네트워크 종속성 워터폴의 프로파일링","성능 메트릭의 접근성 격차 식별"],"es":["Auditoría del rendimiento de carga de página frente a los umbrales de Web Vitals","Depuración de cadenas de recursos que bloquean el renderizado","Optimización de puntuaciones de Lighthouse a través del análisis de trazas","Perfiling de cascadas de dependencia de red","Identificación de brechas de accesibilidad en métricas de rendimiento"],"fr":["Audit du rendement de chargement de page par rapport aux seuils de Web Vitals","Débogage des chaînes de ressources bloquant le rendu","Optimisation des scores de Lighthouse via l''analyse de traces","Profiling des cascades de dépendance réseau","Identification des lacunes d''accessibilité dans les métriques de performances"],"de":["Prüfung der Laderendleistung einer Seite gegenüber Web-Vitals-Schwellenwerten","Fehlerbehebung von Render-Blockierungsressourcenketten","Optimierung von Lighthouse-Scores durch Trace-Analyse","Profiling von Netzwerk-Abhängigkeitskaskaden","Identifizierung von Zugänglichkeitslücken in Leistungsmetriken"],"pt":["Auditoria de desempenho de carregamento de página contra limites de Web Vitals","Depuração de cadeias de recursos que bloqueiam a renderização","Otimização de pontuações do Lighthouse por meio da análise de rastros","Perfil de cascata de dependência de rede","Identificação de lacunas de acessibilidade em métricas de desempenho"],"ru":["Аудит производительности загрузки страницы против порогов Web Vitals","Отладка цепочек ресурсов, блокирующих рендеринг","Оптимизация оценок Lighthouse за счет анализа трассировок","Профилирование водопада сетевой зависимости","Определение пробелов в доступности в метриках производительности"],"ar":["تدقيق أداء تحميل الصفحة ضد حدود أساسيات الويب","تصحيح أخطاء سلاسل الموارد التي تعيق العرض","تحسين درجات منارة الويب من خلال تحليل التتبعات","تحليل مياه الشلال لاعتماد الشبكة","تحديد الفجوات في إمكانية الوصول في مقاييس الأداء"]},"limitations":{"en":["Requires Chrome DevTools Protocol access","Depends on current web.dev documentation retrieval","Limited to web performance-specific metrics and tooling"],"zh":["需要Chrome DevTools Protocol访问","依赖于当前web.dev文档检索","仅限于web性能特定指标和工具"],"ja":["Chrome DevTools Protocolへのアクセスが必要","現在のweb.devドキュメントの取得に依存","Webパフォーマンス特有のメトリクスおよびツールリングに限定"],"ko":["Chrome DevTools Protocol 액세스가 필요합니다.","현재 web.dev 문서 검색에 의존","웹 성능 특정 메트릭 및 툴링에限定"],"es":["Requiere acceso al Protocolo de Chrome DevTools","Depende de la recuperación de documentación actual de web.dev","Limitado a métricas y herramientas específicas de rendimiento web"],"fr":["Nécessite l''accès au Protocole Chrome DevTools","Dépend de la récupération de documentation actuelle de web.dev","Limité à des métriques et à des outils spécifiques de performances Web"],"de":["Erfordert Zugriff auf das Chrome-DevTools-Protokoll","Hängt von der Rückgewinnung aktueller Dokumentation von web.dev ab","Begrenzt auf web-spezifische Leistungsmetriken und -tools"],"pt":["Exige acesso ao Protocolo Chrome DevTools","Depende da recuperação de documentação atual da web.dev","Limitado a métricas e ferramentas específicas de desempenho da web"],"ru":["Требует доступа к протоколу Chrome DevTools","Зависит от получения текущей документации с web.dev","Ограничен метриками и инструментами, специфичными для веб-производительности"],"ar":["يتطلب الوصول إلى بروتوكول أدوات تطوير كروم","يعتمد على استرجاع الوثائق الحالية من web.dev","محدود بمقاييس وأدوات أداء الويب المحددة"]},"version":4},"contentHash":"746b3490d401c8020900f0a62ece846c22d3df15782ee843c082acfa89f26703","repoEtag":"W/\"295e4fcdb92b56b41ac51b00a34c693d22b101994424f954c0d419002c1abf71\"","qualityScore":95}');
