INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/web-perf', 'web-perf', 'cloudflare', 'skills', 'official', 'web-perf cloudflare skills official agents cloudflare skills workers The web-perf skill analyzes web performance using Chrome DevTools MCP, measuring Core Web Vitals and identifying optimization opportunities for developers. It helps optimize page load performance, Lighthouse scores, and site speed. web-perf技能使用Chrome DevTools MCP分析网页性能，测量Core Web Vitals，优化页面加载速度 web-perfスキルはChrome DevTools MCPを使用してWebパフォーマンスを分析し、Core Web Vitalsを測定してページロード速度を最適化します web-perf 스킬은 Chrome DevTools MCP를 사용하여 웹 성능을 분석하고 Core Web Vitals를 측정하여 페이지 로드 속도를 최적화합니다 web-perf analiza el rendimiento web utilizando Chrome DevTools MCP y mide Core Web Vitals como FCP, LCP, TBT, CLS y Speed Index web-perf analyse les performances web à l''aide de Chrome DevTools MCP et mesure les Core Web Vitals tels que FCP, LCP, TBT, CLS et Speed Index web-perf analysiert die Webleistung mit Chrome DevTools MCP und misst Core Web Vitals wie FCP, LCP, TBT, CLS und Speed Index O web-perf analisa o desempenho web usando Chrome DevTools MCP, medindo Core Web Vitals e identificando problemas de renderização e caching ИИ Агент web-perf анализирует производительность веб-сайта с помощью Chrome DevTools MCP, измеряя основные веб-витали и выявляя проблемы рендеринга и кэширования أداة web-perf تحلل أداء الويب باستخدام Chrome DevTools MCP، وتقيس معايير الويب الأساسية وتحدد مشاكل العرض والتخزين المؤقت how to use web-perf web performance optimization Core Web Vitals Chrome DevTools MCP web-perf setup guide web-perf vs Lighthouse web performance audit optimize page load speed web-perf install web development tools web-perf 网页性能优化 Core Web Vitals Chrome DevTools Lighthouse评分 页面加载速度 AIエージェント web开发 Measures Core Web Vitals (FCP, LCP, TBT, CLS, Speed Index) using Chrome DevTools MCP Identifies render-blocking resources, network dependency chains, and layout shifts Detects caching issues and accessibility gaps Provides optimization recommendations based on web.dev and Chrome DevTools documentation Supports retrieval of current documentation for accurate metrics and thresholds web-perf is a skill that analyzes web performance using Chrome DevTools MCP, providing insights into Core Web Vitals, render-blocking resources, and caching issues to optimize page load performance');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langgenius/dify/backend-code-review', 'official', 'langgenius', 'dify', 'langgenius/dify', 'backend-code-review', 131375, 20455, 95, '2026-03-06T06:00:48Z', '2026-03-06T06:03:45.351Z', 'a032c9a81b936f6127b0ad40b97073a18119352f86c87ed371e6e81825d4b552', '{"id":"langgenius/dify/backend-code-review","name":"backend-code-review","description":{"en":"The backend-code-review skill analyzes Python code for quality, security, and maintainability, benefiting developers working with API backend files.","zh":"后端代码审查工具检查Python代码的质量、安全性和可维护性，支持pending-change审查、代码片段审查和文件专注审查","ja":"バックエンドコードレビューツールは、Python コードの品質、セキュリティ、メンテナンス性をチェックし、pending-change レビュー、コード スニペット レビュー、ファイル フォーカス レビューをサポートする","ko":"백엔드 코드 리뷰 도구는 Python 코드의 품질, 보안 및 유지 보수성을 확인하며 pending-change 리뷰, 코드 스니펫 리뷰 및 파일 중심 리뷰를 지원","es":"La revisión de código backend es una herramienta que analiza y mejora la calidad, seguridad y mantenibilidad de tu código Python","fr":"La revue de code backend est un outil qui analyse et améliore la qualité, la sécurité et la maintenabilité de votre code Python","de":"Die Überprüfung von Backend-Code ist ein Tool, das die Qualität, Sicherheit und Wartbarkeit Ihres Python-Codes analysiert und verbessert","pt":"O agente de revisão de código backend analisa arquivos .py no diretório api/ para garantir qualidade, segurança e boas práticas","ru":"Агент проверки бэкенда анализирует файлы .py в директории api/ для обеспечения качества, безопасности и лучших практик","ar":"يوفر وكيل مراجعة رمز الخادم الخلفي تحليلًا لملفات .py في الدليل api/ لضمان الجودة والأمان وأفضل الممارسات"},"owner":"langgenius","repo":"dify","repoPath":"langgenius/dify","stars":131375,"forks":20455,"updatedAt":"2026-03-06T06:00:48Z","topics":["agent","agentic-ai","agentic-framework","agentic-workflow","ai","automation","gemini","genai","gpt","gpt-4","llm","low-code","mcp","nextjs","no-code","openai","orchestration","python","rag","workflow"],"skillMd":{"name":"backend-code-review","description":"Review backend code for quality, security, maintainability, and best practices based on established checklist rules. Use when the user requests a review, analysis, or improvement of backend files (e.g., `.py`) under the `api/` directory. Do NOT use for frontend files (e.g., `.tsx`, `.ts`, `.js`). Supports pending-change review, code snippets review, and file-focused review.","bodyPreview":"# Backend Code Review\n\n## When to use this skill\n\nUse this skill whenever the user asks to **review, analyze, or improve** backend code (e.g., `.py`) under the `api/` directory. Supports the following review modes:\n\n- **Pending-change review**: when the user asks to review current changes (inspect staged/working-tree files slated for commit to get the changes).\n- **Code snippets review**: when the user pastes code snippets (e.g., a function/class/module excerpt) into the chat and asks for a revi","body":"# Backend Code Review\n\n## When to use this skill\n\nUse this skill whenever the user asks to **review, analyze, or improve** backend code (e.g., `.py`) under the `api/` directory. Supports the following review modes:\n\n- **Pending-change review**: when the user asks to review current changes (inspect staged/working-tree files slated for commit to get the changes).\n- **Code snippets review**: when the user pastes code snippets (e.g., a function/class/module excerpt) into the chat and asks for a review.\n- **File-focused review**: when the user points to specific files and asks for a review of those files (one file or a small, explicit set of files, e.g., `api/...`, `api/app.py`).\n\nDo NOT use this skill when:\n\n- The request is about frontend code or UI (e.g., `.tsx`, `.ts`, `.js`, `web/`).\n- The user is not asking for a review/analysis/improvement of backend code.\n- The scope is not under `api/` (unless the user explicitly asks to review backend-related changes outside `api/`).\n\n## How to use this skill\n\nFollow these steps when using this skill:\n\n1. **Identify the review mode** (pending-change vs snippet vs file-focused) based on the user’s input. Keep the scope tight: review only what the user provided or explicitly referenced.\n2. Follow the rules defined in **Checklist** to perform the review. If no Checklist rule matches, apply **General Review Rules** as a fallback to perform the best-effort review.\n3. Compose the final output strictly follow the **Required Output Format**.\n\nNotes when using this skill:\n- Always include actionable fixes or suggestions (including possible code snippets).\n- Use best-effort `File:Line` references when a file path and line numbers are available; otherwise, use the most specific identifier you can.\n\n## Checklist\n\n- db schema design: if the review scope includes code/files under `api/models/` or `api/migrations/`, follow [references/db-schema-rule.md](references/db-schema-rule.md) to perform the review\n- architecture: if the review scope involves controller/service/core-domain/libs/model layering, dependency direction, or moving responsibilities across modules, follow [references/architecture-rule.md](references/architecture-rule.md) to perform the review\n- repositories abstraction: if the review scope contains table/model operations (e.g., `select(...)`, `session.execute(...)`, joins, CRUD) and is not under `api/repositories`, `api/core/repositories`, or `api/extensions/*/repositories/`, follow [references/repositories-rule.md](references/repositories-rule.md) to perform the review\n- sqlalchemy patterns: if the review scope involves SQLAlchemy session/query usage, db transaction/crud usage, or raw SQL usage, follow [references/sqlalchemy-rule.md](references/sqlalchemy-rule.md) to perform the review\n\n## General Review Rules\n\n### 1. Security Review\n\nCheck for:\n- SQL injection vulnerabilities\n- Server-Side Request Forgery (SSRF)\n- Command injection\n- Insecure deserialization\n- Hardcoded secrets/credentials\n- Improper authentication/authorization\n- Insecure direct object references\n\n### 2. Performance Review\n\nCheck for:\n- N+1 queries\n- Missing database indexes\n- Memory leaks\n- Blocking operations in async code\n- Missing caching opportunities\n\n### 3. Code Quality Review\n\nCheck for:\n- Code forward compatibility\n- Code duplication (DRY violations)\n- Functions doing too much (SRP violations)\n- Deep nesting / complex conditionals\n- Magic numbers/strings\n- Poor naming\n- Missing error handling\n- Incomplete type coverage\n\n### 4. Testing Review\n\nCheck for:\n- Missing test coverage for new code\n- Tests that don''t test behavior\n- Flaky test patterns\n- Missing edge cases\n\n## Required Output Format\n\nWhen this skill invoked, the response must exactly follow one of the two templates:\n\n### Template A (any findings)\n\n```markdown\n# Code Review Summary\n\nFound <X> critical issues need to be fixed:\n\n## 🔴 Critical (Must Fix)\n\n### 1. <brief description of the issue>\n\nFilePath: <path> line <line>\n<relevant code snippet or pointer>\n\n#### Explanation\n\n<detailed explanation and references of the issue>\n\n#### Suggested Fix\n\n1. <brief description of suggested fix>\n2. <code example> (optional, omit if not applicable)\n\n---\n... (repeat for each critical issue) ...\n\nFound <Y> suggestions for improvement:\n\n## 🟡 Suggestions (Should Consider)\n\n### 1. <brief description of the suggestion>\n\nFilePath: <path> line <line>\n<relevant code snippet or pointer>\n\n#### Explanation\n\n<detailed explanation and references of the suggestion>\n\n#### Suggested Fix\n\n1. <brief description of suggested fix>\n2. <code example> (optional, omit if not applicable)\n\n---\n... (repeat for each suggestion) ...\n\nFound <Z> optional nits:\n\n## 🟢 Nits (Optional)\n### 1. <brief description of the nit>\n\nFilePath: <path> line <line>\n<relevant code snippet or pointer>\n\n#### Explanation\n\n<explanation and references of the optional nit>\n\n#### Suggested Fix\n\n- <minor suggestions>\n\n---\n... (repeat for each nits) ...\n\n## ✅ What''s Good\n\n- <Positive feedback on good patterns>\n```\n\n- If there are no critical issues or suggestions or option nits or good points, just omit that section.\n- If the issue number is more than 10, summarize as \"Found 10+ critical issues/suggestions/optional nits\" and only output the first 10 items.\n- Don''t compress the blank lines between sections; keep them as-is for readability.\n- If there is any issue requires code changes, append a brief follow-up question to ask whether the user wants to apply the fix(es) after the structured output. For example: \"Would you like me to use the Suggested fix(es) to address these issues?\"\n\n### Template B (no issues)\n\n```markdown\n## Code Review Summary\n✅ No issues found.\n```"},"category":"official","lastSynced":"2026-03-06T06:03:45.351Z","seo":{"title":{"en":"Backend-Code-Review: Automated Python Code Analysis for A...","zh":"后端代码审查工具：Python 代码质量和安全性检查","ja":"バックエンドコードレビューツール：Python コードの品質とセキュリティチェック","ko":"백엔드 코드 리뷰 도구: Python 코드 품질 및 보안检查","es":"Guía de configuración de revisión de código backend","fr":"Guide de configuration de la revue de code backend","de":"Einrichtungsanleitung für die Überprüfung von Backend-Code","pt":"Guia de Configuração do Agente de Revisão de Código Backend","ru":"Настройка агента проверки бэкенда ИИ Агенты","ar":"دليل إعداد وكيل مراجعة رمز الخادم الخلفي"},"description":{"en":"Unlock efficient backend code review with AI-powered analysis for Python files under the api/ directory. Review, analyze, and improve your code now!","zh":"使用后端代码审查工具检查Python代码的质量、安全性和可维护性，确保您的API代码符合最佳实践","ja":"バックエンドコードレビューツールを使用して、Python コードの品質、セキュリティ、メンテナンス性をチェックし、API コードがベストプラクティスに準拠していることを確認する","ko":"백엔드 코드 리뷰 도구를 사용하여 Python 코드의 품질, 보안 및 유지 보수성을 확인하고 API 코드가 최선의 관행에 따라 작성되었는지 확인","es":"Mejora la calidad y seguridad de tu código backend con nuestra herramienta de revisión de código basada en AI","fr":"Améliorez la qualité et la sécurité de votre code backend avec notre outil de revue de code basé sur l''IA","de":"Verbessern Sie die Qualität und Sicherheit Ihres Backend-Codes mit unserer KI-basierten Code-Überprüfung","pt":"Melhore a qualidade e segurança do seu código backend com o agente de revisão de código backend, suportando revisão de alterações pendentes e trechos de código","ru":"Улучшите качество и безопасность вашего бэкенда с помощью агента проверки бэкенда ИИ Агенты, поддерживающего проверку изменений и фрагментов кода","ar":"حسّن جودة وأمان رمز الخادم الخلفي باستخدام وكيل مراجعة رمز الخادم الخلفي، يدعم مراجعة التغييرات المعلقة وأجزاء الشفرة"},"definition":{"en":"backend-code-review is a skill that reviews backend code for quality, security, maintainability, and best practices based on established checklist rules.","zh":"后端代码审查工具是一种检查Python代码质量、安全性和可维护性的工具","ja":"バックエンドコードレビューツールは、Python コードの品質、セキュリティ、メンテナンス性をチェックするツールです","ko":"백엔드 코드 리뷰 도구는 Python 코드의 품질, 보안 및 유지 보수성을 확인하는 도구입니다","es":"La revisión de código backend es una herramienta de AI que revisa y analiza código Python para asegurar su calidad y seguridad","fr":"La revue de code backend est un outil d''IA qui examine et analyse le code Python pour en assurer la qualité et la sécurité","de":"Die Überprüfung von Backend-Code ist ein KI-Tool, das Python-Code überprüft und analysiert, um dessen Qualität und Sicherheit zu gewährleisten","pt":"O que é um agente de revisão de código backend? É uma ferramenta que analisa arquivos de código backend para garantir qualidade e segurança","ru":"Что такое агент проверки бэкенда? Это инструмент, анализирующий файлы кода бэкенда для обеспечения качества и безопасности","ar":"ما هو وكيل مراجعة رمز الخادم الخلفي؟ إنه أداة تقوم بتحليل ملفات رمز الخادم الخلفي لضمان الجودة والأمان"},"features":{"en":["Supports pending-change review for staged/working-tree files","Reviews code snippets pasted into the chat","Analyzes Python files (.py) under the api/ directory","Improves code quality based on established checklist rules","Enhances security and maintainability of backend code"],"zh":["支持pending-change审查","支持代码片段审查","支持文件专注审查","检查Python代码的质量和安全性","确保API代码符合最佳实践","使用Python进行后端代码开发"],"ja":["pending-change レビューをサポート","コード スニペット レビューをサポート","ファイル フォーカス レビューをサポート","Python コードの品質とセキュリティをチェック","API コードがベストプラクティスに準拠していることを確認","Python を使用したバックエンド コード開発"],"ko":["pending-change 리뷰를 지원","코드 스니펫 리뷰를 지원","파일 중심 리뷰를 지원","Python 코드의 품질과 보안을 확인","API 코드가 최선의 관행에 따라 작성되었는지 확인","Python을 사용한 백엔드 코드 개발"],"es":["Revisión de código Python bajo el directorio api/","Análisis de calidad, seguridad y mantenibilidad","Compatibilidad con revisión de cambios pendientes y fragmentos de código","Soporte para Python y otros lenguajes de programación","Integración con frameworks como Next.js y OpenAI"],"fr":["Revue de code Python sous le répertoire api/","Analyse de la qualité, de la sécurité et de la maintenabilité","Compatibilité avec la revue de modifications en attente et les extraits de code","Prise en charge de Python et d''autres langages de programmation","Intégration avec des frameworks tels que Next.js et OpenAI"],"de":["Überprüfung von Python-Code unter dem Verzeichnis api/","Analyse von Qualität, Sicherheit und Wartbarkeit","Unterstützung für die Überprüfung von ausstehenden Änderungen und Code-Snippets","Unterstützung von Python und anderen Programmiersprachen","Integration mit Frameworks wie Next.js und OpenAI"],"pt":["Análise de arquivos .py no diretório api/","Suporte à revisão de alterações pendentes","Suporte à revisão de trechos de código","Verificação de qualidade, segurança e boas práticas","Integração com tecnologias como Python e Next.js"],"ru":["Анализ файлов .py в директории api/","Поддержка проверки изменений","Поддержка проверки фрагментов кода","Проверка качества, безопасности и лучших практик","Интеграция с технологиями seperti Python и Next.js"],"ar":["تحليل ملفات .py في الدليل api/","دعم مراجعة التغييرات المعلقة","دعم مراجعة أجزاء الشفرة","التحقق من الجودة والأمان وأفضل الممارسات","التكامل مع التكنولوجيا مثل Python و Next.js"]},"keywords":{"en":["how to use backend-code-review","backend-code-review vs code analysis tools","backend-code-review setup guide for AI agents","what is backend-code-review","backend-code-review alternative for python developers","automated python code review with backend-code-review"],"zh":["后端代码审查工具","Python 代码质量检查","API 代码安全性检查","代码审查工具","Python 后端开发","AI 代码审查","代码质量检查工具"],"ja":["バックエンドコードレビューツール","Python コード品質チェック","API コードセキュリティチェック","コードレビューツール","Python バックエンド開発","AI コードレビュー","コード品質チェックツール"],"ko":["백엔드 코드 리뷰 도구","Python 코드 품질 확인","API 코드 보안 확인","코드 리뷰 도구","Python 백엔드 개발","AI 코드 리뷰","코드 품질 확인 도구"],"es":["revisión de código backend","herramientas de AI para desarrollo","mejora de la calidad del código","seguridad del código","mantenibilidad del código","Python","Next.js","OpenAI"],"fr":["revue de code backend","outils d''IA pour le développement","amélioration de la qualité du code","sécurité du code","maintenabilité du code","Python","Next.js","OpenAI"],"de":["Überprüfung von Backend-Code","KI-Tools für die Entwicklung","Verbesserung der Code-Qualität","Code-Sicherheit","Code-Wartbarkeit","Python","Next.js","OpenAI"],"pt":["agente de revisão de código backend","revisão de código python","segurança de código backend","boas práticas de código","integração com next.js","revisão de alterações pendentes","revisão de trechos de código"],"ru":["агент проверки бэкенда","проверка кода python","безопасность бэкенда","лучшие практики кода","интеграция с next.js","проверка изменений","проверка фрагментов кода"],"ar":["وكيل مراجعة رمز الخادم الخلفي","مراجعة رمز بايثون","أمان رمز الخادم الخلفي","أفضل ممارسات رمز","التكامل مع next.js","مراجعة التغييرات المعلقة","مراجعة أجزاء الشفرة"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Quality Agents specializing in Python backend security and maintainability analysis.","zh":"非常适合专注于 Python 后端安全性和可维护性分析的代码质量代理。","ja":"Python バックエンドのセキュリティと保守性の分析を専門とするコード品質エージェントに最適です。","ko":"Python 백엔드 보안 및 유지보수성 분석을 전문으로 하는 코드 품질 에이전트에 이상적입니다.","es":"Ideal para Agentes de Calidad de Código especializados en seguridad y análisis de mantenibilidad de backend de Python.","fr":"Idéal pour les agents de qualité de code spécialisés dans la sécurité et l''analyse de maintenabilité du backend Python.","de":"Ideal für Code-Qualitäts-Agents, die auf die Sicherheit und Analyse der Wartbarkeit von Python-Backends spezialisiert sind.","pt":"Ideal para Agentes de Qualidade de Código especializados em análise de segurança e capacidade de manutenção de backend Python.","ru":"Идеально подходит для Агентов Качества Кода, специализирующихся на анализе безопасности и сопровождаемости Python бэкенда.","ar":"مثالي لوكلاء جودة الكود المتخصصين في تحليل أمان وقابلية الصيانة للواجهة الخلفية (backend) بلغة Python."},"recommendation":{"en":"Performs comprehensive static analysis of Python backend code against established checklist rules for security vulnerabilities, code quality, and maintainability best practices. Supports multiple review modes including pending-change analysis for git workflows and direct code snippet evaluation.","zh":"根据既定的安全检查清单规则，对 Python 后端代码执行全面的静态分析，以检测安全漏洞、代码质量和可维护性最佳实践。支持多种审查模式，包括针对 git 工作流程的待处理变更分析和直接代码片段评估。","ja":"セキュリティ脆弱性、コード品質、保守性のベストプラクティスに関する確立されたチェックリストルールに基づいて、Python バックエンドコードの包括的な静的解析を実行します。git ワークフロー用の保留中の変更分析や直接コードスニペット評価を含む、複数のレビューモードをサポートします。","ko":"보안 취약점, 코드 품질 및 유지보수성 모범 사례에 대한 확립된 체크리스트 규칙에 대해 Python 백엔드 코드의 포괄적인 정적 분석을 수행합니다. git 워크플로우를 위한 변경 예정 분석 및 직접 코드 스니펫 평가를 포함한 여러 검토 모드를 지원합니다.","es":"Realiza un análisis estático exhaustivo del código de backend de Python contra reglas de lista de verificación establecidas para vulnerabilidades de seguridad, calidad de código y prácticas recomendadas de mantenimiento. Admite varios modos de revisión, incluido el análisis de cambios pendientes para flujos de trabajo de git y la evaluación directa de fragmentos de código.","fr":"Effectue une analyse statique complète du code backend Python par rapport aux règles de checklist établies pour les vulnérabilités de sécurité, la qualité du code et les meilleures pratiques de maintenabilité. Prend en charge plusieurs modes de révision, notamment l''analyse des modifications en attente pour les workflows Git et l''évaluation directe des extraits de code.","de":"Führt eine umfassende statische Analyse des Python-Backend-Codes gegen etablierte Prüflistenregeln für Sicherheitslücken, Code-Qualität und Wartbarkeitsbest-Practices durch. Unterstützt mehrere Überprüfungsmodi, einschließlich der Analyse von Pending-Changes für Git-Workflows und der direkten Bewertung von Code-Snippets.","pt":"Executa análise estática abrangente do código de backend Python em relação a regras de checklist estabelecidas para vulnerabilidades de segurança, qualidade de código e melhores práticas de capacidade de manutenção. Suporta múltiplos modos de revisão, incluindo análise de alterações pendentes (pending-change) para fluxos de trabalho git e avaliação direta de snippets de código.","ru":"Выполняет комплексный статический анализ кода Python бэкенда на соответствие установленным правилам контрольного списка для уязвимостей безопасности, качества кода и лучших практик сопровождаемости. Поддерживает несколько режимов проверки, включая анализ ожидающих изменений (pending-change) для рабочих процессов git и прямую оценку фрагментов кода.","ar":"يقوم بإجراء تحليل ثابت شامل لكود الواجهة الخلفية (backend) بلغة Python مقابل قواعد قائمة مرجعية معتمدة للثغرات الأمنية، وجودة الكود، وأفضل ممارسات قابلية الصيانة. يدعم أوضاع المراجعة المتعددة بما في ذلك تحليل التغييرات المعلقة (pending-change) لسير عمل git وتقييم snippets الكود مباشرة."},"useCases":{"en":["Reviewing staged code changes before commit","Analyzing pasted Python code snippets for best practices","Conducting security-focused audits of api/ directory files","Identifying maintainability issues in backend modules"],"zh":["在提交前审查暂存的代码更改","针对粘贴的 Python 代码片段进行最佳实践分析","对 api/ 目录文件进行以安全为重点的审计","识别后端模块中的可维护性问题"],"ja":["コミット前のステージングされたコード変更のレビュー","貼り付けられた Python コードスニペットのベストプラクティス分析","api/ ディレクトリファイルのセキュリティに焦点を当てた監査の実施","バックエンドモジュールの保守性問題の特定"],"ko":["커밋 전 스테이징된 코드 변경 사항 검토","붙여넣은 Python 코드 스니펫에 대한 모범 사례 분석","api/ 디렉토리 파일에 대한 보안 중심 감사 수행","백엔드 모듈의 유지보수성 문제 식별"],"es":["Revisar los cambios de código en espera antes de confirmar","Analizar fragmentos de código Python pegados para las mejores prácticas","Realizar auditorías de seguridad enfocadas en archivos del directorio api/","Identificar problemas de mantenimiento en módulos de backend"],"fr":["Réviser les modifications de code en attente avant de confirmer","Analyser les extraits de code Python collés pour les meilleures pratiques","Effectuer des audits de sécurité axés sur les fichiers du répertoire api/","Identifier les problèmes de maintenabilité dans les modules backend"],"de":["Überprüfen von Code-Änderungen, die vor dem Commit wartend sind","Analysieren von eingefügten Python-Code-Snippets für Best-Practices","Durchführen von sicherheitsorientierten Audits von Dateien im api/-Verzeichnis","Identifizieren von Wartbarkeitsproblemen in Backend-Modulen"],"pt":["Revisão de alterações de código em staged antes do commit","Análise de snippets de código Python colados para melhores práticas","Realização de auditorias com foco em segurança de arquivos do diretório api/","Identificação de problemas de capacidade de manutenção em módulos de backend"],"ru":["Проверка ожидающих изменений кода перед коммитом","Анализ вставленных фрагментов кода Python на соответствие лучшим практикам","Проведение аудитов безопасности файлов в каталоге api/","Выявление проблем сопровождаемости в бэкенд модулях"],"ar":["مراجعة تغييرات الكود المعلقة (staged) قبل الالتزام (commit)","تحليل snippets كود Python التي تم لصقها للتأكد من اتباع أفضل الممارسات","إجراء عمليات تدقيق تركز على الأمان لملفات دليل api/","تحديد مشكلات قابلية الصيانة في وحدات الواجهة الخلفية (backend)"]},"limitations":{"en":["Exclusively for backend files (.py) in api/ directory","No frontend file support (.tsx, .ts, .js)","Requires git access for pending-change reviews"],"zh":["仅适用于 api/ 目录中的后端文件 (.py)","不支持前端文件 (.tsx, .ts, .js)","待处理变更审查需要 git 访问权限"],"ja":["api/ ディレクトリ内のバックエンドファイル (.py) 専用","フロントエンドファイルのサポートなし (.tsx, .ts, .js)","保留中の変更レビューには git アクセスが必要"],"ko":["api/ 디렉토리의 백엔드 파일 (.py) 전용","프론트엔드 파일 지원 없음 (.tsx, .ts, .js)","변경 예정 검토를 위해 git 액세스 필요"],"es":["Exclusivamente para archivos de backend (.py) en el directorio api/","No hay soporte para archivos del frontend (.tsx, .ts, .js)","Requiere acceso a git para revisiones de cambios pendientes"],"fr":["Exclusivement pour les fichiers backend (.py) du répertoire api/","Aucun support pour les fichiers frontend (.tsx, .ts, .js)","Nécessite un accès Git pour les révisions de modifications en attente"],"de":["Ausschließlich für Backend-Dateien (.py) im api/-Verzeichnis","Keine Unterstützung für Frontend-Dateien (.tsx, .ts, .js)","Erfordert Git-Zugriff für die Überprüfung von pending-Changes"],"pt":["Exclusivamente para arquivos de backend (.py) no diretório api/","Sem suporte para arquivos de frontend (.tsx, .ts, .js)","Requer acesso ao git para revisões de alterações pendentes (pending-change)"],"ru":["Исключительно для бэкенд файлов (.py) в каталоге api/","Отсутствие поддержки фронтенд файлов (.tsx, .ts, .js)","Требуется доступ к git для проверок ожидающих изменений (pending-change)"],"ar":["حصريًا لملفات الواجهة الخلفية (backend) (.py) في دليل api/","لا يدعم ملفات الواجهة الأمامية (frontend) (.tsx, .ts, .js)","يتطلب الوصول إلى git لمراجعات التغييرات المعلقة (pending-change)"]},"version":4},"contentHash":"a032c9a81b936f6127b0ad40b97073a18119352f86c87ed371e6e81825d4b552","repoEtag":"W/\"8b79270de464b84537dd173d2e750efb4b05e743496516f4c20a14f45fafde09\"","qualityScore":95}');
